window.LXY_WORDS = [{"w":"space","p":"speɪs","m":"n.外层空间；太空；空间","tip":"单词发音类似“四百四”→ 他家房子的面积是 440 平方米，“空间”很大。","ex":["They found the space in the cage too small to stay in.","它们发现笼子里的空间太小，待不下去。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"universe","p":"ˈjuːnɪvɜːs","m":"n.宇宙；领域，体系","tip":"uni-（统一）+ verse（转）→ 万物运转的统一整体 → 宇宙","ex":["The idea of a parallel universe is hard to grasp.","平行宇宙的概念是很难理解的。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"unite","p":"juˈnaɪt","m":"v.联合；团结","tip":"","ex":["We will unite in fighting crime.","我们将联合打击犯罪。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"reunite","p":"ˌriːjuːˈnaɪt","m":"v.（使）重逢；再次相聚","tip":"","ex":["The family was reunited after the war.","战争过后，这家人又相聚了。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"union","p":"ˈjuːniən","m":"n.协会，联合会；工会","tip":"","ex":["I have joined the union.","我已经加入工会。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"diverse","p":"daɪˈvɜːs","m":"adj.不同的；多种多样的","tip":"di-（分开）+ verse（转）→ 转向不同方向 → 多种多样的","ex":["People from diverse backgrounds no longer socialise.","来自不同背景的人不再社交。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"convert","p":"kənˈvɜːt","m":"v.转变；转换","tip":"con-（共同）+ vert（= verse，转变）→ 转变","ex":["You need to ensure that you've converted the data properly.","您需要确保已经正确转换了数据。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"reverse","p":"rɪˈvɜːs","m":"v.逆转；彻底改变；撤销 adj.相反的；反向的；后面的 n.逆转；后面；损失；倒挡","tip":"re-（往回）+ verse（转）→ 逆转","ex":["They are trying to prevent, limit or even reverse disease by changing what patients eat.","他们正试图通过改变患者的饮食来预防、限制甚至逆转疾病。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"anniversary","p":"ˌænɪˈvɜːsəri","m":"n.周年纪念日","tip":"anni（颠倒顺序变成 nian，“年”的拼音）+ vers（转）+ -ary（名词后缀）→ 一年转一次 → 周年纪念日","ex":["The company is celebrating its 100-year anniversary this year.","该公司正庆祝今年成立 100 周年。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"annual","p":"ˈænjuəl","m":"adj.每年的；年度的；一年一次的","tip":"单词发音类似“俺牛了”→ 希望“每年的”年终复盘我都能自豪地说：“俺牛了。”","ex":["Funding will be awarded on an annual basis.","资金将按年度发放。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"controversy","p":"ˈkɒntrəvɜːsi","m":"n.争议；（公开的）争论，论战","tip":"contro-（相反的）+ vers（旋转）+ -y（名词后缀）→ 转向相反的方向 → 争议；争论","ex":["The controversy surrounding his latest movie continues.","围绕他最新电影的争议仍在继续。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"contrary","p":"ˈkɒntrəri","m":"adj.相对立的，相反的 n.相反的事实（或情况）","tip":"con-（全部）+ tra（音似“戳”）+ -(a)ry（形容词后缀）→ 全部人都戳他，大家都是与他“相对立的”人。","ex":["Contrary to popular belief, many cats dislike milk.","与普遍的看法相反，许多猫不喜欢牛奶。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"contrast","p":"ˈkɒntrɑːst","m":"n.明显的差异；对比，对照","tip":"contra-（相反的）+ st（联想 street）→ 这条繁华的街和那条街形成了“对比”。","ex":["In contrast, the recent surge in world grain prices is trend-driven.","相比之下，最近全球粮食价格的飞涨是趋势造成的。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"nasty","p":"ˈnɑːsti","m":"adj.令人厌恶的；令人不快的；严重的；无礼的；危险的","tip":"单词发音类似“那试题”→ 临近期末了，还有那么多试题没有做，这真是一件“令人不快的”事。","ex":["He had a nasty accident.","他出了严重的事故。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"astronaut","p":"ˈæstrənɔːt","m":"n.宇航员，航天员","tip":"astro（星星；天体）+ -naut（水手，航行家）→ 星际航行者 → 宇航员，航天员","ex":["They tried to meet astronauts' specific requirements.","他们试图满足宇航员的特殊要求。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"heaven","p":"ˈhevn","m":"n.天堂；天空","tip":"单词发音类似“骇闻”→ 某人去了“天堂”，这样的消息骇人听闻。","ex":["The island is truly a heaven on earth.","那个岛堪称人间天堂。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"satellite","p":"ˈsætəlaɪt","m":"n.卫星；人造卫星","tip":"单词发音类似“赛他莱特”→ 赛过莱特兄弟发明的飞机的，就是“人造卫星”了。","ex":["The interview came live by satellite from Hollywood.","采访通过卫星从好莱坞实时传送。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"moon","p":"muːn","m":"n.月亮；月球；卫星","tip":"月亮（moon）走，我也走（move）。","ex":["It makes us wonder if scientists can send a man to the moon.","这使我们想知道科学家能否把人送上月球。"],"lesson":"u01-l01","group":"vers(e)相关"},{"w":"develop","p":"dɪˈveləp","m":"v.开发；发展；成长；增强；发挥","tip":"单词发音类似“地位落魄”→ 地位落魄时需要“发展”。","ex":["It takes time to develop new technology.","开发新技术需要时间。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"evolve","p":"ɪˈvɒlv","m":"v.（使）演变，（使）进化；（使）发展","tip":"e-（出去）+ volve（旋转，卷）→ 旋转出去就是螺旋式上升 → 进化；发展","ex":["Lunch boxes have evolved along with the transformation of schools.","随着学校的改革，午餐盒也在不断发展。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"revolve","p":"rɪˈvɒlv","m":"v.旋转；环绕；转动","tip":"re-（表加强）+ volve（旋转）→ 旋转；环绕；转动","ex":["The fan revolved slowly.","电扇缓慢地转动着。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"involve","p":"ɪnˈvɒlv","m":"v.涉及；包含；需要","tip":"in-（入）+ volve（旋转，卷）→ 卷入 → 涉及；包含","ex":["The job involves me travelling all over the country.","这份工作需要我在全国各地奔跑。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"advance","p":"ədˈvɑːns","m":"n.进展，进步；预先 v.进步；前进；推动","tip":"ad-（一再）+ vance（联想人名“万斯”）→ 万斯一再“进步”。","ex":["It contributes greatly to the advance of society as a whole.","它对整个社会的进步做出了巨大贡献。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"ahead","p":"əˈhed","m":"adv.向前；提前；领先","tip":"a-（在……上）+ head（头）→ 在头上 → 领先","ex":["When they look ahead, they see roadblocks to their success.","当他们展望未来时，他们看到了阻碍成功的重重障碍。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"ongoing","p":"ˈɒnɡəʊɪŋ","m":"adj.继续进行的，不断发展的","tip":"","ex":["The police investigation is ongoing.","警方的调查在持续进行中。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"improve","p":"ɪmˈpruːv","m":"v.改进；改善","tip":"i（我）+ m（联想“妹”）+ prove（证明）→ 我妹妹为了证明自己，开始努力“改进”。","ex":["Rewards can improve performance at work and school.","奖励可以改善在工作和学校中的表现。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"approve","p":"əˈpruːv","m":"v.批准；赞成，同意；认可","tip":"ap-（= to）+ prove（证明）→ 向……证明 → 赞成","ex":["Do you approve of my idea?","你同意我的想法吗？"],"lesson":"u01-l01","group":"develop 相关"},{"w":"proof","p":"pruːf","m":"n.证据，证明 adj.能抵御的","tip":"prove v.证明，证实 → proof n. & adj.","ex":["So far there has been no proof that the knife belonged to her.","到目前为止，还没有证据证明那把刀子是她的。"],"lesson":"u01-l01","group":"develop 相关"},{"w":"enhance","p":"ɪnˈhɑːns","m":"v.提高；增强","tip":"en-（使）+ hance（联想人名“汉斯”）→ 努力学习使汉斯“提高”了自身能力。","ex":["This is an opportunity to enhance the reputation of the company.","这是一个提高公司声誉的机会。"],"lesson":"u01-l01","group":"en 相关"},{"w":"enable","p":"ɪˈneɪbl","m":"v.使能够；使成为可能","tip":"en-（使）+ able（能够）→ 使能够","ex":["Self-control enables you to avoid behaviours that don't contribute to your success.","自我控制使你能够避免无益于你成功的行为。"],"lesson":"u01-l01","group":"en 相关"},{"w":"enlarge","p":"ɪnˈlɑːdʒ","m":"v.扩大，扩展；详述","tip":"en-（使）+ large（大）→ 扩大，扩展","ex":["Reading will enlarge your vocabulary.","阅读能扩大你的词汇量。"],"lesson":"u01-l01","group":"en 相关"},{"w":"enrich","p":"ɪnˈrɪtʃ","m":"v.充实；使丰富；使饱含（某物）","tip":"en-（使）+ rich（富有的）→ 充实；使丰富","ex":["The liberal arts in higher education help enrich students' spiritual life.","高等教育中的文科有助于丰富学生的精神生活。"],"lesson":"u01-l01","group":"en 相关"},{"w":"fasten","p":"ˈfɑːsn","m":"v.扎牢，扣住，系牢","tip":"fast（快）+ -en（使）→ “系牢”鞋带能使你跑得更快。","ex":["If you do not fasten your safety belt, your chances of being hurt will be greater.","如果你不系牢安全带，你受伤的概率就会更大。"],"lesson":"u01-l01","group":"en 相关"},{"w":"tight","p":"taɪt","m":"adj.牢固的，紧的；严密的；防……的 adv.紧紧地；牢固地","tip":"单词发音类似“太大”→ 他的鞋子太大，于是他把鞋带“紧紧地”系了起来。","ex":["These shoes are much too tight.","这双鞋太紧了。"],"lesson":"u01-l01","group":"en 相关"},{"w":"buckle","p":"ˈbʌkl","m":"v.扣住，扣紧；（被）压垮 n.（皮带等的）搭扣；锁扣","tip":"单词发音类似“把扣”→ 开车时务必要把安全带“扣紧”。","ex":["He buckled on his sword.","他把剑扣好。"],"lesson":"u01-l01","group":"en 相关"},{"w":"watertight","p":"ˈwɔːtətaɪt","m":"adj.不透水的；防水的；严密的","tip":"water（水）+ tight（防……的）→ 防水的","ex":["The roof has been made watertight.","屋顶已经做了防水处理。"],"lesson":"u01-l01","group":"en 相关"},{"w":"loose","p":"luːs","m":"v.释放；松开 adj.未固定牢的；自由的","tip":"松（loose）去个 o 变丢（lose）。","ex":["One of the bricks feels slightly loose.","有块砖似乎有点儿松动。"],"lesson":"u01-l01","group":"en 相关"},{"w":"undo","p":"ʌnˈduː","m":"v.打开，解开；消除，取消","tip":"un-（否定前缀）+ do（做）→ 打开；取消","ex":["I undid the package and took out the books.","我打开包裹取出书来。"],"lesson":"u01-l01","group":"en 相关"},{"w":"form","p":"fɔːm","m":"n.形式；表格 v.组成；（使）形成","tip":"for（为了）+ m（联想“妈”）→ 为了妈妈，“形式”上也得过得去。","ex":["One form of socialising doesn't replace the other.","一种社交形式并不能取代另一种。"],"lesson":"u01-l01","group":"form 相关"},{"w":"formal","p":"ˈfɔːml","m":"adj.正式的；庄重的；正规的","tip":"form（形式）+ -al（……的）→ 形式上的 → 正式的","ex":["Students' ability to learn formal writing is unlikely to be affected by texting.","学生学习正式写作的能力不太可能受到发短信的影响。"],"lesson":"u01-l01","group":"form 相关"},{"w":"uniform","p":"ˈjuːnɪfɔːm","m":"n.校服，制服 adj.统一的","tip":"uni-（统一）+ form（形式）→ 统一形式的衣服 → 校服，制服","ex":["The hat is part of the school uniform.","这个帽子是校服的一部分。"],"lesson":"u01-l01","group":"form 相关"},{"w":"formation","p":"fɔːˈmeɪʃn","m":"n.形成，组成；形成物，组成物","tip":"form v.形成 → formation n.","ex":["The particles interfere with the formation of carbon-14 on earth.","这些粒子干扰了地球上碳 14 的形成。"],"lesson":"u01-l01","group":"form 相关"},{"w":"reform","p":"rɪˈfɔːm","m":"n. & v.改革，改善","tip":"re-（再）+ form（形成；形式）→ 再形成（新形式）→ 改革","ex":["It may force companies to reform their business practice.","它可能会迫使公司改革其商业惯例。"],"lesson":"u01-l01","group":"form 相关"},{"w":"format","p":"ˈfɔːmæt","m":"n.总体安排；计划；设计 v.格式化","tip":"","ex":["The format of the new quiz show has proved popular.","新的智力竞赛节目的总体安排已被证明很受欢迎。"],"lesson":"u01-l01","group":"form 相关"},{"w":"conform","p":"kənˈfɔːm","m":"v.（～ to）遵守；顺从；相一致","tip":"con-（共同）+ form（形式）→ 使形式统一 → 遵守；顺从；相一致","ex":["A behaviour that does not conform to social norms may be described as being deviant.","不遵守社会规范的行为可能被描述为偏离常轨。"],"lesson":"u01-l01","group":"form 相关"},{"w":"comply","p":"kəmˈplaɪ","m":"v.遵守；顺从","tip":"com-（一起）+ ply（音似“扑来”）→ 他们“遵守”规定，一起扑来倒在地上。","ex":["They refused to comply with the UN resolution.","他们拒绝遵守联合国的决议。"],"lesson":"u01-l01","group":"form 相关"},{"w":"formulate","p":"ˈfɔːmjuleɪt","m":"v.确切表达；认真阐述；制定；规划；构想","tip":"for（音似 four）+ mu（联想“母”）+ late（迟到）→ 开家长会时，四个妈妈迟到了，她们“认真阐述”了理由。","ex":["He struggled to formulate an answer.","他努力想出一个答案。"],"lesson":"u01-l01","group":"form 相关"},{"w":"formula","p":"ˈfɔːmjələ","m":"n.公式；方程式","tip":"有了规划（formulate），就可以套公式（formula）了。","ex":["They copy formulas on their palms.","他们把公式抄在手掌上。"],"lesson":"u01-l01","group":"form 相关"},{"w":"programme","p":"ˈprəʊɡræm","m":"n.计划；程序；节目；项目 v.（为计算机）编写程序；预设","tip":"pro-（往前）+ gr（联想“官人”）+ amme（联想“阿妹”）→ 官人按“计划”追求阿妹。","ex":["In a pilot programme, students are given electronic devices to do assignments when schools are closed.","在一个试点项目中，当学校停课时，学生们可以使用电子设备完成作业。"],"lesson":"u01-l01","group":"form 相关"},{"w":"perform","p":"pəˈfɔːm","m":"v.做；执行；表演；工作；运转","tip":"","ex":["Lion dancers need to have a little imagination to perform well.","舞狮者需要有一点想象力才能表演好。"],"lesson":"u01-l01","group":"form 相关"},{"w":"drill","p":"drɪl","m":"v.钻（孔）；训练；作……演习 n.钻头；（应对紧急情况的）演习，训练","tip":"dri（音似“锥”）+ ll（形似数字 11）→ 他用锥子在墙上“钻”了 11 个孔。","ex":["The dentist started drilling my tooth.","牙医开始钻我的牙。"],"lesson":"u01-l01","group":"form 相关"},{"w":"inform","p":"ɪnˈfɔːm","m":"v.通知，告知；了解，熟悉","tip":"information n.信息 → inform v.","ex":["She is well informed about the design business.","她对设计业务很了解。"],"lesson":"u01-l01","group":"form 相关"},{"w":"notify","p":"ˈnəʊtɪfaɪ","m":"v.（正式）通报，通知","tip":"notice n.通知 → notify v.","ex":["When the system thinks it's being jammed, it'll notify you via push alert.","当系统认为自己被干扰时，它会通过推送警报通知你。"],"lesson":"u01-l01","group":"form 相关"},{"w":"noticeable","p":"ˈnəʊtɪsəbl","m":"adj.显著的；显而易见的","tip":"notice（注意）+ -able（能够）→ 能够注意到的 → 显著的；显而易见的","ex":["There is a noticeable difference between the two brands.","这两个品牌有明显的区别。"],"lesson":"u01-l01","group":"form 相关"},{"w":"coast","p":"kəʊst","m":"n.海岸；海滨","tip":"单词发音类似“靠死它” → 靠山吃山，靠“海岸”吃海。","ex":["One city on the west coast of America has banned single-use bottles from its property and events.","美国西海岸的一个城市禁止在其公有财产处所和活动中使用一次性瓶子。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"toast","p":"təʊst","m":"v.为……干杯；烤 n.吐司；祝酒，敬酒","tip":"单词发音类似“吐司” → “吐司”是“烤”的面包片。","ex":["I usually have a piece of toast for breakfast every day.","我通常每天早餐吃一片吐司。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"roast","p":"rəʊst","m":"v.烤；烘 n.烤肉；庆祝会 adj.烤的，焙的","tip":"他在海岸（coast）上吃烧烤（roast），一边干杯（toast），一边吹牛（boast）。","ex":["The menu included roast grouse.","菜单里有烤松鸡肉。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"sail","p":"seɪl","m":"v.航行；开船；在……上航行；驾驶（船） n.帆；航行","tip":"他扬帆（sail）在海（sea）上航行（sail）。","ex":["People laughed when he said that he wanted to sail around the world.","当他说他想环球航行时，人们都笑了。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"shore","p":"ʃɔː(r)","m":"n.岸，滨","tip":"单词发音类似“首尔” → 首尔部分区域位于汉江两“岸”。","ex":["We spent our vacation at the shore.","我们的假期在海滨度过。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"island","p":"ˈaɪlənd","m":"n.岛","tip":"单词发音类似“爱尔兰” → 爱尔兰共和国位于爱尔兰“岛”。","ex":["They settled on a small island north of England.","他们在英格兰北部的一个小岛上定居了。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"inland","p":"ˌɪnˈlænd","m":"adv.向（或在）内陆","tip":"","ex":["We travelled further inland the next day.","我们第二天继续向内陆行进。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"beach","p":"biːtʃ","m":"n.海滩，沙滩，海滨","tip":"他坐在沙滩（beach）上吃桃子（peach）。","ex":["He lost his way on a beach.","他在海滩上迷了路。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"bench","p":"bentʃ","m":"n.长凳","tip":"单词发音类似“奔驰” → 奔驰车内部空间很大，座椅较长 → 长凳","ex":["I remember sitting on a bench with my aunt at a yoga studio.","我记得我和阿姨一起坐在瑜伽工作室的长凳上。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"harbour","p":"ˈhɑːbə(r)","m":"n.港口 v.庇护；包含","tip":"单词发音类似“哈勃” → 哈勃空间望远镜难以直接观测“港口”细节。","ex":["Several boats lay at anchor in the harbour.","港口停泊着几条船。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"embrace","p":"ɪmˈbreɪs","m":"v.拥抱；包含 n.拥抱","tip":"em-（入）+ brace（大括号） → 进入大括号中 → 拥抱；包含","ex":["Evil behavior is typically thought to embrace one or both forms.","邪恶的行为通常被认为包含一种或两种形式。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"bay","p":"beɪ","m":"n.海湾；分隔间","tip":"单词发音类似“贝” → “海湾”里有很多贝壳。","ex":["It is a place in Upper New York Bay formerly used for exiles.","这是上纽约湾的一个地方，以前是流放者的所在地。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"shelter","p":"ˈʃeltə(r)","m":"n.掩蔽；避难所 v.提供庇护；躲避","tip":"单词发音类似“歇了他” → 他实在太累了，在“避难所”歇下了。","ex":["They have to look for food and shelter underground.","他们不得不在地下寻找食物和避难所。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"shade","p":"ʃeɪd","m":"n.阴凉处，暗处 v.为……遮挡（光线），遮蔽","tip":"sha（联想“沙”）+ de（联想“得”） → 他从“阴凉处”的沙地里淘得了一块金子。","ex":["Most animals seek shade when temperatures in the Sahara Desert soar to 120 degrees Fahrenheit.","当撒哈拉沙漠的温度飙升到120华氏度时，大多数动物都会寻找阴凉的地方。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"shave","p":"ʃeɪv","m":"v.剃，刮去（毛发）；削减，调低 n.刮脸，剃须","tip":"单词发音类似“洗我” → 洗完脸，我又“刮去”了胡子。","ex":["He has completely shaved his head.","他剃了一个光头。"],"lesson":"u01-l02","group":"“大海”相关"},{"w":"belt","p":"belt","m":"n.地带；腰带 v.猛击；用带子系住","tip":"be（是）+ l（形似数字 1）+ t（联想“条”） → 这是一条“腰带”。","ex":["New roads are cutting into the green belt.","一条条新路在逐渐吞噬着绿化地带。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"bond","p":"bɒnd","m":"n.纽带；联系；债券 v.（使）牢固结合","tip":"b + on（上面）+ d → b 在 d 上面，两者“牢固结合”在一起。","ex":["It will help strengthen their emotional bonds.","这将有助于加强他们的情感联系。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"bind","p":"baɪnd","m":"v.捆绑，系，（用长布条）缠绕；结合；约束","tip":"b + in（里面）+ d → b 在 d 里面，两者被“系”在一起。","ex":["The ties that bind us together are so feeble.","把我们联系在一起的纽带是如此脆弱。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"blind","p":"blaɪnd","m":"adj.失明的；盲目的 v.使失明；使失去判断能力","tip":"单词发音类似“不灵的” → 眼睛不灵的 → 失明的；盲目的","ex":["Intelligent people are more prone to silly mistakes because of blind spots in how they use logic.","聪明的人更容易犯愚蠢的错误，因为他们在使用逻辑时存在盲点。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"deaf","p":"def","m":"adj.聋的；失聪的；对……充耳不闻的","tip":"单词发音类似“大夫” → 她一直叫大夫，大夫却听不见，因为她是个“失聪的”人。","ex":["He is a deaf person working in IT.","他是一个在信息技术行业工作的失聪者。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"bend","p":"bend","m":"v.使弯曲；折弯；偏向 n.弯道；弯曲","tip":"b + end（最后） → b 到最后“弯曲”成了 d。","ex":["The doctor told me to avoid bending and stretching.","医生告诉我要避免弯曲和拉伸。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"twist","p":"twɪst","m":"v.使弯曲；（使）扭曲变形；转动；歪曲 n.扭动；转弯处","tip":"单词发音类似“推死他” → 他被人使劲推出去了，气得脸都“扭曲变形”了。","ex":["Twist the wire to form a circle.","把铁丝弯成一个环。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"blend","p":"blend","m":"v.混合，融合","tip":"b（音似“不”）+ lend（借给） → 不要把书借给他，因为他会把书弄混的 → 混合","ex":["Blend together the eggs, sugar and flour.","把鸡蛋、糖和面粉混合到一起。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"mix","p":"mɪks","m":"n.混合；混乱 v.（使）混合；配制","tip":"mi（音似“米”）+ x（联想“线”） → 那个美国人以为把米和线“混合”起来是米线。","ex":["If you mix blue and yellow, you get green.","如果你把蓝色和黄色相混合，那你会得到绿色。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"stir","p":"stɜː(r)","m":"n.（一些人感到的）激动，震动；搅动 v.搅和，搅拌；打动；激发","tip":"s（联想“美女”）+ tir（音似“特”） → 那个美女特爱“搅拌”面粉来做美食。","ex":["It's a book that really stirs the imagination.","这是一本能够真正激发想象力的书。"],"lesson":"u01-l02","group":"“绑”相关"},{"w":"mountain","p":"ˈmaʊntən","m":"n.山；高山","tip":"","ex":["To enjoy the magnificence of a mountain, you have to look upwards in most cases.","在大多数情况下，要欣赏大山的壮丽，你必须仰视。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"fountain","p":"ˈfaʊntən","m":"n.泉水；喷泉；源泉","tip":"foun（联想 found，建立）+ tain（联想 mountain） → 他们建的假山在“喷泉”旁边。","ex":["The new cream is marketed as the fountain of youth.","这种新面霜被营销成青春源泉。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"profound","p":"prəˈfaʊnd","m":"adj.影响深远的；深切的；理解深刻的；深厚的","tip":"pro-（前）+ found（建立） → 武侠片中，早前成立的大多是“影响深远的”门派。","ex":["Beijing has a profound cultural background.","北京有着深厚的文化底蕴。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"foundation","p":"faʊnˈdeɪʃn","m":"n.地基；基础；根据","tip":"found（建立）+ -ation（名词后缀） → 地基；基础；根据","ex":["Many people believe that passion and commitment are the foundations of strong romantic relationships.","许多人认为，激情和承诺是牢固的恋爱关系的基础。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"base","p":"beɪs","m":"n.基础；根据 v.以……为据点（或总部等）；把（总部等）设在","tip":"单词发音类似“贝斯” → 贝斯通常是乐队中的“基础”乐器。","ex":["Then students select an adviser, based on shared academic interests.","然后学生根据共同的学术兴趣选择导师。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"basic","p":"ˈbeɪsɪk","m":"adj.基本的；初级的；必需的","tip":"","ex":["The diving suit and a set of basic tools needed for skin-diving can be bought for 20 dollars.","自由潜水所需的潜水衣和一套基本工具只需20美元。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"basis","p":"ˈbeɪsɪs","m":"n.原因；基础；基准","tip":"","ex":["All members of the committee work on a voluntary basis.","委员会的所有成员都在自愿的基础上工作。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"mount","p":"maʊnt","m":"v.逐步增加；登上，爬上；安排 n.山峰；托架","tip":"mountain n.山；高山 → mount v.& n.","ex":["As the popularity of exercise continues to mount, so does scientific evidence of its health benefits.","随着运动的普及程度不断增加，科学证据也证明了运动对健康的益处。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"amount","p":"əˈmaʊnt","m":"n.数量 v.（～to）等于；总计","tip":"a（一）+ mount（山） → 一座座山连绵起伏，数不清具体的“数量”。","ex":["During the course of trying various things, you will gain a large amount of social experience.","在尝试各事物的过程中，你会获得大量的社会经验。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"soar","p":"sɔː(r)","m":"v.急升，猛增；高飞；升空","tip":"单词发音类似“嗖” → 烟花“嗖”的一声就“升空”了。","ex":["The rocket soared (up) into the air.","火箭升空了。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"ascend","p":"əˈsend","m":"v.升高；攀登","tip":"as-（一再）+ cend（音似 send，发送） → 一再地发送上去 → 升高；攀登","ex":["The children cheered up when they saw the balloons ascending slowly into the sky.","当孩子们看到那些气球缓缓升上天空时，他们欢呼起来。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"descend","p":"dɪˈsend","m":"v.下来，下降；下斜；（夜晚等）降临","tip":"de-（往下）+ scend（音似 send，发送） → 下降","ex":["We managed to reach the top of the mountain, and half an hour later we began to descend.","我们成功到达了山顶，半小时后我们开始下山。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"decline","p":"dɪˈklaɪn","m":"v.下降，衰落；谢绝 n.减少，下降","tip":"de-（往下）+ cline（倾斜） → 下降，衰落；减少","ex":["Research has revealed an enormous decline in reading.","研究显示，阅读量大幅下降。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"incline","p":"ˈɪnklaɪn","m":"v.（使）倾斜，（使）倾向于","tip":"in-（向内）+ cline（倾斜） → （使）倾斜，（使）倾向于","ex":["I incline to the view that we should take no action at this stage.","我倾向于认为我们在这个阶段不应采取行动。"],"lesson":"u01-l02","group":"“大山”相关"},{"w":"ancestor","p":"ˈænsestə(r)","m":"n.祖先；原型","tip":"an（一）+ cest（走）+ -or（名词后缀）→ 一个走在前面的人 → 祖先","ex":["His ancestors had come to America from Ireland.","他的祖先从爱尔兰来到美国。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"ancient","p":"ˈeɪnʃənt","m":"adj.古代的；古老的","tip":"单词发音类似“俺神他”→ 俺喜欢的那个神仙，他住在一座“古老的”建筑中。","ex":["Li Jiang, an ancient town in Yunnan Province, is one of the most famous tourist attractions in China.","丽江，云南省的一个古镇，是中国最著名的旅游景点之一。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"consensus","p":"kənˈsensəs","m":"n.一致的意见，共识","tip":"con-（共同）+ sens（感觉）+ -us（名词后缀）→ 共同的感觉 → 一致的意见，共识","ex":["There is a growing consensus of opinion on this issue.","对这个问题的看法日趋一致。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"proceed","p":"prəˈsiːd","m":"v.进行，继续下去，前进","tip":"pro-（往前）+ ceed（走）→ 进行，前进","ex":["Work is proceeding slowly.","工作进展缓慢。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"procession","p":"prəˈseʃn","m":"n.队伍，行列","tip":"","ex":["Our procession proceeds to the sun.","我们的队伍向太阳前进。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"troop","p":"truːp","m":"n.军队，士兵 v.列队行进","tip":"troo（音似 true）+ p（联想“趴”）→ 他真的看见一群蚂蚁趴在地上“列队行进”。","ex":["The president decided to send in the troops.","总统决定派驻军队。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"process","p":"ˈprəʊses","m":"n.过程 v.加工","tip":"","ex":["She was involved in the production process.","她参与了生产过程。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"procedure","p":"prəˈsiːdʒə(r)","m":"n.程序，步骤","tip":"proceed（联想 proceed）+ -ure（名词后缀）→ 前进要按“步骤”来。","ex":["The proposal may include the topic, aim, procedure and selection of contestants.","提案可能包括主题、目标、程序和选手的选拔。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"access","p":"ˈækses","m":"v.接近；进入；使用 n.通道，（使用或见到的）机会；权利","tip":"","ex":["They must make efforts to increase women's access to health care.","他们必须努力增加妇女获得医疗服务的机会。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"assess","p":"əˈses","m":"v.评估；估算","tip":"a（—）+ ss（联想两个美女）+ e-（出）+ ss（联想两个美女）→ 出口处的两边各有两个美女在“估算”有多少人进出。","ex":["The trial assessed the effectiveness of an early mathematics intervention aimed at preschoolers.","该试验评估了针对学龄前儿童的早期数学干预的有效性。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"exceed","p":"ɪkˈsiːd","m":"v.超过，胜过","tip":"ex-（出）+ ceed（走）→ 青出于蓝而胜于蓝 → 超过，胜过","ex":["The amount raised has far exceeded our wildest expectations.","筹集的资金远远超出了我们最大的期望。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"beyond","p":"bɪˈjɒnd","m":"prep.超出，在……的那边 adv.在另一边","tip":"Beyond 乐队队名的意思就是“超出”。","ex":["They tend to push themselves beyond the limits of their ability.","他们倾向于把自己逼到能力极限之外。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"surplus","p":"ˈsɜːpləs","m":"n.过剩，盈余 adj.过剩的，多余的","tip":"surp（音似“蛇扑”）+ lu（联想“鹿”）+ s（音似“死”）→ 蛇扑向一头鹿并杀死了它，吃了很久还有剩余 → 过剩","ex":["Wheat was in surplus that year.","那一年小麦过剩。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"extra","p":"ˈekstrə","m":"n.额外的事物 adj.额外的；外加的 adv.特别；额外","tip":"ex-（往外）+ tra（音似“戳”）→ 往外戳，把“额外的”东西赶出去。","ex":["They make extra efforts to research their own products.","他们更加努力地研究自己的产品。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"excess","p":"ɪkˈses","m":"n.超过；过度；超过的量","tip":"exceed v.超过 → excess n. & adj.","ex":["We cover costs up to 600 pounds and then you pay the excess.","我们最多支付 600 英镑的费用，超出的部分由你支付。"],"lesson":"u01-l03","group":"ce 相关"},{"w":"success","p":"səkˈses","m":"n.成功，胜利；成功的人（或事物）","tip":"","ex":["Her way to success was full of pains and frustrations.","她的成功之路充满了痛苦和沮丧。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"succeed","p":"səkˈsiːd","m":"v.成功；继任；随后出现","tip":"","ex":["Immigrant parents believe that academic excellence will allow their children equal chances to succeed in the future.","移民父母认为，优秀的学术成绩将使他们的孩子在未来拥有平等的成功机会。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"successor","p":"səkˈsesə(r)","m":"n.继承者，接任者","tip":"success（成功）+ -or（表示人的后缀）→ 继承成功的人 → 继承者，接任者","ex":["He chose a relative newcomer to the organisation as his successor.","他选择了一个相对新加入这个组织的人作为他的继任者。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"excel","p":"ɪkˈsel","m":"v.擅长；突出；胜过平时","tip":"ex-（外）+ cel（突出）→ 向外突出 → 擅长；另一联想：用 excel 程序做表格，优势很“突出”。","ex":["The team excels at turning defence into attack.","这个队善于打防守反攻。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"stride","p":"straɪd","m":"v.大步走；跨过 n.大步；进展","tip":"单词发音类似“死跩的”→ 他一跩一跩地“大步走”。","ex":["She came striding along to meet me.","她大步走上前来迎接我。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"wander","p":"ˈwɒndə(r)","m":"v.漫游，闲逛","tip":"单词发音类似“万达”→ 周末没事，去万达广场“闲逛”吧。","ex":["No longer have we the inclination to let ourselves wander through fields of knowledges, ready to be surprised.","我们不再倾向于让自己在知识的领域漫游，准备好接受惊喜。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"crawl","p":"krɔːl","m":"v. & n.爬行；缓慢行进","tip":"单词发音类似“可弱”→ 他身体可弱了，走路只能“缓慢行进”。","ex":["A man was crawling away from the burning wreckage.","一个男人正爬离燃烧着的残骸。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"climb","p":"klaɪm","m":"v. & n.爬；攀登","tip":"c（音似“可”）+ li（音似“拉”）+ mb（联想“妹包”）→“爬”山的时候可要拉住妹妹的包，别掉下去。","ex":["A raccoon can climb much higher than a cat.","浣熊能爬得比猫高得多。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"progress","p":"ˈprəʊɡres","m":"n.进步；进展","tip":"pro-（往前）+ gress（走）→ 进步；进展","ex":["But innovation, broadly defined, is the crucial ingredient in all economic progress.","但广义上的创新是所有经济发展的关键因素。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"congress","p":"ˈkɒŋɡres","m":"n.国会，代表大会","tip":"con-（一起）+ gress（走）→ 走到一起来（组成）→ 国会，代表大会","ex":["Congress will vote on the proposals tomorrow.","国会明天将对提案进行投票表决。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"aggressive","p":"əˈɡresɪv","m":"adj.好斗的，侵略的；富于攻击性的；有上进心的","tip":"ag-（= to）+ gress（走）+ -ive（形容词后缀）→ 走向（对方）的 → 好斗的；侵略的","ex":["They tend to be a lot more aggressive than right-handed people.","他们往往比右利手的人更具有攻击性。"],"lesson":"u01-l03","group":"“走”相关"},{"w":"move","p":"muːv","m":"n.行动；改变 v.移动；进步；感动","tip":"","ex":["This is how society moves forward.","这就是社会进步的方式。"],"lesson":"u01-l03","group":"move 相关"},{"w":"motion","p":"ˈməʊʃn","m":"n.运动；移动 v.（以头或手）做动作，示意","tip":"mot（= move）+ -ion（名词后缀）→ 运动；移动","ex":["The shaking is caused by the motion of two plates.","震动是由两个板块的运动引起的。"],"lesson":"u01-l03","group":"move 相关"},{"w":"mobile","p":"ˈməʊbaɪl","m":"adj.可移动的 n.移动电话","tip":"","ex":["Our bombers have knocked out the mobile launchers.","我们的轰炸机已经破坏了那些移动发射台。"],"lesson":"u01-l03","group":"move 相关"},{"w":"static","p":"ˈstætɪk","m":"adj.静止的，静态的；不变化的 n.静电","tip":"sta（联想 stay）+ t（联想“他”）+ -ic（后缀）→ 待在那里的他，仿佛是“静止的”。","ex":["The population of this animal has remained static in recent years.","近年来，这种动物的数量保持不变。"],"lesson":"u01-l03","group":"move 相关"},{"w":"motive","p":"ˈməʊtɪv","m":"n.动机；原因；目的","tip":"他的动机（motive）是想让你行动（move）起来。","ex":["You have drawn hostile conclusions about unseen people and their motives.","你对看不见的人及其动机得出了充满敌意的结论。"],"lesson":"u01-l03","group":"move 相关"},{"w":"motivate","p":"ˈməʊtɪveɪt","m":"v.激发；激励；成为……的动机","tip":"","ex":["Effective measures should be taken to motivate employees to set up offices at home.","应采取有效措施激励员工居家办公。"],"lesson":"u01-l03","group":"move 相关"},{"w":"remove","p":"rɪˈmuːv","m":"v.移开；排除（污渍、不愉快的事物等）；摘下；解除（职务等）","tip":"re-（= off）+ move（移动）→ 移开；排除","ex":["How boundaries can be removed between arts and science disciplines?","如何消除艺术和科学学科之间的界限？"],"lesson":"u01-l03","group":"move 相关"},{"w":"emotion","p":"ɪˈməʊʃn","m":"n.情感；情绪","tip":"e-（出）+ motion（移动）→ 从内心移动（表达）出去 → 内情外露 → 情感；情绪","ex":["Above all, it's the emotions one experiences in teaching that facilitate learning.","最重要的是，人们在教学中体验到的情感促进了学习。"],"lesson":"u01-l03","group":"move 相关"},{"w":"rational","p":"ˈræʃnəl","m":"adj.合理的；理性的；明智的","tip":"他拿比例（ratio）作依据，是很理性的（rational）。","ex":["There is no rational explanation for his actions.","对他的所作所为无法作出合理的解释。"],"lesson":"u01-l03","group":"move 相关"},{"w":"ratio","p":"ˈreɪʃiəʊ","m":"n.比；比率；比例","tip":"单词发音类似人名“瑞秋”→ 瑞秋写文章注重核实“比例”。","ex":["The ratio of the hottest position can arrive at 50 : 1.","最热门职位的（报录）比例可以达到 50 : 1。"],"lesson":"u01-l03","group":"move 相关"},{"w":"rate","p":"reɪt","m":"n.速度；比率；价格 v.评价；被列为","tip":"老鼠（rat）出去以后看到四周无人，逃窜的速度（rate）很快。","ex":["Once you get beyond the initial learning curve, knitting and crocheting can lower heart rate and blood pressure.","一旦你超越了最初的学习曲线，针织和钩编就可以降低心率和血压。"],"lesson":"u01-l03","group":"move 相关"},{"w":"percentage","p":"pəˈsentɪdʒ","m":"n.百分率；百分比；提成","tip":"","ex":["In 1970, the percentage of women majoring in engineering was less than 1%.","1970 年，主修工程学的女性比例不到 1%。"],"lesson":"u01-l03","group":"move 相关"},{"w":"remote","p":"rɪˈməʊt","m":"adj.遥远的；远程的；偏远的","tip":"re-（回）+ mote（= move）→ 往回移动 → 遥远的；远程的","ex":["Your university is selecting some students to teach kids in remote rural areas during the coming vacation.","你们大学正在选拔一些学生，在即将到来的假期去偏远的农村地区教孩子们。"],"lesson":"u01-l03","group":"move 相关"},{"w":"promote","p":"prəˈməʊt","m":"v.促进，提升；促销；推动","tip":"pro-（前）+ mote（= move）→ 往前移动 → 促进，提升","ex":["More universities will be seeking heads with international experience to promote international programs.","更多大学将寻找具有国际经验的负责人来推广国际项目。"],"lesson":"u01-l03","group":"move 相关"},{"w":"action","p":"ˈækʃn","m":"n.行为，行动；功能，作用","tip":"act（音似“爱个她”）+ -ion（名词后缀）→ 既然爱她，就要付出“行动”。","ex":["Watching the agent solve problems allows them to see their knowledge put into action.","观看代理人解决问题，使他们得以见证其知识付诸行动。"],"lesson":"u01-l03","group":"act 相关"},{"w":"deed","p":"diːd","m":"n.行为；行动","tip":"音近词 did → 她的行为（deed）相当于给其他同学做了（did）一个示范。","ex":["The tourists' good deed was not noticed by the locals.","当地人没有注意到游客善意的行为。"],"lesson":"u01-l03","group":"act 相关"},{"w":"behave","p":"bɪˈheɪv","m":"v.表现，举止","tip":"be（是）+ have（持有）→ 一个人的行为会“表现”其原本就拥有的品质。","ex":["They continued to behave as they did in the beginning.","他们继续像一开始那样表现。"],"lesson":"u01-l03","group":"act 相关"},{"w":"active","p":"ˈæktɪv","m":"adj.积极的；忙碌的；活跃的","tip":"act（行动）+ -ive（形容词后缀）→（一直在）行动的 → 积极的；忙碌的；活跃的","ex":["Although he's nearly 80, he is still very active.","尽管快 80 岁了，他还是十分活跃。"],"lesson":"u01-l03","group":"act 相关"},{"w":"react","p":"riˈækt","m":"v.回应，反应","tip":"re-（回）+ act（行动）→ 回应行动 → 回应，反应","ex":["You can't tell how the person on the line is reacting.","你不知道电话里的人作何反应。"],"lesson":"u01-l03","group":"act 相关"},{"w":"exact","p":"ɪɡˈzækt","m":"adj.准确的，精确的；严谨的；确切的 v.要求；迫使","tip":"ex-（出）+ act（行动的结果 → 事实）→ 从事实中得出的 → 准确的，精确的","ex":["He is not familiar with the exact details of the goods.","他不熟悉商品的确切细节。"],"lesson":"u01-l03","group":"act 相关"},{"w":"actual","p":"ˈæktʃuəl","m":"adj.实际的；真正的","tip":"act（事实）+ -ual（形容词后缀）→ 事实的 → 实际的；真正的","ex":["It calls for people's actual action to reduce the waste.","这需要人们采取实际行动减少浪费。"],"lesson":"u01-l03","group":"act 相关"},{"w":"practical","p":"ˈpræktɪkl","m":"adj.实际的；真实的；客观存在的","tip":"practice n.实际行动 → practical adj.","ex":["Taken in a practical way, saving for post-work years is like giving money away to others.","从实际的角度来看，为退休后的生活存钱就像给别人钱一样。"],"lesson":"u01-l03","group":"act 相关"},{"w":"virtual","p":"ˈvɜːtʃuəl","m":"adj.事实上的，实际上的；虚拟的","tip":"单词发音类似“龌龊”→他看起来有点龌龊，事实上很正经→事实上的，实际上的；虚拟的⟨?⟩","ex":["The virtual assistant became so advanced and realistic that the students didn't know she was a computer.","这个虚拟助手变得如此先进和逼真，以至于学生们都不知道它是一台电脑。"],"lesson":"u01-l03","group":"act 相关"},{"w":"fragment","p":"ˈfræɡmənt","m":"n.碎片；片段；部分","tip":"fr（联想“芙蓉”）+ ag（联想“阿哥”）+ -ment（名词后缀）→ 芙蓉（人名）把阿哥赶出了门，阿哥的心仿佛变成了“碎片”。","ex":["Dreaming resembles fragments of science fiction.","梦境类似于科幻小说的片段。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"somewhat","p":"ˈsʌmwɒt","m":"adv.稍微，有点","tip":"","ex":["The situation has changed somewhat since we last met.","自我们上次见面以来情况有点变化。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"fraction","p":"ˈfrækʃn","m":"n.小部分；少量；一点儿","tip":"fr（联想“芙蓉”）+ action（行为）→ 芙蓉的行为只有“小部分”人能接受。","ex":["Only a tiny fraction of Americans change any behaviours in an effort to preserve their privacy.","只有一小部分美国人为了保护自己的隐私而改变了一些行为。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"portion","p":"ˈpɔːʃn","m":"n.部分；一份 v.把……分成若干份（或部分）","tip":"单词发音类似“剖心”→“部分”人喜欢讲“比干剖心”的故事。","ex":["We get a fairly large portion of calories from fast food and snacks.","我们从快餐和零食中摄取了相当大部分的卡路里。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"proportion","p":"prəˈpɔːʃn","m":"n.部分；份额；比例；面积","tip":"pro-（提前）+ portion（音似“剖心”）→ 剖心者少，提前剖心的更少 → 部分","ex":["As is now the case in many big firms, a large proportion of staff are temporary contractors.","现在许多大公司的大部分员工都是临时合同工。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"skeleton","p":"ˈskelɪtn","m":"n.骨骼，梗概；框架","tip":"skele（音似“撕盖了”）+ ton（吨）→ 他撕开了盖子，发现约有一吨“骨骼”。","ex":["The human skeleton consists of 206 bones.","人的骨骼由 206 块骨头组成。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"frame","p":"freɪm","m":"n.框架；结构；体形，身材 v.给……做框；制订","tip":"fr（联想“芙蓉”）+ ame（联想“阿妹”）→ 芙蓉和阿妹的“身材”差不多。","ex":["She leaned against the frame of the door.","她靠在门框上。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"framework","p":"ˈfreɪmwɜːk","m":"n.框架；结构；机制；准则","tip":"frame（框架）+ work（制作品）→ 框架；结构","ex":["Paint the wooden frameworks and walls the same colour.","将木质框架和墙壁涂成同样的颜色。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"flame","p":"fleɪm","m":"n.火焰；鲜红色；强烈的感情 v.燃烧；变红","tip":"","ex":["The room was filled with smoke and flame.","房间里烟雾弥漫，烈焰滚滚。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"burn","p":"bɜːn","m":"v.燃烧；灼伤；激怒","tip":"bu（联想“不”）+ r（形似花）+ n（形似门）→ 不要把干花放在门口，它遇火会“燃烧”，很危险。","ex":["It had burned for 45 minutes by the time firefighters arrived.","消防员赶到时，大火已经燃烧了 45 分钟。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"flash","p":"flæʃ","m":"n.闪光；闪现 v.闪光，闪烁","tip":"网页 Flash 弹窗“闪现”推送广告。","ex":["The car keeps flashing its headlights.","这辆车一直在闪烁前灯。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"flesh","p":"fleʃ","m":"n.肉；果肉","tip":"水果的果肉（flesh）很新鲜（fresh）。","ex":["The flesh of the fruit is white.","这种水果的果肉是白色的。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"fresh","p":"freʃ","m":"adj.新鲜的；清凉的；淡的","tip":"","ex":["The memory of the recent great recession is still fresh in their mind.","他们对最近的大衰退记忆犹新。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"refresh","p":"rɪˈfreʃ","m":"v.使恢复精力；使凉爽；提醒","tip":"re-（回）+ fresh（精力充沛的）→ 使回到精力充沛的状态 → 使恢复精力","ex":["The long sleep had refreshed her.","一场酣睡使她恢复了精神。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"flourish","p":"ˈflʌrɪʃ","m":"v.繁荣；茂盛；兴旺","tip":"flour（音似 flower）+ -ish（动词后缀）→ 洛阳的牡丹花长势“茂盛”。","ex":["The arts began to flourish at that time.","艺术是从那时开始繁荣的。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"flour","p":"ˈflaʊə(r)","m":"n.面粉；粉状物","tip":"花（flower）粉多为粉状物（flour）。","ex":["He shaped delicious masterpieces out of flour, butter and sugar.","他用面粉、黄油和糖塑造出了美味的杰作。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"powder","p":"ˈpaʊdə(r)","m":"n.粉；药粉；火药","tip":"单词发音类似“扑的”→ 她化妆时往脸上扑的是“粉”。","ex":["The snow was like powder.","雪像粉末一样。"],"lesson":"u01-l03","group":"fr 相关"},{"w":"cure","p":"ˈkjʊə(r)","m":"v.治愈；消除；改正 n.疗法；治疗","tip":"正在治疗（cure）疾病的他，深切感受到了父母的关心（care）。","ex":["The doctor managed to cure her of her illness.","医生设法治好了她的病。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"curious","p":"ˈkjʊəriəs","m":"adj.好奇的；奇特的；不寻常的","tip":"cur（= care，关心；注意）+ -(i)ous（形容词后缀）→ （人）对……关心的 → 好奇的 / （物）引人注意的 → 奇特的","ex":["Reading literary fiction, he says, makes us more curious.","他说，阅读文学小说会让我们更加好奇。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"accurate","p":"ˈækjərət","m":"adj.精确的，准确的","tip":"ac-（= to）+ cur（= care）+ -ate（形容词后缀）→ 关心以使做得更精确 → 精确的，准确的","ex":["Global warming is the more accurate term.","全球变暖是更准确的术语。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"secure","p":"sɪˈkjʊə(r)","m":"adj.安心的；安全的；可靠的 v.（尤指经过努力）获得；保护；拴牢；抵押","tip":"se-（离开）+ cure（= care）→ 不用担心 → 安全的；可靠的","ex":["She found it difficult to secure a job in that country.","她发现在那个国家很难找到一份工作。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"rescue","p":"ˈreskjuː","m":"n. & v.营救，救援","tip":"re-（回）+ s（联想“女孩”）+ cue（联想 cute）→ 他要回去“营救”那个可爱的女孩。","ex":["After being rescued from the air crash, the people agreed that they had much to be thankful for.","从空难中获救后，人们认为他们有很多值得感谢的事情。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"injure","p":"ˈɪndʒə(r)","m":"v.损害，伤害；受伤","tip":"单词发音类似“阴招”→ 他不屑用阴招“伤害”别人。","ex":["She was injured in a car accident two weeks ago and still in critical condition.","她在两周前的一次车祸中受伤了，目前仍然危急。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"wound","p":"wuːnd","m":"n.创伤；伤口 v.使受伤","tip":"单词发音类似“捂的”→ 捂着的“伤口”容易发炎。","ex":["But disasters can still wound us.","但灾难仍然会伤害我们。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"harm","p":"hɑːm","m":"n. & v.伤害；损害","tip":"har（音似“吓”）+ m（联想“妹”）→ 吓妹妹容易“伤害”到她。","ex":["He may look fierce, but he means no harm.","他可能看上去很凶，但并无恶意。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"hazard","p":"ˈhæzəd","m":"n.危险，危害 v.冒昧提出","tip":"单词发音类似“害咱的”→ 这种行为会“危害”咱们的健康。","ex":["Growing levels of pollution represent a serious health hazard to the local population.","日益严重的污染对当地人民的健康构成了重大威胁。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"danger","p":"ˈdeɪndʒə(r)","m":"n.危险；可能性；威胁","tip":"dang（联想“挡”）+（g）er（联想“哥”）→ 哥哥开车时，被挡住视线是很“危险”的。","ex":["You may expose yourself to unexpected dangers.","你可能会面临意想不到的危险。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"stake","p":"steɪk","m":"n.桩；风险；股本；利害关系 v.拿……冒险","tip":"s（联想“蛇”）+ take（拿）→ 他拿着蛇玩，“风险”很大。","ex":["In some situations, the stakes are low and failure is a healthy part of growth.","在某些情况下，风险很低，失败是成长中健康的一部分。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"risk","p":"rɪsk","m":"n.危险，冒险行为 v.使遭受危险","tip":"ri（联想“日”）+ sk（音似“死磕”）→ 死磕太阳是有“危险”的行为。","ex":["Dare she risk staying where she was?","她敢冒险待在原地不动吗？"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"gamble","p":"ˈɡæmbl","m":"n.赌博；冒险 v.冒风险；以……为赌注","tip":"gam（联想 game）+ ble（音似 ball）→ 那个涉及“赌博”的游戏跟球有关。","ex":["It was wrong to gamble with our children's future.","拿孩子们的未来冒险是错误的。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"bet","p":"bet","m":"n.打赌；预计 v.下赌注（于）；用……打赌","tip":"be（是）+ t（联想“他”）→ 我“打赌”是他偷了我的钱包。","ex":["I bet you get a lot of requests for it.","我打赌你会为此收到很多请求。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"current","p":"ˈkʌrənt","m":"adj.当前的；通用的；流行的 n.水流；气流；电流；趋向","tip":"cur（联想 care）+ rent（租）→ 我们关心“当前的”租房价格。","ex":["Environmental problems must be solved to ease the current global food shortage.","必须解决环境问题，以缓解目前的全球粮食短缺。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"currency","p":"ˈkʌrənsi","m":"n.通货；货币；通用","tip":"current adj.通用的 → currency n.","ex":["You'll need some cash in local currency.","你将需要一些当地的货币现金。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"rental","p":"ˈrentl","m":"n.租金，租用费；出租；租赁","tip":"rent（租）+ -al（名词后缀）→ 租金；出租","ex":["Telephone charges include line rental.","电话费包括线路租用费。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"lease","p":"liːs","m":"n.租约 v.出租；租用，租借","tip":"单词发音类似“立撕”→ 租期一满，他立刻撕了“租约”。","ex":["They leased the land from a local farmer.","他们从当地一位农场主手中租得这块土地。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"release","p":"rɪˈliːs","m":"n.释放；放开，松开；发行；排放 v.释放；放走","tip":"re（字母音似“阿姨”）+ lease（租约）→ 阿姨租约到期时，“释放”出了房源。","ex":["A private wildlife management company will release the animal into the wild.","一家私人野生动物管理公司将把这只动物放归野外。"],"lesson":"u01-l04","group":"cur/cue 相关"},{"w":"recently","p":"ˈriːsntli","m":"adv.不久前；最近","tip":"re（字母音似“阿姨”）+ cent（分）+ -ly（副词后缀）→ 阿姨“最近”穿得只剩一分钱了。","ex":["These effects can also be observed among people who have recently become unemployed.","这些影响也可以在最近失业的人群中观察到。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"modern","p":"ˈmɒdn","m":"adj.现代的；当代的；时髦的","tip":"单词发音类似“摩登”→ 现代的；时髦的","ex":["High schoolers knew nothing about the modern financial world.","高中生对现代金融世界一无所知。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"era","p":"ˈɪərə","m":"n.时代；年代；纪元","tip":"单词发音类似“饿弱”→ 在那个吃不饱的“年代”，人们饿得很瘦弱。","ex":["In the coming era of budget cuts to education, distance learning could become the norm.","在即将到来的教育预算削减时代，远程学习可能会成为常态。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"up-to-date","p":"ˌʌp tə ˈdeɪt","m":"adj.现代的，最新的；时髦的","tip":"","ex":["Now scientists are bringing this ancient wisdom up-to-date.","如今，科学家们正在将这一古老的智慧推向最新。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"outdated","p":"ˌaʊtˈdeɪtɪd","m":"adj.过时的；陈旧的","tip":"out（外面）+ date（日期）+ -(e)d（形容词后缀）→ 在日期外面的 → 过时的","ex":["It is a somewhat outdated expression.","这是个有点过时的表达方式。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"stale","p":"steɪl","m":"adj.不新鲜的；（空气）污浊的；陈腐的；厌倦的","tip":"s（联想“蛇”）+ tale（故事）→ 美女蛇的故事听多了就厌倦了 → 厌倦的","ex":["You need to do some self-assessment to determine where you have become stale in your thinking.","你需要做一些自我评估，以确定你的思维在哪里变得陈旧。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"fashion","p":"ˈfæʃn","m":"n.时尚，时兴；流行款式","tip":"单词发音类似“范神”→ 他穿衣有范，堪称“时尚”男神。","ex":["They have adapted to meet fashion changes.","他们已经适应了迎合时尚的变化。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"contemporary","p":"kənˈtemprəri","m":"adj.当代的，现代的；同一时代的 n.同龄人","tip":"con-（共同）+ tempor（时代）+ -ary（后缀）→ 同一个时代的 → 同龄人","ex":["It is the concern of contemporary economists.","这是当代经济学家所关注的问题。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"temple","p":"ˈtempl","m":"n.庙，寺；太阳穴；鬓角","tip":"单词发音类似“太破”→ 荒郊野外有一座很破的“庙”。","ex":["We went to temple last Saturday.","我们上个星期六去了寺庙。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"temporary","p":"ˈtemprəri","m":"adj.暂时的，临时的","tip":"tempor（时间）+ -ary（形容词后缀）→ 暂时的，临时的","ex":["Since being laid off, he has worked a series of temporary positions.","自从下岗后，他从事过一系列临时工作。"],"lesson":"u01-l04","group":"“当代”相关"},{"w":"abundant","p":"əˈbʌndənt","m":"adj.大量的；丰盛的；充裕的","tip":"a（一）+ bund（音似“帮的”）+ ant（蚂蚁）→ 像蚂蚁似的一大帮 → 大量的","ex":["Abundant information about cooking is available either online or on TV.","网上或电视上都有大量关于烹饪的信息。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"ample","p":"ˈæmpl","m":"adj.足够的；丰裕的","tip":"这些苹果（apple）对我们来说是足够的（ample）。","ex":["It made ample preparations for various possibilities.","它为各种可能性做了足够的准备工作。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"mass","p":"mæs","m":"n.许多，大量；一群；群众 adj.民众的；大量的","tip":"单词发音类似“慢死”→ 我的马跑得慢死了，“一群”人在后面拍它。","ex":["I began sifting through the mass of evidence.","我开始筛选大量的证据。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"massive","p":"ˈmæsɪv","m":"adj.大量的；大规模的；巨大的；非常严重的","tip":"mass（大量）+ -ive（形容词后缀）→ 大量的","ex":["We derive massive economic benefits when we buy the most affordable energy on the world market.","当我们在世界市场上购买最便宜的能源时，也获得了巨大的经济利益。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"massage","p":"ˈmæsɑːʒ","m":"n.按摩 v.按摩，推拿；美化；虚报","tip":"ma（联想“妈”）+ ssage（音似“杀鸡”）→ 妈妈杀鸡后用调料给鸡做“按摩”。","ex":["Massage helps to improve physical function and reduce stress.","按摩有助于改善身体机能，减轻压力。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"numerous","p":"ˈnjuːmərəs","m":"adj.众多的；许多的","tip":"number n.数字 → numerous adj.","ex":["It has great influence on numerous girls and women.","它对许多女孩和妇女产生了巨大的影响。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"multiply","p":"ˈmʌltɪplaɪ","m":"v.乘；成倍增加；（使）繁殖","tip":"multi-（许多的）+ ply（层）→ 许多层叠在一起 → 成倍增加","ex":["It revealed the secret of how bacteria multiply in cream and butter.","它揭示了细菌如何在奶油和黄油中繁殖的秘密。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"gang","p":"ɡæŋ","m":"n.一帮，一伙","tip":"单词发音类似“干”→ 那是“一帮”干大事的人。","ex":["I went out with the usual gang from college on Friday night.","星期五晚上，我和大学的一帮老朋友一起出去了。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"band","p":"bænd","m":"n.流行音乐乐队；一伙，一群；带；条纹","tip":"单词发音类似“帮的”→ 那“一群”在台上帮忙唱歌的人来自那个“流行音乐乐队”。","ex":["The watch comes equipped with a standard battery and a nylon band.","这款手表配有标准电池和尼龙表带。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"bandage","p":"ˈbændɪdʒ","m":"n.绷带 v.用绷带包扎","tip":"band（带）+ -age（后缀）→ 绷带","ex":["Please pass me the bandage.","请把绷带递给我。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"sort","p":"sɔːt","m":"n.种类 v.把……分类，整理","tip":"单词发音类似“扫它”→ 清扫垃圾的时候顺便将其分类 → 把……分类","ex":["This sort of problem is quite common.","这类问题相当普遍。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"resort","p":"rɪˈzɔːt","m":"n.采取，求助；（度假）胜地 v.（～to）求助于；采取","tip":"re（字母音似“阿姨”）+ sort（把……分类）→ 阿姨为了快速把豆子分类，“求助于”我们。","ex":["They resort to different means to survive the bitter cold.","他们采取了不同的手段来度过严寒。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"flock","p":"flɒk","m":"n.（羊或鸟）群 v.群集","tip":"单词发音类似“妇唠嗑”→ 树上一“群”鸟叽叽喳喳叫着，树下妇人们在唠嗑。","ex":["These birds fly in huge flocks.","这些鸟成群结队地飞行。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"crowd","p":"kraʊd","m":"n.人群；观众；一伙人 v.使……拥挤；靠近","tip":"c（音似“可”）+ row（排）+ d（音似“的”）→ 一排一排的人可多了 → 人群；使……拥挤","ex":["There will be crowds of people waiting for her.","会有很多人在等她。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"dozen","p":"ˈdʌzn","m":"n.（一）打；十二个","tip":"单词发音类似“打人”→ 叶问一个人能打“十二个”人。","ex":["A freshman textbook will have dozens of contributors.","一本新生教材将有几十名撰稿人。"],"lesson":"u01-l04","group":"“大量”相关"},{"w":"population","p":"ˌpɒpjuˈleɪʃn","m":"n.（地区、国家等的）人口；某领域的生物；族群","tip":"","ex":["Its population is now showing signs of increase.","它的人口现在正呈现增长的迹象。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"popularity","p":"ˌpɒpjuˈlærəti","m":"n.受欢迎；普及；流行","tip":"","ex":["Even the old metal lunch boxes have regained popularity.","甚至老式全金属饭盒也重新流行起来。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"prevail","p":"prɪˈveɪl","m":"v.普遍存在；盛行；被接受；战胜","tip":"pre-（在……之前）+ vail（力量，强大）→ 盛行","ex":["There's an ancient legend that as long as these eggs are made, evil will not prevail in the world.","有一个古老的传说，只要这些蛋被制作出来，邪恶就不会在世上盛行。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"available","p":"əˈveɪləbl","m":"adj.可获得的；可找到的；有空的","tip":"","ex":["I want my students to search out the answers to questions by using all the resources available to them.","我希望我的学生利用所有可用的资源去寻找问题的答案。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"crew","p":"kruː","m":"n.全体船员；一群工作人员","tip":"单词发音类似“可入”→ 遇到危险时，“全体船员”可以进入救生艇。","ex":["He joined the crew of a large fishing boat.","他加入一艘大型渔船船员的行列。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"screw","p":"skruː","m":"n.螺丝 v.用螺丝固定，拧紧","tip":"单词发音类似“四可入”→ 这是四个可以拧入孔内的“螺丝”。","ex":["She carefully screwed the cap back onto the toothpaste.","她小心地把牙膏盖子拧回去。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"colleague","p":"ˈkɒliːɡ","m":"n.同事，同僚","tip":"他们是在同一所大学（college）教学的同事（colleague）。","ex":["They feel pressured to keep up with female colleagues.","要跟上女同事的步伐，他们感到有压力。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"personnel","p":"ˌpɜːsəˈnel","m":"n.全体人员，职员；人事部门","tip":"","ex":["She works in personnel.","她在人事部门工作。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"staff","p":"stɑːf","m":"n.全体职员","tip":"单词发音类似“士大夫”→ 古代士大夫相当于皇帝的职员 → 全体职员","ex":["The letter is in fairly good condition, in spite of being out of the care of trained museum staff for so long.","这封信虽然长期没有受到训练有素的博物馆员工的维护，但其状况相当好。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"stuff","p":"stʌf","m":"n.东西，物品 v.把……塞进，填进","tip":"一个谨言慎行的（a 像闭口而立）员工（staff）拿着装满物品（stuff）的桶（u）。","ex":["If you want the good stuff, the quality, you have to see it for yourself.","如果你想要好的东西、高品质的东西，你必须自己去看。"],"lesson":"u01-l04","group":"“人群”相关"},{"w":"infant","p":"ˈɪnfənt","m":"n.婴儿；幼儿","tip":"in（里面）+ fant（音似“粉的”）→“婴儿”衣服里面的皮肤粉粉嫩嫩的。","ex":["Hundreds of studies show that infants prefer novelty.","数百项研究表明，婴儿更喜欢新鲜事物。"],"lesson":"u01-l04","group":"“成长阶段”相关"},{"w":"adolescent","p":"ˌædəˈlesnt","m":"n.青少年","tip":"ado（音似 idle）+ lescen（音似 lesson）+ t（联想“头”）→ 那个懒惰的“青少年”一上课就觉得头疼。","ex":["In one recent study, we examined 360 adolescents' beliefs about the nature of \"smartness\".","在最近的一项研究中，我们调查了 360 名青少年对“聪明”本质的看法。"],"lesson":"u01-l04","group":"“成长阶段”相关"},{"w":"idle","p":"ˈaɪdl","m":"v.虚度；闲荡 adj.懒惰的；无所事事的；闲散的","tip":"单词发音类似“爱逗”→ 爱逗狗的人大多是“无所事事的”。","ex":["He never stayed idle for long.","他闲散的时间从来不长。"],"lesson":"u01-l04","group":"“成长阶段”相关"},{"w":"youngster","p":"ˈjʌŋstə(r)","m":"n.年轻人；少年；儿童","tip":"","ex":["The camp is for youngsters aged 8 to 14.","这个度假营是针对 8 至 14 岁的少年儿童的。"],"lesson":"u01-l04","group":"“成长阶段”相关"},{"w":"elder","p":"ˈeldə(r)","m":"adj.年纪较长的 n.长者；长辈","tip":"","ex":["Lawyers can specialise in \"elder law\".","律师可以专攻“老年法”。"],"lesson":"u01-l04","group":"“成长阶段”相关"},{"w":"immigrate","p":"ˈɪmɪɡreɪt","m":"v.（从外地）移居；移民","tip":"immi（音似“移民”）+ grate（音似 great）→ 他说“移民”到中国后的生活很好。","ex":["Her parents immigrated to America.","她的父母移民到了美国。"],"lesson":"u01-l04","group":"“移民”相关"},{"w":"emigrate","p":"ˈemɪɡreɪt","m":"v.移居国外；移民","tip":"emi（音似“移民”）+ grate（音似 great）→ 即使“移居国外”后过得很好，他也没忘了自己的祖籍。","ex":["Immigrant parents could talk about their country of origin and why they emigrated to the United States.","移民父母可以谈论他们的原籍国以及他们为什么移民到美国。"],"lesson":"u01-l04","group":"“移民”相关"},{"w":"migrate","p":"maɪˈɡreɪt","m":"v.（随季节变化）迁徙；移动","tip":"","ex":["Most of the colored people migrated there at the turn of the 20th century.","大多数有色人种在 20 世纪之交移民到那里。"],"lesson":"u01-l04","group":"“移民”相关"},{"w":"surname","p":"ˈsɜːneɪm","m":"n.姓","tip":"sur-（上面）+ name（名字）→ 在名字上面的 → 家族名 → 姓","ex":["The full name of China's Han ethnic group is composed of surname and given name.","中国汉族人的全名由姓和名组成。"],"lesson":"u01-l04","group":"“移民”相关"},{"w":"namely","p":"ˈneɪmli","m":"adv.即；也就是","tip":"","ex":["In the past, electric vehicles had their problems, namely, a limited driving range.","在过去，电动汽车也有它们存在的问题，即驾驶范围有限。"],"lesson":"u01-l04","group":"“移民”相关"},{"w":"ambition","p":"æmˈbɪʃn","m":"n.野心；雄心；志向","tip":"单词发音类似“俺必胜”→ 野心；雄心；志向","ex":["In fact, in some cases, extreme ambition may end up doing more harm than good.","事实上，在某些情况下，极端的野心最终可能弊大于利。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"accomplish","p":"əˈkʌmplɪʃ","m":"v.完成；达到；实现","tip":"ac-（一再地）+ complish（音似“看破历史”）→ 当你完全看透历史的时候，你的人生就“达到”了一个新的境界。","ex":["Curiosity is one of the tools humans have found to accomplish that gigantic task.","好奇心是人类发现的完成那项艰巨任务的工具之一。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"achieve","p":"əˈtʃiːv","m":"v.达到；实现；成功","tip":"a（一）+ chieve（音似“妻屋”）→ 古代有些人认为，“成功”就是有一妻、一屋。","ex":["It is bound to help us achieve greater success.","它必将帮助我们取得更大的成功。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"fulfill","p":"fʊlˈfɪl","m":"v.实现，履行","tip":"","ex":["They think it more urgent to fulfil their social obligations.","他们认为履行社会责任更加紧迫。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"full","p":"fʊl","m":"adj.充满的；大量的；饱的；完全的","tip":"fu（音似“服”）+ ll（形似两根大油条）→ 服务员吃了两根大油条，所以是“饱的”。","ex":["My suitcase was full of books.","我的手提箱装满了书。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"fill","p":"fɪl","m":"v.（使）充满；满足 n.填满……的量","tip":"","ex":["Factories are being digitalised, filled with new sensors and new computers to make them quicker.","工厂正在被数字化，充满了新的传感器和新的计算机，以加快生产速度。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"content","p":"ˈkɒntent","m":"adj.满意的 v.使满意","tip":"con-（所有的）+ tent（帐篷）→ 所有的帐篷都是令人“满意的”。","ex":["Leah easily could have fallen into a trap of feeling content.","利亚很容易陷入满足感的陷阱。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"satisfy","p":"ˈsætɪsfaɪ","m":"v.使满意；使满足","tip":"单词发音类似“塞万提斯”→ 西班牙小说家“塞万提斯”的作品使读者满意 → 使满意","ex":["The office maintained a well-stocked kitchen that would satisfy my every snack desire.","办公室里有一个储备充足的厨房，可以满足我对零食的每一种渴望。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"empty","p":"ˈempti","m":"adj.空的；空虚的 v.使变空","tip":"em（联想“俺妹”）+ pt（联想“扑腾”）+ -y（后缀）→ 俺妹在一个“空的”床上扑腾。","ex":["It gets one into the habit of making empty promises.","这会让人养成许下空头承诺的习惯。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"realistic","p":"ˌriːəˈlɪstɪk","m":"adj.现实的；实际的；明智的；逼真的","tip":"real（真的）+ -istic（形容词后缀）→ 现实的；实际的","ex":["You should try to restrain your ambition and be more realistic.","你应该努力抑制你的野心，而且要更现实一些。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"realise","p":"ˈriːəlaɪz","m":"v.实现；理解，意识到","tip":"","ex":["I came to realise online classes were merely a means to fulfil course requirements.","我开始意识到网络课程仅仅是满足课程要求的一种手段。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"realm","p":"relm","m":"n.领域，场所；王国","tip":"real（真的）+ m（联想 man）→ 真正的男人会在某个“领域”做出成绩。","ex":["The precise function of sleep remains largely in the realm of assumption.","睡眠的确切功能在很大程度上仍属于假设的领域。"],"lesson":"u02-l01","group":"“梦想实现”相关"},{"w":"stack","p":"stæk","m":"v.（使）整齐地堆起 n.一堆","tip":"st（联想 street）+ a（一）+ ck（联想 CK 品牌）→ 街上有“一堆”CK 品牌的衣服。","ex":["A stack of files awaited me on my desk.","我桌上有一堆文件正待我去处理。"],"lesson":"u02-l01","group":"“堆、积”相关"},{"w":"pile","p":"paɪl","m":"n.一堆，一叠 v.堆起，堆积","tip":"单词发音类似“怕了”→ 看到那一堆待处理的文件，我都怕了。","ex":["I found it in a pile of documents on his desk.","我在他桌子上的一堆文件中找到了它。"],"lesson":"u02-l01","group":"“堆、积”相关"},{"w":"accumulate","p":"əˈkjuːmjəleɪt","m":"v.积累；堆积","tip":"ac-（表加强）+ cumu（音似“可莫”）+ late（晚）→ 考试可莫准备晚了，要早“积累”词汇。","ex":["His goal was to accumulate wealth.","他的目标是积累财富。"],"lesson":"u02-l01","group":"“堆、积”相关"},{"w":"calculate","p":"ˈkælkjuleɪt","m":"v.计算；估计；推测","tip":"calcu（音似“开可”）+ late（晚）→ 电脑开得可晚了，因为他“计算”错时间了。","ex":["Restaurants should calculate the tips for customers.","餐馆应该为顾客计算小费。"],"lesson":"u02-l01","group":"“堆、积”相关"},{"w":"calendar","p":"ˈkælɪndə(r)","m":"n.日历；历法","tip":"日历（calendar）就是用来计算（calculate）日期的。","ex":["Chinese New Year is one of the most celebrated holidays on the Chinese calendar.","中国新年是中国历法中最受欢迎的节日之一。"],"lesson":"u02-l01","group":"“堆、积”相关"},{"w":"deem","p":"diːm","m":"v.认为；视为；相信","tip":"dee（音似“弟”）+ m（联想“妹”）→ 弟弟妹妹都把我“视为”最值得“相信”的亲人。","ex":["They deem these exercises counter-productive.","他们认为这些练习适得其反。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"assume","p":"əˈsjuːm","m":"v.假设；认为；承担（责任）","tip":"as-（一再地）+ su（联想“诉”）+ me（我）→ 他一再地向我诉苦，想让我帮他“承担责任”。","ex":["Sleep may be more important than people assumed.","睡眠可能比人们想象的更重要。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"resume","p":"rɪˈzjuːm","m":"v.重新开始；（中断后）继续","tip":"re（字母音似“阿姨”）+ su（联想“诉”）+ me（我）→ 阿姨告诉我要准备一份简历，“重新开始”找工作。","ex":["She resumed her career after an interval of six years.","时隔六年之后她又开始了自己的职业生涯。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"consume","p":"kənˈsjuːm","m":"v.消耗；消费；吃；喝","tip":"con-（都）+ su（联想“诉”）+ me（我）→ 大家都告诉我要多“消耗”一下体力。","ex":["More affluent and educated people tend to consume higher quality diets.","更富裕和受教育程度更高的人倾向于食用更高质量的饮食。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"consumer","p":"kənˈsjuːmə(r)","m":"n.消费者","tip":"","ex":["That was great for the consumer, not so much for the manufacturer.","那对消费者来说很好，对制造商来说则不然。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"custom","p":"ˈkʌstəm","m":"n.风俗，传统，习俗；光顾，惠顾","tip":"单词发音类似“卡死它们”→ 货物进出海关要缴税，这是“传统”；而走私的货物，海关会卡死它们。","ex":["She grew up with Chinese customs and traditions.","她在中国的习俗和传统中长大。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"traditional","p":"trəˈdɪʃənl","m":"adj.传统的；习俗的；惯例的","tip":"tradition（音似“戳地心”）+ -al（形容词后缀）→ “传统的”农业社会中，农民靠戳地心（种地）生存。","ex":["Moreover, schools should be more than simple institutions of traditional learning.","此外，学校不应该是简单的传统学习机构。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"convention","p":"kənˈvenʃn","m":"n.惯例；习俗；公约；大会","tip":"con-（所有的）+ vention（音似“文身”）→ 此地的“习俗”是所有人都文身。","ex":["It is important to distinguish between the rules of grammar and the conventions of written language.","区分语法规则和书面语言的惯例很重要。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"customer","p":"ˈkʌstəmə(r)","m":"n.顾客","tip":"custom n.光顾 → customer n.","ex":["Some hired flag wavers to direct customers to empty parking spaces.","一些（公司）雇用挥舞旗帜的人引导顾客去空置的停车位。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"client","p":"ˈklaɪənt","m":"n.客户；委托人","tip":"clien（音似“可来了”）+ t（联想“他”）→ 傍晚时，我等的“客户”可（终于）来了。","ex":["He inquired about his client's family background.","他询问了客户的家庭背景。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"agent","p":"ˈeɪdʒənt","m":"n.代理人，经纪人","tip":"a-（一）+ gent（联想 gentleman）→ 有一个绅士是我们的“代理人”。","ex":["The agents were able to utilise their full potential and experience.","代理人能够充分利用他们的潜力和经验。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"agency","p":"ˈeɪdʒənsi","m":"n.服务机构；（尤指）代理机构；（政府的）专门机构","tip":"","ex":["Within 10 minutes, I had impressed the interviewer enough to be offered a job with the agency.","不到 10 分钟，我就给面试官留下了深刻的印象，得到了该机构的工作机会。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"deputy","p":"ˈdepjuti","m":"n.副手；代理；警官","tip":"de-（往下）+ put（放）+ -y（名词后缀）→ 老板要把部分工作下放给“副手”去做。","ex":["Deputy chiefs may be more willing to make the jump without a net.","副局长们可能更愿意裸辞。"],"lesson":"u02-l01","group":"“认为”相关"},{"w":"inhabit","p":"ɪnˈhæbɪt","m":"v.栖居于；居住于","tip":"in（里面）+ habit（习惯）→ 习惯在里面居住 → 栖居于；居住于","ex":["Blocks of flats built in the past there were mostly inhabited by people who did not earn much.","那里过去建造的公寓楼大多住着收入不高的人。"],"lesson":"u02-l01","group":"“居住”相关"},{"w":"habitat","p":"ˈhæbɪtæt","m":"n.（动植物的）栖息地；居住地","tip":"habit（习惯）+ at（在）→ “栖息地”是动物习惯在那里生活的地方。","ex":["The natural habitat of wildlife there would be ruined.","那里的野生动物自然栖息地会遭到破坏。"],"lesson":"u02-l01","group":"“居住”相关"},{"w":"reside","p":"rɪˈzaɪd","m":"v.居住在；定居于","tip":"re（字母音似“阿姨”）+ side（面）→ 阿姨“居住在”我家的另一面。","ex":["They reside in our minds, shaping our thoughts.","它们存在于我们的头脑中，塑造着我们的想法。"],"lesson":"u02-l01","group":"“居住”相关"},{"w":"living","p":"ˈlɪvɪŋ","m":"adj.活着的 n.生计；谋生；收入","tip":"","ex":["Numerous professional drivers would have to find new ways of earning a living.","许多职业司机必须找到新的谋生方式。"],"lesson":"u02-l01","group":"“居住”相关"},{"w":"alive","p":"əˈlaɪv","m":"adj.活着的；继续存在的","tip":"","ex":["It remains alive among the majority of American people.","它在大多数美国人中仍然存在。"],"lesson":"u02-l01","group":"“居住”相关"},{"w":"alarm","p":"əˈlɑːm","m":"v.使不安，使恐慌 n.惊恐；忧虑；警报","tip":"a（一）+ larm（音似“辣妹”）→ 他一见到辣妹，就局促“不安”。","ex":["It alarms me that nobody takes this problem seriously.","谁都不认真对待这个问题，我非常不安。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"fear","p":"fɪə(r)","m":"n.恐惧，害怕 v.害怕，畏惧；为……担心","tip":"单词发音类似“飞蛾”→ 有的人看见飞蛾会“害怕”。","ex":["The daughter feared her mother would be ignored there.","女儿害怕她的母亲在那里会被忽视。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"fierce","p":"fɪəs","m":"adj.凶猛的；狂热的；猛烈的；强烈的","tip":"单词发音类似“飞蛾死”→ 飞蛾扑火而死的时候是很“狂热的”。","ex":["It launched a fierce attack against that state.","它对那个国家发动了猛烈的攻击。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"threat","p":"θret","m":"n.恐吓，威胁；凶兆","tip":"threa（联想 throw）+ t（联想“他”）→ 她向坏人扔石头“威胁”他。","ex":["There are growing concerns that robots could become a threat.","人们越来越担心机器人可能成为威胁。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"frighten","p":"ˈfraɪtn","m":"v.使惊吓，使惊恐；威胁","tip":"你用花打（fight）她，使她受了惊吓（frighten）。","ex":["The editor is frightened by this news.","编辑被这个消息吓坏了。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"panic","p":"ˈpænɪk","m":"n.惊恐，恐慌 v.（使）惊慌，惊慌失措","tip":"单词发音类似“怕你磕”→ 小时候你一摔倒，父母就会“惊慌”，怕你磕坏哪里。","ex":["They are spreading panic in the soda industry.","他们正在苏打水行业散布恐慌。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"uneasy","p":"ʌnˈiːzi","m":"adj.心神不安的，焦虑的，不安的；担心的","tip":"un-（不）+ easy（容易 → 舒适）→ 你在做不容易的事情时，一定是“不安的”。","ex":["But across society, the abstraction of the idea of cash makes me uneasy.","但在整个社会中，现金概念的抽象化让我感到不安。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"ease","p":"iːz","m":"n.舒适，轻松 v.减轻，缓和","tip":"easy adj.容易的；舒适的 → ease n.& v.","ex":["He doesn't feel at ease in the firm.","他在公司里感到不舒适。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"disease","p":"dɪˈziːz","m":"n.疾病；弊端","tip":"dis-（不）+ ease（舒适）→ 疾病","ex":["Overuse of electronic devices may cause heart disease.","过度使用电子设备可能会导致心脏病。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"anxious","p":"ˈæŋkʃəs","m":"adj.忧虑的，焦虑的；渴望的","tip":"单词发音类似“俺可笑死”→ 俺都笑死了，因为俺一点也不焦虑 → 焦虑的","ex":["The girl appeared anxious, had lost weight and was not sleeping well.","那个女孩显得很焦虑，体重降了，觉也睡不好。"],"lesson":"u02-l01","group":"“惊恐不安”相关"},{"w":"sign","p":"saɪn","m":"n.迹象；标志；手势 v.签（名）；签字；签约；示意","tip":"sig（联想“四个”）+ n（形似门）→ 这四个门上都有“标志”。","ex":["That's the first sign to them that life is starting to return to normal.","对他们来说，那是生活开始回归正常的第一个迹象。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"token","p":"ˈtəʊkən","m":"n.标志；代金券 adj.象征性的；装模作样的","tip":"我带了（taken）有身份标志（token）的号码牌参赛。","ex":["Please accept this small gift as a token of our gratitude.","区区薄礼，以表谢忱，敬请笑纳。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"signature","p":"ˈsɪɡnətʃə(r)","m":"n.署名；签字","tip":"sign v.签（名）；签字 → signature n.","ex":["Someone had forged her signature on the cheque.","有人在支票上伪造了她的签名。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"signal","p":"ˈsɪɡnəl","m":"n.信号；标志 v.发信号；表明","tip":"","ex":["He thought he had heard the referee's signal to proceed.","他认为他听到了裁判发出的继续进行的信号。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"assign","p":"əˈsaɪn","m":"v.分配（某物）；指派；委派","tip":"as-（= to）+ sign（签字；示意）→ 分配；指派；委派","ex":["In her study, participants were randomly assigned to two groups.","在她的研究中，参与者被随机分配到两组。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"design","p":"dɪˈzaɪn","m":"v.设计；制造 n.设计；图案","tip":"de（音似“弟”）+ sign（签名）→ 弟弟的签名是经过“设计”的。","ex":["She is well informed about the design business.","她对设计行业了如指掌。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"despatch","p":"dɪˈspætʃ","m":"v.发送；派遣，发运 n.派遣；发送；急件","tip":"de-（往下）+ s（音似“饲”）+ patch（音似“派吃”）→ 派人往下给饲养的动物“发送”吃的。","ex":["He feels we should act with despatch.","他觉得我们应该迅速行动。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"resign","p":"rɪˈzaɪn","m":"v.辞职；辞去（某职务）","tip":"re-（离开）+ sign（签字；示意）→ 签字离开；示意离开 → 辞职","ex":["The following year, things got worse and he was forced to resign.","第二年，情况变得更糟，他被迫辞职。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"quit","p":"kwɪt","m":"v.离开；停止做；离职","tip":"单词发音类似“快他”→ 你催他快点“离开”。","ex":["If they don't get more money they'll quit.","不给他们加薪他们就要辞职。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"significant","p":"sɪɡˈnɪfɪkənt","m":"adj.有重大意义的，重要的；显著的","tip":"sig（联想 sign）+ nifi（音似“你非”）+ cant → 你非要对“重要的”事情做标记，这是正确的。","ex":["It witnessed a significant increase in women engineers in the 1970s.","20 世纪 70 年代，女性工程师的数量大幅增加。"],"lesson":"u02-l02","group":"sign 相关"},{"w":"essential","p":"ɪˈsenʃl","m":"n.必需品；要素 adj.必不可少的；重要的；本质的","tip":"essence n.本质；精华 → essential n. & adj.","ex":["They cannot measure the essentials of effective written communication.","他们无法衡量有效书面沟通的要素。"],"lesson":"u02-l02","group":"“必须”相关"},{"w":"indispensable","p":"ˌɪndɪˈspensəbl","m":"adj.不可或缺的；必不可少的","tip":"in-（不）+ dis-（不→没有）+ pens（钢笔）+ able（能够）→ 不能够没有钢笔的 → 不可或缺的；必不可少的","ex":["Higher education is indispensable if you want to go far in both your studies and life.","如果你想在学习和生活中走得更远，高等教育是必不可少的。"],"lesson":"u02-l02","group":"“必须”相关"},{"w":"necessary","p":"ˈnesəsəri","m":"adj.必需的；必要的；必然的","tip":"","ex":["Fast technological change makes it necessary for one to constantly upgrade their skills.","快速的技术变革使人们有必要不断地提高自己的技能。"],"lesson":"u02-l02","group":"“必须”相关"},{"w":"necessity","p":"nəˈsesəti","m":"n.必要；必然性；必需品","tip":"necessary adj.必需的；必要的 → necessity n.","ex":["We recognize the necessity for a written agreement.","我们认为有必要签订一份书面协议。"],"lesson":"u02-l02","group":"“必须”相关"},{"w":"inevitable","p":"ɪnˈevɪtəbl","m":"adj.不可避免的；不能防止的","tip":"in-（不）+ evi（音似“俺为”）+ table（桌子）→ 俺为了买桌子转遍了商场，劳累是“不可避免的”。","ex":["Remember, failure is inevitable, and every failure you survive is a learning experience.","记住，失败是不可避免的，你经历的每一次失败都是一次学习的体验。"],"lesson":"u02-l02","group":"“必须”相关"},{"w":"avoid","p":"əˈvɔɪd","m":"v.避免；回避","tip":"a-（一再地）+ voi（音似“我”）+ d（联想“的”）→ 我一再地“回避”他的眼神。","ex":["It helps us avoid making mistakes.","它有助于我们避免犯错。"],"lesson":"u02-l02","group":"“必须”相关"},{"w":"appoint","p":"əˈpɔɪnt","m":"v.任命；安排；分配；指派","tip":"ap-（= to，给）+ point（指）→ 指派给 → 任命；安排；分配；指派","ex":["Last year Britain even appointed a minister for loneliness.","去年，英国甚至任命了一位孤独部长。"],"lesson":"u02-l02","group":"“适应”相关"},{"w":"disappoint","p":"ˌdɪsəˈpɔɪnt","m":"v.使失望；使破灭","tip":"dis-（不）+ appoint（指派）→ 不被（领导）指派 → 使失望","ex":["I hate to disappoint you, but I'm just not interested.","我不想使你扫兴，但我确实不感兴趣。"],"lesson":"u02-l02","group":"“适应”相关"},{"w":"accommodate","p":"əˈkɒmədeɪt","m":"v.为（某人）提供住宿（或膳宿、座位等）；适应；容纳","tip":"ac-（一再地）+ commo（联想 come）+ date（约会）→ 我经常来和朋友约会，朋友为我提供住宿 → 为（某人）提供住宿","ex":["They are given to accommodate students' needs.","它们是为了满足学生的需求而提供的。"],"lesson":"u02-l02","group":"“适应”相关"},{"w":"adapt","p":"əˈdæpt","m":"v.（使）适应；使适合","tip":"ad-（= to，到）+ apt（适合的）→ 使适应；使适合","ex":["They have difficulty adapting to climate change.","他们很难适应气候变化。"],"lesson":"u02-l02","group":"“适应”相关"},{"w":"adopt","p":"əˈdɒpt","m":"v.收养；采纳；接受","tip":"a（一）+ d（联想“地”）+ o（形似洞口）+ pt → 他在一个地洞口发现了一个小孩，“采纳”了家族的意见，“收养”了他。","ex":["A bride will in most cases adopt a name that combines the couple's last names.","在大多数情况下，新娘会采用一个结合夫妻姓氏的名字。"],"lesson":"u02-l02","group":"“适应”相关"},{"w":"amuse","p":"əˈmjuːz","m":"v.娱乐；逗乐","tip":"a-（表加强）+ muse（音似“缪斯”）→ 缪斯是希腊神话中主管艺术与科学的神 → 娱乐","ex":["At yesterday's party, Elizabeth's boyfriend amused us by imitating Charlie Chaplin.","在昨天的聚会上，伊丽莎白的男朋友模仿查理·卓别林逗我们开心。"],"lesson":"u02-l02","group":"“娱乐”相关"},{"w":"amaze","p":"əˈmeɪz","m":"v.使吃惊；使惊讶","tip":"单词发音类似“啊妹子”→ 啊，妹子上大学后变化好大啊 → 使惊讶","ex":["He spoke perfect Korean—I was really amazed.","他韩语说得很好——我真的很惊讶。"],"lesson":"u02-l02","group":"“娱乐”相关"},{"w":"startle","p":"ˈstɑːtl","m":"v.使惊吓；使吓一跳","tip":"start（开始）+ le（联想“了”）→ 他刚到学校，老师就说考试马上就开始了，使他吓了一跳 → 使惊吓；使吓一跳","ex":["The sound of the explosion startled me.","爆炸声把我吓了一跳。"],"lesson":"u02-l02","group":"“娱乐”相关"},{"w":"leisure","p":"ˈleʒə","m":"n.空闲，闲暇","tip":"lei（联想“累”）+ sure（的确）→ 你的确累了的话，就找个“空闲”放松一下。","ex":["They greatly enrich people's leisure life.","它们极大地丰富了人们的休闲生活。"],"lesson":"u02-l02","group":"“娱乐”相关"},{"w":"pastime","p":"ˈpɑːstaɪm","m":"n.消遣；休闲活动","tip":"pas(t)（过去）+ time（时间）→ 让时间过去的活动 → 消遣；休闲活动","ex":["By nature, Americans are enthusiastic and energetic about hobbies or pastimes.","美国人天生对爱好和休闲活动充满热情和活力。"],"lesson":"u02-l02","group":"“娱乐”相关"},{"w":"recreation","p":"ˌrekriˈeɪʃn","m":"n.娱乐，消遣","tip":"re-（重复）+ creat(e)（创造）+ -ion（名词后缀）→ “娱乐”可以使人重新焕发创造力。","ex":["But the club also acts as a recreation center and safe haven for teenagers, with video games readily available.","但俱乐部同时也是青少年的娱乐中心和避风港，（在那里）他们随时可以玩电子游戏。"],"lesson":"u02-l02","group":"“娱乐”相关"},{"w":"arbitrary","p":"ˈɑːbɪtrəri","m":"adj.武断的，任意的，随心所欲的；专横的","tip":"单词发音类似“啊，别吹”→ 啊，别吹牛了，你说在家很专横，我可不信 → 专横的","ex":["The choice of players for the team seemed arbitrary.","看来这个队的队员是随意选定的"],"lesson":"u02-l02","group":"“娱乐”相关"},{"w":"alter","p":"ˈɔːltə(r)","m":"v.改变，改动","tip":"al（联想 all）+ ter（音似“特”）→ 所有的都进行了特别的“改动”。","ex":["His actions that day altered my perception of him.","他那天的行为改变了我对他的看法。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"alternative","p":"ɔːlˈtɜːnətɪv","m":"n.可供选择的事物 adj.可供选择的；备选的；另类的","tip":"","ex":["When I apologise, I usually choose in-person first, or a phone conversation as my top alternative, and maybe a handwritten note next.","当我道歉时，我通常会首选面对面或电话交谈，其次可能是手写便条。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"shift","p":"ʃɪft","m":"v.转移；改变 n.转变；轮班","tip":"单词发音类似“洗福特”→ 洗那辆福特车要“改变”下位置。","ex":["That doesn't control the cost of education; it just shifts it to taxpayers.","那不能控制教育的成本；它只是把它转移给了纳税人。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"swift","p":"swɪft","m":"adj.快速的，敏捷的；迅即发生的","tip":"单词发音类似“四维福特”→ 那辆四维福特的运动是“快速的”。","ex":["Thank you for your swift reply.","感谢您的迅速回复。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"switch","p":"swɪtʃ","m":"n.开关；转变 v.转变；调换","tip":"s（联想“蛇”）+ witch（巫婆）→ 蛇“转变”成了巫婆，被“开关”电死了。","ex":["Leah shed the safety of her accounting job and made the switch complete.","利亚毅然放弃了安稳的会计工作，彻底完成了职业转型。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"plug","p":"plʌɡ","m":"v.把……塞住；推广 n.插头；塞子","tip":"单词发音类似“扑拉哥”→ 妈妈扑过去拉住哥哥，阻止他摸“插头”。","ex":["He plugged the hole in the pipe with an old rag.","他用一块旧布把管子上的那个洞塞住了。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"vary","p":"ˈveəri","m":"v.改变；变化；使多样化；不同","tip":"通过努力学习，你的改变（vary）非常（very）大。","ex":["Students' test-form preferences vary, too, often depending on the subject and course difficulty.","学生对测试形式的偏好也会有所不同，通常取决于科目和课程的难度。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"variety","p":"vəˈraɪəti","m":"n.多样化；种类；变种","tip":"","ex":["Jeans are available in a greater variety in America.","在美国，牛仔裤有很多种类。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"invariably","p":"ɪnˈveəriəbli","m":"adv.不变地；始终如一地；一贯地","tip":"vary v.变化 → variable adj.可变的 → invariable adj.不变的 → invariably adv.","ex":["Children's personality characteristics are invariably determined by their mothers.","孩子的性格特点总是由其母亲决定。"],"lesson":"u02-l02","group":"“改变”相关"},{"w":"style","p":"staɪl","m":"n.风格；款式；方式 v.设计","tip":"《江南 Style》这首歌展示了独特的“风格”。","ex":["Each artist has their own individual style but all artists share a common aim.","每个艺术家都有自己的个人风格，但所有的艺术家都有一个共同的目标。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"mode","p":"məʊd","m":"n.模式；方式，方法；状态；形式","tip":"单词发音类似“模的”→ 模式；方式","ex":["The operation should be done only once for each mode.","每种模式仅需操作一次。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"model","p":"ˈmɒdl","m":"n.模型，样式；模特儿；模范 v.做模特儿；将……做成模型","tip":"","ex":["Trying to live up to the images of \"perfect\" models and movie heroes has a dark side.","试图追求“完美”模范和电影英雄的形象有其阴暗面。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"modify","p":"ˈmɒdɪfaɪ","m":"v.调整；修改；使更适合","tip":"mod（联想 mode）+ -ify（动词后缀）→ 文章不能太过模式化，要适当进行“调整”和“修改”。","ex":["She modified her article.","她修改了她的文章。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"modest","p":"ˈmɒdɪst","m":"adj.适中的；谦虚的；保守的","tip":"mod（联想 mode）+ -est（最）→ 做人最好的模式是“谦虚的”。","ex":["They did not raise much due to modest targets.","由于目标保守，他们没有筹集太多资金。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"earnest","p":"ˈɜːnɪst","m":"adj.认真的，诚挚的","tip":"earn（挣钱）+ -est（最）→ 想挣钱就要用最“认真的”态度做事。","ex":["The majority of earnest people are trying to get on in life.","大多数认真的人都在努力生活。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"moderate","p":"ˈmɒdəreɪt","m":"adj.适度的；中等的","tip":"mode（联想 model）+ rate（速度）→ 模特走路的速度是“适度的”。","ex":["The team enjoyed only moderate success last season.","上个赛季，这支球队只取得了中等成绩。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"tolerate","p":"ˈtɒləreɪt","m":"v.容忍；忍受；容许","tip":"tole（音似“逃了”）+ rate（速度）→ 他“忍受”不了那种煎熬，以很快的速度逃跑了。","ex":["This sort of behaviour will not be tolerated.","这种行为是不能容许的。"],"lesson":"u02-l02","group":"“模式”相关"},{"w":"beam","p":"biːm","m":"n.光线；梁，横梁","tip":"单词发音类似“闭目”→ 他闭目养神，缓解“光线”对眼睛的刺激。","ex":["A beam about ten feet long collapsed to the ground.","一根约十英尺长的横梁倒塌在地。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"bright","p":"braɪt","m":"adj.明亮的；聪明的；愉快的","tip":"","ex":["Given this, the future for the region's poor doesn't look nearly as bright as it once did.","鉴于此，该地区穷人的未来看起来不像以前那么光明。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"light","p":"laɪt","m":"n.光线；电灯 adj.充满光的；程度轻的 v.使明亮；点燃","tip":"单词发音类似“拉它”→ 有些“电灯”要拉它的灯绳进行开关。","ex":["For his part, Wang said that in his own experience, losing did light a motivating fire.","王（先生）说，从他自己的经历来看，失败确实点燃了一束激励人心的火焰。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"slight","p":"slaɪt","m":"adj.轻微的，少量的","tip":"s（音似“丝”）+ light（光线）→ 一丝光线 → 轻微的，少量的","ex":["The picture was at a slight angle.","这幅画稍微有点歪。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"enlighten","p":"ɪnˈlaɪtn","m":"v.启发；教导；启迪","tip":"en-（使）+ light（照亮 → 明白）+ -en（后缀）→ 使明白 → 启发；教导；启迪","ex":["A few dedicated doctors have fought for years to enlighten the profession.","几位富有献身精神的医生为启蒙这一行业奋斗多年。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"lightning","p":"ˈlaɪtnɪŋ","m":"n.闪电 adj.闪电般的；飞快的","tip":"","ex":["He took shelter under a tree and was struck by lightning.","他躲在一棵树下，被闪电击中了。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"thunder","p":"ˈθʌndə(r)","m":"n.雷声，轰隆声 v.打雷","tip":"thun（音似“仨”）+ der（联想“打呼噜”）→ 他们仨睡觉都打呼噜，呼噜声像“打雷”一样响。","ex":["It has never seen thunder and lightning.","它从未见过电闪雷鸣。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"thumb","p":"θʌm","m":"n.拇指 v.快速翻阅","tip":"thu（音似“仨”）+ m（联想“妹”）+ b → 三个妹妹看书看得特别快 → 快速翻阅","ex":["He caught his thumb in the door.","他的拇指被门夹住了。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"delight","p":"dɪˈlaɪt","m":"n.高兴 v.（使）高兴","tip":"de（音似“弟”）+ light（光）→ 弟弟在黑暗中看到一束光，非常“高兴”。","ex":["He looked up at his father, his features overflowing with energy and delight.","他抬头看着父亲，脸上洋溢着活力和喜悦。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"highlight","p":"ˈhaɪlaɪt","m":"v.突出，使显著 n.高光时刻；最精彩的部分","tip":"high（高）+ light（光）→ 高光时刻","ex":["It may highlight your inability to delegate effectively.","这可能会突出你无法有效地委派任务。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"solar","p":"ˈsəʊlə(r)","m":"adj.太阳的；日光的","tip":"单词发音类似“馊了”→ 东西都馊了，拿到太阳底下晒晒吧 → 太阳的；日光的","ex":["The rest of the energy savings comes from the solar units.","其余的能源节约来自太阳能装置。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"sunlight","p":"ˈsʌnlaɪt","m":"n.阳光","tip":"","ex":["One converts sunlight into energy and the other has to eat food to make its energy.","一种将阳光转化为能量，另一种必须吃食物来产生能量。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"sunset","p":"ˈsʌnset","m":"n.日落","tip":"","ex":["From sunrise to sunset, my father, my younger brother and I cut the weeds in the very large yards.","从日出到日落，我和我的父亲、弟弟在非常大的院子里除草。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"outset","p":"ˈaʊtset","m":"n.开始；开端","tip":"","ex":["You should have made that clear right at the outset.","你应该一开始就说清楚。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"dawn","p":"dɔːn","m":"n.黎明；开端 v.破晓；开始","tip":"黎明（dawn）时他的心才真正沉下来（down）。","ex":["At dawn on July 16, 1945, the atomic bomb was set off.","1945 年 7 月 16 日黎明时分，原子弹爆炸了。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"dusk","p":"dʌsk","m":"n.黄昏；傍晚","tip":"黄昏（dusk）时天色渐渐暗（dark）了下来。","ex":["The street lights go on at dusk.","街灯在黄昏时亮起来。"],"lesson":"u02-l03","group":"“光”相关"},{"w":"shed","p":"ʃed","m":"n.简易房；棚 v.散发出光；流，洒","tip":"she（她）+ d（联想“的”）→ 她的眼泪“流”了出来。","ex":["He put all his belongings in the shed.","他把他所有的东西都放在棚里。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"tear","p":"teə(r)","m":"v.撕裂；戳破","tip":"单词发音类似“太饿”→ 我太饿了，“撕裂”食物的包装袋就吃了起来。","ex":["Cultural differences often tear apart a family built on romantic love.","文化差异常常使建立在浪漫爱情基础上的家庭破裂。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"crystal","p":"ˈkrɪstl","m":"n.水晶；晶粒","tip":"cry（哭）+ st（联想 street）+ al（联想 all）→ 动漫里，女孩在街上哭了，所有的眼泪变成了“水晶”在空中飘。","ex":["Every table had been set with fine china and crystal.","每张桌子上都摆放着精美的瓷器和水晶。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"candle","p":"ˈkændl","m":"n.蜡烛；烛形物；烛光","tip":"can（可以）+ d（联想“的”）+ le（联想“了”）→ 家里停电了，我去点根“蜡烛”，这样写作业是可以的。","ex":["She keeps a supply of candles in the house in case of power failure.","她在家里预备了一些蜡烛以防停电。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"cancel","p":"ˈkænsl","m":"v.取消，废除；删除","tip":"can（可以）+ cel（音似 sell）→ 卖东西的订单也可以“取消”。","ex":["Schools, restaurants, and businesses closed, and more than 1,000 flights were canceled.","学校、餐馆和企业关闭了，超过 1,000 个航班被取消了。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"canteen","p":"kænˈtiːn","m":"n.餐厅；食堂","tip":"can（可以）+ teen（联想 ten）→ 这个商场里可以开十家“餐厅”。","ex":["There is a heated debate regarding whether the university's canteens should be open to the public.","关于大学食堂是否应该向公众开放，人们展开了激烈的争论。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"dizzy","p":"ˈdɪzi","m":"adj.头晕目眩的；傻乎乎的，愚蠢的","tip":"di（音似“弟”）+ zz（联想“睡觉”）+ y → 弟弟都快睡着了，感觉“头晕目眩的”。","ex":["She went to the doctor complaining of dizzy spells.","她去找医生看病，说自己一阵一阵地头晕。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"faint","p":"feɪnt","m":"adj.（光、声、味）微弱的；昏厥的 v.昏厥","tip":"单词发音类似“粉他”→ 他的粉丝看见他激动地“昏厥”了。","ex":["It carries faint noises from a patient's chest to a doctor's ear.","它将微弱的声音从病人的胸部传到医生的耳朵。"],"lesson":"u02-l03","group":"“流”相关"},{"w":"solid","p":"ˈsɒlɪd","m":"n.固体 adj.固体的；坚固的；可靠的；相当好的","tip":"单词发音类似“扫立的”→ 打扫立在地上的“固体”需要用力。","ex":["The candidate was productive, or intelligent, or a solid scientist or something that's clearly solid praise.","候选人要么是多产的，要么是聪明的，要么是一个可靠的科学家，或者是有一些明显值得高度称赞的东西。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"consolidate","p":"kənˈsɒlɪdeɪt","m":"v.使巩固；使加强；合并","tip":"con-（所有的）+ solid（坚固的）+ -ate（动词后缀）→ 使所有的东西都很坚固 → 使巩固；使加强","ex":["Small schools consolidated into larger ones, meaning more students were farther away from home.","小的学校合并成更大的学校，这意味着更多的学生离家更远。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"fluid","p":"ˈfluːɪd","m":"adj.流动的 n.液体","tip":"flui（音似“飞流一”）+ d（联想“地”）→ 屋里飞流一地的是些“液体”。","ex":["A dry mouth may reduce taste sensitivity, but taste is restored by drinking fluids.","口干可能会降低味觉的敏感度，但通过饮用液体可以恢复味觉。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"liquid","p":"ˈlɪkwɪd","m":"n.液体 adj.液体的，液态的","tip":"单词发音类似“立溃的”→ 看到洒了一地的“液体”，他立刻崩溃了。","ex":["The difference lies in what's in the globules and what's in the surrounding liquid.","区别在于液滴中的物质和周围液体中的物质。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"volume","p":"ˈvɒljuːm","m":"n.体积；容积；音量；一卷","tip":"vo（音似“我”）+ lu（联想“路”）+ m（联想“妹”）+ e → 我在路对面看见了妹妹，提高“音量”喊她。","ex":["The song has been recorded at a low volume.","这首歌是以低音量录制的。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"bulk","p":"bʌlk","m":"n.体积；大块；大部分","tip":"单词发音类似“巴克”→《野性的呼唤》主角巴克的“体积”很大。","ex":["The bulk of the world's languages use base-10, base-20 or base-5 number systems.","世界上大部分语言使用以 10、20 或 5 为基数的数字系统。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"batch","p":"bætʃ","m":"n.一批；（食物、药物等）一批生产的量","tip":"单词发音类似“爸吃”→ 我家囤了“一批”爸爸喜欢吃的食物。","ex":["A new batch of young women has been entering the workforce for the past decade.","在过去的十年里，一批新的年轻女性加入了劳动大军。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"patch","p":"pætʃ","m":"v.打补丁 n.补丁；斑；小块土地；戒烟贴片","tip":"单词发音类似“派吃”→ 派送一些吃的给衣服打“补丁”的穷人。","ex":["People in both groups used nicotine patches before they quit.","两组人在戒烟前都使用了尼古丁戒烟贴片。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"minimum","p":"ˈmɪnɪməm","m":"n.最小值；最低限度 adj.最小的；最低限度的","tip":"mini（小）+（i）m（拉丁语最高级）+ um（……的量）→ 最小值；最小的","ex":["They have their weight reduced to minimum.","它们的重量被减到最小。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"maximum","p":"ˈmæksɪməm","m":"n.最大值；最大限度 adj.最多的；最大极限的","tip":"","ex":["What is the absolute maximum you can afford to pay?","你最多能出多少钱？"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"climax","p":"ˈklaɪmæks","m":"n.高潮，顶点 v.达到极点","tip":"c（音似“可”）+ li（联想“立”）+ max（最大值）→ 可站立的高度最大的地方 → 高潮，顶点","ex":["The climax of his career was director.","他职业生涯的顶点就是导演。"],"lesson":"u02-l03","group":"“固体/液体”相关"},{"w":"vessel","p":"ˈvesl","m":"n.船；容器；脉管；导管","tip":"单词发音类似“歪艘”→ 一艘“船”歪了。","ex":["A smaller vessel would have capsized.","小一点的船可能会倾覆。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"pulse","p":"pʌls","m":"n.脉搏；脉率；脉冲 v.搏动；跳动","tip":"pul（联想“噗”）+ se（联想“声”）→ 心脏跳动是“噗噗”的声音，与“脉搏”同频。","ex":["The Chinese doctor took my pulse and asked to see my tongue.","中医给我把了脉，要求看我的舌头。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"impulse","p":"ˈɪmpʌls","m":"n.冲动；心血来潮；推动力；刺激","tip":"im-（= in，里）+ pulse（跳动）→ 内心的跳动 → 冲动","ex":["Many of them buy things on impulse.","他们中的许多人会冲动购物。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"flood","p":"flʌd","m":"n.洪水；水灾 v.（使）灌满水；淹没","tip":"fl（联想“飞流”）+ oo（形似水翻滚）+ d（联想“的”）→ 洪水；水灾","ex":["The heavy rain has caused floods in many parts of the country.","大雨使全国许多地方洪水泛滥。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"fluctuate","p":"ˈflʌktʃueɪt","m":"v.（大小、数量、质量等）波动；（在……之间）起伏，不定","tip":"fluct（流动，波动）+ -(u)ate（动词后缀）→ 使流动 → 波动","ex":["Prices fluctuate in response to harvests.","价格随收成的变化而波动。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"bleed","p":"bliːd","m":"v.出血，流血","tip":"blood n. 血；血统 → bleed v.","ex":["She was bleeding from her face and hands.","她的脸和手都在流血。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"dry","p":"draɪ","m":"adj.干的；干燥的 v.（使）变干；（把……）弄干","tip":"单词发音类似“抓”→ 短头发湿了，抓几下就“变干”了。","ex":["Is my shirt dry yet?","我的衬衣干了吗？"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"drain","p":"dreɪn","m":"n.下水道；耗竭 v.排水；排空；流出；耗尽","tip":"d（联想“滴”）+ rain（雨）→ 雨水滴下来，通过“下水道”“流出”。","ex":["Leave the dishes to drain.","把碟子控干。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"bubble","p":"ˈbʌbl","m":"n.泡；泡沫；（很可能持续不长的）好景，好运 v.起泡；冒泡","tip":"单词发音类似气“泡”爆破时发出的噼噼啪啪的声音。","ex":["When the bubble burst, demand collapsed.","当泡沫破裂时，需求就崩溃了。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"bulb","p":"bʌlb","m":"n.电灯泡；球状物","tip":"单词发音类似“包”→ “电灯泡”就像个大包一样。","ex":["Don't we have a brighter bulb somewhere?","我们不是有一个更亮的电灯泡放在某个地方吗？"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"soak","p":"səʊk","m":"v.浸泡；浸湿 n.浸泡；泡澡","tip":"soa（音似 so）+ k（音似“渴”）→ 他那么渴，看到水恨不得“浸泡”在里面喝个够。","ex":["Leave the apricots to soak for 20 minutes.","把杏子浸泡 20 分钟。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"penetrate","p":"ˈpenətreɪt","m":"v.进入；渗透，打入（组织、团体等）","tip":"pe（音似“拍”）+ net（网络）+ rate（速度）→ 拍打电脑并不能加快“进入”网络的速度。","ex":["The experience of using IT penetrates almost the entire work field.","使用 IT 的经验几乎可以渗透到整个工作领域。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"filter","p":"ˈfɪltə(r)","m":"n.过滤器 v.过滤，渗入","tip":"单词发音类似“飞了它”→ 灰尘从“过滤器”里飞了出来。","ex":["The different shapes of the containers suggest they were used to brew, filter, and store beer.","容器的不同形状表明它们被用来酿造、过滤和储存啤酒。"],"lesson":"u02-l03","group":"“洪水”相关"},{"w":"alcohol","p":"ˈælkəhɒl","m":"n.酒精，乙醇；酒","tip":"a（—）+ l（形似 1）+ cohol（音似“口喝”）→ “感情深，一口闷（喝）”是他劝“酒”时常说的。","ex":["To help prevent headaches, drink plenty of water, and avoid alcohol and coffee.","为了帮助预防头疼，要喝大量的水，不要喝酒和咖啡。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"liquor","p":"ˈlɪkə(r)","m":"n.烈性酒；含酒精饮料","tip":"单词发音类似“立刻”→ 他一喝“烈性酒”，立刻就醉倒了。","ex":["The liquor is not for sale in many countries.","很多国家是不销售烈性酒的。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"drunk","p":"drʌŋk","m":"adj.醉的；陶醉的 n.醉汉","tip":"drink v. 喝，饮 → drunk adj. & n.","ex":["People should pay more attention to the danger of drunk driving.","人们应该更加注意酒驾的危险。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"beer","p":"bɪə(r)","m":"n.啤酒","tip":"单词发音类似“啤呢” → 啤酒","ex":["The method for making beer has changed over time.","酿造啤酒的方法随着时间的推移而改变。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"soda","p":"ˈsəʊdə","m":"n.苏打汽水；苏打；纯碱","tip":"","ex":["It may influence the marketing strategies of the soda business.","它可能会影响苏打水业务的营销策略。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"tobacco","p":"təˈbækəʊ","m":"n.烟草，烟叶","tip":"单词发音类似“吐百口”→ 有些吸烟的人会从口中吐出很多烟圈 → 烟草","ex":["Most countries impose some sort of tax on alcohol and tobacco.","大多数国家对酒精和烟草征收某种税。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"beverage","p":"ˈbevərɪdʒ","m":"n.（除水以外的）饮料","tip":"be（是）+ ver（音似“我”）+ age（年龄）→ 这是我这个年龄喝的“饮料”。","ex":["Alcoholic beverages are served in the hotel lounge.","酒店的公共休息室提供含酒精的饮料。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"average","p":"ˈævərɪdʒ","m":"adj.平均的，正常的，普通的 n.平均数；平均水平","tip":"a（音似“按”）+ ver（音似“我”）+ age（年龄）→ 请按我的年龄来算，因为我的年龄是这群人中的“平均数”。","ex":["I definitely feel things more strongly than the average person.","我对事物的感受肯定比普通人更强烈。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"common","p":"ˈkɒmən","m":"adj.常见的；普遍的；共有的 n.公共用地；公共食堂","tip":"com-（所有的）+ mon（音似“门”）→ 所有的门都是“常见的”样式。","ex":["They will find they have something in common.","他们会发现他们有一些共同点。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"commonplace","p":"ˈkɒmənpleɪs","m":"adj.平凡的，普通的 n.常见的事","tip":"","ex":["This technology is now commonplace in schools.","这项技术现在在学校很常见。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"kettle","p":"ˈketl","m":"n.水壶；锅","tip":"单词发音类似“开透”→ 水开透了，才能倒进“水壶”里。","ex":["I'll put the kettle on and make some tea.","我要烧壶水沏茶。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"basin","p":"ˈbeɪsn","m":"n.盆；盆地","tip":"bas（音似 bath）+ in（里面）→ 他给小宠物在“盆”里洗澡。","ex":["He washed his hands in the basin.","他在盆里洗手。"],"lesson":"u02-l03","group":"“饮料”相关"},{"w":"engage","p":"ɪnˈɡeɪdʒ","m":"v.吸引（注意力）；使从事；使订婚","tip":"单词发音类似“姻给之”→ 给之婚姻 → 使订婚","ex":["More and more women actively engaged in politics.","越来越多的女性积极从政。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"pregnant","p":"ˈpreɡnənt","m":"adj.怀孕的，妊娠的；意义重大的","tip":"pre-（前面）+ g（音似“哥”）+ nant（联想“难他”）→ 前面的哥哥照顾“怀孕的”妻子很顺手，一点也难不住他。","ex":["Pregnant employees struggled to keep up.","怀孕的员工努力跟上进度。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"couple","p":"ˈkʌpl","m":"v.连接；结合 n.一对；几个；夫妻；情侣","tip":"这两只杯子（cup）是一对（couple）。","ex":["There are a couple of ways to compromise on the issue.","在这个问题上有几种折中的方法。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"double","p":"ˈdʌbl","m":"adj.两倍的；双重的 adv.成双地 v.（使）加倍；对折","tip":"","ex":["As a result, wheat prices elsewhere more than doubled, pulling rice and corn prices up with them.","结果，其他地区的小麦价格翻了一倍多，带动了大米和玉米价格的上涨。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"spouse","p":"spaʊs；spaʊz","m":"n.配偶","tip":"单词发音类似“死抱着”→ 他死死地抱着生病的“配偶”不肯撒手。","ex":["One spouse wants a complete name change.","配偶的一方希望彻底改名。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"divorce","p":"dɪˈvɔːs","m":"n. & v.离婚；分离","tip":"单词发音类似“敌我死”→ 夫妻俩的生活如同“敌死我活”，所以“离婚”了。","ex":["The divorce rate in the county has been on a steady rise.","这个县的离婚率一直在稳步上升。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"single","p":"ˈsɪŋɡl","m":"adj.单一的；单身的；仅，唯一的","tip":"sing（唱歌）+ le（联想“了”）→ 那个“单身的”人唱了首歌。","ex":["Young men are less likely to end up as single parents than young women.","年轻男性比年轻女性更不可能成为单亲父母。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"singular","p":"ˈsɪŋɡjələ(r)","m":"adj.单数（形式）的；非凡的；奇特的","tip":"sing（唱歌）+ u（字母音似 you）+ lar（音似“了”）→ 该你唱了，唱歌时的你是“非凡的”。","ex":["Jobs, of course, has enjoyed singular success.","当然，乔布斯取得了非凡的成就。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"gesture","p":"ˈdʒestʃə(r)","m":"n.手势；姿势 v.做手势；用动作示意","tip":"ge（联想“哥”）+ s（联想“摔”）+ ture（联想 true）→ 我哥哥摔跤的“姿势”真的很帅。","ex":["Substitutions of one gesture for the other often create humorous moment.","用一种手势代替另一种手势通常会带来幽默的时刻。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"mortgage","p":"ˈmɔːɡɪdʒ","m":"n.按揭（由银行等提供房产抵押借款） v.（向银行等）抵押（房产）","tip":"mort（联想“摩托”）+ ga（音似“给”）+ ge（联想“哥”）→ 把你最爱的摩托“抵押”给哥哥。","ex":["Today a similar mortgage would claim more than twice that share of his monthly earnings.","如今，类似的房贷月供将占据他月收入的两倍以上。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"recognise","p":"ˈrekəɡnaɪz","m":"v.认出，辨别出；承认；意识到","tip":"re（字母音似“阿姨”）+ cog（音似“靠哥”）+ nise → 阿姨靠着哥哥的提醒“认出”了我。","ex":["The importance of using PowerPoint in education should be recognised by all of us.","我们所有人都应该认识到在教育中使用演示文稿的重要性。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"challenge","p":"ˈtʃælɪndʒ","m":"n.挑战；艰巨任务 v.挑战；对……怀疑（或质疑）","tip":"cha（联想“插”）+ llen（音似“林”）+ ge（联想“哥”）→ 他用叉子插坏了林哥的蛋糕，向他发出“挑战”。","ex":["We can live a peaceful life despite the various challenges of the modern world.","尽管现代世界有各种挑战，我们仍然可以过上和平的生活。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"flag","p":"flæɡ","m":"n.旗帜 v.标示","tip":"fl（联想“飞来”）+ a（一）+ g（联想“哥”）→ 从屋外飞奔进来一个哥哥，手里举着“旗帜”。","ex":["Hundreds of people cheered and waved flags.","数百人欢呼并挥舞旗帜。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"surge","p":"sɜːdʒ","m":"n.突然增加 v.使强烈地感到；突然增加","tip":"sur-（= over，超）+ ge（联想“哥”）→ 当你的成绩超过哥哥时，哥哥的压力就像“突然增加”了。","ex":["We are having trouble keeping up with the recent surge in demand.","对于近来出现的需求猛增，我们难以应对。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"leap","p":"liːp","m":"n. & v.跳跃；剧增","tip":"单词发音类似“立扑”→ 孩子看到妈妈，立刻欢呼“跳跃”着扑向她。","ex":["The run has been taken; now is the time to leap.","跑步已经结束；现在是跳跃的时候了。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"global","p":"ˈɡləʊbl","m":"adj.全球的，全世界的","tip":"g（联想“哥”）+ lo（音似“搂”）+ bal（联想 ball）→ 哥哥搂抱着一个地球仪 → 全球的","ex":["Environmental problems must be solved to ease the current global food shortage.","环境问题必须解决，以缓解目前的全球粮食短缺。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"grain","p":"ɡreɪn","m":"n.谷物；颗粒","tip":"雨（rain）中的哥哥（g）忙着收谷物（grain）。","ex":["Corn and soya beans are more important as feed grains.","玉米和大豆作为饲料谷物更为重要。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"cereal","p":"ˈsɪəriəl","m":"n.谷物；麦片；谷类食品","tip":"ce（音似“塞”）+ real（真的）→ 肚子里塞满了“麦片”，我真的吃饱了。","ex":["They consume plenty of cereal for breakfast.","他们早餐吃了很多麦片。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"wheat","p":"wiːt","m":"n.小麦","tip":"wh（联想 when）+ eat（吃）→ 吃饭时，我们常吃“小麦”制品。","ex":["They grew wheat and corn on a small farm.","他们在一个小农场里种植小麦和玉米。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"glow","p":"ɡləʊ","m":"v.发光，发热 n.亮光；脸红","tip":"g（联想“哥”）+ low（低）→ 哥哥看到低处的我“脸红”了。","ex":["They fill these tubes with gases that glow when electrified.","他们向这些管子充入通电发光气体。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"spark","p":"spɑːk","m":"v.产生火花；引发 n.火花；原因","tip":"s（音似“嘶”）+ park（公园）→“嘶嘶”的声音从公园里传出，还能看到“火花”。","ex":["Her energy sparked a period of experimentation and renewal.","她的活力激发了一段实验和更新（的热潮）。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"sparkle","p":"ˈspɑːkl","m":"n.闪烁；闪耀 v.发光；闪烁","tip":"spark（火花）+ le（联想“了”）→ 我看到有火花在“闪烁”了！","ex":["The sky sparkled with brilliant stars.","天空闪耀着灿烂的星星。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"wrinkle","p":"ˈrɪŋkl","m":"n.皱纹 v.（使）起皱纹","tip":"wr（联想 write）+ ink（墨水）+ le（联想“了”）→ 他写字时，墨水使纸起了“皱纹”。","ex":["There were fine wrinkles around her eyes.","她眼周出现了细纹。"],"lesson":"u02-l04","group":"ge/g 相关"},{"w":"grace","p":"ɡreɪs","m":"n.优美，优雅 v.使荣耀；装饰","tip":"g（联想“哥”）+ race（比赛）→ 比赛中的哥哥动作“优雅”。","ex":["Red Rum's spirit and grace had already begun to charm the leagues of Grand National fans.","红朗姆的精神和优雅已经开始吸引（英国）国家障碍大赛联盟的赛马迷。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"elegant","p":"ˈelɪɡənt","m":"adj.优雅的；简洁的；漂亮致的","tip":"e-（出）+ leg（腿）+ ant（蚂蚁）→ 蚂蚁伸出腿做了个“优雅”的动作。","ex":["I have seen this place—it is elegant, inside and out.","我看过这个地方——它里里外外都很雅致。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"charm","p":"tʃɑːm","m":"n.魅力；吸引力；护身符 v.吸引；迷住","tip":"char（音似“诧”）+ m（联想“妹”）→ 他惊诧于妹妹的“魅力”。","ex":["His good luck charm sank into the sea.","他的幸运符沉入了海里。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"honour","p":"ˈɒnə(r)","m":"n.荣誉；荣幸 v.尊敬；给……荣誉","tip":"荣耀手机的英文名就是 HONOR。","ex":["It can bring wealth and honor to them.","它可以给他们带来财富和荣誉。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"privilege","p":"ˈprɪvəlɪdʒ","m":"n.特权；荣幸","tip":"pri-（提前）+ vile（音似“为了”）+ ge（联想“哥”）→ 他利用手中的“特权”提前为哥哥着想。","ex":["But it's also true that saying \"no\" is not merely a privilege reserved for the successful.","但说“不”并不仅仅是成功人士的特权，这也是事实。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"glory","p":"ˈɡlɔːri","m":"n.荣誉；荣耀；赞美；辉煌","tip":"g（联想“哥”）+ lory（联想“捞日”）→ 哥哥要是能把太阳打捞上来，那可是无上的“荣誉”。","ex":["What was a significant contributor to the past glory of public schools?","公立学校过去辉煌的重要因素是什么？"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"fond","p":"fɒnd","m":"adj.（～of）喜爱；喜欢","tip":"","ex":["He is fond of luxury cat food.","他喜欢奢侈的猫粮。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"favour","p":"ˈfeɪvə(r)","m":"n.喜爱；恩惠；支持 v.偏爱；支持；更喜欢","tip":"单词发音类似“非我”→“偏爱”他人非我莫属。","ex":["It is said, that menu-labeling could favour chains that have more healthy offerings.","据说，菜单标签可能有利于提供更多健康食品的连锁店。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"flavour","p":"ˈfleɪvə(r)","m":"n.味（道）；特色；概述 v.给……调味","tip":"这是我更喜欢（favour）的味道（flavour）。","ex":["Moutai has mild flavour and a special fragrance.","茅台味道温和，香味独特。"],"lesson":"u02-l04","group":"“优雅、荣耀”相关"},{"w":"typical","p":"ˈtɪpɪk(ə)l","m":"adj.典型的；一贯的，平常的","tip":"type n.种类；类型 → typical adj.","ex":["Leah was a typical successful woman before she changed her career.","利亚在转行之前是一个典型的成功女性。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"extraordinary","p":"ɪkˈstrɔːdnri","m":"adj.非凡的；不平常的","tip":"extra（额外的）+ ordinary（一般的）→ 超出一般的 → 非凡的；不平常的","ex":["The response from the public has been quite extraordinary.","公众的反应相当不同寻常。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"eminent","p":"ˈemɪnənt","m":"adj.明显的；杰出的，著名的","tip":"e-（出）+ min（联想“民”）+ ent（联想 enter）→ 外出打工的民众希望进入一家“著名的”企业。","ex":["This description even fits the majority of eminent scholars.","这种描述甚至符合大多数著名的学者。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"prominent","p":"ˈprɒmɪnənt","m":"adj.突出的；卓越的，重要的，著名的","tip":"这位著名的（eminent）科学家为国家做出了突出的（prominent）贡献。","ex":["In the past few years, prominent schools around the world have joined the trend.","在过去的几年里，世界各地的知名学校加入了这一潮流。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"outstanding","p":"aʊtˈstændɪŋ","m":"adj.优秀的，杰出的，突出的","tip":"out（外面）+ stand（站）+ -ing（形容词后缀）→ 站在外面的 → 突出的","ex":["They feel proud of being an outstanding problem solver.","他们为自己是优秀的问题解决者感到自豪。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"mark","p":"mɑːk","m":"n.成绩；等级 v.做记号；标记","tip":"马克笔（marker）就是用来做记号（mark）的笔。","ex":["A student who earns good marks is generally a good student.","一个成绩好的学生通常是个好学生。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"remark","p":"rɪˈmɑːk","m":"n.言论；评述 v.说起；评论","tip":"re（字母音似“阿姨”）+ mark（标记）→ 阿姨在标记处写了“评论”。","ex":["How did people feel when they learned of her remarks?","当人们得知她的言论时，感觉如何？"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"comment","p":"ˈkɒment","m":"n.议论；评论；解释 v.表达意见","tip":"com-（所有的）+ men（男人）+ t（联想“他”）→ 所有的男人都“评论”了他。","ex":["Such comments often seem quite reasonable.","这样的评论往往看似很合理。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"commence","p":"kəˈmens","m":"v.开始；着手","tip":"com-（所有的）+ mence（音似“闷死”）→ 养殖户“着手”清理所有因天气太热而闷死鸡。","ex":["The meeting is scheduled to commence at noon.","会议定于午间召开。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"brilliant","p":"ˈbrɪliənt","m":"adj.明亮的；杰出的；聪颖的；巧妙的","tip":"bri（联想 bright）+ llian（联想“脸”）+ t（联想“他”）→ 他“明亮的”脸上映着光。","ex":["She has one of the most brilliant minds in the country.","她是全国最有才气的人之一。"],"lesson":"u02-l04","group":"“与众不同”相关"},{"w":"terrific","p":"təˈrɪfɪk","m":"adj.极好的，了不起的；惊人的","tip":"te（联想“特”）+（r）ri（联想“日”）+ fic（音似“非可”）→ 特别的日子里非提不可的就是大家做过的“了不起的”事情。","ex":["She is known to have a terrific figure.","大家都知道她的身材很好。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"magnificent","p":"mæɡˈnɪfɪsnt","m":"adj.宏伟的，壮丽的；值得赞扬的","tip":"ma（联想“妈”）+ gni（音似“哥你”）+ ficent（音似“飞身”）→ 妈妈、哥哥和你都飞身而入“宏伟的”殿堂。","ex":["We visited the magnificent libraries.","我们参观了宏伟的图书馆。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"splendid","p":"ˈsplendɪd","m":"adj.极好的；壮丽的，灿烂的","tip":"花费（spend）了（l）我们很多时间和精力做（did）的事情，一定是极好的（splendid）。","ex":["The book includes a wealth of splendid photographs.","这本书有大量极好的照片。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"marvellous","p":"ˈmɑːvələs","m":"adj.极好的；非凡的","tip":"单词发音类似“妈我乐死”→ 看那部“极好的”喜剧片时，妈妈和我都快乐死了。","ex":["It's marvellous what modern technology can do.","现代技术所能做的真是太了不起了。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"marvel","p":"ˈmɑːvl","m":"n.奇迹 v.感到惊奇；大为赞叹","tip":"","ex":["All in all, the Olympic class ships were marvels of sea engineering.","总之，奥林匹克级舰艇是海洋工程的奇迹。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"grand","p":"ɡrænd","m":"adj.宏伟的；（重）大的，壮丽的","tip":"小时候觉得父母（parents）是无所不能的超人，祖父母（grandparents）是更大的（grand）父母。","ex":["The book dares to take on grand themes in the grand manner.","这本书敢于以宏大的方式呈现宏大的主题。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"wonder","p":"ˈwʌndə(r)","m":"v.想知道；惊讶 n.惊异；奇迹","tip":"","ex":["People often wonder why some entrepreneurs have greater success than others.","人们经常想知道为什么有些企业家比其他人更成功。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"miracle","p":"ˈmɪrəkl","m":"n.神迹；奇迹","tip":"照了魔镜（mirror）就会有奇迹（miracle）发生。","ex":["It's a miracle that nobody was killed in the crash.","撞车事故中没人丧生，这真是奇迹。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"magic","p":"ˈmædʒɪk","m":"n.魔法，魔术 adj.魔术的，有魔力的","tip":"ma（联想“妈”）+ g（联想“给”）+ ic（联想“IC 卡”）→ 妈妈给的 IC 卡好像有“魔法”，怎么都用不完。","ex":["We have long feared that this \"revolution in distribution\" uses corporate black magic on our appetite.","长期以来，我们一直担心，这种“分销革命”会利用企业黑魔法影响我们的胃口。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"magnetic","p":"mæɡˈnetɪk","m":"adj.有磁性的；有吸引力的，有魅力的","tip":"ma（联想“妈”）+ gne（音似“哥奶”）+ t（联想“他”）+ ic（联想“IC 卡”）→ 妈妈、哥哥、奶奶和他都喜欢用有防磁功能的 IC 卡乘坐公交车，因为“有磁性的”公交卡容易消磁。","ex":["The magnetic pull of the city was hard to resist.","都市的强大魅力令人难以抗拒。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"magnet","p":"ˈmæɡnət","m":"n.磁铁；有吸引力的人（或事物）","tip":"","ex":["The scent of flowers acts as a magnet to bees.","花的香味像磁铁一样吸引着蜜蜂。"],"lesson":"u02-l04","group":"“宏伟的、极好的”相关"},{"w":"parliament","p":"ˈpɑːləmənt","m":"n.议会；国会","tip":"单词发音类似“怕了没”→“议会”是最高的立法机关，你怕了没？","ex":["Later Parliament increased the speed limit to 14 miles per hour.","后来议会将限速提高到每小时 14 英里。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"delegate","p":"ˈdelɪɡət","m":"v.授（权）","tip":"dele（联想 delete）+ gate（门）→ 我删除了录入的指纹，想开门锁需要重新“授权”。","ex":["Congress delegates rejected the proposals.","国会代表拒绝了这些提议。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"delete","p":"dɪˈliːt","m":"v.删除","tip":"","ex":["They deleted all information about gender.","他们删除了所有关于性别的信息。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"senator","p":"ˈsenətə(r)","m":"n.参议员","tip":"sen（联想 send）+ ator（联想 actor）→ 他们派遣了一个演员做“参议员”。","ex":["The senator called on Facebook to change its privacy policy.","那个参议员呼吁脸书改其隐私政策。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"council","p":"ˈkaʊnsl","m":"n.理事会，委员会，地方议会","tip":"coun（联想 count）+ cil（联想 pencil）→ 那个“理事会”成员不干实事，上班数铅笔。","ex":["The decision still has to be ratified by the full council.","该决定仍需得到整个委员会的批准。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"bureau","p":"ˈbjʊərəʊ","m":"n.局；科；处；办事处","tip":"单词发音类似“不弱”→ 只要能为人民服务，在“办事处”里的工作也不弱。","ex":["According to the Census Bureau, 38 million people in the U.S. are living below the official poverty thresholds.","根据人口普查局的数据，美国有 3,800 万人生活在官方贫困线以下。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"federal","p":"ˈfedərəl","m":"adj.联邦制的","tip":"","ex":["I think we're unique as a federal agency.","我认为我们作为联邦机构是独一无二的。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"govern","p":"ˈɡʌvn","m":"v.统治；控制；支配","tip":"政府（government）就是统治（govern）国家的机关。","ex":["Human lives are governed by the desire to experience joy.","人类的生活被体验快乐的欲望所支配。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"administer","p":"ədˈmɪnɪstə(r)","m":"v.管理，治理；执行，实施","tip":"ad-（= to）+ minister（部长）→ 部长做的 → 管理，治理","ex":["The pension funds are administered by commercial banks.","养老基金由商业银行管理。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"official","p":"əˈfɪʃl","m":"adj.正式的；官方的 n.官员；高级职员","tip":"office n.办公室 → official adj. & n.","ex":["The film's official website is also very informative.","电影官网也很有信息量。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"officer","p":"ˈɒfɪsə(r)","m":"n.军官；官员；高级职员","tip":"","ex":["It was shot to death by a police officer.","它被一名警官开枪击毙。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"minister","p":"ˈmɪnɪstə(r)","m":"n.大臣，部长；牧师 v.当牧师","tip":"mini（小的）+ -(e)st（最高级词尾）+ -er（表示人的后缀）→ 在古代，在皇帝面前自称“小人（微臣）”的人通常是“大臣”。","ex":["She became minister of education in 2016.","她于 2016 年成为教育部长。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"ministry","p":"ˈmɪnɪstri","m":"n.（政府的）部","tip":"","ex":["The Ministry of Transport maintains that speed limits reduce accidents.","交通运输部认为限速可以减少交通事故。"],"lesson":"u02-l04","group":"“政府机构”相关"},{"w":"minor","p":"ˈmaɪnə(r)","m":"adj.较小的，次要的 n.未成年人；辅修课程 v.辅修","tip":"","ex":["He received a minor injury in the Iditarod Race.","他在艾迪塔罗德比赛中受了轻伤。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"minus","p":"ˈmaɪnəs","m":"adj.负的；负面的，不利的 prep.减","tip":"","ex":["Seven minus three is four.","7 减 3 等于 4。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"lead","p":"liːd","m":"v.引领，引导；带路；导致；过（生活） n.领先地位；实例","tip":"","ex":["It often leads to innovations in other related fields.","它往往会促成其他相关领域的创新。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"leading","p":"ˈliːdɪŋ","m":"n.行距（印刷文本两行之间的距离）","tip":"","ex":["She started the last lap just behind the leading group.","她开始跑最后一圈时紧跟在领先的一组人后面。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"mislead","p":"ˌmɪsˈliːd","m":"v.误导；引入歧途；使误信","tip":"mis-（错误，坏）+ lead（引导）→ 误导","ex":["It misleads people to rely on sunscreen for protection.","它误导人们依赖防晒霜来防护。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"misunderstand","p":"ˌmɪsʌndəˈstænd","m":"v.误解；误会","tip":"","ex":["Don't misunderstand me—I am grateful for all you've done.","别误解我的意思，我对你所做的一切都很感激。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"misfortune","p":"mɪsˈfɔːtʃuːn","m":"n.厄运，不幸；不幸的事故（或情况、事件）","tip":"mis-（错误，坏）+ fortune（运气）→ 厄运，不幸","ex":["They all experienced terrible misfortunes.","他们都经历了可怕的不幸事件。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"doom","p":"duːm","m":"n.毁灭；厄运 v.注定（失败、毁灭等）","tip":"doo（音似“赌”）+ m（联想“命”）→ 赌徒赌命，“注定”最后会被“毁灭”。","ex":["Despite these poor figures, it's not all doom and gloom.","尽管这些数字很糟糕，但还不至于说一点希望都没有。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"fate","p":"feɪt","m":"n.命运；天意；定数","tip":"肥（fat）鹅（e）的命运（fate）就是更快地被端上餐桌。","ex":["We regard these disappointments as a fate.","我们把这些失望视为命运。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"guide","p":"ɡaɪd","m":"n.指南；导游；指导者 v.给某人领路（或导游）；指引","tip":"gui（联想“贵”）+ de（联想“的”）→ 有些“导游”的收费还是很贵的。","ex":["He is a tour guide.","他是一个导游。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"guideline","p":"ˈɡaɪdlaɪn","m":"n.指导方针；行动纲领；准则","tip":"","ex":["Those guidelines are outdated and extremely inadequate.","那些指导方针已经过时，而且极不完备。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"compass","p":"ˈkʌmpəs","m":"n.指南针；圆规；界限","tip":"com（联想 come）+ pass（通过）→ 来这里要穿过森林，很容易迷路，所以需要“指南针”。","ex":["We had to rely on a compass and a lot of luck to get there.","我们只得依靠指南针和很大的运气才能到那儿。"],"lesson":"u02-l04","group":"mi(s)相关"},{"w":"count","p":"kaʊnt","m":"v.计数，重要 n.点数；数量；罪状","tip":"co（联想 con-，所有）+ unt（联想 aunt）→ 所有的阿姨都来了，数数有多少个人 → 计数；数量","ex":["It counts less than generally thought.","它没有人们普遍认为的那么重要。"],"lesson":"u03-l01","group":"count 相关"},{"w":"counter","p":"ˈkaʊntə(r)","m":"n.柜台；相对的事物；计算器 v.反驳 adv.相反地","tip":"count（数）+ -er（后缀）→ 算账的人坐在“柜台”里用“计算器”算数。","ex":["It doesn't run counter to the goals of public education.","它并不违背公共教育的目标。"],"lesson":"u03-l01","group":"count 相关"},{"w":"account","p":"əˈkaʊnt","m":"n.账户；账目 v.认为；解释；导致","tip":"ac-（一再地）+ count（数）→ 妈妈一再地数“账户”里有多少钱。","ex":["They account for age differences in learning.","它们解释了学习中的年龄差异。"],"lesson":"u03-l01","group":"count 相关"},{"w":"counterpart","p":"ˈkaʊntəpɑːt","m":"n.相似的人或物","tip":"counter（相对，对应）+ part（部分）→ 相似的人或物","ex":["The Foreign Minister held talks with his Chinese counterpart.","外交部长与中国的同级官员举行了会谈。"],"lesson":"u03-l01","group":"count 相关"},{"w":"encounter","p":"ɪnˈkaʊntə(r)","m":"v. & n.遇见；遭遇","tip":"en-（使……）+ counter（相对）→ 遇见；遭遇","ex":["They may encounter technological problems.","他们可能会遇到技术问题。"],"lesson":"u03-l01","group":"count 相关"},{"w":"discount","p":"ˈdɪskaʊnt","m":"n.折扣 v.打折扣","tip":"dis-（不）+ count（数，计算）→ 不用计算在内的 → 折扣","ex":["Traffic was boosted in America, the home of fast food, with discounts and promotions.","在快餐之乡美国，折扣和促销活动增加了客流量。"],"lesson":"u03-l01","group":"count 相关"},{"w":"coupon","p":"ˈkuːpɒn","m":"n.配给券；优惠券","tip":"单词发音类似“苦盼”→ 我天天苦盼商家多发些“优惠券”来帮我省钱。","ex":["She gets coupons from them regularly.","她经常从他们那里得到优惠券。"],"lesson":"u03-l01","group":"count 相关"},{"w":"payment","p":"ˈpeɪmənt","m":"n.付款；收款；报答","tip":"","ex":["We generally recommend other forms of payment, like credit card.","我们一般建议使用其他付款方式，比如信用卡。"],"lesson":"u03-l01","group":"count 相关"},{"w":"repay","p":"rɪˈpeɪ","m":"v.归还，偿还，清偿","tip":"re-（回）+ pay（付）→ 归还，偿还","ex":["I'll repay the money I owe them next week.","我将在下个星期偿还欠他们的钱。"],"lesson":"u03-l01","group":"count 相关"},{"w":"bill","p":"bɪl","m":"n.账单；议案","tip":"bi-（两个，两）+ ll（联想“两张薄纸”）→ 我收到两页“账单”。","ex":["If a home generates more power than it uses, the bill is zero.","如果一个家庭产生的电比它使用的多，那么账单为零。"],"lesson":"u03-l01","group":"count 相关"},{"w":"loan","p":"ləʊn","m":"n.贷款","tip":"单词发音类似“楼”→ 一般人买楼房需要“贷款”。","ex":["Often there'll be a car loan and perhaps a mortgage.","通常会有汽车贷款，也许还有抵押贷款。"],"lesson":"u03-l01","group":"count 相关"},{"w":"debt","p":"det","m":"n.债务，欠款","tip":"单词发音类似“贷它”→ 他向银行贷款后，有了“债务”。","ex":["They are finally clear of debt.","他们终于偿清了债务。"],"lesson":"u03-l01","group":"count 相关"},{"w":"lawn","p":"lɔːn","m":"n.草坪","tip":"law（联想 lawyer）+ n（形似门）→ 律师家门前有一大片“草坪”。","ex":["In summer we have to mow the lawn twice a week.","夏天我们每周得修剪草坪两次。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"bush","p":"bʊʃ","m":"n.灌木；灌木丛；矮树","tip":"单词发音类似“布什”→ 布什家后院种了许多“灌木”。","ex":["She was hiding in the bushes at the side of the lane.","她躲在道边的灌木丛中。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"brush","p":"brʌʃ","m":"n.刷子；画笔 v.（用刷子）涂；抹","tip":"bush（音似“布什”）+ r（形似花）→ 布什用“画笔”画了一幅以花为主题的画。","ex":["Brush the pastry with beaten egg.","用刷子把打匀的鸡蛋抹在油酥面团上。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"flush","p":"flʌʃ","m":"n. & v.脸红；冲洗","tip":"单词发音类似“服了师”→ 他上课不听话，被老师批评了一顿，服了老师，并且羞愧地“脸红”了。","ex":["There was a flush on her cheeks.","她满脸通红。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"splash","p":"splæʃ","m":"n.落水声；溅洒后留下的污渍 v.把（水、泥等）溅在……上","tip":"电影《美人鱼》（Splash）里的美人鱼扑通一声跳进海里，海水飞溅→落水声","ex":["My clothes were splashed with mud.","我衣服上溅满了泥。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"jungle","p":"ˈdʒʌŋɡl","m":"n.丛林，密林；杂草丛生的地方","tip":"单词发音类似“夹勾”→ 如果你在“丛林”行进，很容易被夹住脚或勾住衣服。","ex":["The elephant was able to return to the jungle.","大象得以回到丛林。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"weed","p":"wiːd","m":"n.杂草，野草","tip":"wee（音似 we）+ d（联想“的”）→ 我们的花园荒废已久，里面长满了“杂草”。","ex":["The yard was overgrown with weeds.","这座庭院杂草丛生。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"hay","p":"heɪ","m":"n.（用作饲料的）干草","tip":"ha（联想“哈”）+ y（联想“爷”）→ 哈！爷爷正在用“干草”喂牲畜。","ex":["He drove by with a big load of hay.","他开着装满干草的车过去了。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"field","p":"fiːld","m":"n.田；地；领域 adj.实地的；野外的","tip":"单词发音类似“肥沃的”→ 这里有一块肥沃的田“地”。","ex":["Great innovators are good at connecting concepts from various academic fields.","伟大的创新者善于将不同学术领域的概念联系起来。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"grasp","p":"ɡrɑːsp","m":"n. & v.抓住，抓紧；理解，领会","tip":"gras（联想 grass）+ p（联想“趴”）→ 他趴在草地上，“抓住”一撮草。","ex":["It takes great efforts for children to grasp the concept of number words.","儿童掌握数字单词的概念需要付出很大的努力。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"grab","p":"ɡræb","m":"n. & v.抓住；抓取","tip":"gr（联想“官人”）+ a（音似“爱”）+ b（联想“宝”）→ 官人爱一个人就要“抓住”她的心，把她视为珍宝。","ex":["She grabbed his arm as he got up to leave.","他起身离开时，她抓住了他的胳膊。"],"lesson":"u03-l01","group":"“草”相关"},{"w":"above","p":"əˈbʌv","m":"prep. & adv.在……上面；超过 adj.上述的","tip":"","ex":["It was built above the sea-water.","它建在海水之上。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"bottom","p":"ˈbɒtəm","m":"n.底部；底面；（容器内的）底 adj.底部的；最后的","tip":"bo（形似 60）+ t + tom（联想“汤姆”，名字）→ 盒子“底部”画了 60 只汤姆猫。","ex":["The idea that those at the bottom can rise to the top is central to America's ideas about itself.","美国自我认知的核心便是社会底层的人有机会跃居社会顶层。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"button","p":"ˈbʌtn","m":"n.按钮；纽扣","tip":"单词发音类似“爸吞”→ 爸爸小时候很调皮，曾吞下过一颗“纽扣”。","ex":["Adam pressed a button and waited for the lift.","亚当按了一个按钮，然后等着乘坐电梯。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"beneath","p":"bɪˈniːθ","m":"prep.在（或往）……下面，在（或往）……下方","tip":"单词发音类似“币泥石”→ 他把钱币藏在泥土和石块的“下面”。","ex":["The city was spread out beneath us in all its glory.","这座城市绚丽多彩地展现在我们下方。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"underneath","p":"ˌʌndəˈniːθ","m":"adv.在下面，在底下 prep.在……下面 n.底部","tip":"","ex":["The coin rolled underneath the piano.","硬币滚到了钢琴底下。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"undergo","p":"ˌʌndəˈɡəʊ","m":"v.经历，经受（变化、不快的事等）","tip":"under（下面）+ go（走）→ 人要是总走在别人的下面，过得不如别人，就可能“经受”冷嘲热讽。","ex":["They had to undergo 2-3 physical checkups.","他们必须接受 2~3 次身体检查。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"experience","p":"ɪkˈspɪəriəns","m":"n.经历；经验 v.经受；感受","tip":"","ex":["Desiring new experiences can help to renovate the brain.","渴望新的体验可以帮助大脑更新。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"endure","p":"ɪnˈdjʊə(r)","m":"v.忍受；持续","tip":"单词发音类似“硬度”→ 人的意志像钢铁般坚硬，能“忍受”一切磨难。","ex":["These people are usually unable or unprepared to endure the long haul.","这些人通常无法或没有准备好忍受长途跋涉。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"durable","p":"ˈdjʊərəbl","m":"adj.持久的；耐用的","tip":"","ex":["These containers were really durable, lasting years on end.","这些容器真的很耐用，可以连续使用数年。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"duration","p":"djuˈreɪʃn","m":"n.持续时间；期间","tip":"","ex":["The average duration of unemployment for older people was 53 weeks.","老年人的平均失业持续时间为 53 周。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"session","p":"ˈseʃ(ə)n","m":"n.会议；（某项活动的）一段时间；学年","tip":"单词发音类似“塞心”→ 一想到每周五下午开会，就觉得心塞→会议","ex":["Participants will have the opportunity to attend sessions on a wide variety of topics.","参与者将有机会参加各种主题的会议。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"span","p":"spæn","m":"n.期间；持续时间；跨度 v.（时间）持续；横跨","tip":"s（联想“美女”）+ pan（音似“盼”）→ 美女盼望着考研成功，让人生能有一个新的“跨度”。","ex":["Their attention span cannot be expanded.","他们的注意力持续时间无法延长。"],"lesson":"u03-l01","group":"“方位”相关"},{"w":"suffer","p":"ˈsʌfə(r)","m":"v.（因疾病、痛苦、悲伤等）受苦，受折磨；遭受，忍受","tip":"单词发音类似“仨佛”→ 一个和尚挑水喝，两个和尚抬水喝，三个和尚没水喝→受苦；遭受","ex":["But while catchings at sea have suffered, fish-farming has been growing at a fast rate.","虽然海上捕捞受到了影响，但渔业一直在快速发展。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"beard","p":"bɪəd","m":"n.胡须","tip":"bear（熊）+ d（联想“的”）→ 熊的“胡须”很长。","ex":["I didn't recognize him—he's grown a beard.","我没认出他来——他留胡子了。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"infer","p":"ɪnˈfɜː(r)","m":"v.推测，推论","tip":"in-（里面）+ fer（音似“佛”）→ 佛心里在想什么？我们不知道，只能“推测”。","ex":["What can we infer from the passage about the author?","从文章中我们可以推断出关于作者的什么？"],"lesson":"u03-l01","group":"fer 相关"},{"w":"refer","p":"rɪˈfɜː(r)","m":"v.提到；涉及","tip":"re-（重复）+ fer（音似“佛”）→ 谈话时，他们重复“提到”佛。","ex":["The report refers to this as the coming of the \"18-hour city\".","该报告称这是“18 小时城市”的到来。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"concern","p":"kənˈsɜːn","m":"v.影响；涉及；使担忧 n.忧虑；关心","tip":"con-（所有）+ cern（音似“心”）→ 妈妈所有的心思都在你身上，她非常“关心”你。","ex":["Their top concern is not that they work too much but that they work too little.","他们最关心的不是工作太多，而是工作太少。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"conference","p":"ˈkɒnfərəns","m":"n.会议，商讨会","tip":"con-（所有）+ fer（音似“佛”）+ -ence（名词后缀）→ 有人建议召集所有的佛来参加“会议”，商讨如何降服孙悟空。","ex":["Debating scientific issues at a conference is now old-fashioned.","在会议上辩论科学问题现在已经过时了。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"fertile","p":"ˈfɜːtaɪl","m":"adj.能结果的；肥沃的","tip":"单词发音类似“佛头”→《西游记》里结出佛头一样人参果的土地是“肥沃的”。","ex":["Forests are eating away the fertile farmland worldwide.","森林正在吞噬全世界肥沃的农田。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"prefer","p":"prɪˈfɜː(r)","m":"v.更喜欢","tip":"","ex":["Hundreds of studies show that infants prefer novelty.","数百项研究表明，婴儿喜欢新奇事物。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"indifferent","p":"ɪnˈdɪfrənt","m":"adj.冷漠的，不关心的","tip":"in-（不）+ different（不同，有差异）→ 他觉得这件事对他不会产生什么差异，所以露出一副“冷漠的”表情。","ex":["Man appears indifferent to what happens in nature.","人类似乎对自然界发生的事情漠不关心。"],"lesson":"u03-l01","group":"fer 相关"},{"w":"skyline","p":"ˈskaɪlaɪn","m":"n.轮廓线；天际线","tip":"sky（天空）+ line（线）→ 天际线","ex":["We are attracted by the skyline of the distant mountains.","我们被远山的轮廓线所吸引。"],"lesson":"u03-l01","group":"line 相关"},{"w":"outline","p":"ˈaʊtlaɪn","m":"n.轮廓，外形；梗概 v.概述；勾勒","tip":"out（外面）+ line（线）→ 外部线条 → 轮廓","ex":["She drew the figures in outline.","她简略地勾勒出人物的轮廓。"],"lesson":"u03-l01","group":"line 相关"},{"w":"online","p":"ˌɒnˈlaɪn","m":"adj.在线的，联网的；线上的","tip":"","ex":["Online classes began to be popularized just a few decades ago.","在线课程在几十年前才开始普及。"],"lesson":"u03-l01","group":"line 相关"},{"w":"underline","p":"ˌʌndəˈlaɪn","m":"v.在（词语等下）画线；强调，重视","tip":"under（下面）+ line（线）→ 在（词语等）下面画线，引申为“强调，重视”。","ex":["It underlined Italy's global reputation as a good steward of art and culture.","它强调了意大利作为艺术和文化的优秀管理者在全球的声誉。"],"lesson":"u03-l01","group":"line 相关"},{"w":"headline","p":"ˈhedlaɪn","m":"n.（报纸的）大字标题，头条；（电视或无线电广播的）新闻摘要","tip":"head（头）+ line（行）→ 一篇文章头上的那行字，就是“大字标题”或“头条”。","ex":["Some of the world's most significant problems never hit headlines.","世界上一些最重要的问题从未上过头条新闻。"],"lesson":"u03-l01","group":"line 相关"},{"w":"deadline","p":"ˈdedlaɪn","m":"n.截止日期，最终期限","tip":"dead（死）+ line（线）→ 最后的那条线 → 截止日期","ex":["He cannot finish his assignment before the deadline.","他不能在最后期限前完成他的任务。"],"lesson":"u03-l01","group":"line 相关"},{"w":"layout","p":"ˈleɪaʊt","m":"n.布局，布置；设计；安排","tip":"lay（放置）+ out（外面）→ 放置在外面 → 布局","ex":["The typical supermarket layout has barely changed over the past 90 years.","过去 90 年里，典型的超市布局几乎没有改变。"],"lesson":"u03-l01","group":"line 相关"},{"w":"undermine","p":"ˌʌndəˈmaɪn","m":"v.逐渐削弱（信心、权威等）；（暗中）破坏","tip":"under（下面）+ mine（矿井）→ 敌人躲在矿井的下面搞“破坏”。","ex":["The passing cruise ships will undermine the foundations of the ancient buildings in Venice.","过往的游轮将会破坏威尼斯古建筑的地基。"],"lesson":"u03-l01","group":"line 相关"},{"w":"determine","p":"dɪˈtɜːmɪn","m":"v.查明；决定；支配，影响","tip":"de（音似“弟”）+ ter（音似“特”）+ mine（矿井）→ 弟弟特意躲在矿井里，终于“查明”是谁在暗中搞破坏。","ex":["There are a few things you can do to determine whether or not a company is a good fit for you.","你可以做一些事情来确定一家公司是否适合你。"],"lesson":"u03-l01","group":"line 相关"},{"w":"deteriorate","p":"dɪˈtɪəriəreɪt","m":"v.恶化；退化","tip":"de（音似“弟”）+ teri（联想“特日”）+ o（形似矿井）+ rate → 在这特别的日子，弟弟仍然心系矿井土地“退化”问题。","ex":["Our interaction skills deteriorate.","我们的互动技能退化了。"],"lesson":"u03-l01","group":"“坏”相关"},{"w":"spoil","p":"spɔɪl","m":"v.破坏，毁掉；溺爱 n.赃物；战利品","tip":"s（联想“蛇”）+ p（联想“扑”）+ oil（油）→ 蛇扑到油桶里，一桶油就这样被“毁掉”了。","ex":["Our camping trip was spoiled by bad weather.","天气不好，破坏了我们的露营计划。"],"lesson":"u03-l01","group":"“坏”相关"},{"w":"boil","p":"bɔɪl","m":"v.煮沸；烧开","tip":"单词发音类似“爆油”→“煮沸”水时油意外入锅，引发了爆油。","ex":["Watch paint dry or water boil, and you might unlock your next big idea.","看着油漆变干或水烧开，你可能会解锁下一个大创意。"],"lesson":"u03-l01","group":"“坏”相关"},{"w":"ruin","p":"ˈruːɪn","m":"v.毁坏；毁灭 n.毁灭；破坏","tip":"ru（音似“辱”）+ in（里面）→ 一直把别人的辱骂记在心里，就是在“毁灭”自己。","ex":["I don't want to ruin the story for you.","我不想破坏你要听的这个故事。"],"lesson":"u03-l01","group":"“坏”相关"},{"w":"destroy","p":"dɪˈstrɔɪ","m":"v.毁坏，破坏；消灭","tip":"单词发音类似“弟死戳”→ 如果弟弟很很地戳一个物体，他就是在“破坏”它。","ex":["Many facilities were destroyed by a wandering cow.","许多设施被一头游荡的奶牛破坏了。"],"lesson":"u03-l01","group":"“坏”相关"},{"w":"decay","p":"dɪˈkeɪ","m":"n. & v.衰退，衰减；腐烂","tip":"单词发音类似“低开”→ 经济在“衰退”，股市每天低开。","ex":["The landlord had let the building fall into decay.","房东任由房子变得破烂不堪。"],"lesson":"u03-l01","group":"“坏”相关"},{"w":"decade","p":"ˈdekeɪd","m":"n.十年，十年期","tip":"de（联想“弟”）+ cade（音似“划的”）→ 小时候弟弟在他脸上划（抓）了一道伤痕，“十年”后疤痕还在。","ex":["The reading culture was seriously affected by cable television some four decades ago.","大约四十年前，阅读文化受到了有线电视的严重影响。"],"lesson":"u03-l01","group":"“坏”相关"},{"w":"outcome","p":"ˈaʊtkʌm","m":"n.结果；效果","tip":"","ex":["In my opinion, the outcome of the game shouldn't matter most.","在我看来，比赛的结果不应是最重要的。"],"lesson":"u03-l02","group":"out 相关"},{"w":"outbreak","p":"ˈaʊtbreɪk","m":"n.（暴力、疾病等坏事的）爆发，突然发生","tip":"out（出来）+ break（打破）→ 打破出来 → 爆发","ex":["Outbreaks of rain are expected in the afternoon.","下午将有暴雨。"],"lesson":"u03-l02","group":"out 相关"},{"w":"breakthrough","p":"ˈbreɪkθruː","m":"n.重大进展，突破 adj.突破性的","tip":"break（打破）+ through（穿过）→ 科学研究要打破一些固有的思维定式，才能穿过重重障碍，取得“重大进展”。","ex":["It could be the breakthrough we've been looking for.","这可能就是我们一直寻求的突破。"],"lesson":"u03-l02","group":"out 相关"},{"w":"outlet","p":"ˈaʊtlet","m":"n.出口；经销店；发泄方式；表现机会","tip":"out（出来）+ let（让）→ 让……出来 → 出口","ex":["Lion dance provides a creative outlet.","舞狮提供了一种创造性的表现机会。"],"lesson":"u03-l02","group":"out 相关"},{"w":"outlook","p":"ˈaʊtlʊk","m":"n.观点；前景；景色","tip":"out（向外）+ look（看）→ 他向外看到了美丽的“景色”。","ex":["He has a much rosier outlook on the future of AI.","他对人工智能的前景更加乐观。"],"lesson":"u03-l02","group":"out 相关"},{"w":"output","p":"ˈaʊtpʊt","m":"n.（人、机器、机构的）产量，输出量 v.输出","tip":"out（向外）+ put（放）→ 产量，输出量","ex":["Focusing on output alone can have unintended consequences.","只关注产出可能会产生意想不到的后果。"],"lesson":"u03-l02","group":"out 相关"},{"w":"overcome","p":"ˌəʊvəˈkʌm","m":"v.克服，战胜","tip":"over（超过）+ come（到达）→ 超过到达，引申为“克服”。","ex":["Focusing on effort is effective in helping children overcome frustration.","专注于努力对帮助孩子克服挫折是有效的。"],"lesson":"u03-l02","group":"over 相关"},{"w":"overlook","p":"ˌəʊvəˈlʊk","m":"v.俯视；忽略","tip":"over（上面）+ look（看）→ 俯视","ex":["The wide diversity of Asian Americans was overlooked.","亚裔美国人的广泛多样性被忽视了。"],"lesson":"u03-l02","group":"over 相关"},{"w":"overnight","p":"ˌəʊvəˈnaɪt","m":"adj.忽然的；夜间的","tip":"","ex":["How did she become rich overnight?","她是如何一夜暴富的？"],"lesson":"u03-l02","group":"over 相关"},{"w":"overtake","p":"ˌəʊvəˈteɪk","m":"v.超过；赶上","tip":"over（上面）+ take（拿）→ 从上面拿走 → 超过；赶上","ex":["He pulled out to overtake a truck.","他驶出车流，以超过一辆卡车。"],"lesson":"u03-l02","group":"over 相关"},{"w":"overtime","p":"ˈəʊvətaɪm","m":"n.加班","tip":"over（超过）+ time（时间）→ 加班","ex":["He thinks he deserves extra pay for overtime.","他认为他应该得到加班费。"],"lesson":"u03-l02","group":"over 相关"},{"w":"overdue","p":"ˌəʊvəˈdjuː","m":"adj.（到期）未付的，未做的；延误的","tip":"over（超过）+ due（到期的）→ 延误的","ex":["My library books are a week overdue.","我借图书馆的书过期一个星期了。"],"lesson":"u03-l02","group":"over 相关"},{"w":"overhear","p":"ˌəʊvəˈhɪə(r)","m":"v.偶然听到，无意中听到","tip":"over（超过）+ hear（听）→ 超越正常的听力范围 → 无意中听到","ex":["The patient overheard the news that he was seriously ill.","病人无意中听到了他病情严重的消息。"],"lesson":"u03-l02","group":"over 相关"},{"w":"overwhelm","p":"ˌəʊvəˈwelm","m":"v.淹没；压倒","tip":"over（上面）+ whel（联想 wheel）+ m（联想 man）→ 时代的车轮从人身上压过，把人“压倒”了。","ex":["Obese people would be overwhelmed with anxiety.","肥胖的人会被焦虑淹没。"],"lesson":"u03-l02","group":"over 相关"},{"w":"undertake","p":"ˌʌndəˈteɪk","m":"v.承担；从事","tip":"under（下面）+ take（拿）→ 在下面拿，引申为“承担”。","ex":["The way chores are undertaken around the world may change people's thinking.","世界各地做家务的方式可能会改变人们的想法。"],"lesson":"u03-l02","group":"over 相关"},{"w":"overall","p":"ˌəʊvərˈɔːl","m":"adj.全面的，综合的 adv.总计；总体上","tip":"over（上面）+ all（所有的）→ 总体上","ex":["The public overall is split on whether they'd like to use a driverless car.","对于是否愿意使用无人驾驶汽车，公众总体上存在分歧。"],"lesson":"u03-l02","group":"over 相关"},{"w":"altogether","p":"ˌɔːltəˈɡeðə(r)","m":"adv.完全；总共；总之","tip":"","ex":["Google aims to save you from the thirst of curiosity altogether.","谷歌的目标是让你完全摆脱好奇心的渴望。"],"lesson":"u03-l02","group":"over 相关"},{"w":"gather","p":"ˈɡæðə(r)","m":"v.收集；聚集；增加","tip":"","ex":["The kids were gathered together in one room.","孩子们被聚集在一个房间里。"],"lesson":"u03-l02","group":"over 相关"},{"w":"headquarters","p":"ˌhedˈkwɔːtəz","m":"n.司令部；总部","tip":"head（头）+ quarter（四分之一）+ s → 只有排名在前四分之一的人，才能进入“总部”。","ex":["Taxes are low, so many businesses have their headquarters here.","这里的税收很低，所以很多企业都把总部设在这里。"],"lesson":"u03-l02","group":"over 相关"},{"w":"quarter","p":"ˈkwɔːtə(r)","m":"n.四分之一；季度；十五分钟 v.分为四份","tip":"","ex":["One quarter of teachers in an American city said that children in kindergartens had no time for playing freely.","美国一座城市四分之一的教师表示，幼儿园的孩子没有时间自由玩耍。"],"lesson":"u03-l02","group":"over 相关"},{"w":"beforehand","p":"bɪˈfɔːhænd","m":"adv.预先，事先","tip":"before（前面）+ hand（手）→ 事先","ex":["People often fail to programme their routines beforehand.","人们往往不能事先安排好他们的日常工作。"],"lesson":"u03-l02","group":"over 相关"},{"w":"ready","p":"ˈredi","m":"adj.准备好的；已完成的；方便使用的 adv.已做完；已完成","tip":"","ex":["Frozen fruit will be ready by morning.","冷冻水果会在早上准备好。"],"lesson":"u03-l02","group":"over 相关"},{"w":"so-called","p":"ˌsəʊ ˈkɔːld","m":"adj.所谓的","tip":"","ex":["How have these so-called improvements helped the local community?","这些所谓的进步对当地社会有什么帮助呢？"],"lesson":"u03-l02","group":"over 相关"},{"w":"corrupt","p":"kəˈrʌpt","m":"v.使腐化，使堕落；破坏 adj.贪污的，腐败的","tip":"单词发音类似“可抓捕他”→ 警察可抓捕“腐败的”人。","ex":["He was corrupted by power and ambition.","权力与野心使他腐化堕落。"],"lesson":"u03-l02","group":"rupt 相关"},{"w":"bribe","p":"braɪb","m":"v.贿赂，向……行贿 n.贿赂","tip":"新娘（bride）贿赂（bribe）马夫，骑马离开了。","ex":["Bribing the boss is punishable.","贿赂老板是应受到惩罚的。"],"lesson":"u03-l02","group":"rupt 相关"},{"w":"bankrupt","p":"ˈbæŋkrʌpt","m":"n.破产者 adj.破产的；完全丧失的","tip":"bank（银行）+ rupt（= break，断裂）→ 银行（资金链）断裂 → 破产的","ex":["Her business went bankrupt while she was in prison.","她在监狱期间，她的生意破产了。"],"lesson":"u03-l02","group":"rupt 相关"},{"w":"deficit","p":"ˈdefɪsɪt","m":"n.赤字，逆差，亏损","tip":"de（联想“弟”）+ fi（音似“非”）+ ci（音似“撕”）+ t（联想“他”）→ 弟弟开的公司出现非常严重的“亏损”，他气得撕了财务报表。","ex":["It will help many African countries reduce trade deficits.","它将帮助许多非洲国家减少贸易赤字。"],"lesson":"u03-l02","group":"rupt 相关"},{"w":"disrupt","p":"dɪsˈrʌpt","m":"v.扰乱；分裂，瓦解；中断；彻底改变结构","tip":"dis-（分开）+ rupt（断裂）→ 分裂","ex":["The global economy continues to be disrupted by technology and other massive change.","全球经济持续被技术和其他巨大的变化所扰乱。"],"lesson":"u03-l02","group":"rupt 相关"},{"w":"interrupt","p":"ˌɪntəˈrʌpt","m":"v.打断；打扰；使暂停","tip":"inter-（中间）+ rupt（断裂）→ 在中间断裂 → 打断","ex":["Please do not interrupt the speaker.","请不要打断讲话者。"],"lesson":"u03-l02","group":"rupt 相关"},{"w":"desert","p":"ˈdezət","m":"v.离开；抛弃","tip":"单词发音类似“弟舍它”→ 弟弟把它舍弃了 → 抛弃","ex":["They are deserted by their family.","他们被家人抛弃了。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"dessert","p":"dɪˈzɜːt","m":"n.（饭后）甜点，甜食","tip":"一个人不要去沙漠（desert）玩，那里的蛇会把你当甜点（dessert）吃掉的。","ex":["He learned his trade from a famous dessert chef in Paris.","他是从巴黎一位著名的甜点师那里学来的手艺。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"insert","p":"ɪnˈsɜːt","m":"v.插入，嵌进","tip":"in-（向内）+ sert（加入）→ 插入","ex":["Insert coins into the slot and press for a ticket.","把硬币放进投币口，按钮取票。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"dump","p":"dʌmp","m":"n.垃圾场；废物堆 v.扔下；倾倒；丢弃","tip":"单词发音类似“当铺”→ 有人会把不经常用的东西放到当铺里当点钱 → 丢弃","ex":["Everything that goes into the dumps might be made into something useful.","所有进入垃圾场的东西都有可能会被做成有用的东西。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"discard","p":"dɪˈskɑːd","m":"v.丢弃，抛弃","tip":"dis-（不）+ card（纸牌）→ 不要纸牌 → 丢弃，抛弃","ex":["Beverage companies should be responsible for collecting and reusing discarded plastic soda bottles.","饮料公司应该负责收集和重新使用丢弃的塑料汽水瓶。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"junk","p":"dʒʌŋk","m":"n.无用的东西，无价值的东西 v.丢弃，废弃，扔","tip":"单词发音类似“夹克”→ 妈妈认为这件夹克是“无用的东西”，于是“丢弃”了它。","ex":["There's nothing but junk on the TV.","电视上全是些无聊的东西。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"trash","p":"træʃ","m":"n.垃圾，废物 v.损坏","tip":"单词发音类似“揣洗”→ 一双“垃圾”一样的臭袜子，他竟然还揣回宿舍洗。","ex":["One person's trash is another's treasure.","一个人的垃圾可能是另一个人的宝藏。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"abolish","p":"əˈbɒlɪʃ","m":"v.废除；取消","tip":"a（—）+ bolish（音似“暴力史”）→ “废除”这一酷刑，终结暴力史。","ex":["Slavery was abolished in America in the 19th century.","美国在19世纪废除了奴隶制。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"abuse","p":"əˈbjuːs","m":"n.滥用；虐待；辱骂","tip":"ab-（否定前缀）+ use（使用）→ 不正常的使用 → 滥用","ex":["That may lead to nursing home abuse and age discrimination.","那可能会导致养老院虐待和年龄歧视。"],"lesson":"u03-l02","group":"“丢弃”相关"},{"w":"clash","p":"klæʃ","m":"n.冲突；不协调；撞击声 v.冲突；争论","tip":"cl（联想“可来”）+ ash（灰）→ 维和部队可来到漫天灰尘的“冲突”现场了。","ex":["Eight people were wounded in a clash with border guards.","在与边防警卫的冲突中有八人受伤。"],"lesson":"u03-l02","group":"“冲击”相关"},{"w":"crash","p":"kræʃ","m":"v.撞车；坠毁 n.撞车事故；失事","tip":"c（联想 car）+ rash（鲁莽的）→ 开车不能太鲁莽，不然会出“撞车事故”的。","ex":["It narrowly escaped a plane crash when turning around.","它转弯时险些撞上飞机。"],"lesson":"u03-l02","group":"“冲击”相关"},{"w":"wreck","p":"rek","m":"n.沉船；失事；交通事故 v.破坏，毁坏","tip":"w（联想“我”）+ re（字母音似“阿姨”）+ ck（联想 CK 品牌）→ 我阿姨的 CK 手表因“交通事故”而被“毁坏”。","ex":["His fishing boat got wrecked on a rock.","他的渔船触礁失事了。"],"lesson":"u03-l02","group":"“冲击”相关"},{"w":"smash","p":"smæʃ","m":"v.打碎，粉碎；猛击","tip":"sm（联想 small）+ ash（废墟）→ 不久前，这个小型建筑被撞了个“粉碎”，成了一片废墟。","ex":["The glass bowl smashed into a thousand pieces.","玻璃碗咣的一声摔了个粉碎。"],"lesson":"u03-l02","group":"“冲击”相关"},{"w":"cash","p":"kæʃ","m":"n.现金；金钱","tip":"单词发音类似“开支”→ 当局需要一大笔开支才能恢复建筑的原貌 → 现金；金钱","ex":["She found it much safer to use cash.","她发现用现金更安全。"],"lesson":"u03-l02","group":"“冲击”相关"},{"w":"ashamed","p":"əˈʃeɪmd","m":"adj.羞愧的，惭愧的","tip":"ash（灰烬）+ a（—）+ me（我）+ d（联想“的”）→ 我的脸上有一点儿灰 → 羞愧的","ex":["He was ashamed of having asked such a silly question.","他为问了这样一个愚蠢的问题而感到羞愧。"],"lesson":"u03-l02","group":"“冲击”相关"},{"w":"dash","p":"dæʃ","m":"v.猛冲，突进；（使）冲撞 n.猛冲，突进；破折号","tip":"单词发音类似“大事”→ 大事不好了，人们“猛冲”过去看发生了什么。","ex":["They dashed into the classroom.","他们冲进了教室。"],"lesson":"u03-l02","group":"“冲击”相关"},{"w":"seal","p":"siːl","m":"v.封上（信封）；密封 n.印章；密封装置","tip":"sea（大海）+ l（形似拉链）→ 在这个神话故事中，他竟然把大海的水用拉链“封上”了。","ex":["My father sealed the bag tightly with sticky tape minutes later.","几分钟之后，我父亲用胶带将袋子牢牢地封住了。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"conceal","p":"kənˈsiːl","m":"v.隐藏；隐瞒；掩盖","tip":"con-（所有）+ ceal（联想 seal）→ 所有的通道都被封上了，才能“隐藏”起来。","ex":["He wanted to conceal something from his parents.","他想对父母隐瞒一些事情。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"reveal","p":"rɪˈviːl","m":"v.揭露，显示；展示","tip":"re-（再）+ veal（联想 real）→ 史学家遍寻典籍，再次还原真相→揭露","ex":["It's important to reveal yourself to friends.","向朋友展示自己是很重要的。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"betray","p":"bɪˈtreɪ","m":"v.泄露；背叛；流露情感","tip":"单词发音类似“背捶”→ 如果一个人“背叛”了你，那你一定捶（打）他的背。","ex":["I could never forgive Mike for betraying a confidence.","迈克泄露了秘密，我决不会饶恕他。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"uncover","p":"ʌnˈkʌvə(r)","m":"v.揭开盖子；揭露；发现","tip":"un-（不）+ cover（覆盖）→ 揭露","ex":["It will be difficult to uncover the truth.","揭开真相会很困难。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"load","p":"ləʊd","m":"n.负载，承载；许多 v.（把大量……）装上","tip":"单词发音类似“楼的”→ 一栋楼“负载”了生活万象。","ex":["The heavy teaching loads left them little time and energy for family life.","沉重的教学负担使他们很少有时间和精力用于家庭生活。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"unload","p":"ˌʌnˈləʊd","m":"v.卸货；取下；取出","tip":"un-（不）+ load（装上）→ 卸货；取下","ex":["He was only responsible for unloading food.","他只负责卸食物。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"unfold","p":"ʌnˈfəʊld","m":"v.打开；呈现；发展，发生","tip":"un-（不）+ fold（折叠）→ 打开","ex":["The audience watched as the story unfolded before their eyes.","观众看着剧情逐渐地展开。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"fold","p":"fəʊld","m":"v.折叠；交叉；倒闭；包裹 n.褶皱；山谷","tip":"父亲（f）老了（old），脸上有褶皱（fold）了。","ex":["Fold the paper in half.","把纸对折起来。"],"lesson":"u03-l02","group":"“掩盖、揭露”相关"},{"w":"substance","p":"ˈsʌbstəns","m":"n.物质；实质；主旨","tip":"sub-（下面）+ st（存在）+ -ance（名词后缀）→ 存在于下面的东西 → 实质","ex":["It was a hard task to remove the spilled substance.","清除溢出物质是一项艰巨的任务。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"instance","p":"ˈɪnstəns","m":"n.例子，实例 v.举……为例","tip":"","ex":["In most instances, there will be no need for further treatment.","多数情况下，不必继续治疗。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"quote","p":"kwəʊt","m":"v.引用，引述 n.原话，引语","tip":"单词发音类似“夸她”→ 当她表现好的时候，我们可以“引用”一些名人名言来夸她。","ex":["He quoted a passage from the minister's speech.","他引用了部长的一段讲话。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"withstand","p":"wɪðˈstænd","m":"v.承受，抵住","tip":"with-（对抗）+ stand（站立）→ 用站立的方式去对抗 → 承受","ex":["They can withstand a drier, warmer climate.","它们能够承受更干燥、更温暖的气候。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"withdraw","p":"wɪðˈdrɔː","m":"v.（使）撤回，收回；提，取（银行账户中的款）","tip":"with-（向后）+ draw（拉）→ 撤回","ex":["He had withdrawn all the money from their joint account.","他已经从他们的联名账户中取出了所有的钱。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"drawer","p":"drɔː(r)","m":"n.抽屉","tip":"draw v.拖，拉 → drawer n.","ex":["I found some old photos at the back of the drawer.","我从抽屉尽里头找到一些旧照片。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"fetch","p":"fetʃ","m":"v.（去）拿来；（去）请来","tip":"单词发音类似“饭吃”→ 在食堂吃饭的时候要自己“拿来”餐品。","ex":["Ask a clerk to fetch items from behind a counter.","让店员从柜台后面拿东西。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"distant","p":"ˈdɪstənt","m":"adj.有距离的；遥远的；不同的","tip":"di-（两）+ stan（联想 stand）+ t → 两个人分开站 → 有距离的；遥远的","ex":["They see a day in the not-too-distant future when all autos will be abandoned and allowed to rust.","他们认为，在不远的将来，所有的汽车都将被抛弃，任其生锈。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"constant","p":"ˈkɒnstənt","m":"adj.不断的；重复的；固定的，不变的","tip":"con-（所有）+ stan（联想 stand）+ t → 所有人都站在他身边，掌声“不断”响起。","ex":["Indoor pollution has remained constant over the past several decades.","在过去的几十年里，室内污染仍然没有改变。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"consistent","p":"kənˈsɪstənt","m":"adj.连续的；一贯的，一致的","tip":"con-（所有）+ sist（= stand）+ -ent（形容词后缀）→ 所有人站在一起的 → 一致的","ex":["We must be consistent in applying the rules.","我们在实施这些规则时必须保持一贯性。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"instant","p":"ˈɪnstənt","m":"n.瞬间，顷刻 adj.立即的；速溶的","tip":"in（里面）+ stan（联想 stand）+ t（联想“他”）→ 他站在接机大厅里，见朋友出来立刻迎了上去 → 立即的","ex":["Only a few months later Leah opened her first yoga studio, but success was not instant.","仅仅几个月后，利亚开设了她的第一家瑜伽馆，但成功不是一蹴而就的。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"instantaneous","p":"ˌɪnstənˈteɪniəs","m":"adj.瞬间的，即时的","tip":"","ex":["The Internet is remarkable for the almost instantaneous speed at which it transmits information.","互联网的显著特征就在于其传送信息的瞬时速度。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"immediate","p":"ɪˈmiːdiət","m":"adj.立刻的，即时的；（地方）紧邻的","tip":"","ex":["We must make an immediate response.","我们必须立即作出反应。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"prompt","p":"prɒmpt","m":"adj.立即的，及时的 v.促使，导致；激励","tip":"pro-（向前）+ m（联想“妹”）+ pt（联想“扑他”）→ 妹妹看到哥哥，立即扑向他 → 立即的","ex":["Professors can give prompt feedback to students' homework.","教授可以对学生的家庭作业给予及时的反馈。"],"lesson":"u03-l03","group":"stan 相关"},{"w":"constitute","p":"ˈkɒnstɪtjuːt","m":"v.组成，构成；设立","tip":"con-（所有）+ stitu（= stand）+ te → 所有人都站在一起，“组成”了一个团队。","ex":["It may constitute a challenge to computer programmers.","它可能对计算机程序员构成挑战。"],"lesson":"u03-l03","group":"stitu 相关"},{"w":"constitution","p":"ˌkɒnstɪˈtjuːʃn","m":"n.宪法，章程","tip":"构成（constitute）一个国家最根本法律的是宪法（constitution），它被称为根本法。","ex":["The British Constitution is to a large extent a product of the historical events described above.","英国宪法在很大程度上是上述历史事件的产物。"],"lesson":"u03-l03","group":"stitu 相关"},{"w":"substitute","p":"ˈsʌbstɪtjuːt","m":"n.替代品；替代者 v.（以……）代替，取代","tip":"sub-（下面）+ stitu（= stand）+ te → 站在场下等待登场的是替补，即“替代者”。","ex":["It substitutes old information with new data.","它用新数据代替旧信息。"],"lesson":"u03-l03","group":"stitu 相关"},{"w":"replace","p":"rɪˈpleɪs","m":"v.代替，取代","tip":"re（字母音似“阿姨”）+ place（位置）→ 阿姨“代替”了这个位置的人。","ex":["It's not likely they will replace traditional textbooks.","它们不太可能取代传统的教科书。"],"lesson":"u03-l03","group":"stitu 相关"},{"w":"institute","p":"ˈɪnstɪtjuːt","m":"n.学院；学会；协会 v.制定；创立","tip":"in（里面）+ stitu（= stand）+ te → 位于大学里面的这座建筑是“学院”楼。","ex":["Individuals can enrol on self-study courses in the university's language institute.","人们可以报名参加这所大学的语言学院的自学课程。"],"lesson":"u03-l03","group":"stitu 相关"},{"w":"institution","p":"ˌɪnstɪˈtjuːʃ(ə)n","m":"n.机构，团体；制度","tip":"","ex":["He has worked as a visiting lecturer for various educational institutions.","他曾在各种教育机构担任客座讲师。"],"lesson":"u03-l03","group":"stitu 相关"},{"w":"separate","p":"ˈsepəreɪt","m":"adj.单独的；不同的","tip":"se（联想“蛇”）+ pa（联想“怕”）+ r（联想“人”）+ -ate（后缀）→ 蛇怕人，所以要与人“分开”。","ex":["The researchers conducted five separate surveys of more than 1,700 people.","研究人员对 1,700 多人进行了五次单独的调查。"],"lesson":"u03-l03","group":"part 相关"},{"w":"sector","p":"ˈsektə(r)","m":"n.部门；领域；行业","tip":"单词发音类似“塞个他”→ 电视剧中，有些人会把亲戚塞到某个“部门”中。","ex":["For the high-tech sector, there are a few other interesting findings.","对于高科技行业，还有其他一些有趣的发现。"],"lesson":"u03-l03","group":"part 相关"},{"w":"section","p":"ˈsekʃn","m":"n.部分；节；阶层；部门","tip":"sec（切）+ -tion（名词后缀）→ 切开的部分 → 部分；部门","ex":["That section of the road is still closed.","那段公路依旧封闭。"],"lesson":"u03-l03","group":"part 相关"},{"w":"segment","p":"ˈsegmənt","m":"n.部分；（水果的）瓣","tip":"seg（分割）+ -ment（后缀）→ 部分；划分","ex":["It is in no one's interest to keep a large segment of the population on the margins of society.","将一大部分人口留在社会边缘不符合任何人的利益。"],"lesson":"u03-l03","group":"part 相关"},{"w":"semester","p":"sɪˈmestə(r)","m":"n.学期","tip":"se（分开）+ me（我）+ ster（联想 sister）→ 这个“学期”我和妹妹分开了，不在同一个班里。","ex":["You took an optional course this semester, didn't you?","你这学期修了一门选修课，不是吗？"],"lesson":"u03-l03","group":"part 相关"},{"w":"term","p":"tɜːm","m":"n.学期；术语；任期","tip":"te（音似“特”）+ rm（联想“任命”）→ 这个“学期”，老师特别任命她当班长。","ex":["Many students now have paid employment during term.","现在许多学生在上学期间就从事有薪工作。"],"lesson":"u03-l03","group":"part 相关"},{"w":"apart","p":"əˈpɑːt","m":"adv.相隔地，分开地 adj.分离的，隔离的","tip":"a（一）+ part（部分）→ 把整体分成一个个部分 → 分开地","ex":["The thing that sets children apart from adults is not their ignorance, nor their lack of skills.","孩子和成年人的区别不是他们无知，也不是他们缺乏技能。"],"lesson":"u03-l03","group":"part 相关"},{"w":"apartment","p":"əˈpɑːtmənt","m":"n.公寓","tip":"a（一）+ part（部分）+ ment（音似“门”）→ 一扇扇门把“公寓”分成一个个独立的部分。","ex":["The woman is fussy about the cleanness of the apartment.","这个女人对公寓的干净程度很挑剔。"],"lesson":"u03-l03","group":"part 相关"},{"w":"department","p":"dɪˈpɑːtmənt","m":"n.部门；院系","tip":"de-（分开）+ part（部分）+ -ment（名词后缀）→ 把一个机构分成一个个独立的部分，每一个部分就是一个“部门”。","ex":["Companies are abandoning conventional functional departments.","公司正在摒弃传统的职能部门。"],"lesson":"u03-l03","group":"part 相关"},{"w":"particle","p":"ˈpɑːtɪkl","m":"n.微粒；极小量","tip":"part（部分）+ i + cle（音似“抠”）→ 抠下来极小的部分 → 微粒；极小量","ex":["There was not a particle of evidence to support the case.","没有丝毫证据支持这个论点。"],"lesson":"u03-l03","group":"part 相关"},{"w":"depart","p":"dɪˈpɑːt","m":"v.离开，出发；离职","tip":"单词发音类似“弟怕他”→ 弟弟怕他，于是“离开”了。","ex":["Were they to arrive before we depart the day after tomorrow, we should have a wonderful dinner party.","如果他们能在后天我们离开之前到达，我们将举行一个盛大的宴会。"],"lesson":"u03-l03","group":"part 相关"},{"w":"partial","p":"ˈpɑːʃl","m":"adj.部分的，局部的；偏袒的","tip":"part n.部分 → partial adj.","ex":["It is said that the math teacher seems partial towards bright students.","据说那位数学老师似乎偏爱聪明的学生。"],"lesson":"u03-l03","group":"part 相关"},{"w":"prejudice","p":"ˈpredʒədɪs","m":"n.偏见；歧视 v.使有偏见","tip":"pre-（提前）+ judi（联想 Judy，人名）+ ce → 他在见到朱迪前就对她有“偏见”。","ex":["Students of different races are prejudiced against each other.","不同种族的学生彼此有偏见。"],"lesson":"u03-l03","group":"part 相关"},{"w":"bias","p":"ˈbaɪəs","m":"n.偏心，偏见 v.使存偏见；使倾向一方","tip":"bi-（两）+ as（音似“儿子”）→ 她有两个儿子，但从不“偏心”。","ex":["If everyone around you has similar views, your work will suffer from confirmation bias.","如果你周围的每个人都有类似的观点，你的工作就会受到确认偏见的影响。"],"lesson":"u03-l03","group":"part 相关"},{"w":"neutral","p":"ˈnjuːtrəl","m":"adj.中立的；持平的；中性的 n.中立者；中立国","tip":"neu（联想 new）+ tr + -al（后缀）→ 一个单位新来的人一般都是“中立的”。","ex":["Technology is neutral, but people aren't.","技术是中立的，但人不是。"],"lesson":"u03-l03","group":"part 相关"},{"w":"independent","p":"ˌɪndɪˈpendənt","m":"adj.独立的；自主的；公正的；私营的","tip":"in-（不，无）+ depend（依靠）+ -ent（形容词后缀）→ 独立的","ex":["It requires consistent education to be financially independent.","要实现经济独立需要持续的教育。"],"lesson":"u03-l03","group":"part 相关"},{"w":"acute","p":"əˈkjuːt","m":"adj.严重的；敏锐的；急性的","tip":"a（一）+ cute（可爱的）→ 一个可爱孩子得了很严重的病，是急性阑尾炎 → 严重的；急性的","ex":["Boys generally have more acute vision, and learn best through touch.","男孩通常视力更敏锐，通过触摸学习效果最好。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"severe","p":"sɪˈvɪə(r)","m":"adj.十分严重的，极为恶劣的；严峻的","tip":"sever（联想 seven）+ e（出去）→ 七楼以上的人暂时都出不去，因为下面的火情是“十分严重的”。","ex":["This can result in severe penalties that continue long after punishment is completed.","这可能导致严重的惩罚，并在刑罚结束后持续很长时间。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"grave","p":"ɡreɪv","m":"n.墓穴，坟墓 adj.严重的；严肃的","tip":"gr（联想“官人”）+ a（联想“爱”）+ ve（音似“我”）→ 官人发誓会爱我终生，“生同衾，死同穴”→ 墓穴","ex":["There were flowers on the grave.","坟上有些花。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"gravity","p":"ˈɡrævəti","m":"n.严重性；严肃；重力","tip":"","ex":["I don't think you realise the gravity of the situation.","我认为你没有意识到形势的严重性。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"grieve","p":"ɡriːv","m":"v.感到悲痛；使……伤心","tip":"gr（联想“官人”）+ i（字母音似“爱”）+ eve（前夕）→ 深爱她的官人在婚礼前夕去世了，这使她“感到悲痛”。","ex":["The little girl was grieved by the death of her dog.","小女孩的狗狗死了，她很伤心。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"relieve","p":"rɪˈliːv","m":"v.缓解，缓和；减轻","tip":"re（字母音似“阿姨”）+ li（音似“立”）+ eve（联想“夏娃”）→ 阿姨见夏娃很难过，立刻来安慰她，“缓解”她内心的痛苦。","ex":["Survey findings show that knitting can help people relieve stress.","调查结果显示，编织可以帮助人们缓解压力。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"belief","p":"bɪˈliːf","m":"n.相信，信心；信念；看法","tip":"","ex":["We hold the belief that hard work leads to success.","我们坚信努力工作会带来成功。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"believe","p":"bɪˈliːv","m":"v.相信；认定","tip":"","ex":["We believe that tomorrow will be different.","我们相信明天会有所不同。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"grateful","p":"ˈɡreɪtfl","m":"adj.感激的，感谢的","tip":"gr（联想“官人”）+ ate（eat 的过去式）+ ful（联想 full）→ 你收留了官人，让他吃饱，他对你是“感激的”。","ex":["People can be educated to be grateful.","人们可以被教育去感恩。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"grant","p":"ɡrɑːnt","m":"n.拨款 v.授予；准予；承认","tip":"gr（联想“官人”）+ ant（蚂蚁）→ 大雨来临，蚂蚁无处可去，官人就开门让蚂蚁进来 → 准予","ex":["There was a much higher rate of attrition among scientists who didn't get grants.","没有获得资助的科学家人员流失率要高得多。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"grind","p":"ɡraɪnd","m":"v.磨碎；磨光；用力挤压；摩擦","tip":"gr（联想“官人”）+ in（里面）+ d（联想“刀”）→ 官人每天在家里磨刀 → 磨光；摩擦","ex":["Parts of the machine were grinding together noisily.","机器零件摩擦发出刺耳的声音。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"polish","p":"ˈpɒlɪʃ","m":"n.擦光剂；抛光 v.擦亮；磨光","tip":"po（音似“抛”）+ lish（音似“历史”）→ 文学家为历史“抛光”。","ex":["You'll need to give your shoes a good polish.","你有必要把鞋好好擦亮一下。"],"lesson":"u03-l03","group":"“严重的”相关"},{"w":"burst","p":"bɜːst","m":"v.爆炸；突然发生 n.爆炸；突发","tip":"bu（联想“不”）+ r（形似花）+ st（联想 street）→ 街上的人手里都有花，就她没有，她的情绪就爆发了 → 爆炸","ex":["Don't burst that balloon!","别把那气球弄爆了！"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"blast","p":"blɑːst","m":"n.爆炸；一阵（风），一股（气流） v.炸毁","tip":"b（联想“不”）+ last（持续）→ 不持续 → 这种烟花的捻子比较短，点燃后烟花会快速“爆炸”，留下“一股”青烟。","ex":["The blast ripped through the building.","爆炸的气浪席卷了整座大楼。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"blow","p":"bləʊ","m":"v.吹奏（哨子、乐器等）；吹出（某物） n.吹；（用手、武器等的）猛击；挫折","tip":"","ex":["There are ways we could soften the coming blow to the global food supply.","我们有办法减轻即将到来的对全球粮食供应的打击。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"explode","p":"ɪkˈspləʊd","m":"v.爆炸；激增；爆发","tip":"ex-（往外）+ plo（联想爆竹的声音）+ de（往下）→ 放爆竹时，爆竹向外飞出，“爆炸”后又落下来。","ex":["Most were sold in Europe and China, where the bikes already have exploded in popularity.","其中大部分在欧洲和中国销售，这种自行车在两地市场的受欢迎度激增。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"explore","p":"ɪkˈsplɔː(r)","m":"v.勘查；探索；研究","tip":"ex-（往外）+ plo（音似“扑姥”）+ re（字母音似“阿姨”）→ 姥姥和阿姨来做客，你往外扑向她们，想要“探索”那过去的事情。","ex":["Suppose we built a robot to explore the planet Mars.","假设我们制造了一个机器人来探索火星这个星球。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"exploit","p":"ɪkˈsplɔɪt","m":"v.利用；开采，开发","tip":"ex-（往外）+ plo（联想“扑落”）+ it（它）→ 猫咪向外扑落杂物，“开发”了它的专属领地。","ex":["Creating the future you want is a lot easier if you are ready to exploit the opportunities that come your way.","如果你准备好利用你遇到的机会，创造你想要的未来就会容易得多。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"bomb","p":"bɒm","m":"n.炸弹 v.轰炸","tip":"单词发音类似“嘣”→“炸弹”爆炸的时候发出“嘣”的声音。","ex":["A bomb exploded somewhere near.","一颗炸弹在附近爆炸了。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"bump","p":"bʌmp","m":"n.撞击（声）；肿块；隆起 v.（无意地）碰，撞","tip":"单词发音类似“砰”→ 撞击时发出的“砰”声就是“撞击声”；身体受到撞击后可能会产生“肿块”。","ex":["He fell to the ground with a bump.","他砰的一声摔倒在地上。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"bumper","p":"ˈbʌmpə(r)","m":"n.（汽车头尾的）保险杠","tip":"bump（撞击）+ -er（后缀）→ 汽车的“保险杠”就是撞击时承受冲击力的首要部位。","ex":["The bumper of the car needs to be crash-tested.","汽车的保险杠需要进行碰撞测试。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"pump","p":"pʌmp","m":"n.抽水机；泵 v.用泵输送；涌出","tip":"单词发音类似“噗噗”→“抽水机”工作时会发出噗噗声。","ex":["Only recently in California has it become profitable to pump water from this depth.","直到最近，在加利福尼亚州，这一深度抽水才变得有利可图。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"lump","p":"lʌmp","m":"n.块；方糖；肿块；笨重的人","tip":"lum（联想“拉妹”）+ p（联想“扑”）→ 他拉着妹妹扑过去，结果头上撞了个“肿块”。","ex":["Do not turn the salad cream into a solid lump.","不要将沙拉奶油变成固体块。"],"lesson":"u03-l03","group":"“爆炸”相关"},{"w":"shot","p":"ʃɒt","m":"n.射击；枪手；射门；发射","tip":"shoot v.射击；冲；奔 → shot n.","ex":["We heard some shots in the distance.","我们听见远处几声枪响。"],"lesson":"u03-l03","group":"“射击”相关"},{"w":"fire","p":"ˈfaɪə(r)","m":"n.火 v.解雇；开火；射击","tip":"","ex":["She doesn't want to use her name for fear of being fired from her job.","她不想使用自己的名字，因害怕被解雇。"],"lesson":"u03-l03","group":"“射击”相关"},{"w":"hire","p":"ˈhaɪə(r)","m":"v.雇用，租用 n.租借，租用","tip":"hi（嗨）+ re（字母音似“阿姨”）→ 家里“雇用”了阿姨，我热情地跟她打招呼。","ex":["There is a growing tendency among employers to hire casual staff.","雇主雇用临时职员的趋势正在增加。"],"lesson":"u03-l03","group":"“射击”相关"},{"w":"retire","p":"rɪˈtaɪə(r)","m":"v.退休；退出；离开（去安静的地方）","tip":"re（字母音似“阿姨”）+ tire（联想 tired）→ 阿姨累了，不工作了，要提前“退休”。","ex":["The goal was to reach the top, accumulate wealth and retire to a life of ease.","他的目标是登上顶峰，积累财富，退休后过上安逸的生活。"],"lesson":"u03-l03","group":"“射击”相关"},{"w":"employ","p":"ɪmˈplɔɪ","m":"v.雇用；应用，运用，使用","tip":"em-（使）+ ploy（音似“捕捞”）→ 我们想要捕捞一艘沉船，但是人手不够，需要另外“雇用”一些人。","ex":["It is said that all of us employ a mix of both these types of planning.","据说我们所有人都混合使用这两种规划方式。"],"lesson":"u03-l03","group":"“射击”相关"},{"w":"employment","p":"ɪmˈplɔɪmənt","m":"n.工作，职业；受雇；就业","tip":"","ex":["As the world migrant crisis intensifies, employment is becoming a global concern.","随着世界移民危机的加剧，就业正成为一个全球性问题。"],"lesson":"u03-l03","group":"“射击”相关"},{"w":"luxury","p":"ˈlʌkʃəri","m":"n.奢侈品；奢华，华贵","tip":"雷克萨斯（Lexus）是一个奢华（luxury）高端的汽车品牌。","ex":["Saying \"no\" is sometimes seen as a luxury that only those in power can afford.","有时候，说“不”被视为一种奢侈，只有当权者才能负担得起。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"treasure","p":"ˈtreʒə(r)","m":"n.金银财宝，财富；心肝宝贝 v.珍惜，珍视","tip":"单词发音类似“揣掖”→ 那些你揣着、掖着不想被别人看到的东西是你倍加“珍惜”的“心肝宝贝”。","ex":["The destruction of these treasures was a loss for mankind that no amount of money could make up.","这些宝藏的毁灭是人类的损失，再多的钱也无法弥补。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"precious","p":"ˈpreʃəs","m":"adj.珍贵的，珍稀的","tip":"price n.价格 → precious adj.","ex":["It keeps our most precious memories until life's end.","它保存着我们最珍贵的回忆，直到生命的尽头。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"beloved","p":"bɪˈlʌv(ɪ)d","m":"adj.钟爱的；亲爱的；深受喜爱的","tip":"be（被）+ love（喜爱）+ d（音似“的”）→ 深受喜爱的","ex":["Today, he is still one of the best-known and most beloved racehorses of all time.","今天，它仍然是有史以来最著名和最受欢迎的赛马之一。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"cherish","p":"ˈtʃerɪʃ","m":"v.珍爱，钟爱","tip":"che（联想“车”）+ ri（联想“日”）+ sh（联想“洗”）→ 他每天都洗爱车 → 珍爱，钟爱","ex":["They are cherished by the rich.","它们受到富人的钟爱。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"appreciate","p":"əˈpriːʃieɪt","m":"v.重视；欣赏；感激","tip":"ap-（一再地）+ preci（联想 precious）+ -ate（动词后缀）→ 一再地说一个对象珍贵 → 重视；欣赏","ex":["Let them know how much you appreciate their contribution.","让他们知道你多么感激他们的付出。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"valuable","p":"ˈvæljuəbl","m":"adj.有价值的，贵重的；很有用的","tip":"","ex":["They gave me many valuable comments as to how to improve my writing.","对于如何提高我的写作水平，他们给了我很多有用的意见。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"costly","p":"ˈkɒstli","m":"adj.昂贵的，贵重的","tip":"","ex":["Buying new furniture may prove too costly.","购买新家具可能会花钱太多。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"evaluate","p":"ɪˈvæljueɪt","m":"v.评价，评估","tip":"e-（出去）+ valu(e)（价值）+ -ate（动词后缀）→ 把价值说出去 → 评价，评估","ex":["They asked unbiased scholars to evaluate them.","他们请公正的学者对它们进行评估。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"estimate","p":"ˈestɪmeɪt","m":"v.估计，评估","tip":"est（联想最高级后缀）+ i（字母音“爱”）+ mate（朋友）→ 他最偏爱哪个朋友？谁也不知道，只能“估计”。","ex":["Surveys estimate that 85% of women and 73% of men report feeling better after shedding tears.","调查估计，85%的女性和 73%的男性称流泪后感觉更好。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"reckon","p":"ˈrekən","m":"v.估算；计算；认为","tip":"re（字母音似“阿姨”）+ ck（联想 CK）+ on（上面）→ 阿姨把手放在 CK 品牌的衣服上，“估算”需要多少钱。","ex":["I reckon I'm going to pass the examination smoothly.","我认为我会顺利通过这次考试。"],"lesson":"u03-l04","group":"“珍贵的”相关"},{"w":"ultimate","p":"ˈʌltɪmət","m":"adj.最后的，最终的","tip":"ul（音似“啊偶”）+ ti（联想“提”）+ mate（朋友）→ 等到“最后的”时候她才提起她的朋友，于是尴尬地发出“啊偶”的声音。","ex":["They are the ultimate solution to droughts.","它们是干旱的最终解决方案。"],"lesson":"u03-l04","group":"mate 相关"},{"w":"intimate","p":"ˈɪntɪmət","m":"adj.亲密的；密切的 n.密友，知己","tip":"in（里面）+ ti（联想“提”）+ mate（朋友）→ 内心会提到的朋友，就是你的“密友”。","ex":["Using voice interaction feels far more intimate than surfing the net the old-fashioned way.","使用语音交互比老式的上网方式感觉亲密得多。"],"lesson":"u03-l04","group":"mate 相关"},{"w":"approximate","p":"əˈprɒksɪmət","m":"adj.大约的；接近的","tip":"ap-（一再地）+ pro-（往前）+ xi（联想“西”）+ mate（配偶）→ 一再地朝西往前走，你大约就会找到你的配偶 → 大约的","ex":["The approximate materials are tomatoes, eggs, oil and salt.","大概的材料是西红柿、鸡蛋、油和盐。"],"lesson":"u03-l04","group":"mate 相关"},{"w":"approach","p":"əˈprəʊtʃ","m":"v.接近；着手处理 n.接近；方法；态度","tip":"单词发音类似“饿扑肉吃”→ 老虎饿了想扑倒猎物吃肉，首先得“接近”猎物。","ex":["She took the wrong approach in her dealings with them.","她和他们打交道的方式错了。"],"lesson":"u03-l04","group":"mate 相关"},{"w":"expend","p":"ɪkˈspend","m":"v.支出，花费；消耗","tip":"昂贵的（expensive）东西需要人们花费（expend）很多钱来购买。","ex":["She expended all her efforts on the care of home and children.","她把所有精力都花在照顾家庭和孩子上。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"expenditure","p":"ɪkˈspendɪtʃə(r)","m":"n.支出，花费；消耗","tip":"","ex":["They find consulting caloric-expenditure charts troublesome.","他们发现查询卡路里消耗表很麻烦。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"capital","p":"ˈkæpɪtl","m":"n.首都；资本；大写字母","tip":"首都（capital）的企业更容易获得资本（capital）的投入。","ex":["It didn't need much capital to start with.","它一开始不需要太多资金。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"captain","p":"ˈkæptɪn","m":"n.船长；机长；首领 v.担任……的队长","tip":"cap（帽子）+ tain（拿）→ 拿着帽子的那个人就是“船长”。","ex":["The captain welcomes you aboard.","船长欢迎你上船。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"capable","p":"ˈkeɪpəbl","m":"adj.有能力，有才能的；能胜任的","tip":"cap（帽子，联想“头”）+ able（能够）→ 他头脑灵活、善于思考，是“有才能的”人。","ex":["They have proved capable of doing almost anything.","事实证明，它们几乎无所不能。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"capacity","p":"kəˈpæsəti","m":"n.容量；领悟（或理解、办事）能力；职位","tip":"cap（帽子）+ a（一）+ city（城市）→ 头戴大盖帽的人在城市里是一个很有“能力”的人 → 领悟（或理解、办事）能力","ex":["She has the capacity to take account of all the important factors.","她有考虑到所有重要因素的能力。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"capture","p":"ˈkæptʃə(r)","m":"v.捕获 n.（被）捕获","tip":"capt（抓）+ -ure（后缀）→ 抓的行为 → 捕获","ex":["A wandering cow was captured by the police.","一头游荡的牛被警察抓住了。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"cabin","p":"ˈkæbɪn","m":"n.小木屋；机舱","tip":"ca（音似“开”）+ b + in（里面）→ 猎人打开“小木屋”并把猎物放到里面。","ex":["He sat quietly in the first class cabin of the flight.","他静静地坐在班机的头等舱内。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"cabinet","p":"ˈkæbɪnət","m":"n.内阁；储藏柜，陈列柜","tip":"单词发音类似“开杯奶他”→ 他从“储藏柜”里拿出一杯奶并打开。","ex":["They are fond of sleeping in cabinets.","它们喜欢睡在储藏柜里。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"cable","p":"ˈkeɪbl","m":"n.缆绳；电缆；电报；网线","tip":"单词发音类似“可包”→“电缆”可以用橡胶包覆。","ex":["Repairs to the cable did not take too long.","维修电缆没花太长时间。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"cattle","p":"ˈkætl","m":"n.牛；牲口，家畜","tip":"ca（联想 capture）+ ttle（音似“头”）→ 我抓住了一头“牛”。","ex":["Raising cattle, pigs, and other land-based animals requires vast sums of grain and water.","饲养牛、猪和其他陆生动物需要大量的粮食和水。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"wire","p":"ˈwaɪə(r)","m":"n.金属线；电线，导线 v.用导线给（建筑物、设备等）接通电源","tip":"单词发音类似“威亚”→ 电线，导线","ex":["A high wire fence encircles the complex.","一个高高的铁丝网围绕着这个建筑群。"],"lesson":"u03-l04","group":"cap/cab 相关"},{"w":"region","p":"ˈriːdʒən","m":"n.地区；（身体）部位","tip":"单词发音类似“瑞金”→ 瑞金是江西的一个“地区”。","ex":["There are lots of different dishes to try and every region has its own special food.","有很多不同的菜肴可以尝试，并且每个地区都有自己的特色食物。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"origin","p":"ˈɒrɪdʒɪn","m":"n.起源；源头；起因；出身","tip":"单词发音类似“噢瑞金”→ 噢，江西瑞金是长征精神的发源地 → 起源；源头","ex":["There are a number of different versions about the origin of the lion dance.","关于舞狮的起源有很多不同的说法。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"originate","p":"əˈrɪdʒɪneɪt","m":"v.创建；起源","tip":"","ex":["She doesn't really know where they originated.","她真不知道它们的起源。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"source","p":"sɔːs","m":"n.来源，出处，源头 v.从某地获得","tip":"单词发音类似“缫丝”→ 缫丝（将蚕茧抽出蚕丝的工艺）起源于中国 → 源头","ex":["Kids and adults alike find in dogs a source of attachment.","儿童和成人都会从狗身上找到依恋的来源。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"resource","p":"rɪˈsɔːs","m":"n.资源；财力","tip":"re-（重复）+ source（源头）→ 重复地寻找源头是需要“资源”支持的。","ex":["Half of the world's water resources have been seriously polluted.","世界上一半的水资源已经被严重污染。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"derive","p":"dɪˈraɪv","m":"v.追溯……的起源，源于；得到，获得","tip":"de（音似“弟”）+ rive（联想 river）→ 弟弟沿着河走，追溯河的源头 → 追溯……的起源","ex":["She always derives great pleasure from designing something new.","她总是从设计新东西中获得极大的乐趣。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"deprive","p":"dɪˈpraɪv","m":"v.剥夺，掠夺；使丧失","tip":"de（音似“弟”）+ p（联想“扑”）+ rive（联想 river）→ 弟弟扑到河里去抓鱼，鱼的自由被“剥夺”。","ex":["Online systems may deprive teachers of opportunities to make the best use of their expertise for their students.","在线系统可能会剥夺教师们为学生充分利用其专业知识的机会。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"seize","p":"siːz","m":"v.抓住；夺取，占领；没收","tip":"个头（size）最大的那只鹅很难被抓住（seize）。","ex":["The men were seized as they left the building.","这些人在离开那栋房子时被抓获。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"rob","p":"rɒb","m":"v.抢劫；盗取；剥夺","tip":"单词发音类似“肉不”→ 在文明社会，肉不用“抢”。","ex":["Her father was shot by someone trying to rob his small retail shop.","她父亲被某个试图抢劫他的小零售店的人开枪打中了。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"rub","p":"rʌb","m":"v.擦，摩擦；揉搓","tip":"单词发音类似“软布”→ 她喜欢用软布“擦”脸。","ex":["When the rats detect the smell, they stop and rub their legs.","当老鼠闻到这种气味时，它们会停下来摩擦自己的腿。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"thrive","p":"θraɪv","m":"v.兴旺，繁荣；茁壮成长","tip":"th(r)（联想 three）+ rive（联想 river）→ 三河交汇的地方经济比较“繁荣”。","ex":["New businesses thrive in this area.","新企业在这一地区蓬勃兴起。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"strive","p":"straɪv","m":"v.努力，奋斗","tip":"st（联想 street）+ rive（联想 river）→ 在河上建一条街需要多方合作与“努力”。","ex":["We must continue to strive for greater efficiency.","我们必须继续为提高效率而努力。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"effort","p":"ˈefət","m":"n.努力；费力的事；试图","tip":"e（音似“爱”）+（f）for（为了）+ t（联想“她”）→ 父母很爱她，为了她，“努力”提升生活质量。","ex":["The local clubs are making every effort to interest more young people.","地方俱乐部正在尽一切努力来吸引更多的年轻人。"],"lesson":"u03-l04","group":"“起源”相关"},{"w":"accord","p":"əˈkɔːd","m":"v.（与……）一致，符合 n.协议；符合，一致","tip":"ac-（一再地）+ cord（音似“靠的”）→ 他一再地靠着这个人，并试图从行为上与他保持“一致”。","ex":["This action would not be in accord with our policy.","这一行动不会符合我们的方针。"],"lesson":"u03-l04","group":"cord 相关"},{"w":"record","p":"ˈrekɔːd","m":"v.记录；标明；录音，录像","tip":"re（字母音似“阿姨”）+ cord（音似“拷的”）→ 阿姨拷贝的是“唱片”。","ex":["It partly records his own experience.","它部分地记录了他自己的经历。"],"lesson":"u03-l04","group":"cord 相关"},{"w":"audio","p":"ˈɔːdiəʊ","m":"adj.声音的；录音的","tip":"单词发音类似“奥迪哦”→ 后面有辆奥迪车，按喇叭的声音很大 → 声音的","ex":["This digital audio player supports multiple formats.","这台数字音频播放器支持多种格式。"],"lesson":"u03-l04","group":"cord 相关"},{"w":"audience","p":"ˈɔːdiəns","m":"n.听众；观众","tip":"单词发音类似“奥迪摁死”→ 一位奥迪车主使劲摁喇叭，“听众”受不了了。","ex":["Make sure to bring the audience into the conversation so that it is not one-sided.","确保让听众参与到对话中来，这样对话就不会一边倒。"],"lesson":"u03-l04","group":"cord 相关"},{"w":"echo","p":"ˈekəʊ","m":"n.回声；启示 v.发出回声；重复；附和","tip":"单词发音类似“隘口”→ 在狭窄的山口容易有“回声”。","ex":["Her footsteps echoed in the empty room.","她的脚步声在空荡荡的屋子里回响着。"],"lesson":"u03-l04","group":"cord 相关"},{"w":"regard","p":"rɪˈɡɑːd","m":"v.认为，把……看作 n.致意，问候","tip":"re（字母音似“阿姨”）+ gard（联想 guard）→ 阿姨向士兵致以“问候”。","ex":["Some people regard professional change as an unpleasant experience that disturbs their stable careers.","有些人认为转行是一种不愉快的经历，会扰乱他们稳定的职业生涯。"],"lesson":"u03-l04","group":"cord 相关"},{"w":"regardless","p":"rɪˈɡɑːdləs","m":"adv.不顾一切地，不管；不理会","tip":"","ex":["Skills are highly valued regardless of age.","无论年龄大小，技能都受到高度重视。"],"lesson":"u03-l04","group":"cord 相关"},{"w":"distinguish","p":"dɪˈstɪŋɡwɪʃ","m":"v.区分，辨别","tip":"单词发音类似“弟似听故事”→ 弟弟似乎在努力地听老师讲故事，试图“辨别”出故事里谁好谁坏。","ex":["What distinguishes children from adults is their strong ability to derive joy from what they are doing.","儿童与成人的区别在于他们从所做的事情中获得快乐的能力很强。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"distinct","p":"dɪˈstɪŋkt","m":"adj.有区别的；明确的；显著的","tip":"","ex":["Start-up investors are a distinct type of rich people.","创业投资者是一类与众不同的富人。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"difference","p":"ˈdɪfrəns","m":"n.差别，不同（之处）；变化（之处）","tip":"","ex":["It all comes down to the difference between learning and practicing.","这一切都归结为学习和练习之间的区别。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"extinguish","p":"ɪkˈstɪŋɡwɪʃ","m":"v.熄灭；消灭","tip":"extinguisher n.灭火器 → extinguish v.","ex":["Firefighters tried to extinguish the flames.","消防队员奋力灭火。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"instinct","p":"ˈɪnstɪŋkt","m":"n.本能；直觉；天赋","tip":"单词发音类似“鹰死盯克它”→ 老鹰死盯着猎物是一种“本能”。","ex":["Compared with other mammals, our numerical instincts are not as remarkable as many assume.","与其他哺乳动物相比，我们对数字的直觉并不像许多人认为的那样卓越。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"sting","p":"stɪŋ","m":"v.刺；蜇 n.刺；痛苦","tip":"单词发音类似“死定”→ 他被蜜蜂“蜇”一下很痛，感觉像是死定了。","ex":["She still remembers the sting of her first experience skipping an assignment due to the high prices.","她仍记得第一次因为价格太高而没交作业所经历的那种痛苦。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"pierce","p":"pɪəs","m":"v.刺穿；刺破；穿孔","tip":"一片（piece）玻璃碎片刺破（pierce）了他的手掌。","ex":["She was pierced by a chicken bone.","她被一块鸡骨头刺到了。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"thrust","p":"θrʌst","m":"v.猛推；冲；刺 n.要点；驱动力；刺","tip":"如果人与人之间没有了信任（trust），生活早晚得刺（thrust）人一刀。","ex":["She thrust her way into the crowd.","她一头扎进人群。"],"lesson":"u03-l04","group":"guish 相关"},{"w":"observe","p":"əbˈzɜːv","m":"v.观察；遵守；评论，评说","tip":"ob-（表方向）+ serve（服务）→ 朝着一个方向为别人服务，要“观察”对方的需求，“遵守”对方的要求。","ex":["He observed his client's life and habits.","他观察了客户的生活和习惯。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"reserve","p":"rɪˈzɜːv","m":"v.保留；预订 n.储备（量）；保护区","tip":"re-（重复）+ serve（服务）→ 想重复接受该酒店的服务，需要重新“预订”房间，这样它才会为你“保留”足够的房间。","ex":["They use their money reserves to back up consumption.","他们用他们的货币储备来支持消费。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"deserve","p":"dɪˈzɜːv","m":"v.值得；应受，应得","tip":"de-（音似“弟”）+ serve（服务）→ 弟弟觉得为家人服务理所应当 → 应受，应得","ex":["Any product that promises to protect your home deserves careful examination.","任何承诺保护您家的产品都值得仔细检查。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"conservative","p":"kənˈsɜːvətɪv","m":"n.保守派，保守的人 adj.保守的，守旧的","tip":"","ex":["They were deeply conservative in their outlook.","他们的观点非常保守。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"preserve","p":"prɪˈzɜːv","m":"v.保护；保留；保存 n.专属领域；独有活动；动物保护区","tip":"pre-（提前）+ serve（保留）→ 保留；保存[servant 最初是俘虏中“保留下来”（serv）不杀“的人”（-ant），为胜利者服务 → serv(e) 服务；保留]","ex":["Hyphenating names allows the bride to preserve her own identity while respecting tradition.","用连字符连接的名字可以让新娘在尊重传统的同时保留自己的身份。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"protect","p":"prəˈtekt","m":"v.保护；防护；防守","tip":"pro-（提前）+ tect（音似“探个它”）→ 他提前把路探好是为了“保护”我们的安全。","ex":["The chief duty of every government is to protect persons and property.","每一个政府的首要职责都是保护人民和财产。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"detect","p":"dɪˈtekt","m":"v.发现；查明；侦察出","tip":"de-（往下）+ tect（音似“探个它”）→ 钻探工人往下钻井，是为了“查明”地下有无石油层。","ex":["The tests are designed to detect changes in mental function.","这些测试旨在检测心理功能的变化。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"scout","p":"skaʊt","m":"n.侦查员；童子军 v.侦查，寻找；物色","tip":"sc（音似“四个”）+ out（出去）→ 四个“侦查员”出去了。","ex":["Both my brothers were scouts.","我的两个哥哥都当过童子军。"],"lesson":"u04-l01","group":"serv(e)相关"},{"w":"prevent","p":"prɪˈvent","m":"v.阻止；妨碍","tip":"pre-（前）+ vent（音似 went）→ 在你前面走 → 阻止；妨碍","ex":["It may prevent your business and career from advancing.","它可能会阻碍你的事业和职业的发展。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"forbid","p":"fəˈbɪd","m":"v.禁止，不准","tip":"单词发音类似“封闭的”→ 封闭的地方是“禁止”入内的。","ex":["These children are forbidden to visit terminally ill patients.","这些儿童被禁止去探望绝症患者。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"bid","p":"bɪd","m":"v. & n.出价；投标；努力争取","tip":"单词发音类似“必得”→ 拍卖时竞拍者“出价”很高，志在必得。","ex":["We deny our children's bids to help until they are 6 or 7 years old.","我们拒绝孩子在 6 或 7 岁之前提供帮助。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"ban","p":"bæn","m":"n.禁令 v.（明令）禁止","tip":"单词发音类似“扳”→“禁止”扳动这个把手。","ex":["He plans to ban tipping in favor of paying his servers a wage.","他计划禁止给服务员小费，而给他们支付工资。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"banner","p":"ˈbænə(r)","m":"n.标语；横幅","tip":"ban（禁止）+ n（联想“那”）+ -er（表示人的后缀）→ 为了禁止那个人这样做，他们贴了个“标语”。","ex":["They carried banners and shouted angrily.","他们高举横幅，愤怒声讨。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"prohibit","p":"prəˈhɪbɪt","m":"v.禁止；阻止","tip":"pro-（前）+ hibi（音似“狠逼”）+ t（联想“他”）→ 有人站在他前面，狠狠地逼他回去，“阻止”他前进。","ex":["They prohibit agents from hiring models with a BMI below 18.","他们禁止经纪公司雇用体重指数低于 18 的模特。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"exhibit","p":"ɪɡˈzɪbɪt","m":"n.（一件）展览品；证据 v.展览；表现","tip":"ex-（往外）+ hi（嗨）+ bit（联想“比她”）→ 他往外打了个招呼，炫耀自己的“展览品”比她多。","ex":["His creative works were exhibited in the shop windows.","他的创意作品在商店的橱窗里展览。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"display","p":"dɪˈspleɪ","m":"n. & v.陈列；展览；表现；（计算机屏幕上的）显示","tip":"","ex":["His cooking displays became the symbol of fine French dining.","他的烹饪展示成了法国美食的象征。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"freeze","p":"friːz","m":"v.冻；冻结；使结冰","tip":"free（自由）+ ze（联想“泽”）→ 他幻想沼泽“冻结”，这样就能在上面自由地行走。","ex":["Water freezes at 0℃.","水在 0 摄氏度时结冰。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"breath","p":"breθ","m":"n.呼吸；一口气；微风","tip":"单词发音类似“不会死”→ 还有“呼吸”就不会死。","ex":["We had to stop for breath before we got to the top.","我们不得不喘口气，然后再登山顶。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"breeze","p":"briːz","m":"n.微风；轻而易举的事","tip":"微风（breeze）拂过冻结（freeze）的湖面，好像春天就要来了。","ex":["The flowers were gently swaying in the breeze.","花儿在微风中轻轻舞动。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"squeeze","p":"skwiːz","m":"v. & n.压；挤；捏","tip":"单词发音类似“死贵死”→ 价格死（很）贵，要往下“压”价。","ex":["We managed to squeeze six people into the car.","我们设法把六个人挤进了那辆车。"],"lesson":"u04-l01","group":"“阻止、冻结”相关"},{"w":"plot","p":"plɒt","m":"v.密谋；策划 n.故事情节；密谋","tip":"单词发音类似“扑捞它”→ 包掉到河里了，不要直接扑进去捞它，而是要“策划”一下打捞方案。","ex":["I forgot the plot of the movie.","我忘记了电影情节。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"flat","p":"flæt","m":"adj.平坦的；无趣的；平淡的 n.公寓；单元房","tip":"fl（联想 fly）+ at（上面）→ 超人飞过来，停留在一块“平坦的”岩石上。","ex":["It has a flat surface at the top.","顶部有一个平面。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"inflate","p":"ɪnˈfleɪt","m":"v.使充气；膨胀；（使）涨价","tip":"in（入）+ flat（平坦的）+ e → 使气体进入平坦的物体 → 使充气；膨胀","ex":["Swimming circles can be inflated by machines.","游泳圈可以用机器充气。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"dense","p":"dens","m":"adj.密集的，稠密的","tip":"单词发音类似“扽死”→ 方言，指东西怎么拽都拽不开，像乱麻一样稠密 → 稠密的","ex":["Their first glimpse of the new land was a sight of dense woods.","他们对这片新大陆的第一印象是茂密的树林。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"condense","p":"kənˈdens","m":"v.压缩；变浓","tip":"con-（表加强）+ dense（稠密的）→ 使变得稠密 → 压缩；变浓","ex":["The mayor was asked to condense his speech.","市长被要求缩短他的讲话。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"shrink","p":"ʃrɪŋk","m":"v.起皱；缩水；退缩；减少","tip":"sh（联想“湿”）+ r（形似花）+ ink（墨水）→ 我的花毛衣被墨水弄湿了，洗了以后就“缩水”了。","ex":["The market for their products is shrinking.","市场对他们产品的需求在减少。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"fade","p":"feɪd","m":"v.褪色，逐渐消失","tip":"单词发音类似“废的”→ 那件羊毛衫洗了几次就“褪色”报废了。","ex":["When students feel isolated, their motivation to continue begins to fade.","当学生们感到被孤立时，他们继续学习的动力就会开始消退。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"compact","p":"kəmˈpækt","m":"adj.紧凑的，紧密的","tip":"com-（都）+ pact（音似“拍个它”）→ 我们做年糕时都杵白使劲拍，越拍就越紧实 → 紧密的","ex":["The kitchen was small and compact so that the disabled could reach everything easily.","厨房又小又紧凑，因此残疾人可以轻松地拿到所有东西。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"impact","p":"ˈɪmpækt","m":"v.撞击，冲击；影响","tip":"im-（里面）+ pact（音似“拍个它”）→ 海水“撞击”海里的岩石，有种惊涛拍岸的感觉。","ex":["More studies are needed to find out the impact of emotion on behavior.","需要更多的研究来发现情绪对行为的影响。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"influence","p":"ˈɪnfluəns","m":"n.影响；势力 v.影响","tip":"in-（里面）+ flu（流感）+ -ence（名词后缀）→ 家里的人得了流感，肯定会对其他人也产生一些“影响”。","ex":["Mothers' influence on children may last longer than fathers'.","母亲对孩子的影响可能比父亲更持久。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"influenza","p":"ˌɪnfluˈenzə","m":"n.流行性感冒；流感","tip":"","ex":["He came down with influenza.","他得了流感。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"exert","p":"ɪɡˈzɜːt","m":"v.运用；施加；努力；竭力","tip":"单词发音类似“一个蛇他”→ 外面有条蛇，这件事给他“施加”了很大的压力。","ex":["He exerted all his authority to make them accept the plan.","他运用他的所有权力让他们接受这个计划。"],"lesson":"u04-l01","group":"“膨胀、压缩”相关"},{"w":"fluent","p":"ˈfluːənt","m":"adj.流利的，流畅的","tip":"flu（联想 fly）+ ent（联想 enter）→ 燕子飞进来的动作是“流畅的”。","ex":["Some employees are fluent in a second language.","一些员工能流利地使用第二语言。"],"lesson":"u04-l01","group":"“足够的”相关"},{"w":"affluent","p":"ˈæfluənt","m":"adj.富裕的，富足的","tip":"af-（一再地）+ fluent（流畅的）→ 一个“富裕的”人可能事事顺畅。","ex":["They enjoyed a fairly affluent life.","他们过着相当富裕的生活。"],"lesson":"u04-l01","group":"“足够的”相关"},{"w":"lack","p":"læk","m":"n.缺乏；匮乏；短缺 v.没有；短缺","tip":"单词发音类似“来客”→ 她的小面馆因“缺乏”宣传，“没有”来客人。","ex":["They may lack adequate knowledge of healthy food.","他们可能缺乏足够的健康食品知识。"],"lesson":"u04-l01","group":"“足够的”相关"},{"w":"scarce","p":"skeəs","m":"adj.缺乏的；不足的；稀少的","tip":"s（联想“死”）+ car（车）+ ce（联想“侧”）→ 他拼死侧身挤上了车，因为车太少了 → 稀少的","ex":["In college, time is scarce, and consequently, very precious.","在大学里，时间很少，因此也非常珍贵。"],"lesson":"u04-l01","group":"“足够的”相关"},{"w":"rare","p":"reə(r)","m":"adj.稀少的；珍贵的；（肉类）三分熟的","tip":"r（形似花）+ are（是）→ 这种花是很“稀少的”。","ex":["Physical books will become much rarer in the marketplace.","实体书籍在市场上会变得更加罕见。"],"lesson":"u04-l01","group":"“足够的”相关"},{"w":"adequate","p":"ˈædɪkwət","m":"adj.足够的；充足的；合格的","tip":"ad-（= to）+ equ（= equal）+ -ate（后缀）→ 趋向相等的 → 足够的","ex":["The basics of adequate sleep, healthy diet and exercise are a good place to start.","充足的睡眠、健康的饮食和锻炼这些基本因素是一个很好的开始。"],"lesson":"u04-l01","group":"“足够的”相关"},{"w":"equivalent","p":"ɪˈkwɪvələnt","m":"n.相等的东西；等量 adj.相等的，相同的","tip":"equi（= equal）+ val（= value）+ -ent（后缀）→ 相等价值的 → 相等的，相同的","ex":["The caffeine—the equivalent of two strong cups of coffee—was sufficient to reverse this effect.","咖啡因——相当于两杯浓咖啡——足以扭转这种影响。"],"lesson":"u04-l01","group":"“足够的”相关"},{"w":"tense","p":"tens","m":"adj.紧张的 v.紧张，紧绷 n.时态","tip":"ten（十）+ se（联想“蛇”）→ 他放学路上看到十条蛇，感到极其“紧张”。","ex":["The atmosphere in the meeting was getting more and more tense.","会议的气氛越来越紧张。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"intensive","p":"ɪnˈtensɪv","m":"adj.集中的，加强的；密集的","tip":"in-（向内）+ tens(e)（伸展）+ -ive（形容词后缀）→ 集中的，加强的","ex":["There have been intensive discussions between the two governments in recent days.","近几天，双方政府一直在进行集中的磋商。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"intense","p":"ɪnˈtens","m":"adj.紧张的；激烈的；十分强烈的","tip":"in-（向内）+ tense（伸展 → 拉紧，紧张）→ 紧张的；激烈的","ex":["It was a period of intense activity.","那是活动激烈的时期。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"sense","p":"sens","m":"n.感觉；见识；理解力；意义 v.感觉到；觉察到","tip":"单词发音类似“神似”→ 有人说我长得神似明星，那只是他们的“感觉”而已。","ex":["She connected with her sense of purpose and dug deep, cultivating a tremendous sense of strength.","她与自己的使命感联系在一起，深入挖掘，培养了一种巨大的力量感。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"sensitive","p":"ˈsensətɪv","m":"adj.敏感的；脆弱的","tip":"sense n.感觉；见识 → sensitive adj.","ex":["They are becoming rather sensitive issues.","它们正在成为相当敏感的话题。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"nonsense","p":"ˈnɒnsns","m":"n.废话，胡说；荒谬的想法","tip":"non-（无）+ sense（意义）→ 无意义的话 → 废话，胡说","ex":["It's nonsense to say they don't care.","说他们不在意那是胡说八道。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"sensible","p":"ˈsensəbl","m":"adj.明智的；感觉得到的","tip":"","ex":["Less stressed people made more sensible decisions.","压力较小的人做决定更为明智。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"mental","p":"ˈmentl","m":"adj.精神的，智力的；思想的","tip":"men（人）+ tal（联想“头”）→ 人的头脑就是“精神的”载体。","ex":["What mattered most was the residents' physical health and mental status.","最重要的是居民的身体健康和精神状态。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"fundamental","p":"ˌfʌndəˈmentl","m":"adj.基础的，根本的；重要的 n.（pl.）基本原则，基本原理","tip":"fund（资金）+ a（一）+ mental（精神的）→ 除了资金需求以外，一个人精神的满足也是他“基础的”需要。","ex":["Hard work is fundamental to success.","勤奋工作是成功的基础。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"fatal","p":"ˈfeɪtl","m":"adj.严重的；致命的","tip":"单词发音类似“肥头”→ 肥头（大头）病是很“严重的”病。","ex":["The research is starting to show that early setbacks don't have to be fatal.","这项研究开始表明，早期的挫折不一定是致命的。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"total","p":"ˈtəʊtl","m":"adj.总的，全部的 n.总数，总计","tip":"单词发音类似“头头”→ 一个一个头地数，最后得出“总数”是多少。","ex":["All the people we interviewed expressed almost total satisfaction with it.","我们采访的所有人对此都表示非常满意。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"digital","p":"ˈdɪdʒɪtl","m":"adj.数字的，数码的","tip":"单词发音类似“低着头”→ 上课时不要总低着头看数码产品 → 数字的，数码的","ex":["Digital technology makes it easier for people to coordinate their activities.","数字技术使人们更容易协调他们的活动。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"talent","p":"ˈtælənt","m":"n.天赋，才能，天才","tip":"ta（联想“他”）+ lent（借给）→ 他总是把好点子借给我，说明他很有“天赋”。","ex":["Teaching is talent and practice; it is not something that just anyone can be good at.","教学是天赋，是实践；这不是任何人都能擅长的事情。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"vital","p":"ˈvaɪtl","m":"adj.至关重要的；必不可少的","tip":"vi（形似罗马数字 6）+ tal（音似“头”）→ 这 6 个人很有头脑，他们的地位都是“至关重要的”。","ex":["We will lose a vital part of what has made humanity as a whole so successful as a species.","我们将失去使人类作为一个物种整体取得如此成功的一个重要部分。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"crucial","p":"ˈkruːʃl","m":"adj.至关重要的；关键性的","tip":"单词发音类似“可入手”→ 可入手的东西一般都是“至关重要的”。","ex":["It proves crucial in making others follow one's course of action.","这证明，使他人遵循自己的行动方针是至关重要的。"],"lesson":"u04-l01","group":"“紧张、感觉”相关"},{"w":"attain","p":"əˈteɪn","m":"v.达到；获得","tip":"at-（一再地）+ tain（= take）→ 他“获得”了喜欢的东西，一再地拿着。","ex":["Most of our students attained five \"A\" grades in their exams.","我们多数学生的考试成绩是五个优。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"contain","p":"kənˈteɪn","m":"v.包含；控制；容纳","tip":"con-（所有）+ tain（= take）→ 把所有东西都拿着 → 包含；容纳","ex":["These studies showed that their water did contain microplastics.","这些研究表明，他们的水确实含有微塑料。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"contaminate","p":"kənˈtæmɪneɪt","m":"v.弄脏；污染；玷污","tip":"con-（所有）+ tamin（联想“他们”）+ ate（吃）→ 他们吃的所有东西都被“污染”了。","ex":["These substances can contaminate groundwater.","这些物质会污染地下水。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"dirty","p":"ˈdɜːti","m":"adj.肮脏的；下流的 v.弄脏","tip":"","ex":["They are often seen as dirty birds.","它们经常被视为肮脏的鸟类。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"pollution","p":"pəˈluːʃn","m":"n.污染；污染物；垃圾","tip":"单词发音类似“破路深”→ 这条破路深处有很多“污染物”。","ex":["Millions die early from air pollution each year.","每年数百万人因空气污染而早逝。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"retain","p":"rɪˈteɪn","m":"v.保持，保留；雇；记住","tip":"re-（回，复）+ tain（保持）→ 保持，保留","ex":["The house retains much of its original charm.","这所房子保留了许多原有的魅力。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"maintain","p":"meɪnˈteɪn","m":"v.维持；维修；认为","tip":"main（主要的）+ tain（保持）→ 我们的生活主要是靠他拿钱“维持”的。","ex":["The best way to maintain good blood circulation is through using the brain.","保持良好血液循环的最佳方法是使用大脑。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"entertain","p":"ˌentəˈteɪn","m":"v.（尤指在自己家中）招待，款待；娱乐","tip":"enter（进来）+ tain（= take）→ 他进来就一直拿着麦克风唱，只顾“娱乐”自己。","ex":["Visiting a bookshop as curiosity leads us can be a good way to entertain ourselves.","我们在好奇心的引导下去书店是一种很好的娱乐方式。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"sustain","p":"səˈsteɪn","m":"v.维持；支撑，承担","tip":"sus-（下面）+ tain（保持）→ 从下面保持 → 维持；支撑","ex":["Some of those small mammals help to sustain such big birds as golden eagles.","有些小型哺乳动物有助于维持像金雕这样的大型鸟类的生存。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"obtain","p":"əbˈteɪn","m":"v.获得，得到","tip":"ob-（表方向）+ tain（= take）→ 朝着某个方向拿 → 获得，得到","ex":["Help it to obtain financial support from industry.","帮助其获得行业的资金支持。"],"lesson":"u04-l01","group":"tain 相关"},{"w":"species","p":"ˈspiːʃiːz","m":"n.物种，种类","tip":"世界上每个物种（species）都很特别（special）。","ex":["This book is called The Origin of Species.","这本书叫《物种起源》。"],"lesson":"u04-l02","group":"species 相关"},{"w":"creature","p":"ˈkriːtʃə(r)","m":"n.生物，动物","tip":"在大多数西方人眼中，生物（creature）是上帝创造（create）的。","ex":["The panda is a shy creature.","熊猫是胆小的动物。"],"lesson":"u04-l02","group":"species 相关"},{"w":"creation","p":"kriˈeɪʃn","m":"n.创造；作品；世界","tip":"","ex":["Job creation needs to be the top priority.","当务之急是创造就业机会。"],"lesson":"u04-l02","group":"species 相关"},{"w":"concrete","p":"ˈkɒŋkriːt","m":"adj.具体的；实在的 n.混凝土","tip":"con-（所有，都）+ crete（联想 create）→传说中，女娲创造出来的都是“具体的”人。","ex":["He had no concrete evidence.","他没有确凿的证据。"],"lesson":"u04-l02","group":"species 相关"},{"w":"clay","p":"kleɪ","m":"n.肉体；黏土，陶土","tip":"单词发音类似“可累”→挖了一天“黏土”，我可累了。","ex":["She moulded the clay into the shape of a head.","她把陶土做成一个人头的形状。"],"lesson":"u04-l02","group":"species 相关"},{"w":"human","p":"ˈhjuːmən","m":"n.人 adj.人的","tip":"","ex":["Some robots are already programmed with basic human values.","一些机器人已经具备了基本的人类价值观。"],"lesson":"u04-l02","group":"species 相关"},{"w":"humble","p":"ˈhʌmbl","m":"adj.谦逊的；卑微的；虚心的 v.贬低；使感到卑微","tip":"单词发音类似“哈木抱”→他点头哈腰，神情木讷，不敢去拥抱别人→谦逊的；卑微的","ex":["A humble partner might be your ideal partner.","谦虚的伴侣可能是你理想的伴侣。"],"lesson":"u04-l02","group":"species 相关"},{"w":"humour","p":"ˈhjuːmə(r)","m":"n.诙谐；幽默，幽默感","tip":"他说谣言（rumour）是从我们嘴里传出的，这也太幽默（humour）了吧。","ex":["He has impressed me with his good sense of humour.","他良好的幽默感给我留下了深刻的印象。"],"lesson":"u04-l02","group":"species 相关"},{"w":"moist","p":"mɔɪst","m":"adj.潮湿的；湿润的；微湿的","tip":"mo（音似“毛”）+ -ist（后缀）→“潮湿的”天气使人的衣服都长毛了。","ex":["Our skins let us know whether the air is moist or dry.","我们的皮肤可以让我们知道空气是潮湿还是干燥。"],"lesson":"u04-l02","group":"“湿”相关"},{"w":"render","p":"ˈrendə(r)","m":"v.使成为；使得；给予，提供；表演","tip":"单词发音类似“润的”→潮湿的天气“使得”你的皮肤变得润润的。","ex":["It may render many teachers jobless.","它可能会使许多教师失业。"],"lesson":"u04-l02","group":"“湿”相关"},{"w":"chill","p":"tʃɪl","m":"adj.冷的 n.寒冷；害怕","tip":"chi（联想“吃”）+ ll（形似两根冰棍）→他吃了两根冰棍，感觉心底都是“冷的”。","ex":["I waited in the chill wind for an hour.","我在寒风中等了一个小时。"],"lesson":"u04-l02","group":"“湿”相关"},{"w":"damp","p":"dæmp","m":"adj.潮湿的 n.潮湿 v.使潮湿","tip":"dam（水坝）+ p（联想 place）→有水坝的地方一般比较潮湿→潮湿的","ex":["The sheets are damp with sweat.","床单被汗水浸湿了。"],"lesson":"u04-l02","group":"“湿”相关"},{"w":"damage","p":"ˈdæmɪdʒ","m":"v.损害，毁坏 n.损害","tip":"dam（水坝）+ age（很长时间）→水坝年久失修可能会“损害”民众的安全。","ex":["The storm didn't do much damage.","暴风雨未造成严重损失。"],"lesson":"u04-l02","group":"“湿”相关"},{"w":"cottage","p":"ˈkɒtɪdʒ","m":"n.小屋，村舍","tip":"cott（联想 cotton）+ age（年代）→纺棉花的那个年代，人们都住在“小屋”里。","ex":["The red roof of the cottage came into view.","小屋的红色屋顶映入眼帘。"],"lesson":"u04-l02","group":"“湿”相关"},{"w":"lodge","p":"lɒdʒ","m":"v.寄住，租住；安置；正式提出 n.乡间小屋","tip":"lo（音似“劳”）+ d（联想“的”）+ ge（联想“哥”）→劳累的哥哥“寄住”在“乡间小屋”里。","ex":["He lodged with Mrs. Brown when he arrived in the city.","他抵达此城时租住在布朗太太家里。"],"lesson":"u04-l02","group":"“湿”相关"},{"w":"individual","p":"ˌɪndɪˈvɪdʒuəl","m":"adj.单独的；个别的 n.个人；个体","tip":"in-（不）+ divid(e)（分开）+ -ual（后缀）→不能再分割的→单独的；个体","ex":["Real friendship is when two individuals share the same soul.","真正的友谊是两个人拥有同一个灵魂。"],"lesson":"u04-l02","group":"“人”相关"},{"w":"divide","p":"dɪˈvaɪd","m":"v.(使)分开；分配；分担 n.不同，分歧","tip":"di-（两个）+ vi（形似罗马数字 6）+ de →把他们分成两组，一组两个人，另一组六个人→分开；分配","ex":["It contributes to the male-female divide in the workplace.","它导致了工作场所的男女分歧。"],"lesson":"u04-l02","group":"“人”相关"},{"w":"personal","p":"ˈpɜːsənl","m":"adj.个人的；人际的；个性的；亲自的","tip":"","ex":["Distance education will never match the personal teaching in a traditional classroom.","远程教育永远比不上传统课堂上的个人教学。"],"lesson":"u04-l02","group":"“人”相关"},{"w":"private","p":"ˈpraɪvət","m":"adj.私有的；私人的；个体的","tip":"priv（私人，单个）+ -ate（形容词后缀）→私人的；个体的","ex":["In the age of the Internet, there's no such thing as a private debate.","在互联网时代，没有私人辩论。"],"lesson":"u04-l02","group":"“人”相关"},{"w":"gender","p":"ˈdʒendə(r)","m":"n.性别","tip":"单词发音类似“真的”→这里真的是不分“性别”，男女均可入内。","ex":["It hardly occurs across gender boundaries.","它几乎不会跨越性别界限。"],"lesson":"u04-l02","group":"“人”相关"},{"w":"male","p":"meɪl","m":"n.男子；雄性植物（动物） adj.男性的","tip":"ma（联想“妈”）+ le（联想“乐”）→妈妈被那个“男子”的滑稽表演逗乐了。","ex":["Only about three percent of early childhood teachers are male.","只有大约3%的幼儿教师是男性。"],"lesson":"u04-l02","group":"“人”相关"},{"w":"female","p":"ˈfiːmeɪl","m":"n.女子；雌性植物（动物） adj.女性的","tip":"fe（音似“非”）+ male（男性）→女子；女性的","ex":["Two of the candidates must be female.","候选人中必须有两名是女性。"],"lesson":"u04-l02","group":"“人”相关"},{"w":"main","p":"meɪn","m":"adj.主要的；最重要的 n.主线路；总管道","tip":"过去，男人（man）是主要的（main）劳动力。","ex":["In my opinion, lack of money is the main problem.","在我看来，缺钱是主要的问题。"],"lesson":"u04-l02","group":"main 相关"},{"w":"remain","p":"rɪˈmeɪn","m":"v.保持；维持；停留；剩下","tip":"re-（重复）+ main（主要的）→重复主要的，即“保持”不变。","ex":["Supplying enough job opportunities for the homeless remains a challenge.","为无家可归者提供足够的就业机会仍然是一个挑战。"],"lesson":"u04-l02","group":"main 相关"},{"w":"inherit","p":"ɪnˈherɪt","m":"v.继承，经遗传获得；接替","tip":"in（里面）+ her（她）+ it（它）→我女儿内心善良，它（这种品质）是从我这里“继承”的。","ex":["She inherited a big fortune from her father.","她从父亲那里继承了一大笔财产。"],"lesson":"u04-l02","group":"main 相关"},{"w":"heritage","p":"ˈherɪtɪdʒ","m":"n.遗产（指国家或社会长期形成的历史、传统和特色）","tip":"her（她）+ it（它）+ age（年龄）→她到了一定年龄才可以继承它——父母留给她的“遗产”。","ex":["The building is part of our national heritage.","这个建筑是我们民族遗产的一部分。"],"lesson":"u04-l02","group":"main 相关"},{"w":"major","p":"ˈmeɪdʒə(r)","m":"adj.主要的；重要的 n.主修课程；专业课 v.主修；专攻","tip":"单词发音类似“每节”→每节“主修课程”都要认真上。","ex":["CO2 emissions constitute a major threat to the environment.","二氧化碳排放对环境构成重大威胁。"],"lesson":"u04-l02","group":"main 相关"},{"w":"mainstream","p":"ˈmeɪnstriːm","m":"n.主流；主流思想；主流群体","tip":"main（主要的）+ stream（溪流）→主流","ex":["The technology is just now becoming mainstream.","这项技术现在正在成为主流。"],"lesson":"u04-l02","group":"main 相关"},{"w":"stream","p":"striːm","m":"n.溪流，小河 v.流动；涌出","tip":"蒸汽（steam）从锅里涌出（stream）来了。","ex":["They value quiet forests and clear streams.","他们珍视宁静的森林和清澈的溪流。"],"lesson":"u04-l02","group":"main 相关"},{"w":"canal","p":"kəˈnæl","m":"n.运河；（体内的）管；道","tip":"can（能）+ al（联想 all）→这里的水能够全部流向“运河”。","ex":["The Grand Canal is the longest man-made river in the world.","京杭大运河是世界上最长的人工河。"],"lesson":"u04-l02","group":"main 相关"},{"w":"scream","p":"skriːm","m":"n. & v.尖叫，喊叫","tip":"s（联想“美女”）+ cream（奶油）→我不小心把奶油涂在美女的脸上，她“尖叫”起来。","ex":["I screamed in pain.","我痛得尖叫起来。"],"lesson":"u04-l02","group":"main 相关"},{"w":"cream","p":"kriːm","m":"n.奶油，乳脂；奶油色","tip":"ice-cream 是冰激凌，cream 是奶油。","ex":["We had strawberries and cream for dessert.","我们的甜点是加奶油的草莓。"],"lesson":"u04-l02","group":"main 相关"},{"w":"dairy","p":"ˈdeəri","m":"n.乳品场；乳制品 adj.牛奶的；乳品的","tip":"他每天（daily）都要喝乳制品（dairy）。","ex":["That's where fresh produce, meat and seafood, and dairy are.","那里有新鲜农产品、肉类、海鲜和乳制品。"],"lesson":"u04-l02","group":"main 相关"},{"w":"butter","p":"ˈbʌtə(r)","m":"n.黄油；牛油 v.涂黄油于","tip":"单词发音类似“爸特”→爸爸特别喜欢吃加“黄油”的面包。","ex":["He shaped delicious masterpieces out of flour, butter and sugar.","他用面粉、黄油和糖做出了杰出的美味。"],"lesson":"u04-l02","group":"main 相关"},{"w":"steam","p":"stiːm","m":"n.蒸汽，水汽；精力 v.蒸发，蒸","tip":"s（联想“美女”）+ tea（茶）+ m（联想“门”）→一个美女在喝茶，门里飘出了“蒸汽”。","ex":["Steam rose from the boiling kettle.","壶里的水开了，冒着蒸汽。"],"lesson":"u04-l02","group":"main 相关"},{"w":"vapour","p":"ˈveɪpə(r)","m":"n.蒸气；水蒸气","tip":"单词发音类似“外婆”→外婆烧的水开了，冒出了“水蒸气”。","ex":["The particles form a vapour.","这些粒子形成蒸气。"],"lesson":"u04-l02","group":"main 相关"},{"w":"appear","p":"əˈpɪə(r)","m":"v.显得；似乎；出现；起源","tip":"ap-（一再地）+ pear（梨）→他一再地让我吃梨，“显得”很热情。","ex":["There does appear to be some psychology behind it.","这背后似乎确实有一些心理因素。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"appearance","p":"əˈpɪərəns","m":"n.外貌，外观，外表；（尤指突然的）抵达，到来","tip":"appear v.出现→appearance n.","ex":["He stressed both the appearance and flavour of dishes.","他注重菜肴的外观和味道。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"vanish","p":"ˈvænɪʃ","m":"v.突然消失","tip":"单词发音类似“玩你失”→玩捉迷藏时，你“突然消失”了。","ex":["Many types of animal have now vanished from the earth.","许多动物物种现已从地球上绝迹。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"emerge","p":"ɪˈmɜːdʒ","m":"v.浮现；出现；兴起","tip":"e-（出去）+ merge（音似“磨叽”）→妈妈让他别磨叽了，赶紧出来→出现","ex":["If a new competitor emerges to threaten your business, you may need to change direction.","如果一个新的竞争对手出现，威胁到你的业务，你可能需要改变方向。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"emergency","p":"ɪˈmɜːdʒənsi","m":"n.紧急情况，非常时刻","tip":"emerge（出现）+ -(e)ncy（名词后缀）→突然出现的事→紧急情况","ex":["The government has declared a state of emergency following the earthquake.","地震发生后政府已宣布进入紧急状态。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"urge","p":"ɜːdʒ","m":"v.主张，强烈要求；催促；鼓励","tip":"单词发音类似“饿极”→他饿极了，“催促”饭店快点上菜。","ex":["It urged tourists to leave Tunisia immediately.","它催促游客立即离开突尼斯。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"marine","p":"məˈriːn","m":"adj.海洋的；海产的；海事的","tip":"单词发音类似“没(mò)人”→大海把人淹没了→海洋的","ex":["Marine biologists are looking for the secret of turtles' reproduction.","海洋生物学家正在寻找海龟繁殖的秘密。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"bacteria","p":"bækˈtɪəriə","m":"n.细菌","tip":"bac（音似 back）+ te（联想“特”）+ ri（联想“日”）+ a→背后晒不到太阳，特别容易滋生“细菌”。","ex":["Certain types of bacteria are extremely harmful.","某些种类的细菌非常有害。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"virus","p":"ˈvaɪrəs","m":"n.病毒；有害影响","tip":"vi（形似罗马数字 6）+ r（形似花）+ us（我们）→这六朵花有“病毒”，我们不能要。","ex":["When a virus attacks your body, your body works hard to get rid of it.","当病毒攻击人体时，人体会努力清除病毒。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"germ","p":"dʒɜːm","m":"n.病菌，细菌；微生物","tip":"单词发音类似“这么”→显微镜下能看到有这么多的“细菌”。","ex":["Dirty hands can be a breeding ground for germs.","脏手可能滋生病菌。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"immune","p":"ɪˈmjuːn","m":"adj.有免疫力的；免除的；豁免的","tip":"im（联想 I'm）+ mune（联想“木讷”）→我是个木讷的人，反应慢，对别人的攻击是“有免疫力的”。","ex":["This is evidence that our immune system really doesn't function so well when we age.","这表明，随着年龄的增长，我们的免疫系统真的不能很好地发挥作用。"],"lesson":"u04-l02","group":"“消失、出现”相关"},{"w":"balance","p":"ˈbæləns","m":"v.(使)平衡 n.平衡","tip":"单词发音类似“芭蕾”→芭蕾舞者的“平衡”感特别好。","ex":["They are under growing pressure to balance their national budgets.","他们承受着越来越大的压力来平衡国家预算。"],"lesson":"u04-l02","group":"para 相关"},{"w":"parallel","p":"ˈpærəlel","m":"n.平行线；相似处 adj.平行的；类似的 v.与……相似；比得上","tip":"para-（旁边）+ llel（联想“e 和线”）→在“e”旁边并排的线→平行线；平行的","ex":["It is one that has seen no parallel in economic history.","这在经济史上是前所未有的。"],"lesson":"u04-l02","group":"para 相关"},{"w":"paradox","p":"ˈpærədɒks","m":"n.矛盾的人（或事物、情况）；悖论","tip":"para-（旁边）+ do（做，干）+ x（形似叉号）→相对立→旁边那个人老是和我对着干，是个和我有“矛盾”的人。","ex":["We seem to exhibit paradox.","我们似乎表现出了矛盾。"],"lesson":"u04-l02","group":"para 相关"},{"w":"parade","p":"pəˈreɪd","m":"n.游行；阅兵；炫耀 v.游行，排队行进；炫耀","tip":"para-（旁边）+ de（联想“的”）→我旁边的同学喜欢“炫耀”成绩。","ex":["They held a parade to mark the soldiers' return.","他们举行了游行庆祝士兵凯旋。"],"lesson":"u04-l02","group":"para 相关"},{"w":"march","p":"mɑːtʃ","m":"v.(使)行军，(使)行进 n.示威游行；行程；(March)三月(略作 Mar.)","tip":"三月（March）是万物复苏的季节，所有小动物都排着队行进（march）。","ex":["The army began their long march to the coast.","部队开始了他们前往沿海地区的长途行军。"],"lesson":"u04-l02","group":"para 相关"},{"w":"bug","p":"bʌɡ","m":"n.虫子；小病；计算机故障","tip":"我们经常说“电脑上的某个程序有个 bug”，bug 就是“计算机故障”。","ex":["This is the strangest bug I've ever seen.","这是我见过的最奇特的虫子。"],"lesson":"u04-l02","group":"para 相关"},{"w":"insect","p":"ˈɪnsekt","m":"n.昆虫","tip":"in（里面）+ sect（音似“塞个它”）→他的耳朵总不舒服，检查发现里面塞了一只“昆虫”。","ex":["On the road there is little to protect them from mud and insects.","在路上，几乎没有什么能保护它们免受泥土和昆虫的伤害。"],"lesson":"u04-l02","group":"para 相关"},{"w":"worm","p":"wɜːm","m":"n.虫，蠕虫","tip":"单词发音类似“乌木”→乌木受潮了，里面特别容易生“虫”。","ex":["Worms burrow down through the soil.","蠕虫往土里钻。"],"lesson":"u04-l02","group":"para 相关"},{"w":"wooden","p":"ˈwʊdn","m":"adj.木制的；呆板的","tip":"","ex":["Their aim was to provide quality, yet affordable wooden furniture.","他们的目标是提供高质量且价格合理的木制家具。"],"lesson":"u04-l02","group":"para 相关"},{"w":"timber","p":"ˈtɪmbə(r)","m":"n.木材；大木料，栋木","tip":"Timberland（添柏岚）是一个户外品牌，我们常常戏称它的谐音为“踢不烂”，因为 timber 是坚固的“木材”。","ex":["At the time, most large homes were constructed of timber and brick.","当时，大多数大房子都是用木材和砖建造的。"],"lesson":"u04-l02","group":"para 相关"},{"w":"chase","p":"tʃeɪs","m":"v.努力获取；追赶，追求；赶走","tip":"cha（联想“叉”）+ se（音似“死”）→他“追赶”着臭虫，想用叉子叉死它。","ex":["They decided to chase the cow away.","他们决定把牛赶走。"],"lesson":"u04-l02","group":"para 相关"},{"w":"purchase","p":"ˈpɜːtʃəs","m":"v.购买；采购","tip":"单词发音类似“破车子”→车子很破了，那就“购买”个新的吧。","ex":["They purchase increasing quantities of sweets.","他们购买越来越多的糖果。"],"lesson":"u04-l02","group":"para 相关"},{"w":"pursue","p":"pəˈsjuː","m":"v.追求；致力于；执行；贯彻","tip":"单词发音类似“破书”→他把书都翻破了，就是为了“追求”真理。","ex":["We should feel happy when we pursue knowledge for knowledge's sake.","当我们为了知识本身而追求知识时，应该感到快乐。"],"lesson":"u04-l02","group":"para 相关"},{"w":"translate","p":"trænzˈleɪt","m":"v.翻译；解释，说明","tip":"","ex":["It can be avoided if human values are translated into their language.","如果把人类的价值观翻译成他们的语言，这是可以避免的。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"transplant","p":"trænsˈplɑːnt","m":"n.（器官等的）移植","tip":"trans-（从……到……）+ plant（种植）→ 从这里种到那里 → 移植；移栽","ex":["Many others attempted to transplant their habits and traditions to the new world.","还有许多人试图将他们的习惯和传统移植到新世界。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"transform","p":"trænsˈfɔːm","m":"v.使改变形态；使改观；变形","tip":"trans-（从……到……）+ form（形式）→ 从一种形式到另外一种形式 → 使改变形态","ex":["It will force cities to transform their infrastructure.","这将迫使城市改变其基础设施。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"platform","p":"ˈplætfɔːm","m":"n.平台；站台；纲领","tip":"plat（平的）+ form（形式，形状）→ 平台；站台","ex":["The train now standing at platform 1 is for Leeds.","停靠在1号站台的火车是开往利兹的。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"transport","p":"ˈtrænspɔːt","m":"n.交通运输系统；运输工具；激动","tip":"trans-（从……到……）+ port（港口）→ 从一个港口到另一个港口 → 运输","ex":["She is used to taking public transport.","她习惯于乘坐公共交通工具。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"transaction","p":"trænˈzækʃn","m":"n.交易，业务；办理","tip":"trans-（从……到……）+ action（行动）→ 从一个行动到另一个行动 → 交易","ex":["Technology has reduced transaction costs.","技术降低了交易成本。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"transfer","p":"trænsˈfɜː(r)","m":"v.转移；改编","tip":"trans-（从……到……）+ fer（音似“佛”）→ 唐僧师徒把佛经从西天“转移”至大唐。","ex":["How many bacteria actually transfer in five seconds?","有多少种细菌能在五秒钟内转移？"],"lesson":"u04-l03","group":"trans 相关"},{"w":"transit","p":"ˈtrænzɪt","m":"v.通过；转运 n.运输，运送","tip":"trans-（从……到……）+ it（它）→ 把它从这“转运”到那。","ex":["He had to transit a forest to reach the finish line.","他必须穿过一片森林才能到达终点线。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"transparent","p":"trænsˈpærənt","m":"adj.透明的；易看穿的，易懂的","tip":"trans-（从……到……）+ parent（父母）→ 父母之间彼此很了解 → 透明的；易懂的","ex":["Let the debates be transparent and vigorous, wherever they are held.","无论在何处举行辩论，都应使辩论易懂而有力。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"apparent","p":"əˈpærənt","m":"adj.显然的；表面上的；貌似的","tip":"ap-（一再地）+ parent（父母）→ 她一再地提到父母，显然她很爱他们 → 显然的","ex":["These invisible duties become apparent only when you don't do them.","只有当你不去做的时候，这些看不见的责任才会变得明显。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"obvious","p":"ˈɒbviəs","m":"adj.明显的，显然的；平淡无奇的","tip":"","ex":["Start with the most obvious place first: the company's website.","首先从最明显的地方开始：公司的网站。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"evident","p":"ˈevɪdənt","m":"adj.明显的；明白的","tip":"单词发音类似“俺为等他”→ 俺为了在机场等他，站在人群中很“明显的”地方。","ex":["The fridge's effect upon the environment has been evident.","冰箱对环境的影响已经很明显了。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"evidence","p":"ˈevɪdəns","m":"n.证据；（法庭）证物，证词","tip":"evident adj. 明显的；明白的 → evidence n.","ex":["There was no evidence that the meeting took place.","没有证据表明有过这次会面。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"trace","p":"treɪs","m":"n.痕迹；微量 v.追踪；跟踪","tip":"我和他比赛（race）追踪（trace）丢失钱包的下落。","ex":["Each time this initial memory trace is \"replayed\", it becomes even stronger.","每次这种最初的记忆痕迹被“重播”时，它就会变得更加强烈。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"trail","p":"treɪl","m":"n.踪迹；痕迹；路线 v.跟踪；拖","tip":"t（联想“他”）+ rail（联想 railway）→ 他沿着铁路走，留下了“踪迹”。","ex":["The hounds were following the fox's trail.","猎犬追踪着狐狸的气味。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"rail","p":"reɪl","m":"n.铁路；栏杆；铁轨 v.怒斥，抱怨","tip":"","ex":["Isn't this the same crowd that rails against processed junk and champions craft cooking?","这不就是那些怒斥加工垃圾、拥护手工烹饪的人吗？"],"lesson":"u04-l03","group":"trans 相关"},{"w":"track","p":"træk","m":"v.跟踪；追踪 n.轨道；踪迹","tip":"单词发音类似“踹开”→ 一个玩具小火车正在“轨道”上跑，突然被他一脚踹开了。","ex":["Keep track of left-handed children's school performance.","跟踪左利手孩子在学校的表现。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"orbit","p":"ˈɔːbɪt","m":"n.轨道 v.沿轨道运行","tip":"or（或者）+ bit（音似“逼他”）→ 朋友们或者劝他，或者逼他，只盼颓废的他重回正常生活的“轨道”。","ex":["The two spacecrafts will link up in orbit.","两艘宇宙飞船将在轨道上对接。"],"lesson":"u04-l03","group":"trans 相关"},{"w":"boom","p":"buːm","m":"v. & n.（发出）隆隆声；激增，繁荣","tip":"boo（形似600）+ m（联想 meter）→ 方圆600米内一片“繁荣”。","ex":["It still has a chance to give rise to a boom in the global economy.","（中国）仍有机会为全球经济带来繁荣。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"bloom","p":"bluːm","m":"n.花 v.开花","tip":"bloo（形似6,100）+ m（联想“美”）→ 广场上布置了6,100朵美丽的“花”。","ex":["With the development in science and technology man can make various flowers bloom before their time.","随着科学技术的发展，人们可以使各种各样的花提前绽放。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"blossom","p":"ˈblɒsəm","m":"n.花朵 v.开花","tip":"单词发音类似“捕捞色木”→ 他捕鱼时捞上来一根彩色的木头，上面刻有漂亮的“花朵”。","ex":["The trees are in blossom.","树上鲜花盛开。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"gloom","p":"ɡluːm","m":"n.忧郁；幽暗；黑暗","tip":"g（联想“哥”）+ loo（形似100）+ m（联想“米”）→ 哥哥看不清100米以外的东西，表情很“忧郁”。","ex":["We watched the boats come back in the gathering gloom.","我们注视着船只在越来越浓的暮色中返航。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"boost","p":"buːst","m":"v.促进，推动；使兴旺 n.促进；宣扬","tip":"boo（形似600）+ st（联想 street）→ 修600条街道能“促进”当地经济的增长。","ex":["Agreeable people boost your confidence.","随和的人会增强你的自信。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"boast","p":"bəʊst","m":"v.自夸；吹嘘；有（值得自豪的东西） n.夸耀","tip":"单词发音类似“宝石塔（一种游戏）”→ 他“吹嘘”说他总能赢宝石塔游戏。","ex":["They boast the longest battery life.","它们拥有最长的电池寿命。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"brag","p":"bræɡ","m":"v.吹嘘；自吹自擂","tip":"单词发音类似“布拉格”→ 他“吹嘘”自己去过布拉格。","ex":["He bragged about how brave he was.","他吹嘘自己多么勇敢。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"raw","p":"rɔː","m":"adj.生的，未加工的；不熟练的，没有经验的","tip":"单词发音类似“肉”→ 这些肉是“生的”，不能吃。","ex":["Many governments have done more than the US government in providing the raw materials for innovation.","在提供原材料促进创新方面，许多政府比美国政府做得更多。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"ripe","p":"raɪp","m":"adj.熟的；时机成熟的","tip":"ri（联想“日”）+ pe（音似“扑”）→ 扑向太阳的植物很容易成熟 → 熟的","ex":["Pick the tomatoes before they get too ripe.","在西红柿过度成熟之前把它们摘下来。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"reap","p":"riːp","m":"v.取得（成果）；收获；收割（庄稼）","tip":"阅读（read）会使你收获（reap）知识。","ex":["Now is the time to reap.","现在是收获的时候了。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"harvest","p":"ˈhɑːvɪst","m":"n.收获，成果 v.收割；采集","tip":"harv（联想 have）+ est（联想“最高级后缀”）→“收获”的季节有最多的好吃的。","ex":["Prices typically returned to normal with the next harvest.","价格通常会在下一次收获时恢复正常。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"yield","p":"jiːld","m":"n.产量；利润 v.出产；屈服","tip":"yi（音似“爷”）+ eld（联想 old）→ 爷爷很老了还在种庄稼，“出产”粮食。","ex":["Their grain yields have begun to decrease sharply in recent years.","近年来，他们的粮食产量已开始急剧下降。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"mature","p":"məˈtʃʊə(r); məˈtjʊə(r)","m":"adj.成熟的，成年的；技艺精湛的 v.成熟；成长","tip":"ma（联想“妈”）+ ture（联想 true）→ 当了妈妈后，她真正“成熟”了。","ex":["He is able to think and speak like a mature adult.","他能够像一个成熟的成年人一样思考和说话。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"plough","p":"plaʊ","m":"n.犁 v.犁，耕（地）","tip":"单词发音类似“扑老”→ 他扑向那个正在“耕地”的老人，要给他帮忙。","ex":["Land currently ploughed up for crops might be able to revert to forest or wilderness.","目前用来种植的土地可能会恢复为森林或荒野。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"irrigation","p":"ˌɪrɪˈɡeɪʃn","m":"n.灌溉","tip":"i（形似人）+ rr（形似两朵花）+ i（形似人）+ gat（联想 gate）+ -ion（名词后缀）→ 两个人站在大门口“灌溉”两朵花。","ex":["The biggest challenge here is irrigation.","这里最大的挑战是灌溉。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"dominate","p":"ˈdɒmɪneɪt","m":"v.支配；控制；俯视","tip":"在过去，那个有圆屋顶（dome）的教堂在本地占统治（dominate）地位。","ex":["The same can be said of their ability to dominate the corporate boardroom.","他们主导公司董事会的能力也是如此。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"dominant","p":"ˈdɒmɪnənt","m":"adj.首要的；占支配地位的；（基因）显性的；优势的","tip":"domin（联想 dome）+ ant（蚂蚁）→ 蚂蚁占领了圆顶的房子 → 首要的；占支配地位的","ex":["It is playing a dominant role in the film market.","它在电影市场上发挥着主导作用。"],"lesson":"u04-l03","group":"“土地”相关"},{"w":"domestic","p":"dəˈmestɪk","m":"adj.家庭的；国内的","tip":"dome（联想 home）+ stic → 中国是我们共同的家 → 家庭的；国内的","ex":["To lower domestic food prices, some countries limited or stopped their grain exports.","为了降低国内食品价格，一些国家限制或停止了粮食出口。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"chore","p":"tʃɔː(r)","m":"n.家庭杂务；日常事务；例行工作","tip":"单词发音类似“瞧”→ 不要每天在家瞧着妈妈干“家庭杂务”，你也要帮把手。","ex":["Paying an allowance for completing chores benefits their children.","为完成家务支付津贴对他们的孩子有好处。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"dull","p":"dʌl","m":"adj.枯燥的；不鲜明的；迟钝的；萧条的","tip":"du（联想“读”）+ ll（形似11）→ 她读了11本书都不感兴趣，感觉很枯燥 → 枯燥的","ex":["Well-functioning machines relieve them of dull tasks.","运行良好的机器可以减轻他们枯燥的任务。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"dumb","p":"dʌm","m":"adj.愚蠢的；哑的；无言的","tip":"du（联想“毒”）+ mb（联想“面包”）→ 公主吃完毒面包变哑了 → 哑的","ex":["Some people are dumb enough to want children just because seeing others do so.","有些人愚蠢到想要孩子只是因为看到别人这样做。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"tedious","p":"ˈtiːdiəs","m":"adj.单调的，乏味的","tip":"te（音似“提”）+ di（音似“弟”）+ -ous（形容词后缀）→ 妈妈总是在外人面前提弟弟过去的事儿，太乏味了 → 单调的，乏味的","ex":["It was a hard and tedious job.","它是一项艰苦而乏味的工作。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"schedule","p":"ˈʃedjuːl","m":"n.工作计划；日程安排；时间表 v.安排，预定","tip":"s（联想“私”）+ chedule（联想“车堵了”）→ 私家车堵在路上了，耽误了我们的“日程安排”。","ex":["They were complete clock watchers, while I would have liked a more flexible schedule.","他们是彻头彻尾的守时者，而我希望有一个更灵活的时间表。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"scheme","p":"skiːm","m":"n.计划；方案；阴谋","tip":"s（联想“美女”）+ che（联想“车”）+ me（我）→ 美女有开车送我的“计划”。","ex":["Universities want the government to introduce a loan scheme for tuition fees.","大学希望政府推出一项学费贷款计划。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"agenda","p":"əˈdʒendə","m":"n.（会议的）议程表，议事日程","tip":"a（一）+ gen（音似“件”）+ da（联想“大”）→ 一件大事必须放到“议程表”里。","ex":["Information protection is high on the boss's agenda in businesses of every variety.","信息保护在各行各业的老板的议事日程上都处于重要地位。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"routine","p":"ruːˈtiːn","m":"n.常规；日常工作；例行程序","tip":"单词发音类似“路听”→ 老板的“日常工作”很忙，时常在路上听秘书汇报工作。","ex":["We love to establish a routine and stick with it.","我们喜欢建立一个常规并坚持下去。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"route","p":"ruːt","m":"n.路线；途径；渠道","tip":"r（形似花）+ out（出去）+ e（字母音似“—”）→ 他每次把花扔出去，都是沿着同一条“路线”的。","ex":["I followed my route like I normally do.","我像往常一样走自己的路线。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"passage","p":"ˈpæsɪdʒ","m":"n.通过；通道；文章","tip":"pass v.通过→passage n.","ex":["To get to the place requires going through a very narrow passage.","要到达这个地方，需要经过一条非常狭窄的通道。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"interior","p":"ɪnˈtɪəriə(r)","m":"n.内部；内地 adj.内部的","tip":"","ex":["The original interior of the hotel has been replaced.","旅馆原来的内部装潢已经更换掉了。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"exterior","p":"ɪkˈstɪəriə(r)","m":"n.外部，表面，外貌 adj.外部的；表面的","tip":"","ex":["The exterior lights of the house came on as I approached the door.","当我走近门的时候，房子外面的灯亮了。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"external","p":"ɪkˈstɜːnl","m":"adj.外部的；外来的；对外的","tip":"","ex":["Why is there both external and internal pressure to look \"perfect\"?","为何会有外在和内在的双重压力来让自己看起来“完美”？"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"internal","p":"ɪnˈtɜːnl","m":"adj.内部的；内政的；国内的","tip":"","ex":["She was on an internal flight from London to Manchester.","她在从伦敦到曼彻斯特的国内航班上。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"inner","p":"ˈɪnə(r)","m":"adj.里面的，向内的；内心的","tip":"","ex":["They seldom expressed their inner thoughts.","他们很少表达内心的想法。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"media","p":"ˈmiːdiə","m":"n.大众传播；媒体，媒介","tip":"","ex":["The news media reported extensively on the story.","新闻媒体广泛报道了这个故事。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"medium","p":"ˈmiːdiəm","m":"adj.中等的；中号的 n.（传播信息的）媒介，方法","tip":"衣服上的m码不是middle（中间的），而是medium（中号的）。","ex":["You have a choice of a small, medium or large soda.","您可以选择小杯、中杯或者大杯苏打水。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"intermediate","p":"ˌɪntəˈmiːdiət","m":"adj.中等的，中间的，中级的 n.中级学生","tip":"inter-（中间的）+ media（媒体）+ te（联想“特”）→ 在中间的媒体，不是特别好也不是特别差 → 中等的","ex":["Fewer than half of Americans say they cook at an intermediate level.","不到一半的美国人说他们的烹饪水平处于中等。"],"lesson":"u04-l03","group":"domestic 相关"},{"w":"local","p":"ˈləʊkl","m":"n.本地人 adj.地方性的，当地的","tip":"单词发音类似“唠嗑”→ 她喜欢跟“本地人”唠嗑。","ex":["It creates a lot of trouble for local residents.","这给当地居民带来了很多麻烦。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"locate","p":"ləʊˈkeɪt","m":"v.探明；定位；位于","tip":"lo（联想“姥”）+ cate（音似 Kate，人名）→ 姥姥要找凯特，让我帮她“定位”。","ex":["Some of the world's most innovative companies are located here.","世界上一些最具创新性的公司都坐落在这里。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"site","p":"saɪt","m":"v.使坐落在 n.位置；网站","tip":"sit（坐）+ e → 使坐落在","ex":["It is an old city with many sites of historical interest.","它是一座有许多名胜古迹的古城。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"situate","p":"ˈsɪtʃueɪt","m":"v.位于；将……置于；使坐落于；处于（某种）状况","tip":"我找到了这座山的位置（site），它位于（situate）东部。","ex":["The test site was situated in southwestern New Mexico.","该试验场位于新墨西哥州西南部。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"cite","p":"saɪt","m":"v.列举；引用","tip":"单词发音类似“赛他”→ 在这场作文大赛中，他“引用”了一些格言。","ex":["She cited examples of companies the city has helped relocate or expand.","她列举了该市帮助搬迁或扩张的公司的例子。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"bite","p":"baɪt","m":"v.咬；上钩；蜇 n.咬伤；寒冷","tip":"单词发音类似“拜他”→ 孩子拜托爸爸帮忙“咬”开他的零食包装袋。","ex":["She was bitten by the family dog.","她被家里的狗咬伤了。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"website","p":"ˈwebsaɪt","m":"n.网站","tip":"","ex":["For current prices, please visit our website.","有关目前的价格，请访问我们的网站。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"web","p":"web","m":"n.网络；蜘蛛网；错综复杂的事物","tip":"","ex":["But what are the challenges of moving to \"spoken web\"?","但是，向“语音网络”转变的挑战是什么呢？"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"click","p":"klɪk","m":"v.点击；单击；豁然开朗 n.（对计算机鼠标的）单击；咔嗒声","tip":"单词发音类似“渴立刻”→ 他口渴了，打开电脑立刻“点击”网站购买水。","ex":["I clicked on the link to the next page of the website.","我单击链接好翻到网站的下一页。"],"lesson":"u04-l03","group":"“位置”相关"},{"w":"pose","p":"pəʊz","m":"n.（为画像、拍照等摆的）姿势 v.摆姿势；造成；引起","tip":"","ex":["It poses a great challenge for customers to do math.","对客户来说算数是一项很大的挑战。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"posture","p":"ˈpɒstʃə(r)","m":"n.姿势，态度；立场","tip":"pose v.摆姿势 → posture n.","ex":["Back pains can be the result of bad posture.","背疼可能是不良姿势造成的。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"expose","p":"ɪkˈspəʊz","m":"v.（使）暴露；使接触；揭露；曝光","tip":"ex-（向外）+ pose（摆放）→（使）暴露；揭露","ex":["My job as a journalist is to expose the truth.","我作为记者的职责就是揭露真相。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"dispose","p":"dɪˈspəʊz","m":"v.处置；布置；排列；安排；使倾向于；去掉","tip":"dis-（分开）+ pose（摆放）→布置；排列","ex":["They find it difficult to dispose of their old-style furniture.","他们发现很难处置他们的旧式家具。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"rid","p":"rɪd","m":"v.摆脱；丢弃；除掉 adj.摆脱的，去掉的","tip":"ri（联想“日”）+ d（音似“的”）→ 后羿射日就是“除掉”天上的九个太阳。","ex":["He intends to get rid of the tipping practice.","他打算取消给小费的做法。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"suppose","p":"səˈpəʊz","m":"v.推断；假设；设想","tip":"sup-（在下面）+ pose（摆放）→在下面摆放（条件）→假设","ex":["I suppose it will rain tomorrow, so we should bring umbrellas.","我猜明天会下雨，所以我们应该带伞。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"positive","p":"ˈpɒzətɪv","m":"adj.乐观的，积极的；阳性的；正面的 n.优势，优点","tip":"posit（= pose，放）+ -ive（后缀）→（把情绪等）摆放出来的→乐观的；积极的","ex":["Its negative effects more than cancel out its positive effects.","它的消极影响不仅仅抵消了它的积极影响。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"deposit","p":"dɪˈpɒzɪt","m":"n.存款；沉积物；押金 v.放下；寄放","tip":"de-（往下）+ posit（摆放）→沉积物；放下","ex":["You can withdraw and deposit money in any of our branches.","您可在我们任意一家分行办理存取款业务。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"compose","p":"kəmˈpəʊz","m":"v.组成，构成；作曲；撰写","tip":"com-（一起）+ pose（摆放）→摆放在一起→组成，构成","ex":["The earth is composed of several layers.","地球由几层组成。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"composition","p":"ˌkɒmpəˈzɪʃn","m":"n.作品，作文；作曲","tip":"compose v.组成；构成；作曲 → composition n.","ex":["He pulls up a music composition textbook, complete with playable demos.","他拿出了一本音乐作曲教材，里面有可播放的小样。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"component","p":"kəmˈpəʊnənt","m":"n.组成部分，成分；部件","tip":"compon（联想 compose）+ -ent（后缀）→组成部分，成分","ex":["The emotional component of the prizes is at work.","奖励的情感因素在起作用。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"impose","p":"ɪmˈpəʊz","m":"v.将……强加于；强制实行；勉强；征税","tip":"im-（里面）+ pose（摆放）→把……放到……里面→将……强加于","ex":["Do not impose your idea on me.","不要把你的思想强加于我。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"oppose","p":"əˈpəʊz","m":"v.反对，对抗","tip":"op-（反）+ pose（摆放）→摆放到相反的位置或立场→反对","ex":["The children strongly opposed the idea.","孩子们强烈反对这个想法。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"opposite","p":"ˈɒpəzɪt","m":"adj.相反的，不同的，对面的","tip":"","ex":["They are actually in opposite directions.","它们实际上是相反的方向。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"rival","p":"ˈraɪvl","m":"n.竞争者，对手 v.与……匹敌；比得上","tip":"riv（联想 river）+ a（形似一个矮胖小人）+ l（形似一个高瘦小人）→矮胖小人和高瘦小人是“对手”，在河的两边叫嚣。","ex":["Computers are man's potential rivals.","计算机是人类潜在的竞争对手。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"position","p":"pəˈzɪʃn","m":"n.位置；处境；地位 v.使处于；安置","tip":"posit（摆放）+ -ion（后缀）→位置；地位；使处于","ex":["In one study, students were told their social position in school is not unchangeable.","在一项研究中，学生们被告知他们在学校的社会地位并非一成不变。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"propose","p":"prəˈpəʊz","m":"v.建议；计划；求婚","tip":"pro-（往前）+ pose（摆放）→（把想法、心意等）在……前面摆放→建议；计划；求婚","ex":["She proposed that the book be banned.","她建议查禁这本书。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"counsel","p":"ˈkaʊnsl","m":"v.提供专业咨询 n.劝告；建议，讨论","tip":"coun-（= con-）+ sel（联想 sell）→我把几套房子一起卖掉，家人“劝告”我要慎重。","ex":["In the end, wiser counsels prevailed.","更高明的建议最终占了上风。"],"lesson":"u04-l04","group":"pose 相关"},{"w":"purpose","p":"ˈpɜːpəs","m":"n.意图；目的；重要意义","tip":"pur（联想 pure）+ pose（摆放）→她把最纯粹的“目的”放在心中。","ex":["For what purpose is \"the bad option\" added?","添加“坏选项”的目的是什么？"],"lesson":"u04-l04","group":"pose 相关"},{"w":"rural","p":"ˈrʊərəl","m":"adj.乡村的，农村的","tip":"单词发音类似“懦弱”→ 现在“农村的”年轻人都去城里打工了，留守在村里的主要是老弱妇孺。","ex":["Rural kids used to walk a long way to school in the old days.","过去农村的孩子们常常走很长的路去上学。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"agriculture","p":"ˈæɡrɪkʌltʃə(r)","m":"n.农业；农学","tip":"ag（联想“阿哥”）+ ri（联想“日”）+ culture（文化）→ 阿哥在太阳下耕种，学习“农业”相关的文化知识。","ex":["African agriculture is still broadly unproductive.","非洲农业仍然普遍缺乏生产力。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"urban","p":"ˈɜːbən","m":"adj.城市的，市内的","tip":"ur（音似“鹅”）+ ban（禁止）→ 该市区禁止养鹅 → 城市的，市内的","ex":["It has long been used to increase food supply and improve urban landscape.","长期以来，它被用来增加食物供给和改善城市景观。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"suburb","p":"ˈsʌbɜːb","m":"n.市郊，郊区","tip":"sub-（下面，次）+ urb（联想 urban）→ 市郊，郊区","ex":["They live in a wealthy suburb of Chicago.","他们住在芝加哥郊区的一处富人区。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"downtown","p":"ˌdaʊnˈtaʊn","m":"adv.往或在城市的商业区（或中心区、闹市区） n.城市的商业区，中心区，闹市区 adj.城市的商业区的，中心区的，闹市区的","tip":"down（下）+ town（城镇）→ 在城镇的下方 → 城市的商业区，中心区","ex":["He lives downtown and it is really noisy.","他住在市区，真的很嘈杂。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"citizen","p":"ˈsɪtɪzn","m":"n.公民；市民，居民","tip":"citi（联想 city）+ zen（音似“人”）→ 市民","ex":["Doing so will send an important message to the nation's youngest citizens.","这样做将向美国最年轻的公民传递一个重要的信息。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"civil","p":"ˈsɪvl","m":"adj.公民的；民用的；文明的","tip":"","ex":["We have been actively exercising our civil rights.","我们一直在积极行使我们的公民权。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"cultural","p":"ˈkʌltʃərəl","m":"adj.文化的；与艺术、文学、音乐等有关的","tip":"","ex":["It's a great way to promote cultural understanding and exchange; we welcome that.","这是促进文化理解和交流的好方法；我们对此表示欢迎。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"civilian","p":"səˈvɪliən","m":"n.平民；老百姓","tip":"civil（公民的）+ -ian（表示人的后缀）→ 平民","ex":["Further measures are needed to protect civilians.","需要采取进一步措施保护平民。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"country","p":"ˈkʌntri","m":"n.国家，国土；农村","tip":"","ex":["Across the country, 285 emergency management teams are devoted to crisis control.","全国有 285 个应急管理小组致力于危机控制。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"county","p":"ˈkaʊnti","m":"n.（英国的）郡，（美国的）县","tip":"","ex":["It sets a bar for similar initiatives across the county.","它为全县的类似举措设定了一个标准。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"nationwide","p":"ˌneɪʃ(ə)nˈwaɪd","m":"adj.全国性的；全国各地的 adv.在全国范围内","tip":"","ex":["Nationwide, the gap is even greater.","在全国范围内，差距甚至更大。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"worldwide","p":"ˌwɜːldˈwaɪd","m":"adj.世界各地的 adv.在全世界；遍及全球","tip":"","ex":["It has been popularised worldwide with the increasing influence of social media.","随着社交媒体影响力的日益增强，它在全球范围内得到了普及。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"widespread","p":"ˈwaɪdspred","m":"adj.分布广的；广泛流传的","tip":"","ex":["Such corporate sponsorship is widespread in some fields.","这种企业赞助在某些领域非常普遍。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"throughout","p":"θruːˈaʊt","m":"prep. & adv.遍及，到处；贯穿整个时期","tip":"through（穿过）+ out（出来）→ 遍及，到处","ex":["The dance group performs throughout the year but was now preparing for its biggest events.","这个舞蹈团全年都在表演，但现在正在为最盛大的活动做准备。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"continent","p":"ˈkɒntɪnənt","m":"n.洲，大陆","tip":"con-（所有）+ tin（音似“听”）+ ent（联想 enter）→ 所有听装罐头都运进“大陆”了。","ex":["Now we could sell our products all across the continent.","现在我们可以在整个大陆销售我们的产品。"],"lesson":"u04-l04","group":"“乡村、城市”相关"},{"w":"siege","p":"siːdʒ","m":"n.围困，包围，围攻","tip":"si（联想“四”）+ e（联想“鹅”）+ ge（联想“哥”）→ 四只鹅正在“围攻”哥哥。","ex":["Crowds of journalists laid siege to the star's apartment.","成群的记者包围了明星的公寓。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"surround","p":"səˈraʊnd","m":"n.周围；环绕 v.包围；环绕","tip":"sur-（上面）+ round（围绕）→ 包围；环绕","ex":["I am making my way through Columbia University, surrounded by students.","我正在哥伦比亚大学的路上，周围都是学生。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"surface","p":"ˈsɜːfɪs","m":"n.表面 v.升到表面","tip":"sur-（上面）+ face（面）→ 上面的面 → 表面","ex":["Eggs provide a unique surface to paint on.","鸡蛋为绘画提供了一个独特的表面。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"preface","p":"ˈprefəs","m":"n.序言，前言","tip":"pre-（前面）+ face（脸）→ 一本书前面那张“脸”就是“前言”。","ex":["Bruce added this key point in the preface to the panel's report.","布鲁斯在专家组报告的前言中补充了这一要点。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"climate","p":"ˈklaɪmət","m":"n.气候；氛围；形势","tip":"c（形似半圆）+ li（联想“立”）+ mate（朋友）→ 朋友们围着我站立成了半圆，营造出节日的“氛围”。","ex":["The terms \"global warming\" and \"climate change\" are used by us.","“全球变暖”和“气候变化”这两个术语被我们使用。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"mood","p":"muːd","m":"n.情绪；心情；气氛；（动词的）语气","tip":"他一个人坐着看月亮（moon），情绪（mood）有点儿低落。","ex":["People are ungrateful when in a bad mood.","人们心情不好的时候是不会领情的。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"atmosphere","p":"ˈætməsfɪə(r)","m":"n.大气；空气；气氛","tip":"atmo（联想“阿童木”）+ sphere（领域）→ 阿童木总在天上飞来飞去，“大气”就是他的活动领域。","ex":["They favoured a more rigid, closed-door, corporate atmosphere.","他们倾向于更严格、更封闭的公司氛围。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"sphere","p":"sfɪə(r)","m":"n.球体；范围；领域","tip":"s（联想“蛇”）+ p（联想“趴”）+ here（这里）→ 一条蛇趴在这里，这里就是它的活动“领域”。","ex":["Its advantage would be the improvement of freedom in every sphere of daily life.","它的优点是提高日常生活各个领域的自由度。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"scope","p":"skəʊp","m":"n.范围；（发挥能力等的）余地 v.查明","tip":"s（联想“美女”）+ cope（处理）→ 一个美女可以在一定“范围”内处理问题。","ex":["This subject lies beyond the scope of our investigation.","这一问题超出了我们的调查范围。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"environment","p":"ɪnˈvaɪrənmənt","m":"n.环境；客观环境","tip":"","ex":["He felt disappointed working in the environment.","在这种环境中工作让他感到失望。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"circumstance","p":"ˈsɜːkəmstæns","m":"n.条件；环境；状况","tip":"circum（联想 circle）+ st（联想 stand）+ -ance（名词后缀）→ 周围站立的事物等 → 环境","ex":["One is forced by circumstances to stop working.","一个人因环境而被迫停止工作。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"condition","p":"kənˈdɪʃn","m":"n.状态；条件；状况","tip":"单词发音类似“肯低身”→ 肯低身适应外界环境和“条件”，才能调整好身心“状态”。","ex":["They are responsible for their own condition.","他们对自己的状况负责。"],"lesson":"u04-l04","group":"surround 相关"},{"w":"cycle","p":"ˈsaɪkl","m":"n.自行车；循环 v.骑自行车；循环","tip":"","ex":["The cycle of renewal never ends.","更新的循环永远不会结束。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"recycle","p":"ˌriːˈsaɪkl","m":"v.回收利用，再利用；重新使用","tip":"","ex":["The objective would be to recycle 98 percent of domestic waste.","该目标是循环使用 98% 的生活垃圾。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"circle","p":"ˈsɜːkl","m":"n.圆；圈子；阶层 v.环绕；画圈","tip":"","ex":["Start a public discussion on how to raise women's status in academic circles.","就如何提高女性在学术圈的地位展开公开的讨论。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"oval","p":"ˈəʊvl","m":"adj.椭圆形的 n.椭圆形","tip":"o（形似蛋）+ v（形似罗马数字 5）+ al（联想 all）→ 这五个蛋都是“椭圆形的”。","ex":["Eggs have an oval shape appealing to artists.","鸡蛋呈椭圆形，对艺术家很有吸引力。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"circuit","p":"ˈsɜːkɪt","m":"n.环行；环行路线；电路；赛车道","tip":"circle n.圆；圈子 v.环绕 → circuit n.","ex":["The earth takes a year to make a circuit of the sun.","地球绕太阳运行一周需要一年的时间。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"circus","p":"ˈsɜːkəs","m":"n.马戏团；马戏表演","tip":"他沿着一条环形路线（circuit）去了马戏团（circus）。","ex":["We took the children to the circus.","我带孩子去看了马戏表演。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"circulate","p":"ˈsɜːkjəleɪt","m":"v.（液体或气体）环流，循环，流传","tip":"circul（联想 circle）+ -ate（动词后缀）→ 使绕圈转起来 → 循环","ex":["They don't want their photos to be circulated on the Internet.","他们不希望自己的照片在网上流传。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"setting","p":"ˈsetɪŋ","m":"n.环境；背景；挡位","tip":"set（设置）+ ting（联想“听”）→ 他设置好播放器，选择了一个安静的“环境”来听音乐。","ex":["The technology has a place in educational settings.","这项技术在教育环境中占有一席之地。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"background","p":"ˈbækɡraʊnd","m":"n.背景；幕后","tip":"back（背后）+ ground（地面）→ 背景；幕后","ex":["Carey's background is in deal making and innovation.","凯里的背景是交易和创新。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"context","p":"ˈkɒntekst","m":"n.背景，上下文","tip":"con-（所有）+ text（课本）→ 我们要了解课本上所有文章的“背景”和来龙去脉。","ex":["It is heavily dependent on the context.","它严重依赖于上下文。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"contest","p":"ˈkɒntest","m":"n.竞争；比赛","tip":"con-（一起）+ test（检验）→ 一起检验孰优孰劣 → 竞争；比赛","ex":["I'm preparing for the speech contest.","我正在为演讲比赛做准备。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"protest","p":"ˈprəʊtest","m":"n.抗议；反对","tip":"pro-（在前，公开）+ test（检验，作证）→ 公开作证，表达立场 → 抗议；反对","ex":["It kept sending letters of protest to the media.","它不断向媒体发抗议信。"],"lesson":"u04-l04","group":"“环”相关"},{"w":"conduct","p":"ˈkɒndʌkt","m":"v.执行；指挥；引导；传导（热，电）","tip":"con-（都）+ duct（音似“搭客特”）→ 他“指挥”众人都搭上了那辆客车，特别有秩序。","ex":["It is a code of conduct based on laws and ethics.","它是基于法律和道德的行为准则。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"direct","p":"dəˈrekt; daɪˈrekt","m":"adj.直接的 v.管理，指导；指挥；把……对准","tip":"di（联想“弟”）+ re（字母音似“阿姨”）+ ct（音似“渴特”）→ 弟弟“指导”阿姨跳舞，说话说得特别渴。","ex":["The food industry has, in general, been firmly opposed to such direct government action.","总的来说，食品行业一直坚决反对这种直接行动。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"direction","p":"dəˈrekʃn; daɪˈrekʃn","m":"n.方向，方位；指示","tip":"direct（指导）+ -ion（名词后缀）→ 方向，方位；指示","ex":["This research provides a useful direction for organisations.","本研究为组织提供有益的指示。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"instruct","p":"ɪnˈstrʌkt","m":"v.命令，指示；告知；传授","tip":"in（里面）+ struct（音似“死抓个他”）→ 他们在里面死抓着他，“命令”他交出证据。","ex":["You will be instructed where to go when the plane is ready.","飞机准备好时，会通知你去何处。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"command","p":"kəˈmɑːnd","m":"v.指挥；命令；控制 n.指挥；命令；指示","tip":"com-（所有）+ mand（音似“慢的”）→ 所有速度慢的车都在听他“指挥”。","ex":["He commanded his men to retreat.","他命令手下撤退。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"military","p":"ˈmɪlətri","m":"n.军方 adj.军事的","tip":"mili（音似“迷了”）+ tary（音似 tree）→ 他在外面迷了路，发现树下有辆“军方”的车。","ex":["They told him the military exercise was over.","他们告诉他军事演习结束了。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"enemy","p":"ˈenəmi","m":"n.敌人；敌军；危害物","tip":"单词发音类似“俺的米”→ 俺的米被“敌人”洗劫一空。","ex":["Boredom is the enemy of learning.","厌学是学习的大敌。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"forth","p":"fɔːθ","m":"adv.向前","tip":"fore n.前部，前面 → forth adv.","ex":["Closing post offices is one of several proposals the Postal Service has put forth recently to cut costs.","关闭邮局是邮政服务最近为了降低成本提出的几个建议之一。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"forthcoming","p":"ˌfɔːθˈkʌmɪŋ","m":"adj.即将到来的；现成；随要随有","tip":"","ex":["Keep an eye on the noticeboards for forthcoming events.","注意布告牌上的活动预告。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"forward","p":"ˈfɔːwəd","m":"adv.向前 adj.向前的 v.发送，促进","tip":"for(e)（前）+ -ward（表示方向的后缀）→ 向前（的）","ex":["It is the force that pushes human society forward.","它是推动人类社会前进的力量。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"forever","p":"fərˈevə(r)","m":"adv.永远；不断地；长久地","tip":"","ex":["Just keep telling yourself that it won't last forever.","要不停地提醒自己，不会一直都是这样的。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"foremost","p":"ˈfɔːməʊst","m":"adj.最先的；最重要的 adv.首先","tip":"fore（前）+ most（最）→ 最前面的 → 最先的；最重要的","ex":["I'd like to introduce you to the world's foremost authority on the subject.","我想把你介绍给该学科全世界首屈一指的专家。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"foresee","p":"fɔːˈsiː","m":"v.预见，预知","tip":"fore（前）+ see（看见）→ 提前看见 → 预见","ex":["It is impossible to foresee how life will work out.","预知生命将如何发展是不可能的。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"oversee","p":"ˌəʊvəˈsiː","m":"v.监督；监视","tip":"over（在上面）+ see（看见）→ 在上面看 → 监督","ex":["United Nations observers oversaw the elections.","联合国观察员监督了选举。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"overhead","p":"ˌəʊvəˈhed","m":"adv.在头顶上 adj.头上方的；地面上的","tip":"over（在上面）+ head（头）→ 在头顶上","ex":["Planes flew overhead constantly.","飞机不断从头顶上飞过。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"forecast","p":"ˈfɔːkɑːst","m":"v. & n.预测；预报","tip":"fore（前）+ cast（投；抛）→ 在事情发生前投出来 → 预测","ex":["The forecast assumes continued improvements in yields.","这一预测假设收益会持续提高。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"cast","p":"kɑːst","m":"v.投；抛；投射（光等） n.投；抛；全体演员","tip":"","ex":["Someone was standing in the dark shadow cast by the light.","有人站在灯光投下的阴影中。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"toss","p":"tɒs","m":"v.扔，抛；使摇摆 n.掷硬币决定；猛抬头","tip":"他们掷硬币决定（toss）谁做老板（boss）。","ex":["How can you predict where the ball you tossed will land?","你怎么能预测你扔出的球会落在哪里？"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"broadcast","p":"ˈbrɔːdkɑːst","m":"v.播送（电视或无线电节目）；广播；散布，传播（信息等） n.广播节目；电视节目","tip":"broad（广阔的）+ cast（投）→ 在广阔的地方投放 → 广播；散布；广播节目；电视节目","ex":["Chase Carey used to serve as a top advisor for a major broadcasting company.","蔡斯·凯里曾是一家大型广播公司的首席顾问。"],"lesson":"u05-l01","group":"“指挥”相关"},{"w":"status","p":"ˈsteɪtəs","m":"n.法律地位（或身份）；地位；职位","tip":"stat（联想 state）+ us（我们）→ 在我们国家，人人“地位”平等。","ex":["People's earnings are closely related to people's social status.","人们的收入与其社会地位密切相关。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"statue","p":"ˈstætʃuː","m":"n.雕像，雕塑","tip":"sta（联想 stay）+ tue（联想 true）→ 那个“雕像”真的一直待在那儿。","ex":["The Statue of Liberty stands above the harbour of New York.","自由女神像耸立在纽约港的上空。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"liberty","p":"ˈlɪbəti","m":"n.自由","tip":"liber（音似“隶搏”）+ -ty（名词后缀）→ 奴隶拼搏是为了“自由”。","ex":["The prisoner was deprived of his civil liberty for three years.","该囚犯被剥夺公民自由长达三年。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"liberate","p":"ˈlɪbəreɪt","m":"v.使自由；解放；使摆脱约束（或限制）","tip":"","ex":["Writing poetry liberated her from the routine of everyday life.","写诗使她从日常生活的例行公事中解放出来。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"liberal","p":"ˈlɪbərəl","m":"adj.自由的，开明的；慷慨的；丰富的 n.开明人士","tip":"","ex":["I had quite liberal parents.","我的父母思想很开明。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"deliberate","p":"dɪˈlɪbərət","m":"adj.故意的；深思熟虑的","tip":"de（联想“弟”）+ liberate（使自由）→ 弟弟经过“深思熟虑”，决定还那只小鸟自由。","ex":["See if there was a deliberate cover-up of the problem.","看看是否有人故意掩盖问题。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"generous","p":"ˈdʒenərəs","m":"adj.慷慨的，大方的；丰富的","tip":"单词发音类似“姐弄肉丝”→ 我去姐姐家做客，“慷慨的”她炒了一大盘鱼香肉丝。","ex":["Oh, and they'd give me two months of paid vacation with a very generous salary.","哦，他们还会给我两个月的带薪假期，薪水很丰厚。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"mean","p":"miːn","m":"v.原意为；意味 adj.吝啬的；卑鄙的，不善良的","tip":"me（音似“米”）+ an（一）→ 她说我只请她吃了一碗米饭，是个“吝啬的”人。","ex":["It doesn't mean it's all good news for future food.","这并不意味着这对未来的食品来说都是好消息。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"means","p":"miːnz","m":"n.方式；方法；手段；途径","tip":"","ex":["There are various means the consumers may use to gain satisfaction.","消费者可以使用各种方式来获得满足。"],"lesson":"u05-l01","group":"“雕像、自由”相关"},{"w":"author","p":"ˈɔːθə(r)","m":"n.作家，作者；创造者，发起人","tip":"au（音似“傲”）+ thor（音似 sir）→ 那位骄傲的先生是个“作家”。","ex":["The criticism the author received from his readers changed him.","作者从读者那里受到的批评改变了他。"],"lesson":"u05-l01","group":"“作者”相关"},{"w":"authority","p":"ɔːˈθɒrəti","m":"n.专家；权威；许可，授权；当局","tip":"作家（author）就是自己作品的创造者，也是权威（authority）。","ex":["Decentralisation of authority was also found to be more effective in military operations.","权力下放也被发现在军事行动中更为有效。"],"lesson":"u05-l01","group":"“作者”相关"},{"w":"authentic","p":"ɔːˈθentɪk","m":"adj.真正的，真实的；可靠的","tip":"关于作品的中心思想，原作者（author）的观点才是真实的、可靠的（authentic）。","ex":["But sharing our experiences in an authentic way to connect with other people is what makes us interesting.","但是以一种真实的方式分享我们的经历以便与他人建立联系，可以让我们变得有趣。"],"lesson":"u05-l01","group":"“作者”相关"},{"w":"sincere","p":"sɪnˈsɪə(r)","m":"adj.诚挚的，真诚的，诚恳的","tip":"since（自从）+ re（字母音似“阿姨”）→ 自从遇见这位阿姨，这个小孩变成一个“真诚的”人了。","ex":["He wanted to make a sincere apology to Jimmy.","他想向吉米真诚地道歉。"],"lesson":"u05-l01","group":"“作者”相关"},{"w":"genuine","p":"ˈdʒenjuɪn","m":"adj.真正的；真诚的，真挚的","tip":"单词发音类似“姐牛”→ 姐姐很专业，是“真正的”牛人。","ex":["It may prevent people from developing a genuine sense of community.","它可能会阻碍人们形成真正的社区意识。"],"lesson":"u05-l01","group":"“作者”相关"},{"w":"genius","p":"ˈdʒiːniəs","m":"n.天才；天赋；才能，本领","tip":"ge（联想“哥”）+ nius（音似“牛死”）→ 哥哥是个非常厉害的牛人，人称“天才”。","ex":["I had heard that genius could show itself at an early age.","我听说天赋在很小的时候就能表现出来。"],"lesson":"u05-l01","group":"“作者”相关"},{"w":"elite","p":"eɪˈliːt; ɪˈliːt","m":"n.精英；上层人士 adj.杰出的；精英的","tip":"e-（向外，出）+ lite（音似“离他”）→ 他走出去离开父母，努力拼搏，成了“精英”。","ex":["Students in elite school districts have gained attention in recent years.","近年来，精英学区的学生受到了关注。"],"lesson":"u05-l01","group":"“作者”相关"},{"w":"previous","p":"ˈpriːviəs","m":"adj.先前的，以往的；（时间上）稍前的","tip":"pre-（前面）+ vi（= way）+ -ous（形容词后缀）→ 走在前面的 → 先前的，以往的","ex":["The majority of previous research has focused on how we learn and remember new information.","大部分之前的研究侧重于我们如何学习和记忆新信息。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"prior","p":"ˈpraɪə(r)","m":"adj.先前的；较早的；优先的；较重要的","tip":"pri（联想 pre-，前面）+ -or（后缀）→ 先前的；较早的","ex":["Absorbing new information is helpful in making better decisions prior to action.","吸收新信息有助于在行动前做出更好的决定。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"priority","p":"praɪˈɒrəti","m":"n.优先，优先权；优先事项","tip":"prior（优先的）+ -ity（名词后缀）→ 优先，优先权","ex":["After mail service stops due to weather, the agency's top priority is ensuring that employees are safe.","因天气原因暂停邮政服务后，该机构的首要任务是确保员工的安全。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"inferior","p":"ɪnˈfɪəriə(r)","m":"adj.差的；劣等的；下级的","tip":"in（里面）+ fer（音似“废”）+ -ior（形容词后缀）→ 一个人内在是颓废，那精神状态就是“差的”。","ex":["Modern music is often considered inferior to that of the past.","现代音乐常被认为不如过去的。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"inferiority","p":"ɪnˌfɪəriˈɒrəti","m":"n.低等；劣等；劣势","tip":"","ex":["The enemy forces were reduced to absolute inferiority.","敌军已处于绝对劣势。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"super","p":"ˈsuːpə(r)","m":"adj.极好的，超级的 adv.特别","tip":"","ex":["We had a super time in Italy.","我们在意大利过得十分惬意。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"superior","p":"suːˈpɪəriə(r)","m":"n.级别（或地位、职位）更高的人，上级 adj.更高级的；更好的","tip":"super（在……上 → 超越）+ -ior（后缀）→ 上级；更高级的","ex":["They feel superior in science and technology.","他们觉得自己在科学技术上更胜一筹。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"superiority","p":"suːˌpɪəriˈɒrəti","m":"n.优势；优越性","tip":"superior（更好的）+ -ity（名词后缀）→ 优势；优越性","ex":["They tend to have a sense of superiority over their peers.","他们往往比同龄人更有优越感。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"superb","p":"suːˈpɜːb","m":"adj.极佳的，卓越的；质量极高的","tip":"super（超越）+ b（音似“不”）→ 不能再超越了 → 极佳的，卓越的","ex":["His artistic taste is superb.","他的艺术品位极好。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"supreme","p":"suˈpriːm","m":"adj.最高的，至高无上的；最大的","tip":"supre（联想 super，极好的）+ me（我）→ 极好的我要向“最高的”目标迈进。","ex":["The Supreme Court has delivered its opinion in a controversial case.","最高法院对一个有争议的案件发表了意见。"],"lesson":"u05-l01","group":"pre/super 相关"},{"w":"communicate","p":"kəˈmjuːnɪkeɪt","m":"v.交流，沟通；相通","tip":"我们通过联通（united communications）与大家沟通（communicate）。","ex":["This is a family who can't communicate with each other.","这是一个成员间彼此无法沟通的家庭。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"mutual","p":"ˈmjuːtʃuəl","m":"adj.相互的，彼此的；共有的，共同的","tip":"mu（联想“木”）+ tu（联想“土”）+ -al（形容词后缀）→ 木克土 → “五行学说”研究事物之间“相互的”关系。","ex":["They shared mutual friends in school.","他们在学校有共同的朋友。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"telecommunications","p":"ˌtelikəˌmjuːnɪˈkeɪʃnz","m":"n.电信；电讯","tip":"tele-（电）+ communications（通信）→ 电信；电讯","ex":["Mobile telecommunications capacity is expected to double in Shanghai this year.","今年，上海的移动通信容量预计将翻一番。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"message","p":"ˈmesɪdʒ","m":"n.（书面或口头的）信息，消息 v.向（某人）传送（电子信息）","tip":"","ex":["He called the woman and left her a message.","他打电话给那个女人，给她留了个信息。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"community","p":"kəˈmjuːnəti","m":"n.社区；社会；群体；界","tip":"交流（communication）常在一个社区（community）中进行。","ex":["Since then, she has formed a new community of people.","从那以后，她建立了一个新的社群。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"commune","p":"ˈkɒmjuːn","m":"n.群体；公社","tip":"community n.社区；群体 → commune n. & v.","ex":["Mack lived in a commune.","麦克生活在一个群体里。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"commute","p":"kəˈmjuːt","m":"v.通勤，上下班往返 n.上下班路程","tip":"com-（所有）+ mu（联想“母”）+ te（音似“他”）→ 所有的母亲和他都需要“通勤”。","ex":["He commutes by subway.","他乘地铁上下班。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"neighbourhood","p":"ˈneɪbəhʊd","m":"n.街坊，四邻；街道；附近地区，邻近","tip":"neighbo(u)r（邻居）+ -hood（名词后缀）→ 街坊；附近地区","ex":["You can walk in parks or in your neighbourhood.","你可以在公园里或附近地区散步。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"block","p":"blɒk","m":"n.木块；街区；障碍物 v.妨碍，阻塞","tip":"单词发音类似“不唠嗑”→ 他俩不唠嗑了，因为有人“妨碍”他们交流。","ex":["Japan says fear of disease is its main reason to block fresh imports.","日本表示，对疾病的恐惧是其阻止生鲜进口的主要原因。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"associate","p":"əˈsəʊʃieɪt","m":"n.同事；伙伴；合伙人","tip":"as-（一再地）+ so（如此）+ ci（音似“吸”）+ -ate（后缀）→ 一再地如此吸在一起 → 联系","ex":["Blue is associated with the positive qualities of trust, quietness and calm.","蓝色与信任、安静和冷静等积极的品质有关。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"sociable","p":"ˈsəʊʃəbl","m":"adj.好交际的，友善的","tip":"好交际的（sociable）人会熟知很多有关社会（society）的规则。","ex":["Being sociable looks like a good way to add years to your life.","善于交际似乎是延长寿命的好方法。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"easy-going","p":"ˌiːzi ˈɡəʊɪŋ","m":"adj.悠闲的；随和的；不慌不忙的","tip":"","ex":["Frankly, Mary is not what I'd call \"easy-going\".","坦率地说，玛丽不是我所称的“随和的”人。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"ally","p":"ˈælaɪ","m":"v.（使）联盟，（使）联合","tip":"单词发音类似“艾丽”→ 艾丽是我的“盟友”。","ex":["He had no choice but to ally himself with the new movement.","他除了与新运动结盟别无选择。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"rally","p":"ˈræli","m":"v.集合，重新振作 n.集会；公路汽车赛","tip":"他让盟友（ally）集合（rally）起来。","ex":["He will join the team at the rally next week.","他将在下周的集会上加入该队。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"network","p":"ˈnetwɜːk","m":"n.网络；关系网；广播网；电视网 v.将……连接成网络","tip":"Internet n.因特网 → net n.网 → network n. & v.","ex":["But having a large network and some promotional skills may be more crucial.","但拥有一个庞大的网络和一些促销技巧可能更为重要。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"cyberspace","p":"ˈsaɪbəspeɪs","m":"n.网络空间","tip":"cyber（音似“赛博”）+ space（空间）→ 互联网上常说的赛博空间即“网络空间”。","ex":["Students are discovering the endless amount of information in cyberspace.","学生正在网络空间里探索无穷尽的信息。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"hack","p":"hæk","m":"v.劈，砍；非法侵入（他人计算机系统）","tip":"计算机黑客（hacker）非法侵入（hack）了他的电脑。","ex":["The order asks them to hack their own devices.","该命令要求他们入侵自己的设备。"],"lesson":"u05-l01","group":"“交流、联系”相关"},{"w":"democratic","p":"ˌdeməˈkrætɪk","m":"adj.民主的；有民主精神的","tip":"demo（音似“戴帽”）+ c（联想“可”）+ rat（老鼠）+ ic（联想“IC 卡”）→ 动画片里，戴帽子的老鼠可以刷 IC 卡坐公交车，这是个多么“民主的”社会啊！","ex":["He is a member of the Democratic Party.","他是民主党的成员。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"generate","p":"ˈdʒenəreɪt","m":"v.产生；生产；引起","tip":"gene（基因）+ rat（老鼠）+ e → 老鼠的基因使它“生产”后代的能力很强。","ex":["It generates a great deal of electronic garbage.","它会产生大量的电子垃圾。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"generation","p":"ˌdʒenəˈreɪʃn","m":"n.一代，一代人；产生","tip":"每一代人（generation）都是由上一代产生（generate）出来的。","ex":["Lion dance should be handed down to future generations as part of Chinese culture.","舞狮应该作为中国文化的一部分传承给子孙后代。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"general","p":"ˈdʒenrəl","m":"adj.普通的；一般的 n.将军","tip":"gene（基因）+ r（联想“人”）+ al（联想 all）→ 所有人都有的基因是很“普通的”。","ex":["General farm management can go a long way toward easing changes.","一般的农场管理可以在很大程度上缓解变化。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"strategy","p":"ˈstrætədʒi","m":"n.策略；行动计划；战略","tip":"st（联想 street）+ rat（老鼠）+ egy → 对付街上的老鼠是需要“策略”的。","ex":["One strategy is called market modification.","一种策略被称为市场调整。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"scratch","p":"skrætʃ","m":"v.挠，搔（痒处）；划伤，抓伤（皮肤） n.划伤；挠痒","tip":"sc（音似“四个”）+ rat（老鼠）+ ch（音似“吃”）→ 那四个老鼠边“挠”边吃。","ex":["He apologised for scratching an athlete's gold medal.","他为划伤运动员的金牌而道歉。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"sketch","p":"sketʃ","m":"n.素描，速写；概述 v.（给……）画素描；概述","tip":"","ex":["The artist is making sketches for his next painting.","画家正为他的下一幅作品画素描。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"pinch","p":"pɪntʃ","m":"v.捏，拧，掐；使经济拮据","tip":"他说桃子（peach）不能捏（pinch）。","ex":["His administration is financially pinched.","他的政府财政拮据。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"claw","p":"klɔː","m":"n.爪 v.抓；挠","tip":"单词发音类似“可捞”→ 猴子可以用“爪”捞井中的月亮。","ex":["His hands clawed the air.","他的双手在空中乱抓。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"flaw","p":"flɔː","m":"n.瑕疵；缺点 v.使有瑕疵","tip":"单词发音类似“飞喽”→ 笼子里的鸟飞了，说明笼子有“瑕疵”。","ex":["Their extraordinary minds are still using the same flawed tools that the rest of us rely on.","他们非凡的大脑仍然在使用有瑕疵的工具，和我们其他人用的一样。"],"lesson":"u05-l02","group":"rat 相关"},{"w":"cater","p":"ˈkeɪtə(r)","m":"v.提供饮食及服务；满足需要；迎合","tip":"cat（猫）+ -er（表示人的后缀）→ 有些猫很喜欢“迎合”人。","ex":["It cannot cater to personal needs.","它无法满足个人需求。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"category","p":"ˈkætəɡəri","m":"n.类别；种类","tip":"cat（猫）+ e（音似“鹅”）+ gory（音似“果仁”）→ 猫和鹅喜欢吃的果仁不是同一个“类别”。","ex":["Sales people often fall into this category.","销售人员通常属于这一类。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"feed","p":"fiːd","m":"v.喂养；供给；养活","tip":"单词发音类似“肥的”→ 这只很肥的猫是他“喂养”的。","ex":["By 2050, the world will need to feed an estimated 9.7 billion people.","到 2050 年，世界估计将需要养活 97 亿人。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"diet","p":"ˈdaɪət","m":"n.日常饮食 v.节食","tip":"单词发音类似“得饿他”→ 医生说他太胖了，得饿饿他，让他适度“节食”。","ex":["One possible solution to the food security problem is diversification of diet.","解决粮食安全问题的一个可能办法是饮食多样化。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"catalogue","p":"ˈkætəlɒɡ","m":"n.目录 v.将……编入目录","tip":"cat（猫）+ a（一）+ log（原木）→“目录”上有幅插图，是一只猫抱着一根原木。","ex":["They can apply for fully funded access to Coursera's course catalogue.","他们可以申请全额资助访问 Coursera 的课程目录。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"dialogue","p":"ˈdaɪəlɒɡ","m":"n.对话；对白","tip":"di-（两个）+ a（形似乌龟）+ logue（音似“唠嗑”）→ 两只小乌龟在唠嗑 → 对话；对白","ex":["Over the centuries, they have simulated dialogues in a number of ways.","几个世纪以来，它们用多种方式模拟了对话。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"log","p":"lɒɡ","m":"n.日志；正式记录；原木 v.正式记录","tip":"单词发音类似“捞个”→ 他在河里捞了个“原木”。","ex":["I checked the server's error logs.","我查验了服务器的错误日志。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"logic","p":"ˈlɒdʒɪk","m":"n.思维方式；逻辑，逻辑学","tip":"单词发音类似“逻辑”。","ex":["Statistics and logic are both challenging subjects.","统计学和逻辑学都是具有挑战性的学科。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"index","p":"ˈɪndeks","m":"n.索引；（物价和工资等的）指数；标志；指标 v.为……编索引；将……编入索引；使指数化","tip":"in（在……里面）+ dex（音似“德克士”）→ 他在德克士里看到了菜单上的“索引”。","ex":["Researchers have shown that body mass index is related to wages and income.","研究人员表明，体重指数与工资和收入有关。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"chat","p":"tʃæt","m":"v. & n.聊天","tip":"单词发音类似“拆台”→ 大家不喜欢和他“聊天”，因为他总是喜欢拆台。","ex":["My kids spend hours chatting on the phone to their friends.","我的孩子在电话里和他们的朋友聊天，聊了几个小时。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"scatter","p":"ˈskætə(r)","m":"v.撒播；散开","tip":"s（音似“四”）+ cat（猫）+ ter（音似“特”）→ 那四只猫特别精，闯了祸就“散开”了。","ex":["At the first gunshot, the crowd scattered.","枪声一响，人群便逃散了。"],"lesson":"u05-l02","group":"cat 相关"},{"w":"exile","p":"ˈeksaɪl; ˈeɡzaɪl","m":"v. & n.流放；流亡","tip":"ex-（往外）+ i（我）+ le（联想“了”）→ 使我往外走了 → 流放","ex":["His years in exile resulted in an innovation discount.","他的流亡岁月导致了创新力下降。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"exchange","p":"ɪksˈtʃeɪndʒ","m":"n. & v.交换；互换；兑换","tip":"ex-（出）+ change（改变，变换）→ 拿出去以变换 → 交换","ex":["At 8 years old, he worked as a kitchen boy for a restaurant in Paris in exchange for room and board.","8 岁时，他在巴黎的一家餐馆当厨房帮工，以换取食宿。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"expel","p":"ɪkˈspel","m":"v.把……开除（或除名）；驱逐出境；排出","tip":"ex-（往外）+ pel（音似“排”）→ 把……往外排 → 驱逐出境；排出","ex":["Cultivating positive interpersonal relationships helped him expel solitary feelings.","培养积极的人际关系帮他摆脱了孤独感。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"compel","p":"kəmˈpel","m":"v.强迫，迫使；使必须","tip":"com-（所有）+ pel（音似“排”）→ 所有人都排斥你，“强迫”你出去。","ex":["The agents' questions compel student tutors to think and explain the materials in different ways.","代理的问题迫使学生家教以不同的方式思考和解释这些材料。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"force","p":"fɔːs","m":"n.力量，暴力；武装部队；有影响力的人 v.强迫","tip":"一股力量（force）推着他继续向前（forth）。","ex":["It forces the customer to compensate the waiter.","它迫使顾客赔偿服务员。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"workforce","p":"ˈwɜːkfɔːs","m":"n.（国家或行业等的）劳动力，劳动大军，劳动人口","tip":"work（工作）+ force（力量）→ 劳动力","ex":["More than 15% of the workforce are jobless or underemployed.","超过 15% 的劳动力处于失业或未充分就业状态。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"workshop","p":"ˈwɜːkʃɒp","m":"n.车间；工场；作坊；研讨会","tip":"work（工作）+ shop（工坊）→ 车间","ex":["She equipped a small workshop.","她配备了一个小车间。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"enforce","p":"ɪnˈfɔːs","m":"v.强迫，强制执行（法律）","tip":"en-（使）+ force（强迫）→ 使强迫 → 强迫，强制执行","ex":["United Nations troops enforced a ceasefire in the area.","联合国军队在该地区强迫停火。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"reinforce","p":"ˌriːɪnˈfɔːs","m":"v.加强，加固；给……加强力量，增援","tip":"re-（重复）+ in（里面）+ force（力量）→ 重复往里面增加力量 → 加强，加固","ex":["Our job as designers is to reinforce the airline's brand.","作为设计师，我们的工作是强化航空公司的品牌。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"backup","p":"ˈbækʌp","m":"n.后援，支援；（文件等的）备份","tip":"back（背）+ up（向上）→ 让你的后背向上直起来 → 后援，支援","ex":["The old technology remains as a backup.","旧的技术仍然是一种备份。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"strength","p":"streŋ(k)θ","m":"n.力量；强度；毅力；优势","tip":"strong adj. 强壮的 → strength n.","ex":["But the greatest strength of this book (on fashion) is its intellectual profoundness.","但这本书（关于时尚）最大的优势在于它的思想深度。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"power","p":"ˈpaʊə(r)","m":"n.权力；能力；力量；政权；强国 v.驱动，推动","tip":"单词发音类似“怕我”→ 他们怕我是因为我有“权力”。","ex":["Like swords, books have symbolic power.","就像刀剑一样，书籍也具有象征性的力量。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"willpower","p":"ˈwɪlpaʊə(r)","m":"n.意志力","tip":"will（意志）+ power（力量）→ 意志力","ex":["Your feelings about your willpower affect the way you behave.","你对意志力的感觉会影响你的行为方式。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"willing","p":"ˈwɪlɪŋ","m":"adj.愿意的，自愿的","tip":"我将要（will）帮助你，我是自愿的（willing）。","ex":["Consumers must be willing to pay for these solutions.","消费者必须愿意为这些解决方案付费。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"volunteer","p":"ˌvɒlənˈtɪə(r)","m":"n.志愿者；志愿兵 v.自愿做","tip":"","ex":["She now helps in a local school as a volunteer.","她现在作为一名志愿者在当地一所学校帮忙。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"reluctant","p":"rɪˈlʌktənt","m":"adj.不情愿的，勉强的","tip":"re（字母音似“阿姨”）+ luc（音似“拉客”）+ tant（音似“忐忑”）→ 阿姨刚开面馆时，拉客人进来吃面内心忐忑，怕他们是“不情愿的”。","ex":["Most people surveyed were reluctant to reveal what they ate.","大多数被调查者不愿透露他们吃了什么。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"strain","p":"streɪn","m":"n.压力；重负；类型 v.用力推（或拉）；拉紧","tip":"st（联想 street）+ rain（雨）→ 一个寒冷的冬天，街上下着雨，我“拉紧”了衣服领子。","ex":["Some strains of bacteria are so harmful that a tiny few can have deadly consequences.","有些细菌类型危害极大，以至于极少量细菌就能带来致命的后果。"],"lesson":"u05-l02","group":"ex 相关"},{"w":"clothe","p":"kləʊð","m":"v.给……穿衣","tip":"","ex":["They clothe their children in the latest fashions.","他们给他们的孩子穿最时髦的服装。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"strip","p":"strɪp","m":"v.脱光衣服；除去，剥 n.（纸、金属、织物等）条，带；商业街","tip":"st（联想 street）+ rip（撕扯）→ 在大街上撕扯衣服 → 除去，剥","ex":["He tied a metal key and a strip of silk to the kite line.","他把一把金属钥匙和一条丝绸系在风筝线上。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"stripe","p":"straɪp","m":"n.条纹；线条","tip":"str（联想 street）+ ip（联想 IP）+ e（字母音似“衣”）→ 他在街上点开了一个 IP 网址，发现是卖“条纹”衣服的。","ex":["He wears a shirt with black and white stripes.","他穿着一件黑白条纹的衬衫。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"ribbon","p":"ˈrɪbən","m":"n.丝带，绸带，带状物","tip":"单词发音类似“瑞本”→ 一个叫“瑞本”的人腰间系着一条“丝带”。","ex":["Justin Le, aged 18, tied a red ribbon around his waist to practice jumping.","18 岁的贾斯汀·乐在腰间系了一条红丝带，以便练习跳跃。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"rip","p":"rɪp","m":"v.撕开，裂开","tip":"单词的发音像撕裂衣服的声音。","ex":["I ripped the package open.","我撕开了包裹。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"grip","p":"ɡrɪp","m":"n. & v.紧握，紧抓，掌控","tip":"g（联想“哥”）+ rip（撕开）→ 哥哥撕开包装袋前，得先“紧握”它。","ex":["She tried to get a grip on the icy rock.","她尽力抓住那块冰冷的岩石。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"string","p":"strɪŋ","m":"n.线；弦；一连串 v.用线穿起来；悬挂","tip":"st（联想 street）+ ring（戒指）→ 他在街上捡了一个用“线”穿起来的戒指。","ex":["He went off to change a guitar string.","他离开去换一根吉他弦了。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"thread","p":"θred","m":"n.线；思路，线索；主线；螺纹 v.穿线于；装好（胶卷或磁带）","tip":"th（音似“思”）+ read（读）→ 边读书边思考才能找到书中的“线索”。","ex":["A common thread runs through these discussions.","这些讨论都贯穿着一条共同的主线。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"trap","p":"træp","m":"v.使陷入困境 n.（捕捉动物的）陷阱；圈套；诡计；困境","tip":"单词发音类似“踹扑”→ 狐狸走着走着，被踹了一脚，扑进了“陷阱”里。","ex":["My co-workers would all be friendly with one another, without ever falling into the office gossip trap.","我的同事们彼此之间都很友好，不会落入办公室八卦的陷阱。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"bait","p":"beɪt","m":"n.饵；诱饵 v.下诱饵","tip":"单词发音类似“贝特”→ 海钓时，贝壳肉特别适合作“诱饵”。","ex":["A trap was laid, with fresh bait.","陷阱布置好了，还投放了新鲜诱饵。"],"lesson":"u05-l02","group":"“衣服”相关"},{"w":"fair","p":"feə(r)","m":"adj.合理的，公平的 adv.公平合理地 n.集市","tip":"","ex":["Can they be honest and fair?","他们能诚实和公平吗？"],"lesson":"u05-l02","group":"fair 相关"},{"w":"fairly","p":"ˈfeəli","m":"adv.公平地；一定地；相当地","tip":"","ex":["We get a fairly large portion of calories from fast food and snacks.","我们从快餐和零食中获得相当大一部分的卡路里。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"affair","p":"əˈfeə(r)","m":"n.事务；事情；事件","tip":"af-（一再地）+ fair（公平地）→ 一再公平地对待“事情”。","ex":["These teams are gaining more power to run their own affairs.","这些团队正在获得更多的权力来管理他们自己的事务。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"business","p":"ˈbɪznəs","m":"n.商业；生意，交易；事情；工作","tip":"busi（= busy，忙的）+ -ness（名词后缀）→ 忙着做的事 → 生意，交易","ex":["Not all your business partners are your soul mates.","并不是所有的商业伙伴都是你的灵魂伴侣。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"payroll","p":"ˈpeɪrəʊl","m":"n.（公司员工的）工资名单；（公司的）工资总支出","tip":"","ex":["The firm is growing fast with a monthly payroll of $1 million.","这家企业快速成长，月度工资总额达到了 100 万美元。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"trolley","p":"ˈtrɒli","m":"n.手推车；手拉车","tip":"t（联想“他”）+ roll（滚动）+ -ey（名词后缀）→ 他推着超市的“手推车”，轮子在滚动。","ex":["Don't forget to return the trolley after you finish shopping.","购物结束后别忘了归还手推车。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"toll","p":"təʊl","m":"n.过路费；严重的不良影响 v.（为丧者）敲（钟）","tip":"单词发音类似“偷”→ 很多车辆偷偷从旁边的小路走，以节省“过路费”。","ex":["Years of smoking have taken their toll on his health.","多年吸烟已严重损害他的健康。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"recruit","p":"rɪˈkruːt","m":"v.招聘，吸收（新成员）；劝说 n.新成员","tip":"re（字母音似“阿姨”）+ cruit（音似“可入他”）→ 阿姨可以“招聘”一些“新成员”加入公司。","ex":["New teachers and staff have to be recruited.","必须招聘新的教师和工作人员。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"renew","p":"rɪˈnjuː","m":"v.重新开始，继续；更新","tip":"","ex":["It has renewed her passion for life.","它重燃了她对生活的热情。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"continuous","p":"kənˈtɪnjuəs","m":"adj.不断的；持续的；连续的","tip":"","ex":["There was continuous firing throughout the night.","整夜枪炮不息。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"entitle","p":"ɪnˈtaɪtl","m":"v.给……权利或资格；给……命名（或题名）","tip":"en-（使……）+ title（名称）→ 使……有名称 → 给……命名","ex":["Everyone's entitled to their own opinion.","人人都有权发表自己的意见。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"qualify","p":"ˈkwɒlɪfaɪ","m":"v.取得资格（或学历）；使合格；达标","tip":"产品要保证质量（quality）才能达标（qualify）。","ex":["He qualified as a doctor last year.","他去年获得了医生资格。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"quality","p":"ˈkwɒləti","m":"n.质量；品质；素质 adj.优质的；高质量的","tip":"","ex":["The food is fresh and of good quality.","食物新鲜，质量好。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"register","p":"ˈredʒɪstə(r)","m":"v.登记；注册；注意到 n.登记表，注册簿","tip":"re-（回）+ g（联想“哥”）+ ister（联想 sister）→ 哥哥和姐姐找回了曾经“注册”的账号。","ex":["The site has 114 million registered users.","该网站拥有 1.14 亿注册用户。"],"lesson":"u05-l02","group":"fair 相关"},{"w":"concentrate","p":"ˈkɒnsntreɪt","m":"v.集中（注意力），专心；聚精会神 n.浓缩物","tip":"con-（所有）+ centr（联想 centre）+ -ate（动词后缀）→ 所有人都以某物为中心 → 集中（注意力），专心","ex":["She tried to concentrate on reading her book but couldn't.","她试图集中精力看书，但没能做到。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"central","p":"ˈsentrəl","m":"adj.最重要的，首要的；在中心的","tip":"center n.中心 → central adj.","ex":["Fresno, in the central valley, comes top of the list in America for year-round pollution.","位于中央谷地的弗雷斯诺是美国全年污染最严重的地区。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"focus","p":"ˈfəʊkəs","m":"n.焦点；中心 v.使聚焦；集中（注意力、精力等）","tip":"他的福克斯（Focus，福特的一款车）是大家的焦点（focus）。","ex":["When most of us set goals, we focus on long-term results we want to see.","当我们大多数人设定目标时，我们关注的是我们想要看到的长期结果。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"addict","p":"ˈædɪkt","m":"n.入迷的人；成瘾的人","tip":"ad-（一再地）+ dict（说）→ 祥林嫂一再地说她的阿毛死了，已经成瘾了 → 成瘾的人","ex":["I used to be a video game addict.","我过去是个电子游戏迷。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"dictate","p":"dɪkˈteɪt","m":"v.口述；强行规定；支配；命令","tip":"dict（说；命令）+ -ate（动词后缀）→ 口述；命令","ex":["Now they can dictate notes on a patient's health condition and treatment.","现在他们可以口述关于病人的健康状况和治疗情况的记录。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"dictionary","p":"ˈdɪkʃənri","m":"n.字典","tip":"diction（措辞）+ -ary（名词后缀）→ 存放措辞的地方 → 字典","ex":["Its dictionary definition should be updated.","它的字典定义应该更新。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"contradict","p":"ˌkɒntrəˈdɪkt","m":"v.反驳，否认；相抵触","tip":"contra-（反）+ dict（说）→ 反驳","ex":["The two stories contradict each other.","这两种说法相互矛盾。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"deny","p":"dɪˈnaɪ","m":"v.否认；拒绝","tip":"单词发音类似“抵赖”→ 抵赖就是“否认”。","ex":["There is no denying that mobile phones have brought much convenience.","不可否认，手机带来了很多便利。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"predict","p":"prɪˈdɪkt","m":"v.预言；预测；预告","tip":"pre-（在前）+ dict（说）→ 预言","ex":["In other words, when it comes to cities—or anything else—it is hard to predict the future.","换句话说，当提到城市或其他任何事物时，很难预测未来。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"indicate","p":"ˈɪndɪkeɪt","m":"v.暗示；表明","tip":"in-（在内）+ dic（说）+ -ate（动词后缀）→ 在内心说，没有明示 → 暗示；表明","ex":["The saying indicates the importance of lifelong learning.","这句话表明了终身学习的重要性。"],"lesson":"u05-l03","group":"“专注”相关"},{"w":"facility","p":"fəˈsɪləti","m":"n.设施，设备；天赋，才能","tip":"fac（联想 fact）+ -ility（名词后缀）→ 做实事的东西 → 设施，设备","ex":["They provide facilities management services to corporations, hospitals and universities.","他们为公司、医院和大学提供设施管理服务。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"defect","p":"ˈdiːfekt","m":"n.缺点，缺陷","tip":"de（音似“弟”）+ fect（联想 fact）→ 事实上，弟弟做事总有“缺点”。","ex":["The creative aspects of advertisement often cover up the defects or problems in products.","广告的创意往往掩盖了产品的缺陷或问题。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"effect","p":"ɪˈfekt","m":"n.效果，影响","tip":"ef-（向外）+ fect（做）→ 做出来的事会产生一些“影响”。","ex":["Such personality characteristics as self-discipline have no effect on longevity.","自律等这些人格特征对长寿没有影响。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"affect","p":"əˈfekt","m":"v.影响；侵袭，（使）感染","tip":"af-（一再地）+ fect（做）→ 一再地做事会产生一些“影响”。","ex":["Mothers' negative personality characteristics may affect their children's lifespans.","母亲的消极人格特征可能会影响孩子的寿命。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"affection","p":"əˈfekʃn","m":"n.感情；影响；喜爱，钟爱","tip":"affect（影响）+ -ion（名词后缀）→ 受到影响后产生的心理状态 → 感情；喜爱","ex":["People of different ages and genders show affection in different ways.","不同年龄、不同性别的人以不同的方式表达感情。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"infect","p":"ɪnˈfekt","m":"v.传染；感染；使携带病菌","tip":"in（里面）+ fect（做）→ 病菌进入身体里面做（坏事）→ 传染；使感染","ex":["Two million bees were infected with disease.","200万只蜜蜂感染了疾病。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"manufacture","p":"ˌmænjuˈfæktʃə(r)","m":"v.生产，制造 n.大量制造，批量生产","tip":"manu-（手）+ fact（做）+ -ure（后缀）→ 生产，制造","ex":["They were profitable to manufacture.","大量生产它们是有利可图的。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"manual","p":"ˈmænjuəl","m":"adj.体力的；手工的 n.使用手册；指南","tip":"manu（手）+ -al（后缀）→ 手工的；使用手册","ex":["Why don't you read the manual?","你为什么不看使用手册？"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"perfect","p":"ˈpɜːfɪkt","m":"adj.完美的；最佳的","tip":"","ex":["The new restaurant is a perfect place for dating.","那家新餐馆是约会的完美场所。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"ideal","p":"aɪˈdiːəl","m":"adj.完美的；理想的 n.理想的人或物","tip":"","ex":["Create an ideal study environment for them.","为他们创造理想的学习环境。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"thoughtful","p":"ˈθɔːtfl","m":"adj.沉思的，思考的；体贴的，关心的","tip":"","ex":["The hotel manager was very kind and thoughtful.","酒店经理非常亲切、体贴。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"thorough","p":"ˈθʌrə","m":"adj.彻底的，完全的，深入的","tip":"单词发音类似“仨肉”→ 他们仨把盘子里的肉全吃完了 → 彻底的，完全的","ex":["The doctor gave him a thorough check-up.","医生给他做了一次全面的体检。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"entire","p":"ɪnˈtaɪə(r)","m":"adj.全部的；整个的；完全的","tip":"en-（使……）+ tire（劳累）→ 什么使他如此劳累？他做了“全部的”工作。","ex":["They must be used in combination for an entire collective.","它们必须结合起来用于整个集体。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"whole","p":"həʊl","m":"n.整个；全部，全体 adj.全部的；完整的","tip":"who（音似“糊”）+ le（联想“了”）→ 粥是不是“全部”糊了？","ex":["It contributes greatly to the advance of society as a whole.","它对整个社会的进步做出了巨大贡献。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"deadly","p":"ˈdedli","m":"adj.（可能）致命的；彻底的，十足的 adv.极其；非常","tip":"","ex":["A deadly fish has been spotted in the Mediterranean waters.","在地中海水域发现了一种致命的鱼。"],"lesson":"u05-l03","group":"fac(t)/fect“做”相关"},{"w":"factory","p":"ˈfæktri","m":"n.工厂；制造厂","tip":"fact（做）+ -ory（名词后缀）→ 做东西的地方 → 工厂","ex":["They work in shifts in a factory.","他们在工厂轮班工作。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"mill","p":"mɪl","m":"n.工厂；磨坊 v.用磨碾碎","tip":"mi（联想“米”）+ ll → 磨大米的地方就是“磨坊”。","ex":["The old mill is now little more than a ruin.","老磨坊现在只剩下一点残垣断壁了。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"territory","p":"ˈterətri","m":"n.领土，领地；领域，范围","tip":"te（联想“特”）+（r）ri（联想“日”）+ t（联想“提”）+ -ory（名词后缀）→ 他在这个特别的日子里提到要保卫我们的“领土”。","ex":["It's certainly new territory, especially as home security cameras become easier to install.","这当然是一个新领域，尤其是在家庭安全摄像头变得更容易安装的情况下。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"laboratory","p":"ləˈbɒrətri","m":"n.实验室","tip":"labor（劳动）+ -atory（名词后缀）→ 进行劳动的场所 → 实验室","ex":["In this study, students came into the laboratory and were asked to give a public speech.","在这项研究中，学生们进入实验室，并被要求发表一个公开的演讲。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"lavatory","p":"ˈlævətri","m":"n.盥洗室","tip":"la（联想“拉”）+ va（音似“我”）+ t（联想“吐”）+ -ory（名词后缀）→ 拉着我去能吐的地方 → 盥洗室","ex":["Is there any lavatory in this room?","这个房间里有盥洗室吗？"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"laundry","p":"ˈlɔːndri","m":"n.待洗衣物；洗衣店","tip":"laun（音似“捞”）+ dry（干）→ 洗洗、捞捞再沥干，这通常是“洗衣店”的日常事务。","ex":["He worked in the laundry at a prison.","他曾在一所监狱的洗衣房工作。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"gallery","p":"ˈɡæləri","m":"n.美术馆，画廊；（大厅的）楼座，楼上旁听席","tip":"galle（音似“盖了”）+ -(e)ry（名词后缀）→ 盖了一个地方，用作“画廊”。","ex":["In his spare time, he visited the local art galleries.","在业余时间，他参观了当地的艺术画廊。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"corridor","p":"ˈkɒrɪdɔː(r)","m":"n.走廊，通道，（建筑物内的）过道","tip":"cor-（联想 con-，都）+ ri（联想“日”）+ dor（联想 door）→ 每天都要经过这道门，并穿过“走廊”。","ex":["There's a door at either end of the corridor.","走廊两端各有一道门。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"aisle","p":"aɪl","m":"n.走道，过道","tip":"单词发音类似“挨哦”→ 备考的学生在“过道”里可以挨着坐哦，方便一起学习。","ex":["Coffee and tea are in the next aisle.","下一个过道处有咖啡和茶。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"lane","p":"leɪn","m":"n.（乡间）小路，小巷；车道；航线","tip":"la（联想“拉”）+ ne（联想“呢”）→ 牛在农村的“小路”上拉车呢。","ex":["The highways have wide lanes and shoulders.","公路有宽阔的车道和路肩。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"alley","p":"ˈæli","m":"n.小巷，小街","tip":"单词发音类似“哎累”→ 住在这条“小巷”的人们每天都感叹：“哎！累！”","ex":["When he saw the police arrive, he ran down an alley.","他看见警察来了，便跑进了一条小巷。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"pave","p":"peɪv","m":"v.（用砖石）铺（地）","tip":"单词发音类似“陪我”→ 我的父母提前为我的未来“铺”路，是想更好地陪伴我。","ex":["The city centre streets are paved with dark local stone.","市中心的街道用当地的深色石块铺砌而成。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"grocery","p":"ˈɡrəʊsəri","m":"n.杂货店；食品杂货（店）","tip":"gro（音似“割肉”）+ c + -ery（名词后缀）→ 哥哥常去割（买）肉的地方 → 杂货店","ex":["There is plenty of decent food in the grocery stores.","杂货店里有很多像样的食物。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"nursery","p":"ˈnɜːsəri","m":"n.托儿所，幼儿园；儿童房；婴儿室","tip":"nurs(e)（护理，照看）+ -ery（名词后缀）→ 托儿所；婴儿室","ex":["Her youngest child is at nursery now.","她最小的孩子现在上幼儿园。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"scenery","p":"ˈsiːnəri","m":"n.风景，景色；舞台布景","tip":"单词发音类似“新挪威”→ 这个新舞台布景表现的是挪威的“风景”。","ex":["He doesn't know how to describe the beautiful country scenery.","他不知道如何形容那美丽的乡村风景。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"scene","p":"siːn","m":"n.（戏剧）场景；景色，情景；地点，现场","tip":"","ex":["It has been the scene of several fatal accidents recently.","这里是最近几起致命事故的现场。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"landscape","p":"ˈlændskeɪp","m":"n.风景，景色","tip":"land（陆地）+ sc（音似“死看”）+ ape（猿猴）→ 她在陆地上死盯着一只猿猴看，觉得这也算一道特别的“风景”。","ex":["This pattern of woods and fields is typical of the English landscape.","这是具有典型英格兰风景特征的森林与田野。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"landlord","p":"ˈlændlɔːd","m":"n.业主；地主；房东","tip":"单词发音类似“懒得劳的”→ 这个“房东”说自己懒得劳动，收租就够了。","ex":["Landlords had to wait 60 days to get rid of problem tenants.","房东必须等60天才能清除有问题的租户。"],"lesson":"u05-l03","group":"ory/ery 相关"},{"w":"invade","p":"ɪnˈveɪd","m":"v.侵犯，侵略，入侵","tip":"in（里面）+ vade（联想“洼的”）→ 当下雨的时候，洼的地方容易被水“入侵”。","ex":["It invades employees' privacy.","它侵犯了员工的隐私。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"intrude","p":"ɪnˈtruːd","m":"v.侵入，打扰，闯入","tip":"in（里面）+ tru（音似 true）+ de（联想“德”）→ 里面真的“闯入”了一个德国人。","ex":["The security camera installed may intrude into their privacy.","安装的安全摄像头可能会侵犯他们的隐私。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"attack","p":"əˈtæk","m":"v.攻击，袭击；批评 n.袭击，抨击；批评","tip":"a（一）+ ttack（音似“坦克”）→ 一辆坦克正在“袭击”敌人。","ex":["It is possible for burglars to make jamming attacks with the necessary equipment and skill.","窃贼有可能利用必要的设备和技巧进行干扰攻击。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"conquer","p":"ˈkɒŋkə(r)","m":"v.征服，占领；击败","tip":"con-（所有的）+ quer（音似“克”）→ 所有的都攻克了 → 征服","ex":["The only way to conquer a fear is to face it.","克服恐惧的唯一方法就是正视恐惧。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"colony","p":"ˈkɒləni","m":"n.殖民地；群体；群","tip":"单词发音类似“靠了你”→ 那“群”人靠你才逃离了那个地方。","ex":["The colony of ants are busy moving upward because it will rain heavily.","这群蚂蚁正忙着向上迁移，因为要下大雨了。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"retreat","p":"rɪˈtriːt","m":"v. & n.撤退；退却；逃避","tip":"re-（回）+ treat（拖）→ 拖回去 → 撤退","ex":["Is watching television a retreat from reality?","看电视是对现实的一种逃避吗？"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"treaty","p":"ˈtriːti","m":"n.（国家之间的）条约，协定","tip":"晚清时期，西方国家对待（treat）中国很不公平，签订了各种不平等条约（treaty）。","ex":["The treaty banning mining here comes up for review.","禁止在这里采矿的条约将进行审查。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"defeat","p":"dɪˈfiːt","m":"v.击败；战胜 n.失败；击败","tip":"单词发音类似“弟废他”→ 弟弟必须“击败”他，废了他的武功。","ex":["AlphaGo's victory and Taylor's defeat happened at about the same time.","阿尔法狗的胜利和泰勒的失败几乎同时发生。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"triumph","p":"ˈtraɪʌmf","m":"v.打败，战胜 n.巨大成功；喜悦","tip":"特朗普（Trump）期望取得成功（triumph）。","ex":["They triumphed ultimately over evil in the battle.","他们最终在战斗中战胜了邪恶势力。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"victory","p":"ˈvɪktəri","m":"n.胜利，成功","tip":"vict（征服）+ -ory（名词后缀）→ 胜利，成功","ex":["She is confident of victory in Saturday's final.","她对在星期六决赛中取得胜利充满信心。"],"lesson":"u05-l03","group":"“入侵”相关"},{"w":"interact","p":"ˌɪntərˈækt","m":"v.相互影响，相互作用","tip":"inter-（中间）+ act（行动，起作用）→ 在中间起作用 → 相互影响，相互作用","ex":["It has much to do with whom employees interact with.","这与员工和谁互动有很大关系。"],"lesson":"u05-l03","group":"inter 相关"},{"w":"interfere","p":"ˌɪntəˈfɪə(r)","m":"v.干涉，阻碍；弄坏","tip":"inter-（中间）+ fere（音似“飞”）→ 他学习时，有只苍蝇来回地飞，“干涉”他的学习。","ex":["Most of us may sometimes feel the frustration of having old memories interfere with new, relevant memories.","我们大多数人有时会因为旧记忆干扰新的相关记忆而感到沮丧。"],"lesson":"u05-l03","group":"inter 相关"},{"w":"interval","p":"ˈɪntəvl","m":"n.间隔；幕间休息","tip":"inter-（中间）+ val（音似“我”）→ 我到达的时候在他俩中间 → 间隔","ex":["The interval between major earthquakes might be 200 years.","大地震的间隔时间可能有200年。"],"lesson":"u05-l03","group":"inter 相关"},{"w":"interpret","p":"ɪnˈtɜːprət","m":"v.解释，说明；口译","tip":"inter-（中间）+ pre-（提前）+ t（联想“他”）→ 我们谈话时，要提前让他在中间进行“口译”。","ex":["It is interpreted differently in different times.","它在不同的时代有不同的解释。"],"lesson":"u05-l03","group":"inter 相关"},{"w":"interview","p":"ˈɪntəvjuː","m":"n.面试，面谈；采访 v.面试，面谈；接见","tip":"inter-（中间）+ view（看）→ 相互之间来回地看 → 面试；采访","ex":["The interview didn't go as well as he expected.","面试没有他预期的那么顺利。"],"lesson":"u05-l03","group":"inter 相关"},{"w":"journal","p":"ˈdʒɜːnl","m":"n.期刊，日报；日记","tip":"单词发音类似“姐能”→ 姐姐很有能力，自己主办了一个“期刊”。","ex":["The findings are in the journal Nature Geoscience.","研究结果发表在《自然·地球科学》期刊上。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"print","p":"prɪnt","m":"n.印刷业；印刷字体 v.打印；印刷；刊登；发表","tip":"p（联想“派”）+ r（联想“人”）+ in（音似“印”）+ t（联想“它”）→ 派人印它 → 印刷","ex":["More readers choose the digital over the print edition.","更多的读者选择数字版而不是印刷版。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"fingerprint","p":"ˈfɪŋɡəprɪnt","m":"n.指纹；指印","tip":"","ex":["Faces, like fingerprints, are unique.","人脸和指纹一样，都是独一无二的。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"blueprint","p":"ˈbluːprɪnt","m":"n.蓝图；行动方案；模型，型板","tip":"","ex":["He studied the blueprints of other famous buildings.","他研究了其他著名建筑的蓝图。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"pirate","p":"ˈpaɪrət","m":"n.（尤指旧时的）海盗；盗版者 v.盗印；窃用","tip":"pi（音似“派”）+ rate（速度）→ “盗版者”派人“盗印”别人书籍的速度很快。","ex":["The area is frequented by pirates.","这个地区经常有海盗出没。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"publish","p":"ˈpʌblɪʃ","m":"v.出版，发行；刊登；发布","tip":"让某本书公开（public）面世就是让它出版（publish）。","ex":["It is first published in Washington and then in Paris.","它首先在华盛顿出版，然后在巴黎出版。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"public","p":"ˈpʌblɪk","m":"adj.公共的；公开的 n.民众","tip":"","ex":["It doesn't run counter to the goals of public education.","这并不违背公共教育的目标。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"republic","p":"rɪˈpʌblɪk","m":"n.共和国，共和政体","tip":"","ex":["Mary McAleese was the President of the Republic of Ireland.","玛丽·麦卡利斯曾是爱尔兰共和国的总统。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"edit","p":"ˈedɪt","m":"v.编辑；剪辑；主编","tip":"单词发音类似“爱抵他”→ 他在“编辑”一本关于爱国抵抗侵略的故事书。","ex":["You have time to edit and do more research.","你有时间去编辑和做更多的研究。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"version","p":"ˈvɜːʃn","m":"n.变体；变种；版本","tip":"ver（音似“我”）+ s（联想“撕”）+ -ion（名词后缀）→ 我不小心撕坏了那个“版本”的书。","ex":["He submitted the unedited version to a more respected journal and got accepted.","他把未经编辑的版本提交给一家更受尊敬的杂志，并被接受了。"],"lesson":"u05-l03","group":"journal 相关"},{"w":"tutor","p":"ˈtjuːtə(r)","m":"n.导师；家庭教师，私人教师 v.指导","tip":"单词发音类似“土特”→ 我们工作后有时会带着土特产看望“导师”。","ex":["Activities all take place under the guidance of an experienced tutor.","所有活动都在经验丰富的导师的指导下进行。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"educator","p":"ˈedʒukeɪtə(r)","m":"n.教育工作者；教师","tip":"educate v.教育 → educator n.","ex":["Educators and business leaders have more in common than it may seem.","教育工作者和商界领袖有着比表面上看起来更多的共同点。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"academic","p":"ˌækəˈdemɪk","m":"n.大学教师，学者 adj.学业的，学术的","tip":"aca（音似“挨个”）+ dem（音似“点名”）+ -ic（词缀）→ 这个“大学老师”一上课就开始挨个点名。","ex":["It is essential to a person's future academic success.","这对一个人未来的学业成功至关重要。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"academy","p":"əˈkædəmi","m":"n.（高等）专科院校；研究院；学会","tip":"a(c)-（一再地）+ cade（音似“开的”）+ my（我的）→ 我一再努力学习，因为我的梦想是打开“研究院”的大门。","ex":["I don't hear people in the academy saying it.","我没有听到学院里的人说过它。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"scholar","p":"ˈskɒlə(r)","m":"n.学者；奖学金获得者","tip":"单词发音类似“四告乐”→ 他们四个快乐地告诉我，他们对那个“学者”的报告很感兴趣。","ex":["Scholars have different opinions about it.","学者对此有不同的看法。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"seminar","p":"ˈsemɪnɑː(r)","m":"n.研讨会；培训班","tip":"单词发音类似“思秘那”→ 他们在“研讨会”上思考、讨论那些神秘的东西。","ex":["I attended practically every seminar when I was a student.","上学时，我几乎参加了每一场研讨会。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"forum","p":"ˈfɔːrəm","m":"n.论坛；讨论会","tip":"fo（联想 for）+ rum（音似 room）→ 为了租个好房间，他去学校的“论坛”查看合租信息。","ex":["Goel and his team sourced the online discussion forum to find all 40,000 questions.","戈尔和他的团队在在线论坛上找到了所有的4万个问题。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"tuition","p":"tjuˈɪʃn","m":"n.教学；学费","tip":"单词发音类似“推身”→ 她推着朋友的身体询问特长班的“学费”价格。","ex":["The tuition they charge has been rising considerably.","他们收取的学费一直大幅上涨。"],"lesson":"u05-l04","group":"“学术”相关"},{"w":"faculty","p":"ˈfæklti","m":"n.全体教师；（高等院校的）系，院","tip":"fa（联想“发”）+ cu（联想“醋”）+ l（联想“利”）+ -ty（名词后缀）→ 过节时，学校给“全体教师”发了醋作为福利。","ex":["They will bring with them more international faculty.","他们将带来更多国际化的师资。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"dean","p":"diːn","m":"n.系主任；（大学的）学院院长","tip":"《憨豆先生》（Mr. Bean）中的主角是个不折不扣的高材生，以他的学术水平当个双一流高校的系主任（dean）是绰绰有余的！","ex":["They are set by the dean of the graduate school.","它们是由研究生院院长定的。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"expert","p":"ˈekspɜːt","m":"n.专家 adj.专家的","tip":"ex-（出去）+ per（音似“破”）+ t（联想“它”）→ 出去破它（炸弹）的人是个“专家”。","ex":["What is the argument against the experts' idea of a long summer vacation?","反对专家们提出的长暑假想法的理由是什么？"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"experiment","p":"ɪkˈsperɪmənt","m":"v.进行实验；试用","tip":"ex-（出去）+ peri（尝试）+ -ment（后缀）→ 出去不断尝试 → 实验","ex":["What did Dr. Sasaki do when she first did her experiment?","佐佐木博士第一次做实验时做了什么？"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"discipline","p":"ˈdɪsəplɪn","m":"n.纪律；学科；训练","tip":"dis-（不）+ cip（抓，拿）+ line（线）→ 遵守学校的“纪律”，不旷课，是他要牢牢抓住的底线。","ex":["She keeps good discipline in class.","她严格执行课堂纪律。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"principal","p":"ˈprɪnsəpl","m":"n.校长；首长 adj.最重要的，主要的","tip":"princi（形似 prince）+ pal（联想“怕了”）→ 让王子都怕了的人 → 校长；首长","ex":["The principal reason for this omission is lack of time.","跳过它的主要原因是时间不足。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"principle","p":"ˈprɪnsəpl","m":"n.法则，原则","tip":"princi（形似 prince）+（ci）p（抓）+ le（联想“了”）→ 由于违背了“法则”，王子被抓了。","ex":["It is a moral principle to guide people's behaviour.","这是引导人们行为的一项道德准则。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"theory","p":"ˈθɪəri","m":"n.理论，原理；假设","tip":"theo（音似“谁饿”）+ -ry（名词后缀）→ “理论”上，现在没人挨饿了。","ex":["This is a theory that appeals to many economists.","这是一个吸引许多经济学家的理论。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"policy","p":"ˈpɒləsi","m":"n.政策；方针；原则","tip":"poli（联想“魄力”）+ cy（联想“才有”）→ 要有魄力才有能力将“政策”推行下去。","ex":["We don't really have a missed assignment policy.","我们其实没有一个漏交作业的规定。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"political","p":"pəˈlɪtɪkl","m":"adj.政治的；政府的；政党的","tip":"","ex":["He reviews books on political affairs.","他审查政治事务方面的书籍。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"prince","p":"prɪns","m":"n.王子；亲王","tip":"pr（联想“仆人”）+ in（里面）+ ce（联想“侧”）→ 仆人在“王子”家里面侧立待命。","ex":["Its ruler Prince Rainier married an American actress.","其统治者雷尼尔王子娶了一位美国女演员。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"princess","p":"ˈprɪnses","m":"n.公主；王妃","tip":"","ex":["Angry politicians launched an attack on the Princess in the press.","愤怒的政客们在新闻媒体上攻击公主。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"palace","p":"ˈpæləs","m":"n.宫，宫殿","tip":"Summer Palace 颐和园","ex":["One day, he received an invitation to dinner at the ruler's palace.","有一天，他收到了在统治者的宫殿享用晚餐的邀请。"],"lesson":"u05-l04","group":"“教职工”相关"},{"w":"camp","p":"kæmp","m":"n.营地 v.宿营；露营","tip":"ca（音似“开”）+ m（联想“门”）+ p（联想“坡”）→ 他在野外“露营”的时候，拉开帐篷门，外面就是一个坡。","ex":["I used to attend a summer music camp for five weeks.","我曾经参加过一个为期五周的音乐夏令营。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"campus","p":"ˈkæmpəs","m":"n.校园","tip":"camp（露营）+ us（我们）→ 我们一起在大学“校园”里露营吧。","ex":["She lives on campus.","她住在校园内。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"campaign","p":"kæmˈpeɪn","m":"n.运动；活动","tip":"camp（露营）+ aign（联想 gain）→ 他们推出的露营“活动”得到了大学生的支持。","ex":["The artist merely continued his campaign on the other side.","这位艺术家只是在另一边继续他的活动。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"champion","p":"ˈtʃæmpiən","m":"n.冠军；第一名；优胜者","tip":"","ex":["Many have become national chess champions.","许多人已经成为全国象棋冠军。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"dormitory","p":"ˈdɔːmətri","m":"n.集体寝室；宿舍","tip":"单词发音类似“捣米锤”→ 他的“宿舍”里有一个捣米锤。","ex":["Many colleges now have wired dormitories.","现在许多大学的学生宿舍已经联网。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"graduate","p":"ˈɡrædʒuət","m":"n.大学毕业生；学士学位获得者","tip":"","ex":["It is a special offer to recent college graduates working in offices.","这是给在办公室工作的应届大学毕业生的特别优惠。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"undergraduate","p":"ˌʌndəˈɡrædʒuət","m":"n.本科生","tip":"under（下面）+ graduate（毕业）→ 在毕业下面 → 还没有毕业 → 本科生","ex":["This fall, thousands of college students from across the country will begin their undergraduate studies.","今年秋天，来自全国各地的数千名大学生将开始他们的本科学习。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"freshman","p":"ˈfreʃmən","m":"n.（大学）一年级新生","tip":"fresh（新的）+ man（人）→ 新来大学的人 → （大学）一年级新生","ex":["But as a scared freshman looking at their grades, it's not fun.","但是作为一个恐慌地关注着自己成绩的新生，这并不好玩。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"junior","p":"ˈdʒuːniə(r)","m":"adj.年少的 n.晚辈；下属；三年级学生","tip":"单词发音类似“拘泥”→ 那个大学“三年级学生”还是很拘泥。","ex":["He's a member of the club's junior team.","他是俱乐部青年队的成员。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"senior","p":"ˈsiːniə(r)","m":"adj.长辈的；高级的 n.长辈；上司；毕业班的学生","tip":"","ex":["At the very top are the senior executives.","位于最高层的正是高管们。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"bachelor","p":"ˈbætʃələ(r)","m":"n.单身汉；学士","tip":"ba（联想“爸”）+ che（联想“车”）+ l（联想“了”）+ -or（人）→ 爸爸车里面只坐了一个人，他是个“单身汉”。","ex":["Students earn their bachelor of science in nursing in a year.","学生们在一年内获得护理学学士学位。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"master","p":"ˈmɑːstə(r)","m":"n.（男）主人，雇主；大师；硕士学位 v.精通；掌握，控制","tip":"单词发音类似“马斯特（人名）”→ 马斯特是这匹马的“主人”。","ex":["It's a good problem to have, but it can be a tough skill to master.","这是一个很好的问题，但它可能是一个很难掌握的技能。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"masterpiece","p":"ˈmɑːstəpiːs","m":"n.代表作；杰作；名著","tip":"master（大师）+ piece（件）→ 大师的一件作品 → 杰作；名著","ex":["Her work is a masterpiece of simplicity.","她的作品是朴实的典范。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"drop","p":"drɒp","m":"v.（使）变弱，降低；（意外地）落下；放弃 n.下降；滴；减少","tip":"dro（音似“着”）+ p（联想“拍”）→ 沙包从空中“落下”着地，拍在地上。","ex":["Children may be tempted to drop litter.","孩子们可能会忍不住乱扔垃圾。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"dropout","p":"ˈdrɒpaʊt","m":"n.辍学者；退学者","tip":"drop（落下）+ out（出）→ 被落下、排除出去的人 → 辍学者","ex":["He's a dropout who doesn't have a steady job.","他是个辍学者，没有稳定工作。"],"lesson":"u05-l04","group":"campus 相关"},{"w":"nourish","p":"ˈnʌrɪʃ","m":"v.滋养，养育，培养","tip":"护士（nurse）像养花一样养育（nourish）他。","ex":["By investing in education, we nourish the talents of our children.","我们通过教育投资培养孩子们的才能。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"cultivate","p":"ˈkʌltɪveɪt","m":"v.培育，培养；开垦，耕作","tip":"cultiv（联想 culture）+ -ate（动词后缀）→ 为了使你有文化，需要“培养”你。","ex":["People may either be born with it or be able to cultivate it.","人们要么天生就有这种能力，要么能够培养它。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"rear","p":"rɪə(r)","m":"n.后面，背部 v.抚养，栽培","tip":"rea（联想 real）+ r（形似花）→ 她衣服“后面”真的有个花的刺绣。","ex":["There are toilets at both front and rear of the plane.","飞机前后舱都有洗手间。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"breed","p":"briːd","m":"v.饲养，繁殖；培养，养育","tip":"单词发音类似“哺育的”→ 饲养；养育","ex":["Hard times breed hard feelings.","艰难时期会酿成怨气。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"intelligent","p":"ɪnˈtelɪdʒənt","m":"adj.有才智的，聪明的","tip":"intel（联想“英特尔”）+ li（联想“立”）+ gent（音似“进他”）→ 英特尔公司立刻通知那个“聪明的”人，让他进公司上班。","ex":["Some studies have found that first-born children are more intelligent than their later-born siblings.","一些研究发现，头胎的孩子比后生的孩子更聪明。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"intellectual","p":"ˌɪntəˈlektʃuəl","m":"adj.智力的；聪明的；理智的 n.知识分子","tip":"intel（联想“英特尔”）+ lect（选择）+ -ual（后缀）→ 选择进入英特尔公司上班的是“聪明的”人。","ex":["He was a leading intellectual of his day.","他是那个时代杰出的知识分子。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"sharp","p":"ʃɑːp","m":"adj.锋利的；清晰的；急转的","tip":"有一家电器公司叫夏普，它的英文名是 Sharp。","ex":["It made a series of sharp turns in the sky.","它在空中做出了一系列的急转弯。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"shape","p":"ʃeɪp","m":"n.形状；外形；身材；状况 v.形成，塑造","tip":"单词发音类似“沙皮”→ 这只沙皮狗的“外形”有点胖。","ex":["Eggs have an oval shape appealing to artists.","鸡蛋呈椭圆形，对艺术家很有吸引力。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"acknowledge","p":"əkˈnɒlɪdʒ","m":"v.承认；认可；致谢","tip":"ac-（一再地）+ knowledge（知识）→ 我一再地“承认”他有知识，是个博学多才的人。","ex":["I also acknowledge that we have a work-life problem.","我也承认我们有工作与生活的问题。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"pioneer","p":"ˌpaɪəˈnɪə(r)","m":"n.先锋；先驱 v.当开拓者，倡导","tip":"pi（联想“披”）+ on（在上面）+ -eer（人）→ 披挂上阵的人 → 先锋；先驱","ex":["These pioneers reflected on the challenges they faced.","这些先驱反思了他们所面临的挑战。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"peer","p":"pɪə(r)","m":"n.同龄人；同等的人 v.仔细看，端详","tip":"pe（联想“拍”）+ -er（表示人的后缀）→ 能拍着彼此肩膀的人 → 同龄人","ex":["Students prefer to rely on peers to relieve stress and anxiety.","学生更喜欢依靠同伴来缓解压力和焦虑。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"compatible","p":"kəmˈpætəbl","m":"adj.可共用的；兼容的；关系好的，和睦相处的","tip":"com-（所有）+ pat（联想“拍他”）+ -ible（形容词后缀）→ 所有人都喜欢拍他 → 关系好的","ex":["The new system will be compatible with existing equipment.","新的系统将与现有的设备相互兼容。"],"lesson":"u05-l04","group":"“培养、养育”相关"},{"w":"curriculum","p":"kəˈrɪkjələm","m":"n.课程","tip":"cur（音似“课”）+ ri（联想“日”）+ culu（音似“可乐”）+ m（联想 me）→ 我每天上课都感到很快乐 → 课程","ex":["Students of ethnic backgrounds learn better from a multicultural curriculum.","有种族背景的学生能在多元文化课程中学得更好。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"chemical","p":"ˈkemɪkl","m":"n.化学制品；化学品 adj.与化学有关的","tip":"单词发音类似“开煤科”→ 把煤打开研究里面是什么成分，这是“与化学有关的”科学。","ex":["Toy manufacturers have been banned from using the chemicals.","玩具制造商被禁止使用这些化学物质。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"geometry","p":"dʒiˈɒmətri","m":"n.几何（学）；几何图形","tip":"ge（联想“哥”）+ o（形似圆）+ me（我）+ try（尝试）→ 哥哥和我尝试画一个圆，我们在研究“几何学”。","ex":["We feel that geometry is a difficult subject.","我们认为几何是一门很难的课程。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"triangle","p":"ˈtraɪæŋɡl","m":"n.三角形","tip":"tri-（三）+ angle（角，角度）→ 三角形","ex":["Everything you learned in elementary school about triangles is pretty basic.","你在小学学到的所有关于三角形的东西都是很基础的。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"trifle","p":"ˈtraɪfl","m":"n.琐事；少量 v.怠慢，小看","tip":"tri-（三）+ fle（音似“伏”）→ 三伏天，他热得只能做“少量”的工作。","ex":["You will probably never think of fashion as a trifle again.","你可能再也不会认为时尚是琐事了。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"mathematics","p":"ˌmæθəˈmætɪks","m":"n.数学；计算；运算（= math，maths）","tip":"","ex":["Her proof is a remarkable piece of mathematics.","她的证明是一个了不起的数学作品。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"sociology","p":"ˌsəʊsiˈɒlədʒi","m":"n.社会学","tip":"","ex":["I don't study sociology or political theory.","我不学习社会学或政治理论。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"psychology","p":"saɪˈkɒlədʒi","m":"n.心理学；心理影响","tip":"单词前半部分发音类似“思考”→ 心理学","ex":["There does appear to be some psychology behind it.","这背后似乎确实有某种心理因素。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"art","p":"ɑːt","m":"n.艺术；文科（如语言、历史、文学）；技能","tip":"","ex":["They are favored as a form of art.","它们作为一种艺术形式备受青睐。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"architecture","p":"ˈɑːkɪtektʃə(r)","m":"n.建筑学；建筑设计；结构","tip":"archi（联想 art）+ tecture（联想 structure）→ 充满艺术的结构 → 建筑学","ex":["The architecture of these buildings is in the Greek style.","这些楼房的建筑设计是希腊风格的。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"architect","p":"ˈɑːkɪtekt","m":"n.建筑师；设计师；创造者","tip":"","ex":["They are copies built to the architect's designs.","它是按照建筑师的设计建造的复制品。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"construct","p":"kənˈstrʌkt","m":"v.修建，建造；组成；编制","tip":"con-（所有的）+ struct（联想 structure）→ 所有的结构都是“建造”的。","ex":["The building was constructed in 1993.","这座建筑建于1993年。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"structure","p":"ˈstrʌktʃə(r)","m":"n.结构；体系；建筑物 v.组织，安排","tip":"","ex":["I admire the structure of the building.","我欣赏这座建筑物的结构。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"infrastructure","p":"ˈɪnfrəstrʌktʃə(r)","m":"n.（国家或机构的）基础设施，基础建设","tip":"in（里面的）+ fra（音似“服我”）+ structure（结构）→ 里面的结构框架是为我们提供服务的“基础设施”。","ex":["It will force cities to transform their infrastructure.","它将迫使城市改造其基础设施。"],"lesson":"u05-l04","group":"“课程”相关"},{"w":"paste","p":"peɪst","m":"n.酱；膏；糊糊 v.粘贴","tip":"刷牙用的牙膏（toothpaste）就是膏（paste）体。","ex":["Nigeria is dependent on $1 billion worth of tomato paste imports every year.","尼日利亚每年依赖价值10亿美元的番茄酱进口。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"portable","p":"ˈpɔːtəbl","m":"adj.便携式的；手提的；轻便的","tip":"port（音似“泡它”）+ -able（形容词后缀）→ 她减肥时吃的冲泡代餐都是“便携式的”。","ex":["The device is said to be the world's first portable transistor.","据说这种装置是世界上第一个便携式晶体管。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"compound","p":"ˈkɒmpaʊnd","m":"n.混合物，化合物；复合词 adj.复合的","tip":"com-（所有的，一起）+ pound（音似“泡的”）→ 把牛奶、坚果和麦片泡在一起作早餐，这样的“混合物”很健康。","ex":["A compound sentence contains two or more clauses.","复合句包含两个或多个从句。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"pond","p":"pɒnd","m":"n.池塘；水池（尤指人工的）","tip":"单词发音类似“泡的”→ 他们在“池塘”泡澡。","ex":["The wrong name is invariably fished out from the same relationship pond.","“错误”的名字总是从同一个关系池中找到的。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"complex","p":"ˈkɒmpleks","m":"n.建筑群；情结 adj.复杂的；复合的","tip":"com-（所有的）+ plex（联想“扑来”）→ 所有人都扑过来，反倒使事情更复杂了 → 复杂的","ex":["It helps people to understand complex issues.","它帮助人们理解复杂的问题。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"collapse","p":"kəˈlæps","m":"v.（突然）倒塌，坍塌 n.（突然的）倒塌，塌陷","tip":"col-（所有的）+ lap（音似“来扑”）+ se → 所有人都向一张桌子扑来，它就“坍塌”了。","ex":["A man was pulled to safety after a building collapse.","一幢建筑物倒塌后，一名男子被拉到安全地带。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"complicate","p":"ˈkɒmplɪkeɪt","m":"v.使复杂化","tip":"com-（所有的）+ pli（联想“扑来”）+ cate（音似“剋他”）→ 所有人都扑过来剋（打）他，使事情变得复杂了 → 使复杂化","ex":["I do not wish to complicate the task more than is necessary.","我不想使这项任务不必要地复杂化。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"confuse","p":"kənˈfjuːz","m":"v.使糊涂，使迷惑；混淆","tip":"con-（一起）+ fuse（流）→ 流到一起 → 混合，混淆 → 混淆","ex":["Their loud claps can be confused with explosions.","他们响亮的掌声可能与爆炸声相混淆。"],"lesson":"u06-l01","group":"“混合、复杂”相关"},{"w":"request","p":"rɪˈkwest","m":"n. & v.要求，请求","tip":"re-（重复）+ quest（寻找，追求）→ 重复地寻找或追求 → 要求，请求","ex":["As for the organisation itself, it declined a request for an interview.","至于该组织本身，它拒绝了采访请求。"],"lesson":"u06-l01","group":"request 相关"},{"w":"require","p":"rɪˈkwaɪə(r)","m":"v.需要；要求，规定","tip":"re-（再，又）+ quire（= ask）→ 又问 → 需要，要求","ex":["As what happened with tobacco, this will require a cultural shift, but that can happen.","正如烟草的情况一样，这虽需要文化转变，但也可能会发生。"],"lesson":"u06-l01","group":"request 相关"},{"w":"demand","p":"dɪˈmɑːnd","m":"n.（坚决的）要求，需求；所需之物 v.强烈要求","tip":"de（音似“弟”）+ ma（联想“妈”）+ nd（联想“的”）→ 妈妈满足了弟弟买玩具的“要求”。","ex":["They take up a lot of our fresh water demands across the world.","它们占用了我们在世界各地的大量淡水需求。"],"lesson":"u06-l01","group":"request 相关"},{"w":"demanding","p":"dɪˈmɑːndɪŋ","m":"adj.要求高的；苛求的","tip":"demand n.要求 → demanding adj.","ex":["They find these exercises too demanding.","他们发现这些练习要求太高了。"],"lesson":"u06-l01","group":"request 相关"},{"w":"acquire","p":"əˈkwaɪə(r)","m":"v.获得，得到；购得；养成（习惯）","tip":"ac-（一再地）+ quire（询问）→ 经过一再地询问，他最终“得到”了答案。","ex":["It can be acquired through persistent practice.","它可以通过坚持练习获得。"],"lesson":"u06-l01","group":"request 相关"},{"w":"inquire","p":"ɪnˈkwaɪə(r)","m":"v.询问；查究；研究","tip":"in（入）+ quire（询问）→ 询问到很深入的境界，就需要“研究”了。","ex":["He inquired about his client's family background.","他询问了客户的家庭背景。"],"lesson":"u06-l01","group":"request 相关"},{"w":"courage","p":"ˈkʌrɪdʒ","m":"n.勇气；勇敢；胆量；无畏","tip":"c + our（我们的）+ age（时代）→ 我们这个时代需要“勇气”去拼搏。","ex":["Her courage is an example to all of us.","她的勇气是我们大家的榜样。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"encourage","p":"ɪnˈkʌrɪdʒ","m":"v.支持；鼓励，激励；刺激","tip":"en-（使）+ courage（勇气）→ 鼓励","ex":["Parents should encourage their child to take the risks needed to learn and grow.","父母应该鼓励他们的孩子承担学习和成长中必要的风险。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"discourage","p":"dɪsˈkʌrɪdʒ","m":"v.使气馁，使灰心；阻止","tip":"dis-（不）+ courage（勇气）→ 使气馁，使灰心","ex":["Playing with digital devices discourages kids from active discovery.","玩数字设备会阻碍孩子们积极探索。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"frustrate","p":"frʌˈstreɪt","m":"v.使懊恼；使气馁，使沮丧","tip":"fru（联想“妇孺”）+ st（联想 street）+ rat（老鼠）+ e → 一群妇孺在街上追老鼠却没追上，感到沮丧 → 使沮丧","ex":["Gender inequality continues to frustrate a lot of female employees.","性别不平等仍令许多女性员工沮丧。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"provoke","p":"prəˈvəʊk","m":"v.激起，引发；挑衅，激怒","tip":"pro-（提前）+ voke（音似“我剋”）→ 拳击比赛还没开始，我就剋（打）了对手一拳，“激怒”了他。","ex":["The article was intended to provoke discussion.","这篇文章旨在引发讨论。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"advocate","p":"ˈædvəkət","m":"n.拥护者，支持者；辩护律师","tip":"ad-（= to）+ voc（说）+ -ate（后缀）→ 对……说 → 支持；提倡","ex":["It is evident that the writer advocates the idea of returning to nature.","很明显，作者提倡回归自然的思想。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"choke","p":"tʃəʊk","m":"v.（使）窒息；噎住；哽咽","tip":"单词发音类似“撬开”→ 他吃饭时“噎住”了，她立刻撬开他的嘴，以防“窒息”。","ex":["Very small toys can choke a baby.","很小的玩具可使婴儿窒息。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"sponsor","p":"ˈspɒnsə(r)","m":"v.主办；赞助 n.发起人，赞助者","tip":"s（联想“美女”）+ pon（音似“帮”）+ sor（音似 sir）→ 美女帮助了一位先生，成了他的“赞助者”。","ex":["It refused to sponsor the 1984 Olympics.","它拒绝赞助1984年的奥运会。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"spontaneous","p":"spɒnˈteɪniəs","m":"adj.自发的；自然的","tip":"sponta（音似“死帮他”）+ neous → 他努力帮助那位先生的行为是“自发的”。","ex":["He found many lies are spontaneous responses to an unexpected demand.","他发现，许多谎言都是对意外需求的自发反应。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"spirit","p":"ˈspɪrɪt","m":"n.精神；心灵；本质","tip":"我喝完雪碧（Sprite）瞬间有了精神（spirit）。","ex":["They had a strong community spirit.","他们有强烈的集体精神。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"inspire","p":"ɪnˈspaɪə(r)","m":"v.激励，鼓舞；赋予灵感","tip":"in-（入）+ spire（= spirit）→ 注入精神力量 → 激励，鼓舞；赋予灵感","ex":["Our philosophy is to inspire kids at a young age to understand that engineering is a great career.","我们的理念是在孩子们很小的时候就启迪他们，让他们明白工程学是一个伟大的职业。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"inspiration","p":"ˌɪnspəˈreɪʃn","m":"n.灵感；鼓舞人心的人或事物；好主意","tip":"inspire v. 激励；赋予灵感 → inspiration n.","ex":["Music gives me inspiration.","音乐给我灵感。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"aspire","p":"əˈspaɪə(r)","m":"v.渴望，有志于","tip":"a-（= to）+ spire（= spirit）→ 对……有精神 → 渴望，有志于","ex":["He aspired to be their next leader.","他渴望成为他们的下一届领导。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"eager","p":"ˈiːɡə(r)","m":"adj.热切的，渴望的","tip":"单词发音类似“一哥”→ 很多人都想成为某个行业的“一哥”→ 渴望的","ex":["They were more eager to enjoy a movie.","他们更渴望看电影。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"eagle","p":"ˈiːɡl","m":"n.鹰","tip":"这只鹰（eagle）渴望（eager）成为鸟界一哥。","ex":["They fell victim to eagles.","他们沦为老鹰的受害者。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"thirst","p":"θɜːst","m":"v.渴望，渴求 n.渴望；口渴","tip":"","ex":["Thousands are dying of thirst.","成千上万的人都干渴得奄奄一息。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"desire","p":"dɪˈzaɪə(r)","m":"n.愿望，欲望；渴望 v.渴望；期望","tip":"de（音似“弟”）+ sir（先生）+ e（联想“鹅”）→ 弟弟“渴望”先生讲鹅的故事。","ex":["I have no desire to make millions of dollars.","我不想赚数百万美元。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"cease","p":"siːs","m":"v.停止，终止","tip":"单词发音类似“谁死”→ 停止，终止","ex":["The close link between age and stage may cease to exist in a multi-stage life.","在多阶段的人生中，年龄和所处阶段之间的密切联系可能不复存在。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"suspend","p":"səˈspend","m":"v.悬，挂；暂停，中止","tip":"sus-（下面）+ pen（钢笔）+ d（联想“袋”）→ 他身着中山装，钢笔则朝下“挂”在口袋上。","ex":["They suspend import of necessities from overseas.","他们暂停从海外进口必需品。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"halt","p":"hɔːlt; hɒlt","m":"v.（使）停止，停下 n.停止；阻止；暂停","tip":"ha（联想“哈”）+ l（联想“了”）+ t（联想“他”）→ 他哈（吓）了一跳，目瞪口呆地停在那里 → 停止；暂停","ex":["The eyes of a very good reader move quickly, taking long jumps and making very short halts.","一个优秀的阅读者眼睛移动得很快，跳得很远，停顿很短。"],"lesson":"u06-l01","group":"“精神”相关"},{"w":"describe","p":"dɪˈskraɪb","m":"v.形容，描述","tip":"de-（往下）+ scribe（写）→ 写下来 → 描述","ex":["What three words would you use to describe the culture here?","你会用哪三个词来描述这里的文化？"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"script","p":"skrɪpt","m":"n.手迹，笔迹；剧本","tip":"这个抄写员（scribe）的笔迹（script）很容易辨认。","ex":["Page 55 is missing from the woman's scripts.","这位女士的剧本中少了第55页。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"prescribe","p":"prɪˈskraɪb","m":"v.开处方；规定","tip":"pre-（提前）+ scribe（写）→ 拿药前，医生会提前写好处方 → 开处方","ex":["Police regulations prescribe that an officer's number must be clearly visible.","警政制度规定，警察的编号必须清晰可见。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"skill","p":"skɪl","m":"n.技巧；技艺，技术，技能","tip":"","ex":["Cooking skills can be improved with practice.","烹饪技巧可以通过练习来提高。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"technique","p":"tekˈniːk","m":"n.技巧，技艺，工艺；技能","tip":"单词发音类似“泰克尼克”→ 泰克认为泰坦尼克号发生事故的原因之一可能是建造“技艺”不成熟。","ex":["They learned the techniques of collaborative writing.","他们学习了协同写作的技巧。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"technology","p":"tekˈnɒlədʒi","m":"n.科技；工艺；工程技术","tip":"","ex":["The era of personal technology is in many ways just beginning.","从很多方面来说，个人技术的时代才刚刚开始。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"high-tech","p":"ˌhaɪ ˈtek","m":"adj.高科技的（尤指电子方面）；样式新颖的","tip":"","ex":["Hi-tech products can boost people's integrative thinking.","高科技产品可以提高人们的综合思维。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"biotechnology","p":"ˌbaɪəʊtekˈnɒlədʒi","m":"n.生物科技","tip":"bio-（生物）+ technology（科技）→ 生物科技","ex":["On balance, biotechnology should be good news for developing countries.","总的来说，生物技术对发展中国家应该是好消息。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"clone","p":"kləʊn","m":"n.克隆动物（或植物） v.克隆，复制","tip":"","ex":["Genetic researchers in China have made a clone of a star police dog.","中国的基因研究人员克隆了一只明星警犬。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"genetic","p":"dʒəˈnetɪk","m":"adj.基因的，遗传学的","tip":"gene n.基因 → genetic adj.","ex":["There are about 4,000 inherited human genetic diseases.","人类遗传性疾病约有4,000种。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"technician","p":"tekˈnɪʃn","m":"n.技术员；技师","tip":"technic（技术）+ -ian（表示人的后缀）→ 技术员","ex":["He asked a technician to fix the broken production line.","他请技术员修理坏了的生产线。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"mechanic","p":"məˈkænɪk","m":"n.机械师，机械修理工；技工","tip":"mechan（联想 machine）+ -ic（表示人的后缀）→ 修机器的人 → 机械师；技工","ex":["Buying that second-hand car without having it checked by a mechanic first cost us dear.","购买那辆二手车时没有先请技师检查，让我们损失惨重。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"mechanism","p":"ˈmekənɪzəm","m":"n.机械装置，机件；方法；（生物体内的）机制","tip":"mechan（联想 machine）+ -ism（名词后缀）→ 机械装置","ex":["There is no mechanism to ensure that they make the required effort.","没有任何机制可以确保他们做出必要的努力。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"machinery","p":"məˈʃiːnəri","m":"n.机器，机械；体系；（使机器运转的）部件","tip":"","ex":["It accompanies all machinery involving high technology.","它伴随着所有涉及高科技的机器。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"radar","p":"ˈreɪdɑː(r)","m":"n.雷达","tip":"单词发音类似“雷达”。","ex":["By moving the radar beam around slowly in circles, we can explore the surroundings.","通过让雷达波绕着圆圈慢慢移动，我们可以探索周围的环境。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"radiation","p":"ˌreɪdiˈeɪʃn","m":"n.辐射；放射线；放射疗法","tip":"","ex":["Enormous quantities of radiation from the sun are screened off.","来自太阳的大量辐射被屏蔽掉。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"hardware","p":"ˈhɑːdweə(r)","m":"n.硬件；工具，设备，机器","tip":"hard（硬的）+ wa（音似“挖”）+ re（重复）→ 用硬东西重复地挖 → 工具，设备","ex":["For the consumer, it's a matter of paying now for the hardware to save later on the utilities.","对于消费者来说，现在支付硬件费用可以节省以后的水电费。"],"lesson":"u06-l01","group":"“描述、技术”相关"},{"w":"press","p":"pres","m":"n.新闻；出版社；记者 v.按，压","tip":"pressure n.压力；紧张 → press n. & v.","ex":["A major auto company is holding a press conference next week.","一个大型汽车公司将于下周举行新闻发布会。"],"lesson":"u06-l02","group":"press 相关"},{"w":"pressure","p":"ˈpreʃə(r)","m":"n.压力；紧张","tip":"pre-（前面）+ ss（形似两条蛇）+ -ure（名词后缀）→ 他的前面有两条蛇，让他倍感“压力”。","ex":["Furthermore, in-class exams force students to learn how to perform under pressure, an essential work skill.","而且，课堂考试迫使学生学习如何在压力下表现，这是一项基本的工作技能。"],"lesson":"u06-l02","group":"press 相关"},{"w":"depress","p":"dɪˈpres","m":"v.使沮丧；使萧条；压制","tip":"de-（往下）+ press（压）→ 心理上往下压 → 使沮丧","ex":["Wet weather always depresses me.","潮湿的天气常常使我沮丧。"],"lesson":"u06-l02","group":"press 相关"},{"w":"repress","p":"rɪˈpres","m":"v.镇压；抑制（感情）","tip":"re-（重复）+ press（压）→ 重复地压 → 镇压；抑制","ex":["It's good to let your emotions show, don't repress them.","让你的情绪表现出来很好，不要抑制它们。"],"lesson":"u06-l02","group":"press 相关"},{"w":"suppress","p":"səˈpres","m":"v.镇压；忍住（眼泪等）","tip":"sup-（往下）+ press（压）→ 镇压；忍住","ex":["She was unable to suppress a giggle.","她忍不住笑出声来。"],"lesson":"u06-l02","group":"press 相关"},{"w":"impress","p":"ɪmˈpres","m":"v.留下印象，使铭记","tip":"im-（= in-，入）+ press（压）→ 压进脑海里 → 留下印象，使铭记","ex":["His sincerity impressed her.","他的真诚给她留下了印象。"],"lesson":"u06-l02","group":"press 相关"},{"w":"remind","p":"rɪˈmaɪnd","m":"v.提醒；使想起","tip":"re-（重复）+ mind（大脑）→ 重复地出现在大脑中 → 提醒；使想起","ex":["Some services, however, remind us that life will eventually return to normal.","然而，一些服务提醒我们，生活最终将恢复正常。"],"lesson":"u06-l02","group":"press 相关"},{"w":"recall","p":"rɪˈkɔːl","m":"v.召回（残损货品等）；回忆起","tip":"re-（重复）+ call（呼唤）→ 召回；回忆起","ex":["\"I felt empowered because I broke through my own limitations,\" she recalls.","“我觉得自己被赋予了力量，因为我突破了自己的局限。”她回忆道。"],"lesson":"u06-l02","group":"press 相关"},{"w":"monument","p":"ˈmɒnjumənt","m":"n.纪念碑（或馆、堂、像等）；历史遗迹","tip":"单词发音类似“牦牛门特”→ 当地特别修了一个牦牛门“纪念碑”来纪念它。","ex":["It is a historical monument.","它是一座历史纪念碑。"],"lesson":"u06-l02","group":"press 相关"},{"w":"memorial","p":"məˈmɔːriəl","m":"n.纪念碑；纪念品 adj.纪念的，悼念的","tip":"memory n.记忆，回忆 → memorial n. & adj.","ex":["The town raised a memorial to those killed in the war.","这座小镇为战争中牺牲的人树立了一座纪念碑。"],"lesson":"u06-l02","group":"press 相关"},{"w":"memo","p":"ˈmeməʊ","m":"n.备忘录","tip":"","ex":["I have to finish this memo and put it in the mail.","我必须完成这份备忘录并把它寄出去。"],"lesson":"u06-l02","group":"press 相关"},{"w":"express","p":"ɪkˈspres","m":"v.表示，表达，表露 adj.特快的；快速的；快递的 n.特快列车","tip":"ex-（往外）+ press（压）→ 把内心的话往外压 → 表达","ex":["Most people express gratitude for help.","大多数人都对帮助表示感激。"],"lesson":"u06-l02","group":"press 相关"},{"w":"expressway","p":"ɪkˈspresweɪ","m":"n.（美国）高速公路","tip":"","ex":["There was an immense network of paved roads, residential streets and expressways.","铺设的道路、住宅街道和高速公路组成了庞大的网络。"],"lesson":"u06-l02","group":"press 相关"},{"w":"freeway","p":"ˈfriːweɪ","m":"n.（美国）高速公路","tip":"","ex":["The speed limit on the freeway is 55 mph.","高速公路限速每小时 55 英里。"],"lesson":"u06-l02","group":"press 相关"},{"w":"motorway","p":"ˈməʊtəweɪ","m":"n.（英国）高速公路","tip":"","ex":["In 1958, Britain celebrated the opening of its first motorway.","1958 年，英国庆祝其第一条高速公路开通。"],"lesson":"u06-l02","group":"press 相关"},{"w":"highway","p":"ˈhaɪweɪ","m":"n.公路，大路","tip":"","ex":["He left his paintings at a highway rest stop.","他把画忘在高速公路休息站了。"],"lesson":"u06-l02","group":"press 相关"},{"w":"bypass","p":"ˈbaɪpɑːs","m":"n.（绕过城市的）旁路，旁道 v.绕过，避开","tip":"by（在旁边）+ pass（通过）→ 绕过，避开","ex":["A new road now bypasses the town.","一条新路绕城镇而过。"],"lesson":"u06-l02","group":"press 相关"},{"w":"sideways","p":"ˈsaɪdweɪz","m":"adv.斜向一边地；侧着","tip":"","ex":["The truck skidded sideways across the road.","卡车侧滑到公路另一侧。"],"lesson":"u06-l02","group":"press 相关"},{"w":"vertical","p":"ˈvɜːtɪkl","m":"adj.垂直的，直立的；纵向的","tip":"单词发音类似“我体考”→ 我参加体育考试时，身体是“直立的”。","ex":["There are numerous vertical solar panels.","这里有无数个垂直太阳能电池板。"],"lesson":"u06-l02","group":"press 相关"},{"w":"justice","p":"ˈdʒʌstɪs","m":"n.公平，公正；法官；司法制度","tip":"just adj. 公正的；应得的 → justice n.","ex":["It is to recognise that in America's vast criminal justice system, second chances are crucial.","要认识到，在美国庞大的刑事司法体系中，第二次机会至关重要。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"justify","p":"ˈdʒʌstɪfaɪ","m":"v.证明……是正当的；为……辩护","tip":"just（公正的）+ -ify（动词后缀）→ 证明……是正当的","ex":["Are the benefits of the product important enough to justify buying it?","产品的好处是否重要到值得购买？"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"court","p":"kɔːt","m":"n.法院，法庭；球场","tip":"在法庭（court）上要有礼貌（courteous）。","ex":["The suspect returns to court a week or two later.","嫌疑人会在一两个星期后回到法庭。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"jury","p":"ˈdʒʊəri","m":"n.陪审团；（竞赛或展览的）评判委员会","tip":"ju（联想“救”）+ ry（联想“阿姨”）→ “陪审团”帮助阿姨伸张正义，救阿姨于水火。","ex":["The jury has returned a verdict of guilty.","陪审团已作出有罪裁定。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"trial","p":"ˈtraɪəl","m":"n.试验，试用；审判 v.测试","tip":"try n.尝试 v.尝试；试验 → trial n. & v.","ex":["We learn, in a sense, by trial and error.","从某种意义上说，我们是通过反复试错来学习的。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"arrest","p":"əˈrest","m":"v.逮捕 n.逮捕，拘留","tip":"ar（音似“啊”）+ rest（休息）→ 罪犯被“逮捕”之后感叹：“啊，终于可以休息了。”","ex":["They arrested the suspect immediately.","他们立即逮捕了犯罪嫌疑人。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"crime","p":"kraɪm","m":"n.犯罪活动，不法行为；罪行","tip":"cri（联想 cry）+ me（我）→ 罪犯往往在最后审判的时候痛哭流涕，悔恨自己的“犯罪活动”。","ex":["A couple of them have got involved in crimes.","他们中有几人被卷入了犯罪。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"discrimination","p":"dɪˌskrɪmɪˈneɪʃn","m":"n.歧视；偏袒","tip":"dis-（不）+ crimi（联想 crime）+ nation → 他认为不能“歧视”犯罪嫌疑人。","ex":["There is discrimination against male nurses.","男护士受到歧视。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"oblige","p":"əˈblaɪdʒ","m":"v.（以法律、义务等）强迫，迫使","tip":"单词发音类似“我不来挤”→ 你不来挤也不能逃避，因为这是你的责任和义务 → 强迫，迫使","ex":["They were obliged to fulfill the signed contract.","他们不得不履行已签订的合同。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"responsible","p":"rɪˈspɒnsəbl","m":"adj.有责任的；承担义务的","tip":"re（字母音似“阿姨”）+ s（联想“死”）+ p（联想“趴”）+ on（上面）+ s + -ible（形容词后缀）→ 阿姨死死地趴在工作上面，因为她是“有责任的”。","ex":["They are responsible for working through that problem.","他们有责任解决那个问题。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"duty","p":"ˈdjuːti","m":"n.责任；义务；上班；税，关税","tip":"du（联想 do）+ ty（联想 it）→ 他有“责任”和“义务”去做它。","ex":["He felt it his duty to revolutionise its management.","他觉得改革它的管理是他的责任。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"charge","p":"tʃɑːdʒ","m":"n.收费；负责；指控；指责；掌管 v.收（费）；起诉；指责；充电；索赔","tip":"char（音似“插”）+ ge（联想“哥”）→ 她不小心插到哥哥的手，哥哥让她“负责”；哥哥开玩笑说如果不负责，就“起诉”她。","ex":["He faces trial on several charges.","他面临针对多项指控的审判。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"discharge","p":"ˈdɪstʃɑːdʒ","m":"n.排出；获准离开；免职；出院；退伍","tip":"dis-（不）+ charge（负责）→ 不让你负责 → 你被“准许离开”了，因为你被“解雇”了。","ex":["The child had been treated and was being prepared for discharge.","这个孩子已经接受了治疗，正准备出院。"],"lesson":"u06-l02","group":"“司法”相关"},{"w":"legal","p":"ˈliːɡl","m":"adj.与法律有关的；合法的","tip":"单词发音类似“立个”→ 立个法来确定哪些行为是“合法的”。","ex":["Duck hunting remains legal in many parts of the world.","猎鸭在世界许多地方仍然是合法的。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"legislation","p":"ˌledʒɪsˈleɪʃn","m":"n.立法；法律","tip":"legal adj.合法的 → legislation n.","ex":["They are calling for tough legislation to tackle this problem.","他们提出制订严格的法律来解决这个问题。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"item","p":"ˈaɪtəm","m":"n.项目；条款；一件商品（或物品）；一条（新闻）","tip":"i（音似“爱”）+ te（联想“他”）+ m（联想“妈”）→ 他列出了很多爱妈妈的“条款”。","ex":["Sharing items such as cars does good to the environment.","共享汽车等共享物品对环境有好处。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"clause","p":"klɔːz","m":"n.从句；条款","tip":"单词发音类似“可老实”→ 看到法律的“条款”，不法分子可老实了。","ex":["A clever lawyer might find a way of getting round that clause.","高明的律师也许能找到绕过那个条款的办法。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"draft","p":"drɑːft","m":"n.草稿；草案；汇票 v.起草；草拟","tip":"草稿（draft）就像是漂流（drift）的东西，定不下来。","ex":["She worked on the draft of the American Constitution.","她参与起草了《美国宪法》。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"drift","p":"drɪft","m":"n.流动 v.漂流","tip":"单词发音类似“坠浮它”→ 吊坠它浮在水面上 → 漂流","ex":["We proceeded to drift on up the river.","我们继续向河流的上游漂流。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"flow","p":"fləʊ","m":"v. & n.流动","tip":"单词发音类似“浮楼”→ 随着水的“流动”，水面上浮现出一栋楼的倒影。","ex":["Blood flow can be reduced as blood vessels narrow.","随着血管变窄，血流可能会减少。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"float","p":"fləʊt","m":"n.流动；漂流物 v.浮动，漂浮","tip":"单词发音类似“浮楼它”→ 有些楼房建在河边，看着就像“漂浮”在水面上一样。","ex":["They float around in the oven.","它们在烤箱里漂浮。"],"lesson":"u06-l02","group":"legal 相关"},{"w":"valid","p":"ˈvælɪd","m":"adj.（法律上）有效的；合理的","tip":"单词发音类似“娃累的”→ 因为娃学习了一整天，所以他感觉累是“合理的”。","ex":["There are valid reasons boredom may feel so painful.","无聊可能会（让人）感到如此痛苦，这是有合理的理由的。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"validate","p":"ˈvælɪdeɪt","m":"v.证明，确认；使生效","tip":"valid（有效的）+ -ate（动词后缀）→ 使生效","ex":["We validated these expectations in a study.","我们在一项研究中证明了这些期望。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"appeal","p":"əˈpiːl","m":"n.呼吁，恳求；上诉 v.有吸引力；上诉；恳请，呼吁","tip":"a（一）+ ppeal（音似“皮”）→ 志愿者在太阳下“呼吁”人们环保，脸被晒得蜕了一层皮。","ex":["It appeals to kids' curiosity to find out what is hidden inside.","它吸引了孩子们的好奇心，要弄清里面藏着什么。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"beg","p":"beɡ","m":"v.恳求，请求；乞求","tip":"单词发音类似“拜哥”→ 他拜你做哥哥是为了“恳求”你帮个忙。","ex":["Kids would beg for a new lunch box every year to keep up with the newest characters.","孩子们每年还是会乞求买新饭盒来跟上最新角色的潮流。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"surrender","p":"səˈrendə(r)","m":"v.投降，自首；放弃；交出","tip":"sur（音似“射”）+ ren（联想“人”）+ der（音似“的”）→ 狙击手射人的枪法很准，歹徒立马就“投降”了。","ex":["They surrendered their guns to the police.","他们向警察交出了枪。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"condemn","p":"kənˈdem","m":"v.指责，谴责；宣判；使陷入","tip":"con-（所有）+ demn（联想 damn）→ 所有人都在咒骂他 → 谴责","ex":["The president condemns their greed.","总统谴责了他们的贪婪。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"verify","p":"ˈverɪfaɪ","m":"v.核实；证明","tip":"veri（联想 very，恰好的）+ fy（联想“反应”）→ 恰好她反应快，“证明”了自己。","ex":["It is urgent that schools teach kids how to verify online information.","学校迫切需要教孩子们如何核实在线信息。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"witness","p":"ˈwɪtnəs","m":"n.目击者；证人 v.目击；见证","tip":"证人（witness）需要有一定的智力（wit）水平才能给他人作证。","ex":["It has witnessed several traffic accidents this year.","今年这里发生了几起交通事故。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"bystander","p":"ˈbaɪstændə(r)","m":"n.旁观者","tip":"by（在旁边）+ stand（站）+ -er（表示人的后缀）→ 站在旁边的人 → 旁观者","ex":["A bystander wrote a poem about the event.","一位旁观者就此事件写了一首诗。"],"lesson":"u06-l02","group":"“证明、证实”相关"},{"w":"torture","p":"ˈtɔːtʃə(r)","m":"n.拷打；折磨 v.折磨，使痛苦；拷问","tip":"单词发音类似“偷窃”→ 小偷偷窃后被抓住“拷问”。","ex":["He spent his life tortured by the memories of his childhood.","童年的记忆使他痛苦了一辈子。"],"lesson":"u06-l02","group":"“惩罚”相关"},{"w":"victim","p":"ˈvɪktɪm","m":"n.受害者；牺牲品","tip":"单词发音类似 weak team → 比赛中很弱的团队只能是“牺牲品”。","ex":["One benefit of this change is that students will not fall victim to the \"summer slide\".","这种变化的一个好处是学生们不会成为“暑期（学习）退步”的受害者。"],"lesson":"u06-l02","group":"“惩罚”相关"},{"w":"sacrifice","p":"ˈsækrɪfaɪs","m":"n.牺牲；舍弃 v.牺牲；献出","tip":"单词发音类似“杀可就非死”→ 读起来有种“为有牺牲多壮志，敢教日月换新天”的感觉 → 牺牲","ex":["The pursuit of a fulfilling career involves personal sacrifice.","追求令人满意的事业需要个人的牺牲。"],"lesson":"u06-l02","group":"“惩罚”相关"},{"w":"jail","p":"dʒeɪl","m":"n.监狱 v.监禁","tip":"单词发音类似“舅”→ 他的舅舅蹲“监狱”了。","ex":["He has been released from jail.","他已从监狱里放出来了。"],"lesson":"u06-l02","group":"“惩罚”相关"},{"w":"prison","p":"ˈprɪzn","m":"n.监狱；看守所 v.监禁；关押","tip":"","ex":["He visited a prison located on a faraway island.","他参观了一个位于遥远岛屿上的监狱。"],"lesson":"u06-l02","group":"“惩罚”相关"},{"w":"punish","p":"ˈpʌnɪʃ","m":"v.处罚；惩罚","tip":"单词发音类似“怕你失”→ 妈妈怕你迷失了自己，要严格管教你 → 惩罚","ex":["Their parents often punish them for minor faults.","他们的父母经常因为小错误而惩罚他们。"],"lesson":"u06-l02","group":"“惩罚”相关"},{"w":"penalty","p":"ˈpenəlti","m":"n.处罚，惩罚；不利","tip":"pe（音似“怕”）+ na（联想“那”）+ l（形似 1）+ -ty（名词后缀）→ 孩子很怕那个人，因为那个人经常“惩罚”他。","ex":["Especially for women, there is a clear penalty at work for being overweight or obese.","尤其是对女性来说，在工作中，超重或肥胖会有明显的不利。"],"lesson":"u06-l02","group":"“惩罚”相关"},{"w":"guilt","p":"ɡɪlt","m":"n.内疚；犯罪；责任","tip":"gui（联想“跪”）+ l（联想“了”）+ t（联想“他”）→ 他因为“内疚”而向老人下跪了。","ex":["More than half of the interviewees felt no sense of guilt over cheating.","超过一半的受访者对作弊没有罪恶感。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"apologise","p":"əˈpɒlədʒaɪz","m":"v.道歉；谢罪","tip":"ap-（一再地）+ (p)olo（音似“抛了”）+ gise（音似 jazz，爵士乐）→ 他因为一再地抛弃爵士乐课而向老师“道歉”。","ex":["Have you ever used email to apologize to a colleague?","你曾经用电子邮件向同事道歉吗？"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"sin","p":"sɪn","m":"n.罪行；过错 v.犯戒律","tip":"s（联想“美女”）+ in（里面）→ 一个美女因为严重“过错”被关在监狱里。","ex":["He felt guilty for his sins and decided to change.","他为自己的过错感到内疚，决定改变。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"kneel","p":"niːl","m":"v.跪下","tip":"knee（膝盖）+ l（联想“了”）→ 膝盖软了 → 跪下","ex":["People sometimes kneel to pray.","人们有时跪着祈祷。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"mud","p":"mʌd","m":"n.泥，泥浆","tip":"","ex":["The busy streets in Paris were uneven and caked in thick mud.","巴黎繁忙的街道坑坑洼洼，到处都是厚厚的泥。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"dignity","p":"ˈdɪɡnəti","m":"n.庄重；尊严；高贵","tip":"dig（挖）+ ni（联想“泥”）+ ty（音似“体”）→ 从挖泥开始不断奋斗，获得体面，赢得“尊严”。","ex":["It causes them to lose dignity.","这使他们失去了尊严。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"innocent","p":"ˈɪnəsnt","m":"adj.清白的，无罪的；天真的 n.无辜者，单纯的人","tip":"in（里面）+ no（没有）+ cent（分）→ 口袋里没有一分钱的人一般都是小孩，他们的特点是“天真的”。","ex":["She was found innocent of any crime.","她获判无罪。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"decent","p":"ˈdiːsnt","m":"adj.得体的，体面的；正派的","tip":"de（音似“弟”）+ cent（分）→ 弟弟捡到一分钱，把它交到了警察叔叔手里面，这是多么“得体的”行为！","ex":["They won't help you get a decent job.","他们不会帮你找到一份体面的工作。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"incentive","p":"ɪnˈsentɪv","m":"n.动机；刺激，激励","tip":"in（里面）+ cent（分）+ -ive（名词后缀）→ 口袋里面只剩一分钱了，生活压力就会“刺激”你去挣钱。","ex":["But there needs to be strong economic incentives for companies to locate here.","但需要有强有力的经济激励措施来鼓励企业在这里落户。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"execute","p":"ˈeksɪkjuːt","m":"v.执行；处死","tip":"他被起诉（prosecute）后，很有可能被执行（execute）死刑。","ex":["He was the first minor to be executed in South Carolina.","他是南卡罗来纳州第一个被处决的未成年人。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"loophole","p":"ˈluːphəʊl","m":"n.（法律、合同等的）漏洞","tip":"loo（形似 100）+ p（联想“趴”）+ hole（洞）→ 100 个人趴在会场才能组成奥运五环，如果人数不够，就会出现“漏洞”。","ex":["The government promised to close the loophole in the law.","政府承诺填补法律中的漏洞。"],"lesson":"u06-l02","group":"“犯罪”相关"},{"w":"cause","p":"kɔːz","m":"n.起因；理由；事业 v.导致","tip":"","ex":["A lot of times, though, the act of keeping your name is still something that causes concern.","然而，很多时候，保留你的名字的行为仍然令人担忧。"],"lesson":"u06-l03","group":"“原因”相关"},{"w":"due","p":"djuː","m":"adj.由于；预期的；应得的 n.应付款；应得之物 adv.正向，正对着","tip":"单词发音类似“丢”→ 他“由于”弄丢了手表，没有在“预期的”时间内到达目的地。","ex":["This is partly due to a lack of necessary evidence.","部分原因是缺乏必要的证据。"],"lesson":"u06-l03","group":"“原因”相关"},{"w":"given","p":"ˈɡɪvn","m":"adj.规定的；特定的 prep.考虑到","tip":"","ex":["Given his age, he's remarkably active.","考虑到他的年龄，他已是相当活跃的了。"],"lesson":"u06-l03","group":"“原因”相关"},{"w":"ingredient","p":"ɪnˈɡriːdiənt","m":"n.成分；(尤指烹饪)材料；(成功的)因素，要素","tip":"in（里面）+ gredi（联想“搁点”）+ ent → 做饭时要往锅里搁点“材料”。","ex":["But innovation, broadly defined, is the crucial ingredient in all economic progress.","但广义上说，创新是所有经济进步的关键因素。"],"lesson":"u06-l03","group":"“原因”相关"},{"w":"element","p":"ˈelɪmənt","m":"n.要素，因素；(学科的)基本原理，基础，纲要","tip":"","ex":["Credit cards and loans will be a central element.","信用卡和贷款将是核心要素。"],"lesson":"u06-l03","group":"“原因”相关"},{"w":"factor","p":"ˈfæktə(r)","m":"n.因素，要素","tip":"","ex":["It is a chief factor affecting students' learning.","它是影响学生学习的主要因素。"],"lesson":"u06-l03","group":"“原因”相关"},{"w":"sake","p":"seɪk","m":"n.缘故，为了……起见","tip":"他一直在寻找（seek）是何缘故（sake）。","ex":["They stayed together for the sake of the children.","为了孩子，他们还待在一起。"],"lesson":"u06-l03","group":"“原因”相关"},{"w":"forgive","p":"fəˈɡɪv","m":"v.原谅；免除(债务)","tip":"for（因为）+ give（给）→ 因为他给了我礼物，所以我“原谅”他了。","ex":["The society fails to forgive them for their mistakes.","社会未能原谅他们的错误。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"curse","p":"kɜːs","m":"v.诅咒，咒骂 n.咒骂，咒语","tip":"单词发音类似“克死”→ 诅咒","ex":["They seemed cursed to suffer disastrous fates.","他们似乎被诅咒了，要遭受灾难性的命运。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"scold","p":"skəʊld","m":"v.责骂，训斥","tip":"他们入住的酒店太冷（cold）了，酒店经理训斥（scold）员工失职。","ex":["He scolded them for arriving late.","他斥责他们迟到了。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"accuse","p":"əˈkjuːz","m":"v.控诉，控告；谴责","tip":"ac-（一再地）+ cuse（联想 curse）→ 他一再地诅咒别人，这种行为应该被“谴责”。","ex":["He was accused of causing a fire.","他被控告纵火。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"excuse","p":"ɪkˈskjuːz","m":"v.原谅；免除","tip":"ex（联想“前任”）+ cuse（音似“求死”）→ 前任找“借口”求“原谅”。","ex":["To forbid a thing one day and excuse it the next is no foundation for morality.","第一天禁止一件事，第二天又原谅它，这是没有道德基础的。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"quarrel","p":"ˈkwɒrəl","m":"v. & n.争吵，吵架","tip":"单词发音类似“口哟”→ 争吵，吵架","ex":["He has just quarreled with his girlfriend.","他刚和女朋友吵了一架。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"insult","p":"ˈɪnsʌlt","m":"n.辱骂；侮辱；冒犯","tip":"in（音似“言”）+ sult（联想 result）→ 用语言“侮辱”别人不会得到好的结果。","ex":["The questions were an insult to our intelligence.","那些问题有辱我们的智力。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"consult","p":"kənˈsʌlt","m":"v.咨询，请教；查阅","tip":"con-（所有）+ sult（联想 result）→ 请放心，通过“咨询”，所有事项都会有结果的。","ex":["She had not consulted the government before the visit.","她在访问前没有咨询过政府。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"blame","p":"bleɪm","m":"v.责备，责怪 n.责备；责任","tip":"b（联想“不”）+ la（联想“拉”）+ me（我）→ 我腿脚不灵活，跑步时他还不拉我一把，我忍不住“责备”了他。","ex":["But not everything is to be blamed on technology.","但并不是所有的事情都要归咎于科技。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"tame","p":"teɪm","m":"v.驯服，制服 adj.(动物)驯服的；温顺的","tip":"ta（联想“她”）+ me（我）→ 我曾是一个桀骜不驯的人，遇见她之后就被“驯服”了。","ex":["They are quite easy to tame.","它们很容易驯服。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"melt","p":"melt","m":"v.(使)融化","tip":"me（我）+ l（联想“了”）+ t（联想“他”）→ 我“融化”了他的内心。","ex":["The sun had melted the snow.","阳光融化了积雪。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"critic","p":"ˈkrɪtɪk","m":"n.批评家，评论家","tip":"cr（联想“超人”）+ i（字母音似“爱”）+ tic（音似“提个”）→ 超人爱提个棍到处批评人 → 批评家","ex":["Some critics say it is a luxury and shouldn't be free to families able to pay.","一些批评家表示，它是一种奢侈品，不应该免费提供给有能力支付的家庭。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"criticise","p":"ˈkrɪtɪsaɪz","m":"v.批评；评论","tip":"","ex":["The ads criticised the measure, characterizing it as a \"grocery tax\".","广告批评了这项措施，称其为“杂货税”。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"criticism","p":"ˈkrɪtɪsɪzəm","m":"n.批评，批判；评论","tip":"","ex":["It has drawn a lot of criticism from overseas.","招致了海外的大量批评。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"critical","p":"ˈkrɪtɪkl","m":"adj.决定性的，关键的；严重的；批判性的","tip":"","ex":["It is likely to be a critical turning point in one's life.","它可能是一个人一生中的关键转折点。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"criterion","p":"kraɪˈtɪəriən","m":"n.标准，准则；原则","tip":"评判一个人是需要标准（criterion）的，不能随意批判（criticise）别人。","ex":["The criterion for a snow day is primarily the inability of school buses.","雪休日的标准主要是校车无法通行。"],"lesson":"u06-l03","group":"“言语冲突”相关"},{"w":"assist","p":"əˈsɪst","m":"v.帮助，促进","tip":"as-（一再地）+ sist（站）→ 她一再地站在你旁边是为了“帮助”你。","ex":["He assists the professor with his teaching.","他协助教授进行教学。"],"lesson":"u06-l03","group":"sist“站”相关"},{"w":"resist","p":"rɪˈzɪst","m":"v.抵抗，抵制；阻挡","tip":"re-（回）+ sist（站）→ 往回站 → 抵抗，抵制","ex":["Neither children nor adults could resist the temptation of a free toy.","孩子和大人都无法抗拒免费玩具的诱惑。"],"lesson":"u06-l03","group":"sist“站”相关"},{"w":"insist","p":"ɪnˈsɪst","m":"v.坚决要求，坚持；坚称","tip":"in-（向内）+ sist（站）→ 向内站在自己的立场里 → 坚持；坚称","ex":["The textbook industry insists the online systems represent a better deal for students.","教材行业坚称，在线系统对学生来说是更好的选择。"],"lesson":"u06-l03","group":"sist“站”相关"},{"w":"persist","p":"pəˈsɪst","m":"v.坚持；继续存在","tip":"per（每一）+ sist（站）→ 每一天都站着 → 坚持","ex":["If our findings persist, we may be faced with a financial crisis.","如果我们的发现持续下去，我们可能会面临一场金融危机。"],"lesson":"u06-l03","group":"sist“站”相关"},{"w":"consist","p":"kənˈsɪst","m":"v.由……组成，构成","tip":"con-（一起）+ sist（站）→ 站在一起 → 由……组成，构成","ex":["The large bowl consisted of two equal parts.","大碗由两个相等的部分组成。"],"lesson":"u06-l03","group":"sist“站”相关"},{"w":"comprise","p":"kəmˈpraɪz","m":"v.包括；由……组成","tip":"com-（一起）+ prise（联想 prize）→ “包括”他在内的所有成员一起得到了奖品。","ex":["Teenagers comprise about half of the group.","青少年约占团体的一半。"],"lesson":"u06-l03","group":"sist“站”相关"},{"w":"praise","p":"preɪz","m":"v. & n.表扬，赞美","tip":"p（联想“趴”）+ raise（举起，竖起）→ 人们竖起大拇指“表扬”累趴在地上的搜救犬。","ex":["A lifetime of praise leads smart people to develop too much faith in their intelligence and abilities.","一生的赞美会使聪明人对自己的智力和能力产生过度的信心。"],"lesson":"u06-l03","group":"sist“站”相关"},{"w":"enterprise","p":"ˈentəpraɪz","m":"n.企业；规划，事业","tip":"enter（进入）+ prise（联想 praise）→ “企业”领导走进办公室，表扬他出色的工作。","ex":["These platforms create a bridge between traditional enterprises and this emerging economy.","这些平台在传统企业和这个新兴经济体之间架起了一座桥梁。"],"lesson":"u06-l03","group":"“公司”相关"},{"w":"entrepreneur","p":"ˌɒntrəprəˈnɜː(r)","m":"n.企业家","tip":"entre（联想 enter）+ pre-（提前）+ ne（联想 new）+ ur（联想 -or）→ 提前进入新领域的人是富有远见和冒险精神的“企业家”。","ex":["People often wonder why some entrepreneurs have greater success than others.","人们经常想知道为什么有些企业家比其他人更成功。"],"lesson":"u06-l03","group":"“公司”相关"},{"w":"corporation","p":"ˌkɔːpəˈreɪʃn","m":"n.公司；法人","tip":"单词发音类似“靠谱为生”→“公司”要靠谱才能生存。","ex":["Employers attach great importance to their corporations' diversity.","雇主非常重视公司的多元化。"],"lesson":"u06-l03","group":"“公司”相关"},{"w":"empire","p":"ˈempaɪə(r)","m":"n.帝国；大企业","tip":"单词发音类似“俺妹怕”→ 我妹妹怕“帝国”的威严。","ex":["He has built a huge business empire from humble beginnings.","他白手起家创建了庞大的商业帝国。"],"lesson":"u06-l03","group":"“公司”相关"},{"w":"accompany","p":"əˈkʌmpəni","m":"v.陪伴，伴随","tip":"ac-（= to）+ company（陪伴）→ 陪伴，伴随","ex":["What are entrepreneurs advised to do to avoid traps that often accompany rivalry?","建议企业家们采取哪些措施来避免竞争中常出现的陷阱呢？"],"lesson":"u06-l03","group":"“公司”相关"},{"w":"manage","p":"ˈmænɪdʒ","m":"v.完成；解决；管理","tip":"man（人）+ age（年代）→ 有人的年代就有“管理”。","ex":["Women are more likely than men to take charge of their stress and manage it.","女性比男性更有可能掌控自己的压力并加以管理。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"chair","p":"tʃeə(r)","m":"n.椅子；主席 v.主持；使……就任要职","tip":"","ex":["\"We didn't do any global consideration,\" says the board's chair.","董事会主席说：“我们没有做任何全球性的考虑。”"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"president","p":"ˈprezɪdənt","m":"n.总统，主席；董事长；总经理；(大学)校长","tip":"pre-（前面）+ sid（联想 side）+ ent（联想 enter）→ 从前面侧门进来的人是“总经理”。","ex":["It was suggested by the firm's vice president.","这是公司副总裁提出的建议。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"harness","p":"ˈhɑːnɪs","m":"v.控制；利用 n.马具，挽具","tip":"harne（音似 honey）+ ss（联想“死”）→ 这个公司的决策者去世了，他亲爱的配偶“控制”了整个公司。","ex":["So executives hit on an idea that would harness the new-found popularity of television.","因此，高管们想出了一个主意，可以利用最近流行起来的电视。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"control","p":"kənˈtrəʊl","m":"v.指挥；控制；掌管 n.管理权，支配权；控制(或操纵)能力","tip":"","ex":["Some people find that craftwork helps them control their weight.","有些人发现，手工(活动)可以帮助他们控制体重。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"compete","p":"kəmˈpiːt","m":"v.参加比赛；竞争","tip":"com（联想 company）+ pete（联想 PK）→ 公司之间 PK，就是“竞争”。","ex":["It is well positioned to compete with the giants.","它处于与巨头竞争的有利位置。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"competition","p":"ˌkɒmpəˈtɪʃn","m":"n.竞争；比赛","tip":"","ex":["There will be more competition in the job market.","就业市场上的竞争将更加激烈。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"competent","p":"ˈkɒmpɪtənt","m":"adj.有能力的；称职的","tip":"我的竞争对手（competitor）是一个有能力的（competent）人。","ex":["But what makes you a competent lion dancer is that there's a sense of imagination involved.","但让你成为一个称职的舞狮者的是，其中蕴含着一种想象力。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"complete","p":"kəmˈpliːt","m":"v.完成；填写(表格) adj.完成的；彻底的","tip":"compete（竞争）+ l（联想“了”）→ 竞争结束了 → 完成","ex":["One spouse wants a complete name change.","配偶的一方希望彻底改名。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"versus","p":"ˈvɜːsəs","m":"prep.(表示两队或双方对阵)对抗；与……相对","tip":"单词的缩写形式是 VS，表示“对抗”。","ex":["It is France versus Brazil in the final.","决赛是法国队对巴西队。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"crisis","p":"ˈkraɪsɪs","m":"n.危机；危急关头","tip":"cri（联想 cry）+ sis（联想“死”）→ 这次“危机”让他哭得死去活来。","ex":["New research has found deep water reserves under the state which could help solve their drought crisis.","新的研究发现，该州的深水储备可能有助于解决干旱危机。"],"lesson":"u06-l03","group":"“管理、竞争”相关"},{"w":"finance","p":"ˈfaɪnæns","m":"n.资金；财政，金融 v.提供资金","tip":"单词发音类似“犯难死”→ 当西方发生“金融”危机的时候，破产者犯难死了。","ex":["She started an ice-cream business to finance her daughter's education.","她开了一家冰淇淋店来资助女儿的教育。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"funding","p":"ˈfʌndɪŋ","m":"n.专款，资金；提供资金","tip":"fund n. 专款，资金 → funding n.","ex":["Funding for science has changed with the times.","科学资助随着时代而变化。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"commerce","p":"ˈkɒmɜːs","m":"n.(尤指国际的)贸易，商业","tip":"com-（所有的）+ merce（音似“没死”）→ 商海如战场，稍有不慎所有人就会被淹没 → 贸易，商业","ex":["International commerce plays a vital role in global economic growth.","国际贸易在全球经济增长中发挥着至关重要的作用。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"commodity","p":"kəˈmɒdəti","m":"n.商品；有用的东西","tip":"","ex":["How do we assess the value of a commodity?","我们如何评估一件商品的价值？"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"goods","p":"ɡʊdz","m":"n.商品；动产；私人财产","tip":"单词发音类似“谷子”→ 谷子就是他的“商品”。","ex":["The other sections you should get to know are the frozen foods and the durable goods.","你应该了解的其他部分是冷冻食品和耐用商品。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"merchant","p":"ˈmɜːtʃənt","m":"n.商人；批发商","tip":"单词发音类似“摸钱他”→ 他是个每天摸钱，和钱打交道的“商人”。","ex":["The family was forced to live on credit from local merchants.","这家人不得不靠向当地商人赊账生活。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"stock","p":"stɒk","m":"n.库存；股票 v.存货","tip":"这个商店（store）里面摆满了各种库存（stock）商品。","ex":["That particular model is not currently in stock.","那种特定型号目前没货。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"storage","p":"ˈstɔːrɪdʒ","m":"n.贮存，贮藏(空间)","tip":"","ex":["There's a lot of storage space in the loft.","阁楼上有很大的存储空间。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"trade","p":"treɪd","m":"n.贸易；交易(量) v.做生意，从事贸易","tip":"单词发音类似“槌的”→ 拍卖的时候，敲木槌确定“交易”完成。","ex":["It will help many African countries reduce trade deficits.","它将帮助许多非洲国家减少贸易逆差。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"trademark","p":"ˈtreɪdmɑːk","m":"n.商标，标志","tip":"trade（交易）+ mark（标记）→ 商标","ex":["If you don't register your trademark yourself, there's a good chance that it will be squatted by others.","如果你不注册自己的商标，那么很有可能它会被别人占用。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"budget","p":"ˈbʌdʒɪt","m":"n.预算 v.做预算","tip":"bud（音似“爸的”）+ get（得到）→ 爸爸得到了很多的“预算”。","ex":["They are under growing pressure to balance their national budgets.","他们承受着越来越大的平衡国家预算的压力。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"gadget","p":"ˈɡædʒɪt","m":"n.小玩意，小装置","tip":"","ex":["A relatively harmless gadget may be turning friends away from your home.","一个相对无害的小玩意可能会让朋友远离你的家。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"target","p":"ˈtɑːɡɪt","m":"n.目标；(射击的)靶子 v.瞄准","tip":"tar（音似“它”）+ get（得到）→ 得到它就是我们的“目标”！","ex":["Scotland will reach the national target in carbon emissions reduction ahead of schedule.","苏格兰将提前实现全国碳减排目标。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"destination","p":"ˌdestɪˈneɪʃn","m":"n.目的地，终点；目标","tip":"desti（联想“的士”）+ nation（国家）→ 在任何一个国家坐的士，都要告诉司机“目的地”。","ex":["Venice is one of the hottest tourist destinations in the world.","威尼斯是世界上最热门的旅游胜地之一。"],"lesson":"u06-l03","group":"“商贸”相关"},{"w":"revenue","p":"ˈrevənjuː","m":"n.收入，收益；(政府的)税收","tip":"re（字母音似“阿姨”）+ venue（联想 Venus）→ 阿姨把一部分“收入”捐献给贫困学生，学生们夸她像维纳斯一样美丽。","ex":["Most of their revenues come from the government.","他们的大部分收入来自政府。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"avenue","p":"ˈævənjuː","m":"n.大街，林荫道；途径，手段","tip":"a（一）+ venue（联想 Venus）→ 他今天在“大街”上遇见了一个像维纳斯一样美丽的人。","ex":["She aims to open up fresh avenues for women post-doctors to join in research work.","她力求为女性博士后参与研究工作开辟新的途径。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"income","p":"ˈɪnkʌm","m":"n.收入，收益","tip":"in（里面）+ come（来）→ 钱进到家里，就变成了“收入”。","ex":["It started when people's income was relatively high.","它始于人们收入相对较高的时候。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"gross","p":"ɡrəʊs","m":"adj.总的，毛的；严重的 v.总收入为；总共赚得","tip":"单词发音类似“割肉丝”→ 他割了块肉切成了肉丝，毛重 1 千克 → 总的，毛的","ex":["The main measure of economic progress is the gross national product (GNP).","衡量经济发展的主要标准是国民生产总值。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"economy","p":"ɪˈkɒnəmi","m":"n.经济；(就经济体制而言)国家","tip":"","ex":["They organise a series of seminars on world economy.","他们组织了一系列关于世界经济的研讨会。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"economics","p":"ˌiːkəˈnɒmɪks","m":"n.经济学；经济情况","tip":"","ex":["She rented her economics and statistics textbooks for about $20 each.","她租的经济学和统计学课本每本大约 20 美元。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"economist","p":"ɪˈkɒnəmɪst","m":"n.经济学家","tip":"","ex":["It is the concern of contemporary economists.","这是当代经济学家关注的问题。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"economical","p":"ˌiːkəˈnɒmɪkl","m":"adj.经济的；节俭的，节约的；简洁的","tip":"economi（联想 economy）+ cal（音似“抠”）→ 他在经济方面是很“节俭的”，甚至有点儿抠门。","ex":["It should become more economical.","它应该变得更经济。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"scientific","p":"ˌsaɪənˈtɪfɪk","m":"adj.科学(上)的；细致严谨的","tip":"science n. 科学 → scientific adj.","ex":["These groups provide invaluable funding for scientific research.","这些团体为科学研究提供了宝贵的资金。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"evil","p":"ˈiːvl; ˈiːvɪl","m":"adj.恶毒的，邪恶的 n.邪恶；恶行","tip":"有些人生活（live）的另一面就是邪恶的（evil）魔鬼。","ex":["I suppose that's what these films are all about—good triumphing over evil.","我想那就是这些电影的主题——正义战胜邪恶。"],"lesson":"u06-l03","group":"“经济、收入”相关"},{"w":"produce","p":"prəˈdjuːs","m":"n.产品，(尤指)农产品","tip":"","ex":["A quarter of this year's American grain harvest will be used to produce bio-fuel for cars.","今年美国谷物收成的四分之一将用于生产汽车生物燃料。"],"lesson":"u06-l03","group":"“生产”相关"},{"w":"productivity","p":"ˌprɒdʌkˈtɪvəti","m":"n.生产率；生产力","tip":"","ex":["The unions will try to increase productivity.","工会将努力提高生产力。"],"lesson":"u06-l03","group":"“生产”相关"},{"w":"industry","p":"ˈɪndəstri","m":"n.工业，行业；勤奋，勤劳","tip":"indu（联想“印度”）+ st（联想 street）+ ry（联想“人员”）→ 印度的大街上有各个“行业”的人员，大家都很“勤劳”。","ex":["The food industry plays a major role in fighting obesity.","食品行业在对抗肥胖方面扮演着重要角色。"],"lesson":"u06-l03","group":"“生产”相关"},{"w":"manipulate","p":"məˈnɪpjuleɪt","m":"v.(熟练地)操作；操纵；影响","tip":"单词发音类似“摸你扑了它”→ 工作的时候，你一会儿摸摸这台机器，一会儿扑向那台机器，熟练地“操作”着它们。","ex":["Several studies have implied that emotional intelligence can be used to manipulate others for personal gains.","几项研究表明，情商可以用来操纵他人以谋取个人利益。"],"lesson":"u06-l03","group":"“生产”相关"},{"w":"operate","p":"ˈɒpəreɪt","m":"v.运转，工作；操作，控制；动手术","tip":"","ex":["Those who want to use computers should know how computers operate.","那些想要使用电脑的人应该知道电脑是如何运转的。"],"lesson":"u06-l03","group":"“生产”相关"},{"w":"cooperate","p":"kəʊˈɒpəreɪt","m":"v.合作，协作","tip":"co-（= con-，一起）+ operate（操作）→ 合作","ex":["They cooperated well with the police.","他们与警方合作得很好。"],"lesson":"u06-l03","group":"“生产”相关"},{"w":"collaborate","p":"kəˈlæbəreɪt","m":"v.合作，协作","tip":"col-（= con-，一起）+ labor（劳动）+ -ate（动词后缀）→ 合作","ex":["They collaborated on building the first space coffee machine.","他们合作开发了第一台太空咖啡机。"],"lesson":"u06-l03","group":"“生产”相关"},{"w":"profit","p":"ˈprɒfɪt","m":"n.利润；利益，好处 v.得利，有益于……","tip":"pro-（提前）+ fit（音似“肥他”）→ 他提前得到了一份有很多“好处”的肥差。","ex":["I'm not sure whether I can gain any profit from the investment.","我不确定我是否能从这次投资中获利。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"benefit","p":"ˈbenɪfɪt","m":"n.利益；津贴 v.使受益","tip":"单词发音类似“比你肥的”→ 他找的差事比你肥（好），“利益”颇丰。","ex":["Tips benefit the boss rather than the employees.","小费使老板受益，而不是使雇员受益。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"salary","p":"ˈsæləri","m":"n.薪水","tip":"","ex":["His salary was too low for his responsibility.","与他承担的责任相比，他的薪水太低。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"earnings","p":"ˈɜːnɪŋz","m":"n.薪水；利润","tip":"earn v.挣得；挣钱 → earnings n.","ex":["What have researchers found out about people's earnings?","研究人员对人们的收入有什么发现？"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"wage","p":"weɪdʒ","m":"n.工资 v.开展，发动","tip":"wa（联想“哇”）+ ge（联想“哥”）→ 哇！哥哥的“工资”真高。","ex":["He is always complaining about low wages.","他总是抱怨工资低。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"fee","p":"fiː","m":"n.费用；酬金","tip":"单词发音类似“费”。","ex":["A fee should be charged on used containers for recycling.","对回收的旧容器应收取费用。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"fare","p":"feə(r)","m":"n.（车或船的）费用，票（价） v.成功","tip":"far（远）+ e（字母音似“姨”）→ 阿姨住得很远，坐车去她家需要一笔不小的“费用”。","ex":["Children travel at half fare.","儿童交通费减半。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"farewell","p":"ˌfeəˈwel","m":"n.告别","tip":"far（远）+ e（字母音似“姨”）+ well（好）→ 住在远方的阿姨要启程回去了，我要跟她好好地“告别”。","ex":["You should bid farewell to guilt and regret.","你应当告别内疚和遗憾。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"welfare","p":"ˈwelfeə(r)","m":"n.福利，救济；幸福","tip":"wel（联想 well）+ far（远）+ e（字母音似“姨”）→ 他想好好地去看望远方的阿姨，但是路费只能靠“救济”。","ex":["They live on charity and social welfare.","他们靠慈善和社会福利生活。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"pension","p":"ˈpenʃn","m":"n.养老金；抚恤金","tip":"单词发音类似“陪心”→ 人老的时候，除了陪伴，能让他安心的就是“养老金”。","ex":["People may be able to enjoy generous defined-benefits from pension plans.","人们也许可以享受养老金计划带来的丰厚的固定福利。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"allowance","p":"əˈlaʊəns","m":"n.津贴，补助","tip":"allow（允许）+ ance（音似“恩赐”）→ 允许给的恩赐→津贴","ex":["They give me a really generous allowance.","他们给了我一笔非常丰厚的津贴。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"bonus","p":"ˈbəʊnəs","m":"n.奖金；意外收获","tip":"bo（形似 60）+ nus（联想 nut）→ 公司发了 60 袋坚果作为“奖金”。","ex":["She received a bonus unexpectedly.","她意外地收到了一笔奖金。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"award","p":"əˈwɔːd","m":"v.授予；给予奖励 n.奖品，奖金","tip":"a（—）+ ward（音似 word）→ 快要下课了，老师给认真听课的同学发单词卡作为“奖品”。","ex":["The three students were awarded scholarships totaling $21,000.","这三名学生获得了总计 2.1 万美元的奖学金。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"reward","p":"rɪˈwɔːd","m":"n.报酬；赏金；回报 v.奖励；奖赏","tip":"re-（回）+ ward（音似 word）→ 作为“回报”，学生给老师讲了个单词。","ex":["Big houses are advertised as a reward for hard work and diligence.","大房子被宣传为对努力工作和勤奋的奖赏。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"awkward","p":"ˈɔːkwəd","m":"adj.令人尴尬的，难对付的，笨拙的","tip":"awk（音似“拗口”）+ ward（音似 word）→ 他在很多人面前反复读错一个拗口的单词，感觉是“令人尴尬的”。","ex":["Some of them find it awkward when hugging children.","他们中的一些人觉得拥抱孩子很尴尬。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"awe","p":"ɔː","m":"n.敬畏 v.使敬畏","tip":"单词发音类似“哦”→ 当你对某件事心怀“敬畏”时，只能连连发出“哦”的声音。","ex":["Children looked up in awe and delight.","孩子们都怀着敬畏和喜悦的心情抬起头来。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"awesome","p":"ˈɔːsəm","m":"adj.令人惊叹的，使人惊惧的；很好的","tip":"awe（使敬畏）+ -some（形容词后缀，具有……倾向的）→ 令人惊叹的","ex":["The show was just awesome.","演出实在棒极了。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"retail","p":"ˈriːteɪl","m":"n. & v.零售","tip":"re-（再）+ tail（切）→ 一再地切割（单卖）→ 零售","ex":["He owned a small retail business in Michigan years ago.","几年前，他在密歇根州拥有一家小型零售公司。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"tailor","p":"ˈteɪlə(r)","m":"n.裁缝 v.专门制作；定做","tip":"tail（切）+ -or（名词后缀）→ 负责裁切的人→裁缝","ex":["Treatment is tailored to the needs of each patient.","治疗方案是针对各个病人的需要而制订的。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"detail","p":"ˈdiːteɪl","m":"n.细节，详情","tip":"de-（分开）+ tail（切）→ 分开切，切成很小的一份→细节","ex":["She can add multiple details to the design to communicate her idea.","她可以在设计中添加多个细节来传达她的想法。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"advertise","p":"ˈædvətaɪz","m":"v.（为……）做广告；宣传","tip":"ad-（向）+ ver（音似“我”）+ ti（联想“提”）+ se → 他们向我提那个产品，是在为它“做广告”。","ex":["They are advertised as a way for adults to finish their education.","它们被宣传为成年人完成教育的一种方式。"],"lesson":"u06-l04","group":"“钱”相关"},{"w":"bar","p":"bɑː(r)","m":"n.酒吧；（长方形）条，棒 v.（用铁条或木条）堵；阻挡；禁止","tip":"","ex":["They stopped the car at a bar.","他们把车停在一家酒吧前面。"],"lesson":"u06-l04","group":"bar 相关"},{"w":"barrier","p":"ˈbæriə(r)","m":"n.障碍物；阻力；分界线","tip":"bar(r)（棒）+ -ier（名词后缀）→ 用木棒做的东西→障碍物","ex":["Language barriers can be a big obstacle.","语言障碍是一个很大的阻碍。"],"lesson":"u06-l04","group":"bar 相关"},{"w":"barrel","p":"ˈbærəl","m":"n.桶；一桶（的量）","tip":"bar(r)（棒）+ -el（后缀）→ 把木棒箍起来做的东西→桶","ex":["They got through two barrels of beer.","他们喝了两桶啤酒。"],"lesson":"u06-l04","group":"bar 相关"},{"w":"bucket","p":"ˈbʌkɪt","m":"n.（有提梁的）桶；一桶（的量）；大量","tip":"单词发音类似“巴克它”→ 电影《野性的呼唤》里的犬王巴克体形很大，一顿能吃“一桶”饭。","ex":["We used two buckets of paint to paint the room.","我们用了两桶漆来粉刷房间。"],"lesson":"u06-l04","group":"bar 相关"},{"w":"bargain","p":"ˈbɑːɡən","m":"n.便宜货；交易 v.讨价还价；谈判","tip":"bar（条，棒）+ gain（获得）→ 买东西时，他跟老板“讨价还价”，用木棒换得了一个“便宜货”。","ex":["He said he wasn't prepared to bargain.","他说他不愿讨价还价。"],"lesson":"u06-l04","group":"bar 相关"},{"w":"gain","p":"ɡeɪn","m":"v.获得，受益；增加 n.增加；好处，收益","tip":"","ex":["She might not gain more experience.","她可能不会获得更多的经验。"],"lesson":"u06-l04","group":"bar 相关"},{"w":"embarrass","p":"ɪmˈbærəs","m":"v.使窘迫，使尴尬","tip":"em-（使）+ bar（棍子）+ r（字母音似“啊”）+ ass（屁股）→ 妈妈拿着棍子，到处追着他打啊打，他很尴尬→使尴尬","ex":["He didn't want to embarrass her by asking questions.","他不想通过提问题让她尴尬。"],"lesson":"u06-l04","group":"bar 相关"},{"w":"deficient","p":"dɪˈfɪʃnt","m":"adj.缺乏的，不足的；有缺点的，有缺陷的","tip":"发音“弟弟费心的”→ 弟弟做什么都不费心思，做的事总是“有缺点的”。","ex":["They failed to meet the deadline because their time was deficient.","因为缺少时间，他们没能如期完成（任务）。"],"lesson":"u06-l04","group":"fici 相关"},{"w":"artificial","p":"ˌɑːtɪˈfɪʃl","m":"adj.人工的，人造的；虚假的","tip":"art(i)（艺术）+ fici（音似“费心”）+ -al（形容词后缀）→ 艺术是人费心创造出来的→人工的，人造的","ex":["Millions of jobs will be threatened by robotics and artificial intelligence.","数百万个工作岗位将受到机器人技术和人工智能的威胁。"],"lesson":"u06-l04","group":"fici 相关"},{"w":"proficient","p":"prəˈfɪʃnt","m":"adj.熟练的，精通的","tip":"pro-（提前）+ fici（音似“费心”）+ -ent（形容词后缀）→ 你提前费心准备单词考试，达到了“熟练的”掌握程度。","ex":["For instance, many babies are perfectly proficient crawlers.","例如，许多婴儿都是非常熟练的爬行者。"],"lesson":"u06-l04","group":"fici 相关"},{"w":"efficient","p":"ɪˈfɪʃnt","m":"adj.效率高的，能干的","tip":"单词发音类似“一飞身的”→ 别人爬楼梯来上课，他一飞身就上来了→效率高的","ex":["It's not necessarily an efficient way to learn.","它并不是一种有效的学习方式。"],"lesson":"u06-l04","group":"fici 相关"},{"w":"sufficient","p":"səˈfɪʃnt","m":"adj.充足的，足够的","tip":"单词发音类似“歇费心他”→ 他做这件事歇（很）费心，因为他想做得足够好→充足的，足够的","ex":["It has ensured a sufficient food supply to millions.","它确保了数百万人的充足粮食供应。"],"lesson":"u06-l04","group":"fici 相关"},{"w":"superficial","p":"ˌsuːpəˈfɪʃl","m":"adj.肤浅的，表面的","tip":"super（上面）+ fici（音似“费心”）+ -al（形容词后缀）→ 费的心思只浮在表面上没有深入→肤浅的，表面的","ex":["The book shows only a superficial understanding of the historical context.","这本书只表现出对历史背景肤浅的理解。"],"lesson":"u06-l04","group":"fici 相关"},{"w":"shallow","p":"ˈʃæləʊ","m":"n.浅滩 adj.浅的","tip":"sha（音似“山”）+（l）low（低的）→ 山下的“浅滩”水位很低。","ex":["These fish are found in shallow waters around the coast.","这些鱼生长在海边浅水水域。"],"lesson":"u06-l04","group":"low 相关"},{"w":"shadow","p":"ˈʃædəʊ","m":"n.影子，阴影；影响","tip":"单词发音类似“歇逗”→ 孩童追逐自己“影子”的场景歇（很）逗。","ex":["A shadow fell across her face.","一片阴影掠过她的脸庞。"],"lesson":"u06-l04","group":"low 相关"},{"w":"lower","p":"ˈləʊə(r)","m":"adj.更低的；下面的 v.把……放低，降低","tip":"","ex":["The energy used by microwaves is lower than any other form of cooking.","微波炉所消耗的能量比其他任何烹饪方式都更低。"],"lesson":"u06-l04","group":"low 相关"},{"w":"swallow","p":"ˈswɒləʊ","m":"n.燕子 v.吞下，咽下","tip":"s（联想“蛇”）+ wal（联想 wall）+ low（低的）→ 在低矮的墙上有一条蛇，它想要“吞下”那只“燕子”。","ex":["Their homes will be swallowed up by the hungry sea.","他们的家园将会被饥饿的大海吞没。"],"lesson":"u06-l04","group":"low 相关"},{"w":"hollow","p":"ˈhɒləʊ","m":"n.山谷；洼地 adj.空的；空虚的","tip":"hol（联想 hole）+ low（低的）→ “山谷”的低处有一个洞，洞是“空的”。","ex":["To some of the residents, Songdo feels hollow.","对一些居民来说，松岛空荡荡的。"],"lesson":"u06-l04","group":"low 相关"},{"w":"pillow","p":"ˈpɪləʊ","m":"n.枕头 v.枕着","tip":"pil（联想 pill）+ low（低的）→ 她吃了几粒药片，就“枕着”低低的“枕头”睡下了。","ex":["She lay back against the pillows.","她半躺半坐靠在枕头上。"],"lesson":"u06-l04","group":"low 相关"},{"w":"pillar","p":"ˈpɪlə(r)","m":"n.支柱；柱子；栋梁；富有某种素质的人","tip":"单词发音类似“劈了”→ 他不小心把“柱子”给劈了。","ex":["She is a pillar of strength in a crisis.","她在危难中表现非常坚强。"],"lesson":"u06-l04","group":"low 相关"},{"w":"follow","p":"ˈfɒləʊ","m":"v.跟随；遵循；密切注意","tip":"","ex":["It proves crucial in making others follow one's course of action.","事实证明，这对于让别人遵循自己的行动方针至关重要。"],"lesson":"u06-l04","group":"low 相关"},{"w":"fellow","p":"ˈfeləʊ","m":"n.人，家伙；伙伴，同事 adj.同伴的，同事的","tip":"有一只鹅（e）一直跟随（follow）着这个家伙（fellow）。","ex":["Our fellow students have just come out of high school.","我们的同学刚从高中毕业。"],"lesson":"u06-l04","group":"low 相关"},{"w":"spy","p":"spaɪ","m":"n.间谍 v.从事间谍活动；认出；查明","tip":"","ex":["No spy agency or criminal organization could actively gather the type of data.","没有任何间谍机构或犯罪组织能够主动收集此类数据。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"aspect","p":"ˈæspekt","m":"n.方面；外貌","tip":"a（—）+ spect（看）→ 只看一眼，了解的只是事物的一个“方面”。","ex":["The most researched aspect of breakfast and breakfast-skipping has been its links to obesity.","关于吃早餐和不吃早餐的研究最多的方面是它与肥胖的关系。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"spin","p":"spɪn","m":"v.（使）快速旋转；纺纱","tip":"sp（看）+ in（里面）→ 我看见了教室里小女孩转的舞姿→（使）快速旋转","ex":["The plane was spinning out of control.","飞机失去控制，进入尾旋状态。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"suspect","p":"səˈspekt","m":"n.嫌疑分子 adj.可疑的","tip":"sus-（下面）+ pect（看）→ 往下面看→怀疑","ex":["Police suspect the eggs came from a freighter that lost part of its cargo.","警方怀疑这些鸡蛋来自一艘丢失部分货物的货船。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"suspicious","p":"səˈspɪʃəs","m":"adj.可疑的，猜疑的","tip":"","ex":["They became suspicious of his behaviour and contacted the police.","他们觉得他行为可疑，便报了警。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"inspect","p":"ɪnˈspekt","m":"v.调查；检查","tip":"in（里面）+ spect（看）→ 往里面看→调查；检查","ex":["I'll inspect the product before we put it in the container.","在我们把产品装进集装箱之前，我会先检查一下。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"check","p":"tʃek","m":"v.检查，核对；制止 n.支票，结账单","tip":"che（联想“车”）+ ck（联想品牌 CK）→ 安检人员要“检查”车上是否有 CK 品牌的商品。","ex":["She checked all the items with the man.","她和那个人核对了所有项目。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"cheque","p":"tʃek","m":"n.支票","tip":"请检查（check）好支票（cheque）。","ex":["I had just posted the letter when I remembered that hadn't enclosed the cheque.","我刚把信寄出去，就想起了信里面没有附上支票。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"examine","p":"ɪɡˈzæmɪn","m":"v.审查；（仔细地）检查；测验","tip":"exam（考试）+（m）ine（我的）→ 考试是为了“检查”我的学习情况。","ex":["Meanwhile, it pays to examine studies funded by industry or special interest groups with extra care.","与此同时，仔细检查由行业或特殊利益集团资助的研究是值得的。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"monitor","p":"ˈmɒnɪtə(r)","m":"n.显示屏；监视器；班长；监督员 v.监视，监测；跟踪调查","tip":"monit（监视，警告）+ -or（表示人或物的后缀）→ 班长；监督员；监视器→监视","ex":["She monitored the brain activity of participants sleeping in a new environment.","她监测了在新环境中睡觉的参与者的大脑活动。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"respect","p":"rɪˈspekt","m":"v.尊重；重视 n.尊敬；方面","tip":"re-（重复）+ spect（看）→ 说话时重复（一直）看别人的眼睛，是对别人的“尊重”。","ex":["The people who live there respect the land.","住在那里的人尊重那片土地。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"respective","p":"rɪˈspektɪv","m":"adj.分别的，各自的","tip":"","ex":["We should respect our respective aspects.","我们应该尊重我们各自的方面。"],"lesson":"u06-l04","group":"“看”相关(1)"},{"w":"prospect","p":"ˈprɒspekt","m":"n.前途，前景；预期，展望；设想","tip":"pro-（向前）+ spect（看）→ 向前看到的→前途","ex":["So is there any evidence that setbacks might actually improve our career prospects?","那么，有没有证据表明挫折实际上会改善我们的职业前景呢？"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"speculate","p":"ˈspekjuleɪt","m":"v.推测；投机","tip":"spec（看）+ u（字母音似 you）+ late（联想 later）→ 他看了你一会儿，随后“推测”出你过得很幸福。","ex":["The researchers speculate that craft activities promote the development of nerve pathways in the brain.","研究人员推测，手工艺活动促进了大脑神经通路的发展。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"perspective","p":"pəˈspektɪv","m":"n.看法，观点","tip":"per-（透过）+ spect（看）+ -ive（名词后缀）→ 看穿后得出“看法”。","ex":["It's nice to have people agree, but you need conflicting perspectives to dig out the truth.","人们意见一致是件好事，但你需要相互矛盾的观点来挖掘真相。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"standpoint","p":"ˈstændpɔɪnt","m":"n.立场；观点","tip":"stand（站）+ point（点）→ 立足点→立场；观点","ex":["We must approach the problem from a different standpoint.","我们必须换一种角度来处理这个问题。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"statement","p":"ˈsteɪtmənt","m":"n.声明；观点；陈述","tip":"state（声明；陈述）+ -ment（名词后缀）→ 声明；陈述","ex":["The article contained several false statements.","这篇文章包含几个错误的陈述。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"point","p":"pɔɪnt","m":"n.观点；重点；核心问题；得分，点；地点 v.指；对着，朝着","tip":"","ex":["But is there a point where it reaches capacity?","但是，是否存在一个达到容量极限的临界点呢？"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"notion","p":"ˈnəʊʃn","m":"n.观念；信念；理解","tip":"单词发音类似“闹心”→ 她女儿的这种“观念”让她很闹心。","ex":["She had only a vague notion of what might happen.","对于可能发生的事她只有一个模糊的概念。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"concept","p":"ˈkɒnsept","m":"n.观念；概念","tip":"","ex":["The concept is often presented as something to achieve, or a goal to reach.","这个概念通常被呈现为要实现的东西或要达到的目标。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"telescope","p":"ˈtelɪskəʊp","m":"n.望远镜","tip":"tele-（远）+ scope（看，观察）→ 能看到远处的工具→望远镜","ex":["Buy $50 million worth of new telescopes right now.","现在就购买价值 5,000 万美元的新望远镜。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"expect","p":"ɪkˈspekt","m":"v.期待，预料；猜想","tip":"ex-（向外）+ pect（看）→ 向外看→喜出望外→期待","ex":["When you look at today's digital activity, the facts are much more positive than you might expect.","当你审视当今的数字活动时，事实比你预料的要积极得多。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"anticipate","p":"ænˈtɪsɪpeɪt","m":"v.预料，预计（并做准备）；期望","tip":"an（联想“俺”）+ ti（联想“提”）+ ci（联想“喜之郎 cici 果冻”）+ pate（音似“陪她”）→ 俺提着 cici 果冻去陪她，“期望”她喜欢。","ex":["My financial aid did not anticipate any of these costs.","我的经济援助没有预计到这些费用。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"participate","p":"pɑːˈtɪsɪpeɪt","m":"v.参加，参与","tip":"parti（音似“怕他”）+ ci(p)（抓）+ pate（音似“陪他”）→ 我怕他被坏人抓去，于是主动陪他“参加”活动。","ex":["She had participated in the Berkeley study.","她参与了伯克利的研究。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"antique","p":"ænˈtiːk","m":"n.文物，古董 adj.古老的；古董的","tip":"单词发音类似“俺提个”→ 俺提个“古董”送给爷爷。","ex":["It stores lots of priceless antiques.","它储存着许多无价的古董。"],"lesson":"u06-l04","group":"“看”相关(2)"},{"w":"margin","p":"ˈmɑːdʒɪn","m":"n.边缘；利润；极限；白边，页边空白处","tip":"mar（联想 Mars）+ gin（音似“进”）→ 探测器要从“边缘”进入火星。","ex":["Most students write questions or short notes in the margins.","大多数学生在页边空白处写问题或简短的笔记。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"boundary","p":"ˈbaʊndri","m":"n.边界，界限；分界线","tip":"bound（音似“邦德”）+ -ary（名词后缀）→ 邦德是一个善恶分明，有“边界”感的人。","ex":["The left boundary of this plate is the west coast of North America.","这个板块的左边界是北美的西海岸。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"bound","p":"baʊnd","m":"adj.一定会；有义务（做某事）；准备前往（某地） v.跳跃；形成……的边界（或界限）","tip":"单词发音类似“蹦跶”→ 你可以在一定范围内蹦跶 → 跳跃；形成……的边界","ex":["It is bound to help us achieve greater success.","它一定会帮助我们取得更大的成功。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"bounce","p":"baʊns","m":"v.跳动；弹起；反射 n.弹跳；活力","tip":"单词发音类似“棒死”→ 他简直太棒了，一把就接住了“弹跳”球。","ex":["The ball bounced twice before he could reach it.","球弹跳了两次他才接到。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"horizon","p":"həˈraɪzn","m":"n.地平线；范围；眼界","tip":"ho（联想“好”）+ riz（联想 rise）+ on → 好大的太阳从“地平线”升起来了。","ex":["She wanted to travel to broaden her horizons.","她想旅行，以开阔眼界。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"edge","p":"edʒ","m":"n.刀口；边缘；优势","tip":"单词发音类似“挨挤”→ 景区的“边缘”人挨人，人挤人。","ex":["The brown animal was spotted stuck on a narrow window edge of the office tower.","这只棕色的动物被发现卡在办公大楼的一个狭窄的窗户边上。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"hedge","p":"hedʒ","m":"n.树篱；防范措施","tip":"he（他）+（e）dge（边缘）→ 他在房子的边缘修了一个“树篱”。","ex":["The cottage was surrounded by a hedge.","小屋被一道树篱包围着。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"frontier","p":"ˈfrʌntɪə(r)","m":"n.边境；（尤指知识的）前沿，新领域","tip":"front（前面）+ -ier（名词后缀）→ 一个国家的最前面就是“边境”。","ex":["For many scientists, public debate is a new frontier.","对许多科学家来说，公开辩论是一个新的领域。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"border","p":"ˈbɔːdə(r)","m":"n.国界；边界 v.与……接壤","tip":"b（联想“兵”）+ order（命令）→ 士兵接到了命令，去驻守国家的边境 → 国界；边界","ex":["It gave rise to a lot of problems on the border.","这在边境引发了很多问题。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"import","p":"ˈɪmpɔːt","m":"n.进口；重要性","tip":"im-（里面）+ port（港口）→ 运到港口里 → 进口","ex":["The country has to import most of its raw materials.","这个国家必须进口大多数原料。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"export","p":"ˈekspɔːt","m":"n.出口（物）；输出（物）","tip":"ex-（往外）+ port（港口）→ 运到港口外 → 出口","ex":["The country banned its exports for several months.","该国禁止了几个月的出口。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"passport","p":"ˈpɑːspɔːt","m":"n.护照；途径，手段","tip":"pass（通过）+ port（港口）→ 通过港口时需要“护照”。","ex":["They appear more formal than other passports.","它们看起来比其他护照更正式。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"visa","p":"ˈviːzə","m":"n.签证","tip":"","ex":["He was surprised to find that his visitor's visa expired.","他惊讶地发现，他的访问签证过期了。"],"lesson":"u07-l01","group":"“边缘”相关"},{"w":"specific","p":"spəˈsɪfɪk","m":"n.细节，详情 adj.具体的，详细的；特定的","tip":"speci（联想 special）+ fic（音似“非可”）→ 在这特别的日子，他非把“细节”做到完美不可。","ex":["They tried to meet astronauts' specific requirements.","他们尽力满足航天员的特定需求。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"specification","p":"ˌspesɪfɪˈkeɪʃn","m":"n.规格；说明书","tip":"","ex":["The office was furnished to a high specification.","办公室是按高规格装潢的。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"especially","p":"ɪˈspeʃəli","m":"adv.尤其；专门；非常","tip":"","ex":["Chocolates save us from many things, especially emotional distress.","巧克力可以让我们远离许多事情，尤其是情绪上的痛苦。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"particular","p":"pəˈtɪkjələ(r)","m":"adj.特别的；挑剔的；详细的；专指的 n.（正式记下的）细节，详情","tip":"","ex":["They are particular about the quality of toilet paper.","他们对卫生纸的质量特别挑剔。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"special","p":"ˈspeʃl","m":"adj.特殊的；特设的 n.特别活动；特色菜","tip":"","ex":["Museum's special exhibition area will now be free of charge.","博物馆的特殊展区将免费开放。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"specialist","p":"ˈspeʃəlɪst","m":"n.专家；专科医生 adj.专业的；专家的","tip":"special（特别的）+ -ist（表示人的后缀）→ 在某个行业特别的人 → 专家","ex":["This rat detection method doesn't rely on specialist equipment.","这种检测老鼠的方法不依赖于专业设备。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"doctor","p":"ˈdɒktə(r)","m":"n.医生；博士 v.篡改","tip":"","ex":["It assigns doctors to give advice to shoppers in food stores.","它指派医生为食品店的购物者提供建议。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"peculiar","p":"pɪˈkjuːliə(r)","m":"adj.奇怪的；特殊的；罕见的","tip":"pecu（音似“皮裤”）+ liar（说谎者）→ 那个穿皮裤的说谎者是很“奇怪的”。","ex":["There was something peculiar in the way he smiled.","他笑起来有点怪。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"unique","p":"juˈniːk","m":"adj.唯一的；独特的；罕见的","tip":"u（字母音似 you）+ ni（联想“你”）+ que（音似“可”）→ 你们每个人可都是一个“唯一的”且“独特的”存在。","ex":["Each of the healthy eating cultures has its own unique feature.","每种健康饮食文化都有其特色。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"odd","p":"ɒd","m":"adj.奇怪的；临时的；不成对的，奇数的","tip":"单词发音类似“熬的”→ 我熬的粥里加了很多配菜，有种“奇怪的”味道。","ex":["He'd always been odd, but not to this extent.","他曾一直很古怪，但没到这种程度。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"odds","p":"ɒdz","m":"n.可能性，概率；不利条件；差异","tip":"奇怪的（odd）事情不会每天发生，是有一定概率（odds）的。","ex":["The odds are very much in our favour.","我方获胜的概率极大。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"weird","p":"wɪəd","m":"adj.奇异的；不寻常的；怪诞的","tip":"单词发音类似“we 饿的”→ 如果我们三餐富足却天天说饿，那么这种行为是很“奇异的”。","ex":["He's got some weird ideas.","他有些怪念头。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"acquaint","p":"əˈkweɪnt","m":"v.使熟悉，使了解","tip":"ac-（一再地）+ quai（联想 guai“怪”）+ nt → 再奇怪的东西，只要一再地见到也见怪不怪了，因为已经熟悉了 → 使熟悉，使了解","ex":["Please acquaint me with the facts of the case.","请把这件事的实情告诉我。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"familiar","p":"fəˈmɪliə(r)","m":"adj.熟悉的；通晓","tip":"","ex":["Snow days are a familiar theme in American film and TV shows.","雪休日是美国电影和电视节目中一个熟悉的主题。"],"lesson":"u07-l01","group":"“具体、熟悉”相关"},{"w":"troublesome","p":"ˈtrʌblsəm","m":"adj.引起麻烦的，令人讨厌的","tip":"trouble（麻烦）+ -some（……的）→ 引起麻烦的，令人讨厌的","ex":["He needed surgery to cure a troublesome back injury.","他需要手术来治好烦人的背伤。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"bother","p":"ˈbɒðə(r)","m":"v.（使某人）烦恼，打扰 n.麻烦，烦扰","tip":"有花（r）的是自家兄弟（brother），没花（r）的是来打扰（bother）大家的人。","ex":["I have been bothered for a long time about the curious lack of curiosity.","很长一段时间以来，我一直感到困扰的是缺乏好奇心这一奇怪现象。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"plague","p":"pleɪɡ","m":"v.困扰，使苦恼 n.瘟疫；灾害","tip":"p（联想“扑”）+ la（联想“拉”）+ gue（音似“哥”）→ 他常常突然扑过来拉住哥哥，这让哥哥感到很“困扰”。","ex":["The team has been plagued by injury this season.","本赛季这支队伍一直为队员受伤所困扰。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"annoy","p":"əˈnɔɪ","m":"v.使苦恼；使生气；骚扰","tip":"an（一个）+ noy（音似“闹唉”）→ 如果家里有一个常哭闹的小孩，这会令人苦恼不已 → 使苦恼；使生气","ex":["The authorities were annoyed but could find nothing to charge him with.","当局很恼火，但找不到任何指控他的罪名。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"ignore","p":"ɪɡˈnɔː(r)","m":"v.忽视；不予理睬","tip":"单词发音类似“一个闹”→ 对付一个无理取闹的孩子，最好的方法就是“不予理睬”。","ex":["They attempt to ignore the whole situation.","他们试图忽视整个情况。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"neglect","p":"nɪˈɡlekt","m":"n. & v.忽略，忽视","tip":"neg-（否定前缀）+ lect（选择）→ 不去选择 → 忽略，忽视","ex":["It leads students to neglect their studies.","它导致学生忽视他们的学业。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"negative","p":"ˈneɡətɪv","m":"adj.有害的；消极的，负面的；否定的","tip":"单词发音类似“奶哥提我”→ 我小时候调皮，奶奶和哥哥一提到我都是“消极的”态度。","ex":["They have strong negative emotions towards maths.","他们对数学有着强烈的负面情绪。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"passive","p":"ˈpæsɪv","m":"adj.被动的；消极的","tip":"单词发音类似“怕媳妇”→ 他怕媳妇，常使自己处于“被动的”地位。","ex":["Textbooks are not passive or lifeless.","教科书并不是消极或毫无生气的。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"optimistic","p":"ˌɒptɪˈmɪstɪk","m":"adj.乐观（主义）的","tip":"她小时候很调皮，家人提起她的表现时是消极的（negative），后来她变得懂事乖巧，家人再提起她是很乐观的（optimistic）。","ex":["Try to be optimistic whatever happens.","无论发生什么，都要保持乐观。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"pessimistic","p":"ˌpesɪˈmɪstɪk","m":"adj.悲观的，厌世的","tip":"pessi（音似“拍死”）+ mistic（音似 mistake）→ 他一做错事就想拍死自己，这是一种“悲观的”态度。","ex":["Some pessimistic experts feel that the automobile is bound to fall into disuse.","一些悲观的专家认为汽车一定会被淘汰。"],"lesson":"u07-l01","group":"“打扰、忽视”相关"},{"w":"opt","p":"ɒpt","m":"v.选择，挑选","tip":"op-（表示方向）+ t（联想“他”）→ 她面朝他的方向走去，并表示自己“选择”了他。","ex":["The digital access codes are even harder for students to opt out of.","数字访问代码甚至让学生们更难选择退出。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"compulsory","p":"kəmˈpʌlsəri","m":"adj.强制的；义务的","tip":"com-（都）+ pul（音似“扑”）+ sory（联想 sorry）→ 所有护卫都扑过去向国王道歉，他们这种行为是被“强制的”。","ex":["The use of seat belts was compulsory for the population.","人们使用安全带是强制性的。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"course","p":"kɔːs","m":"n.课程；过程；航线；方针；进展","tip":"","ex":["Many universities offer courses in business administration.","许多大学都开设工商管理课程。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"case","p":"keɪs","m":"n.实例；诉讼；容器；情况","tip":"ca（联想“开”）+ se（音似“撕”）→ 我撕下标签，打开“容器”。","ex":["What should be done in such cases?","这种情况应该怎么办？"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"choice","p":"tʃɔɪs","m":"n.选择；入选者","tip":"choose v.选择，挑选 → choice n.","ex":["People's choice of food depends on their individual taste.","人们对食物的选择取决于他们的个人口味。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"select","p":"sɪˈlekt","m":"v.选择，选拔 adj.精选的；优等的","tip":"se-（分开）+ lect（选择）→ 选择，选拔","ex":["It helps people to select the most effective sunscreen.","它帮助人们选择最有效的防晒霜。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"lecture","p":"ˈlektʃə(r)","m":"n.演讲；讲座；教训 v.讲授；告诫；指责","tip":"lect（说）+ -ure（名词后缀）→ 演讲；讲座","ex":["The content of the lecture is a much more effective method for students to learn.","对于学生来说，讲座里讲的内容是一种更有效的学习方法。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"elect","p":"ɪˈlekt","m":"v.选举，推选；选择","tip":"e-（出去）+ lect（选择）→ 选举，推选；选择","ex":["People who elect to track their sleep may try to get more sleep.","那些选择跟踪自己睡眠的人可能会努力睡得更多。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"poll","p":"pəʊl","m":"n.民意调查；投票 v.对……进行民意测验；获得（票数）","tip":"他拉（pull）着我，让我为他投票（poll）。","ex":["The final result of the poll will be known tomorrow.","投票的最终结果将于明天公布。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"collect","p":"kəˈlekt","m":"v.收集；收藏；采集","tip":"col-（一起）+ lect（选择）→ 收集","ex":["Its conclusions are based on carefully collected data.","它的结论是基于仔细收集的数据的。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"collective","p":"kəˈlektɪv","m":"adj.集体的；共有的 n.集体企业，企业集团","tip":"collect（采集）+ -ive（形容词后缀）→ 共同采集的 → 集体的；共有的","ex":["They must be used in combination for an entire collective.","它们必须结合起来用于整个集体。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"dialect","p":"ˈdaɪəlekt","m":"n.方言；土话","tip":"dia（联想“嗲”）+ lect（说）→ 那个地方的人说话都很嗲，这就是他们的“方言”特色。","ex":["Dialects should be preserved to retain a culture.","应该保留方言来保留一种文化。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"accent","p":"ˈæksent","m":"n.口音；腔调；重音","tip":"ac-（一再地）+ cent（分）→ 他一再地把一分钱硬币含在嘴里，练习一种特殊的“口音”。","ex":["She spoke English with an accent.","她说英语带有口音。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"rhythm","p":"ˈrɪðəm","m":"n.节奏，韵律","tip":"","ex":["A basic sense of rhythm is essential in a music teacher.","基本的节奏感是音乐教师的必备素质。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"tone","p":"təʊn","m":"n.音调；语气，腔调 v.使（皮肤、肌肉等）更强健","tip":"这个女孩说话的语气（tone）像石头（stone）一样冰冷、生硬。","ex":["Don't speak to me in that tone of voice.","别用那种口吻跟我讲话。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"tune","p":"tjuːn","m":"n.曲调；曲子，歌曲","tip":"他用温和的语气（tone）哼唱出悠扬的曲子（tune）。","ex":["The piano is out of tune.","钢琴音走调了。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"orchestra","p":"ˈɔːkɪstrə","m":"n.管弦乐队","tip":"or + chest（胸膛）+（t）ra（音似“吹”）→ “管弦乐队”中的乐手吹奏时，乐声萦绕他们的胸膛。","ex":["She listened to recordings of many European orchestras.","她听了许多欧洲管弦乐队的录音。"],"lesson":"u07-l02","group":"“选择”相关"},{"w":"outdoors","p":"ˌaʊtˈdɔːz","m":"adv.在户外；在野外 n.旷野，郊外","tip":"","ex":["Taking a walk can instantly lift your mood, especially when you go outdoors.","散步可以立即提升你的情绪，尤其是当你在户外的时候。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"venture","p":"ˈventʃə(r)","m":"n.企业，商业；冒险事业 v.冒险；小心地说","tip":"ven（联想 went）+ ture（联想 true）→ 他们真的去“冒险”了。","ex":["They may adopt strategies that are bound to ruin their venture.","他们可能会采取注定会毁掉企业的策略。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"vacation","p":"veɪˈkeɪʃn","m":"n.假期 v.度假；休假","tip":"单词发音类似“我开心”→“假期”到了，我很开心。","ex":["She might not get enough vacation.","她可能没有足够的假期。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"vocation","p":"vəʊˈkeɪʃn","m":"n.工作，职业；生活方式","tip":"我们的假期（vacation）比较少，大部分时间都奉献给了工作（vocation）。","ex":["She believes that she has found her true vocation.","她相信自己找到了真正适合自己的职业。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"excursion","p":"ɪkˈskɜːʃn","m":"n.远足，短途旅行","tip":"ex-（出去）+ cursion（音似“开心”）→ 出去“远足”让我很开心。","ex":["We took an excursion around the island yesterday.","我们昨天进行了一次环岛短途旅行。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"tour","p":"tʊə(r)","m":"n.旅行，观光 v.在……旅游；在……巡回演出（或做宣传广告等）","tip":"t（联想“他”）+ our（我们的）→ 他和我们的朋友一起去“旅行”了。","ex":["He toured the Forbidden City.","他游览了故宫。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"journey","p":"ˈdʒɜːni","m":"n.（尤指长途）旅行；历程","tip":"单词发音类似“脚泥”→ 在“旅行”的路上，我们的脚都沾了泥巴。","ex":["She took her sister with her to keep her company on the journey.","她带着妹妹在旅途中作伴。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"cruise","p":"kruːz","m":"v.乘船游览；巡航 n.乘船游览","tip":"cru（联想 cross）+ -ise（后缀）→ 船只在海上跨水域航行 → 巡航","ex":["Every time I see a cruise ship, I feel sad.","每次一看见游轮，我就会觉得很难过。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"voyage","p":"ˈvɔɪɪdʒ","m":"n. & v.航行；旅行","tip":"vo（音似“我”）+ yage（联想 yoga）→ 在进行瑜伽冥想时，我的思想就像在“航行”。","ex":["The Titanic sank on its maiden voyage.","泰坦尼克号首航便沉没了。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"yoga","p":"ˈjəʊɡə","m":"n.瑜伽","tip":"单词发音类似“瑜伽”。","ex":["She wasn't so much interested in hot yoga.","她对高温瑜伽不怎么感兴趣。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"training","p":"ˈtreɪnɪŋ","m":"n.训练，培训；锻炼","tip":"","ex":["Training a patient to prepare healthy food can change their life.","训练患者准备健康的食物可以改变他们的生活。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"workout","p":"ˈwɜːkaʊt","m":"n.锻炼","tip":"","ex":["She does a 20-minute workout every morning.","她每天早晨做 20 分钟的锻炼。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"fit","p":"fɪt","m":"v.（形状和尺寸）适合，合身；使胜任 adj.健康的","tip":"","ex":["Learning by doing doesn't really fit that mold anymore.","在实践中学习已经不符合那种模式了。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"well-being","p":"ˈwel biːɪŋ","m":"n.健康；安乐","tip":"well（好的）+ being（存在，生命）→ 健康；安乐","ex":["They're concerned about their health and the well-being of the planet.","他们关心自己的健康和地球的福祉。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"gym","p":"dʒɪm","m":"n.体育馆，健身房；健身","tip":"单词发音类似“健美”→ 我去“健身房”做健美操。","ex":["The school has recently built a new gym.","学校最近新建了一个体育馆。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"muscle","p":"ˈmʌsl","m":"n.肌肉；体力；权力；威信","tip":"","ex":["Willpower is just like a muscle; to keep it strong you need to constantly exercise it.","意志力就像一块肌肉，需要不断锻炼才能保持强壮。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"calorie","p":"ˈkæləri","m":"n.卡路里；千卡（测量食物含热量的单位）","tip":"","ex":["We get a fairly large portion of calories from fast food and snacks.","我们从快餐和零食中获得相当大一部分的卡路里。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"energy","p":"ˈenədʒi","m":"n.精力，活力；能源","tip":"单词发音类似“俺奶鸡”→ 俺奶奶还能抓住鸡，说明她“活力”十足。","ex":["The last important point to consider is that practice focuses your energy on the process.","最后要考虑的一点是，练习将你的精力集中在这个过程上。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"energetic","p":"ˌenəˈdʒetɪk","m":"adj.精力充沛的，充满活力的；积极的","tip":"","ex":["The heart responds well to energetic exercise.","心脏对剧烈运动反应良好。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"battery","p":"ˈbætri","m":"n.电池","tip":"这个牌子的电池（battery）用起来更好（better）。","ex":["More funding will be invested in bike battery research.","更多的资金将投入自行车电池研究中。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"vigorous","p":"ˈvɪɡərəs","m":"adj.精力充沛的；健壮的","tip":"单词发音类似“喂个肉丝”→ 他喂小狗吃肉丝后，小狗的状态是“精力充沛的”。","ex":["Let the debates be transparent and vigorous, wherever they are held.","无论在何处举行辩论，都应使辩论清晰而有力。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"dynamic","p":"daɪˈnæmɪk","m":"adj.充满活力的，精力充沛的；动力的；动态的","tip":"dy（联想“大雁”）+ na（联想“拿”）+ mic（音似“麦克”）→ 大雁只要拿着麦克风走上讲台，就会变成“充满活力的”老师。","ex":["It is a dynamic and self-improving process.","这是一个动态的、自我完善的过程。"],"lesson":"u07-l02","group":"“户外、活动”相关"},{"w":"visit","p":"ˈvɪzɪt","m":"v.访问 n.参观；逗留；看望","tip":"vis（看）+ it（它）→ 看它 → 访问；参观","ex":["His friends feel reluctant to visit his home.","他的朋友不愿意去他家。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"visible","p":"ˈvɪzəbl","m":"adj.可见的；明显的","tip":"vis（看）+ -ible（形容词后缀）→ 可见的；明显的","ex":["They can lead to the creation of new clouds easily visible from space.","它们能形成新的云，这从太空中很容易看到。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"invisible","p":"ɪnˈvɪzəbl","m":"adj.看不见的，无形的","tip":"in-（不）+ visible（可见的）→ 看不见的，无形的","ex":["These invisible duties become apparent only when you don't do them.","只有当你不去做的时候，这些看不见的责任才会变得明显。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"revise","p":"rɪˈvaɪz","m":"v.修改；复习","tip":"re-（再）+ vise（看）→ 再看一遍 → 修改；复习","ex":["Patients' data has to be revised from time to time.","患者的数据必须不时地进行修改。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"vision","p":"ˈvɪʒn","m":"n.视力；视野；幻象；远见卓识","tip":"vis（看）+ -ion（名词后缀）→ 视力；视野；幻象","ex":["They help an organization to broaden its vision effectively.","它们帮助组织有效地拓宽视野。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"supervise","p":"ˈsuːpəvaɪz","m":"v.监督，管理","tip":"super（上面；超越）+ vise（看）→ 监督","ex":["It does not supervise its employees.","它不监督它的员工。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"visual","p":"ˈvɪʒuəl","m":"adj.视力的，视觉的 n.视觉资料","tip":"","ex":["A reader creates visual images of the characters in a novel.","读者创造小说中人物的视觉形象。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"view","p":"vjuː","m":"n.看法；风景 v.看待；观察","tip":"","ex":["There were magnificent views of the surrounding countryside.","四周乡间的景色壮观秀丽。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"devise","p":"dɪˈvaɪz","m":"v.设计，发明；想出","tip":"de-（往下）+ vise（看）→ 他一低头，眼睛一转圈，就“想出”一个主意。","ex":["Employees with a growth mindset may be more likely to devise innovative ideas.","具有成长心态的员工也许更有可能想出创新的想法。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"gaze","p":"ɡeɪz","m":"n. & v.凝视，注视","tip":"ga（联想“尬”）+ ze（音似“死”）→ 有人一直“凝视”着他，他觉得尴尬死了。","ex":["When looking at angry humans, they tended to turn away their gaze.","当看到愤怒的人类时，它们往往会转移视线。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"glance","p":"ɡlɑːns","m":"n.匆匆一看，一瞥，扫视 v.瞥一眼，扫视","tip":"单词发音类似“哥懒死”→ 哥哥懒死了，读书只是“瞥一眼”。","ex":["I only had time to glance at my emails.","我只来得及瞥一眼我的电子邮件。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"glimpse","p":"ɡlɪmps","m":"n.一瞥，一看 v.瞥见；看一眼","tip":"g（联想“哥”）+ li（联想“立”）+ m（联想“妹”）+ pse → 哥哥站立在妹妹旁边，“瞥见”了她。","ex":["He caught a glimpse of her in the crowd.","他一眼瞥见她在人群里。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"stare","p":"steə(r)","m":"v.凝视，盯着看","tip":"star（星星）+ e（联想 eye）→ 眼睛盯着星星看 → 凝视，盯着看","ex":["You just stare across the table blankly with your mouth hanging open.","你只是张着嘴，茫然地盯着桌子对面。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"scan","p":"skæn","m":"v.细看；扫描；审视 n.浏览；扫描检查","tip":"单词发音类似“死看”→ 死死地盯着一个人看 → 细看；审视","ex":["She scanned through the newspaper over breakfast.","她边吃早饭，边浏览报纸。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"scandal","p":"ˈskændl","m":"n.丑闻；流言蜚语，谣言","tip":"单词发音类似“撕堪斗”→ 两人撕破脸皮，觉得难堪，于是发生争斗，最终爆发了“丑闻”。","ex":["The press could scent a scandal.","记者觉察出有桩丑闻。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"browse","p":"braʊz","m":"v.浏览，上网浏览信息；（在商店里）随便看看","tip":"b(r)（联想 bring）+ row（排）+ se → 他把所有的数据拿来，然后开始一排一排地“浏览”。","ex":["She browsed in an up-market antiques shop.","她逛了一家高级古董店。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"sight","p":"saɪt","m":"n.视力；看见；视野；景象 v.看见；发现","tip":"","ex":["The disease has affected her sight.","这种病影响了她的视力。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"sightseeing","p":"ˈsaɪtsiːɪŋ","m":"n.观光，游览","tip":"","ex":["Did you have a chance to do any sightseeing?","你有没有出去游览的机会？"],"lesson":"u07-l02","group":"vi 相关"},{"w":"insight","p":"ˈɪnsaɪt","m":"n.洞察力，领悟，洞悉；了解","tip":"in-（向内，进入）+ sight（看见）→ 洞察力","ex":["He has insight, vision and a deep humanity.","他有洞察力、远见和深厚的人文关怀。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"oversight","p":"ˈəʊvəsaɪt","m":"n.疏忽，忽略；失察，负责","tip":"over-（超过，覆盖）+ sight（视野）→ 忽略","ex":["The cause of the fire was a minor oversight of the staff.","火灾的原因是工作人员的轻微疏忽。"],"lesson":"u07-l02","group":"vi 相关"},{"w":"device","p":"dɪˈvaɪs","m":"n.设备；手段","tip":"de（音似“弟”）+ vi（形似罗马数字 6）+ ce（联想“车”）→ 弟弟用六辆车拉“设备”。","ex":["The survey allowed for reading materials on a digital device.","调查允许在数字设备上阅读材料。"],"lesson":"u07-l03","group":"device 相关"},{"w":"equipment","p":"ɪˈkwɪpmənt","m":"n.用具，设备；装备过程","tip":"equip（音似“一块布”）+ -ment（名词后缀）→ 仆人总是拿着一块布当作清洁“用具”。","ex":["This requires purchasing desks, chairs and office equipment.","这需要购买桌椅和办公设备。"],"lesson":"u07-l03","group":"device 相关"},{"w":"apparatus","p":"ˌæpəˈreɪtəs","m":"n.仪器，器械","tip":"appar（联想 appear）+ a（—）+ tus（联想“吐丝”）→ 科技时代，出现了一种会吐丝的“仪器”。","ex":["Firefighters needed breathing apparatus to enter the burning house.","消防队员需要呼吸器械以便进入燃烧的大楼。"],"lesson":"u07-l03","group":"device 相关"},{"w":"fix","p":"fɪks","m":"v.修理，校正；使固定；找到，确定，说出 n.解决方法；困境；定位；理解","tip":"","ex":["They lack talent to fix their deepening problems.","他们缺乏解决日益严重的问题的才能。"],"lesson":"u07-l03","group":"device 相关"},{"w":"air conditioning","p":"ˈeə kəndɪʃənɪŋ","m":"n.空气调节系统","tip":"汽车的 A/C 按钮就是空调的开关键 → 空气调节系统","ex":["The air conditioning can adjust automatically.","空调可以自动调节。"],"lesson":"u07-l03","group":"device 相关"},{"w":"furnish","p":"ˈfɜːnɪʃ","m":"v.布置家具；供应，提供","tip":"有些人喜欢用毛皮（fur）布置家具（furnish）。","ex":["The room was furnished with antiques.","房间里摆放了古董。"],"lesson":"u07-l03","group":"device 相关"},{"w":"decorate","p":"ˈdekəreɪt","m":"v.装饰，装修","tip":"de（联想“弟”）+ cor（联想 core）+ ate → 弟弟想买一套核心地段的房子，然后亲自“装修”。","ex":["It has walls decorated with jewels.","它的墙上装饰着珠宝。"],"lesson":"u07-l03","group":"device 相关"},{"w":"ornament","p":"ˈɔːnəmənt","m":"n.装饰，点缀；饰物","tip":"ornam（音似“哦那美”）+ ent → 哦，那栋房子的“装饰”真美。","ex":["The British public loved his cheap gold earrings and his tasteless silver ornaments.","英国公众喜欢他廉价的金耳环和毫无品位的银饰。"],"lesson":"u07-l03","group":"device 相关"},{"w":"conclude","p":"kənˈkluːd","m":"v.断定；得出结论；结束","tip":"con-（所有的）+ clude（= close）→ 得出结论；结束","ex":["Most animals conclude that a situation is hopeless and beyond their control.","大多数动物得出结论，情况是无望的，无法控制的。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"summary","p":"ˈsʌməri","m":"n.总结 adj.总结性的","tip":"to sum up 总而言之，概括地说 → summary n.","ex":["I made a summary report for the records.","我对记录的内容做了总结报告。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"sum","p":"sʌm","m":"n.金额；算术；总数","tip":"单词发音类似“仨木”→ 这个房间总共有三道木门 → 总数","ex":["He gives his staff a considerable sum for tips.","他给他的员工一笔丰厚的小费。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"include","p":"ɪnˈkluːd","m":"v.包括；使成为……的一部分","tip":"","ex":["GNP includes loss in value of factories and equipment.","国民生产总值包括工厂和设备的价值损失。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"exclude","p":"ɪkˈskluːd","m":"v.不包括；防止……进入；排除","tip":"ex-（向外）+ clude（= close）→ 把……关闭在外 → 不包括；排除","ex":["Buses run every hour, Sundays excluded.","公共汽车每小时一班，星期天除外。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"eliminate","p":"ɪˈlɪmɪneɪt","m":"v.排除；（比赛中）淘汰","tip":"e-（出去）+ limi（联想 limit）+ n（联想“你”）+ -ate（动词后缀）→ 把针对你的限制剔除出去 → 排除","ex":["At first, you just eliminate the obvious distractions and explore the rest.","一开始，你只需要排除那些明显的干扰，然后探索剩下的内容。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"except","p":"ɪkˈsept","m":"v.不包括；把……除外 prep.（用于所言不包括的人或事物前）除……之外 conj.除了；只是","tip":"","ex":["We were assured that, except for low grades or a raise in family income, no money would be taken away.","我们得到保证，除了成绩不佳或家庭收入增加外，任何钱都不会被拿走。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"exception","p":"ɪkˈsepʃn","m":"n.一般情况以外的人（或事物）；例外","tip":"","ex":["Universities today are in the business of education, and mine is no exception.","现在的大学都以教育为业，我的大学也不例外。"],"lesson":"u07-l03","group":"clude 相关"},{"w":"herd","p":"hɜːd","m":"n.兽群，牧群 v.放牧；驱赶（兽群）","tip":"her（她的）+ d（联想“的”）→ 那群羊是她的，她是个“放牧”的小女孩。","ex":["They want to get back to their herds.","他们想回到自己的牧群。"],"lesson":"u07-l03","group":"car 相关"},{"w":"pigeon","p":"ˈpɪdʒɪn","m":"n.鸽子","tip":"母婴用品品牌“贝亲”就是 pigeon（鸽子）的音译，表达了对婴儿茁壮成长、社会和平的期许。","ex":["Pigeons are often seen as a symbol of peace.","鸽子常被认为是和平的象征。"],"lesson":"u07-l03","group":"car 相关"},{"w":"vivid","p":"ˈvɪvɪd","m":"adj.生动的，逼真的；鲜艳的","tip":"单词发音类似“娓娓的”→ 娓娓动听的 → 生动的","ex":["A vivid example of such replay can be seen in a video.","这种回放的生动例子可以在一段视频中看到。"],"lesson":"u07-l03","group":"car 相关"},{"w":"survive","p":"səˈvaɪv","m":"v.生存；幸免于难，幸存；艰难度过","tip":"sur-（上面）+ viv(e)（= live）→ 从死亡线上面活了下来 → 幸存","ex":["Remember, failure is inevitable, and every failure you survive is a learning experience.","记住，失败是不可避免的，你艰难度过的每一次失败都是一次学习的经历。"],"lesson":"u07-l03","group":"car 相关"},{"w":"appetite","p":"ˈæpɪtaɪt","m":"n.胃口；喜爱","tip":"ap-（一再）+ pet（宠物）+ ite → 他一再地提到家里的宠物，说明很“喜爱”它。","ex":["Don't spoil your appetite by eating between meals.","不要在两餐之间吃东西，以免影响胃口。"],"lesson":"u07-l03","group":"car 相关"},{"w":"carpet","p":"ˈkɑːpɪt","m":"n.地毯，毛毯","tip":"car（汽车）+ pet（宠物）→ 汽车上载有宠物时，最好铺块“地毯”。","ex":["To find out, we introduced bacteria to squares of tile, carpet or wood.","为了找到答案，我们将细菌引入了瓷砖、地毯或木材中。"],"lesson":"u07-l03","group":"car 相关"},{"w":"pad","p":"pæd","m":"n.垫；便笺本 v.轻轻地走","tip":"iPad 苹果平板电脑 → pad n.","ex":["She always kept a pad by the phone.","她总是在电话旁放一个便笺本。"],"lesson":"u07-l03","group":"car 相关"},{"w":"blanket","p":"ˈblæŋkɪt","m":"n.毛毯，毯子，羊毛毯","tip":"他身上披了条毯子（blanket），脸色煞白（blanch）。","ex":["The atmosphere again acts as our protective blanket on earth.","大气再次充当着我们在地球上的保护毯。"],"lesson":"u07-l03","group":"car 相关"},{"w":"blank","p":"blæŋk","m":"adj.空白的；空着的；没有表情的 n.空白处，空格","tip":"单词发音类似“不来客”→ 我开了一家面馆，晚上不来客人，总是“空着的”。","ex":["At that moment his brain went blank.","那一刻，他的脑子一片空白。"],"lesson":"u07-l03","group":"car 相关"},{"w":"vacant","p":"ˈveɪkənt","m":"adj.空缺的，未被占用的；茫然的","tip":"单词发音类似“未垦的”→ 一片未被开垦的土地 → 未被占用的","ex":["The seat next to him was vacant.","他旁边的座位空着。"],"lesson":"u07-l03","group":"car 相关"},{"w":"vacuum","p":"ˈvækjuːm","m":"n.真空 v.用真空吸尘器清扫","tip":"vacu（联想 vacant）+ u + m（联想“妹”）→ 妹妹内心是空缺的，仿佛“真空”状态。","ex":["Exclusion of air creates a vacuum in the bottle.","瓶子里的空气排除后就产生真空。"],"lesson":"u07-l03","group":"car 相关"},{"w":"career","p":"kəˈrɪə(r)","m":"n.职业；事业","tip":"car（汽车）+ (e)er（表示人的后缀）→ 这个开汽车的人的“职业”是司机。","ex":["In the process, she built a radically new life and career.","在这个过程中，她建立了一番全新的生活和事业。"],"lesson":"u07-l03","group":"car 相关"},{"w":"cargo","p":"ˈkɑːɡəʊ","m":"n.（船或飞机装载的）货物","tip":"car（车）+ go（去）→ 车装满了“货物”才出发。","ex":["It had one of its cargo planes land at a wrong airport.","它使一架货机降落在了一个错误的机场。"],"lesson":"u07-l03","group":"car 相关"},{"w":"scar","p":"skɑː(r)","m":"n.伤疤；创伤 v.使结疤；使……破损","tip":"s（联想“死”）+ car（汽车）→ 他从车祸中死里逃生，身上留下了“伤疤”。","ex":["So many of our own past scars and dashed hopes can surface.","我们自己过去的许多伤疤和破灭的希望都会浮现出来。"],"lesson":"u07-l03","group":"car 相关"},{"w":"carrot","p":"ˈkærət","m":"n.胡萝卜","tip":"car（汽车）+ rot（腐烂）→ 汽车上装了腐烂的“胡萝卜”。","ex":["Chop the carrots up into small pieces.","把胡萝卜切成小块。"],"lesson":"u07-l03","group":"car 相关"},{"w":"root","p":"ruːt","m":"n.根；根源，基础 v.（使）生根，使固定","tip":"这盆植物的根（root）腐烂（rot）了。","ex":["Doctors used carrot seeds and roots as medicine.","医生用胡萝卜的种子和根作药。"],"lesson":"u07-l03","group":"car 相关"},{"w":"carpenter","p":"ˈkɑːpəntə(r)","m":"n.木工，木匠","tip":"car（汽车）+ pen（联想“棚”）+ t（联想“他”）+ -er（表示人的后缀）→ 他会修理汽车和车棚，是个全能的“木匠”。","ex":["They were skilled carpenters themselves.","他们自己就是技术熟练的木匠。"],"lesson":"u07-l03","group":"car 相关"},{"w":"cartoon","p":"kɑːˈtuːn","m":"n.（报刊中与政治或时事有关的）漫画，讽刺画；动画片","tip":"单词发音类似“卡通”。","ex":["As a child I used to love the Scooby-Doo cartoons.","当我还是个孩子的时候，我很喜欢《史酷比》动画片。"],"lesson":"u07-l03","group":"car 相关"},{"w":"paint","p":"peɪnt","m":"n.油漆；颜料 v.在……上刷油漆；用颜料画；描绘","tip":"单词发音类似“喷它”→ 他用“颜料”喷绘墙体。","ex":["Life Reimagined paints a picture of middle age that is far from gloomy.","《重新想象的生活》描绘了一幅远非悲观的中年图景。"],"lesson":"u07-l03","group":"car 相关"},{"w":"photography","p":"fəˈtɒɡrəfi","m":"n.照相术，摄影","tip":"","ex":["Its picture won a photography prize.","它的照片获得了摄影奖。"],"lesson":"u07-l03","group":"car 相关"},{"w":"chart","p":"tʃɑːt","m":"n.图，图表；海图","tip":"单词发音类似“插它”→ 我在幻灯片上插入了一张“图表”。","ex":["The accompanying chart shows data for eight countries.","附图显示了八个国家的数据。"],"lesson":"u07-l03","group":"car 相关"},{"w":"carrier","p":"ˈkæriə(r)","m":"n.（尤指经营空运的）运输公司；运输工具；携带者","tip":"carry v.携带 → carrier n.","ex":["It can be seen from the cheapest budget airlines to the world's largest carriers.","从最便宜的廉价航空公司到世界上最大的航空公司，都可以看到这一点。"],"lesson":"u07-l03","group":"car 相关"},{"w":"carriage","p":"ˈkærɪdʒ","m":"n.（火车的）客车厢；四轮大马车；婴儿车；运输","tip":"carri（联想 carry）+ age（时代）→ 在以前那个时代，运输东西要用“四轮马车”。","ex":["There are mothers pushing baby carriages, and old women with walkers.","有推着婴儿车的母亲，还有推着助行器的老妇人。"],"lesson":"u07-l03","group":"car 相关"},{"w":"cart","p":"kɑːt","m":"n.（两轮或四轮）运货马车；手推车","tip":"单词发音类似“卡他”→ 他推着“手推车”上扶梯时被卡住了。","ex":["People are cheering and holding their carts in the air.","人们欢呼着，把手推车举到空中。"],"lesson":"u07-l03","group":"car 相关"},{"w":"automate","p":"ˈɔːtəmeɪt","m":"v.使自动化","tip":"auto（自动的）+ -(m)ate（使……成为）→ 使自动化","ex":["Automated grading systems are now widespread.","自动评分系统现在很普遍。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"automatic","p":"ˌɔːtəˈmætɪk","m":"adj.自动的；无意识的；必然的 n.自动手枪（或步枪）；自动变速汽车；自动换挡汽车","tip":"","ex":["Most drivers have test driven cars with automatic braking features.","大多数驾驶员都试驾过带有自动制动功能的汽车。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"engine","p":"ˈendʒɪn","m":"n.发动机，引擎；机车；火车头","tip":"单词发音类似“引擎”。","ex":["It's clear that petrol-driven engines have no future.","很明显，汽油发动机没有未来。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"vehicle","p":"ˈviːəkl","m":"n.交通工具","tip":"单词发音类似“维柯”→“依维柯”汽车是一款“交通工具”。","ex":["There's no question that self-driving vehicles could be an enormous benefit.","毫无疑问，自动驾驶汽车会带来巨大的好处。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"motor","p":"ˈməʊtə(r)","m":"n.发动机；汽车 adj.有引擎的；由发动机推动的","tip":"","ex":["It marked a new era in motor travel.","它标志着汽车旅行的新时代。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"motel","p":"məʊˈtel","m":"n.汽车旅馆（附有停车设施）","tip":"mo（= motor）+ tel（= hotel）→ 汽车旅馆","ex":["Just search the name of the motel.","只需搜索这家汽车旅店的名字即可。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"petrol","p":"ˈpetrəl","m":"n.汽油","tip":"单词发音类似“排出”→“汽油”车会排出尾气。","ex":["The petrol is running out.","汽油快要耗尽了。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"coach","p":"kəʊtʃ","m":"n.长途客车；四轮大马车；（体育运动的）教练；（客机的）经济舱 v.训练，培训；指导","tip":"轻奢品牌 Coach（蔻驰）的标志上就有驾“四轮大马车”。","ex":["The teacher's role is more of a coach or observer.","教师的角色更多的是一个教练或观察者。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"horn","p":"hɔːn","m":"n.（汽车等的）喇叭；（羊、牛等动物的）角；（乐器）号","tip":"单词发音类似“号”。","ex":["Horn is prohibited in the park.","公园内禁止使用喇叭。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"fleet","p":"fliːt","m":"n.舰队；（同一机构或统一调度的）机群，车队","tip":"flee（音似“飞离”）+ t（联想“他”）→ 他带领“舰队”飞速逃离。","ex":["He owns a fleet of aircraft.","他拥有一支机队。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"flee","p":"fliː","m":"v.迅速离开；逃跑","tip":"单词发音类似“飞离”→ 他飞速离开 → 迅速离开","ex":["He was caught trying to flee the country.","他试图逃离该国时被抓住了。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"breakdown","p":"ˈbreɪkdaʊn","m":"n.（车辆或机器的）故障；（关系的）破裂；（讨论、系统的）失败","tip":"","ex":["There has obviously been a breakdown in communications between the two sides.","双方的交流明显中断了。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"crack","p":"kræk","m":"v.破裂；重击；找到解决（难题等的）方法 n.裂缝","tip":"cr（联想 cry）+ a（—）+ ck（联想“CK 品牌”）→ 他哭着望向那一块“破裂”的 CK 手表。","ex":["It may shed light on people's desire to crack a secret.","这或许能揭示人们想要破解秘密的欲望。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"tunnel","p":"ˈtʌnl","m":"n.地道，隧道；（动物的）洞穴通道","tip":"单词发音类似“探呢”→ 他在准备探索一条神秘的“隧道”呢。","ex":["They've built a new tunnel through the mountain.","他们修建了一条新的穿山隧道。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"channel","p":"ˈtʃænl","m":"n.海峡；航道；频道；电视台","tip":"","ex":["The channel needs to interview the boy.","电视台需要采访那个男孩。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"steer","p":"stɪə(r)","m":"v.驾驶（船、汽车等）；操纵；引导","tip":"他在街（street）上驾驶（steer）汽车的时候，目不转睛地看着前方。","ex":["Steering through change and facing obstacles brings us face to face with our fears.","驾驭变化和面对障碍会让我们直面恐惧。"],"lesson":"u07-l03","group":"“汽车”相关"},{"w":"applaud","p":"əˈplɔːd","m":"v.鼓掌；称赞","tip":"ap-（一再地）+ p（联想“扑”）+ lau（音似“老”）+ d（联想“的”）→ 他为了救人，一再地扑向老虎，大家都为他的英勇而“鼓掌”。","ex":["She was applauded as she came on stage.","她上台时人们向她鼓掌。"],"lesson":"u07-l04","group":"s 相关"},{"w":"clap","p":"klæp","m":"v.鼓掌；轻拍 n.拍手","tip":"单词发音类似“客来铺”→ 当有客人来到店铺时，店里的员工“鼓掌”表示欢迎。","ex":["The band played a familiar tune which had everyone clapping along.","乐队演奏了一首熟悉的曲子，每个人都跟着拍手。"],"lesson":"u07-l04","group":"s 相关"},{"w":"slap","p":"slæp","m":"v.（用手掌）打，拍，掴；啪的一声放下","tip":"s（联想“美女”）+ la（联想“拉”）+ p（联想“拍”）→ 美女把他拉过来，“拍”了他一下。","ex":["He slapped the newspaper down on the desk.","他啪的一声把报纸摔在桌上。"],"lesson":"u07-l04","group":"s 相关"},{"w":"slip","p":"slɪp","m":"v.滑倒；下降；溜 n.差错","tip":"s（联想“美女”）+ li（联想“立”）+ p（联想“扑”）→ 美女立刻扑向我，接着“滑倒”了。","ex":["If you have memory slips, you probably needn't worry.","如果你一时出现记忆偏差，或许不必担心。"],"lesson":"u07-l04","group":"s 相关"},{"w":"slope","p":"sləʊp","m":"n.斜坡 v.倾斜","tip":"slo（音似 slow）+ pe（音似“坡”）→ 这是个“斜坡”，所以要慢慢爬。","ex":["They nest on the volcano's slopes.","它们在火山的山坡上筑巢。"],"lesson":"u07-l04","group":"s 相关"},{"w":"slogan","p":"ˈsləʊɡən","m":"n.口号；标语","tip":"slo（音似 slow）+ gan（联想“干”）→ 我们的“口号”是慢慢干，慢工出细活。","ex":["The ceremony was disrupted by slogan-chanting.","典礼因口号声而中断。"],"lesson":"u07-l04","group":"s 相关"},{"w":"steep","p":"stiːp","m":"adj.陡峭的，险峻的；过高的；急剧的","tip":"stee（音似“死提”）+ p（联想“爬”）→ 爬这座“陡峭的”山峰时，他快吓死了，一直提心吊胆的。","ex":["The steep banks of the river are largely tree-covered.","陡峭的河岸大部分被树林覆盖。"],"lesson":"u07-l04","group":"s 相关"},{"w":"stain","p":"steɪn","m":"n.污点，污渍 v.（被）玷污；给……染色","tip":"这污渍（stain）怎么也洗不掉，就沾在（stay）衣服上。","ex":["Résumés arrive with stains.","简历上有污点。"],"lesson":"u07-l04","group":"s 相关"},{"w":"steady","p":"ˈstedi","m":"adj.平稳的；牢固的；冷静的 v.使平稳，稳住","tip":"他站（stand）在那里，就像牢固的（steady）建筑物。","ex":["They provide a steady supply of freshwater.","它们提供稳定的淡水补给。"],"lesson":"u07-l04","group":"s 相关"},{"w":"stable","p":"ˈsteɪbl","m":"adj.稳定的；牢固的；稳重的 n.养马场；马房","tip":"s（音似“似”）+ table（桌子）→ 像桌子一样稳定 → 稳定的","ex":["Keep your blood sugar stable throughout the day.","保持你的血糖全天都很稳定。"],"lesson":"u07-l04","group":"s 相关"},{"w":"establish","p":"ɪˈstæblɪʃ","m":"v.建立，设立；确定","tip":"","ex":["Let's establish some ground rules.","我们来制订一些基本原则吧。"],"lesson":"u07-l04","group":"s 相关"},{"w":"slide","p":"slaɪd","m":"n.滑梯；滑倒；跌落 v.滑行；下跌","tip":"s（联想“蛇”）+ lide（音似“来的”）→ 这条蛇是一路“滑行”来的。","ex":["Some people have said aging is more a slide into forgetfulness than a journey towards wisdom.","有人说，衰老与其说是通往智慧的旅程，不如说是滑向遗忘的过程。"],"lesson":"u07-l04","group":"s 相关"},{"w":"swing","p":"swɪŋ","m":"n.摆动；转动；秋千 v.（使）摆动，摇荡","tip":"s（联想“蛇”）+ wing（翅膀）→ 蛇左右“摆动”，就像要长出翅膀一样。","ex":["He sat on the stool, swinging his legs.","他坐在凳子上晃动着两条腿。"],"lesson":"u07-l04","group":"s 相关"},{"w":"wing","p":"wɪŋ","m":"n.翼，翅膀","tip":"单词发音类似“嗡”→ 苍蝇扇动“翅膀”时发出“嗡嗡”声。","ex":["This bird's large wings enable it to fly very fast.","这只鸟的大翅膀使它能飞得非常快。"],"lesson":"u07-l04","group":"s 相关"},{"w":"sway","p":"sweɪ","m":"n.摇摆，摆动 v.（使）摇摆，摇动","tip":"s（联想“蛇”）+ way（路）→ 蛇在路上左右“摆动”前进。","ex":["Billy swayed and fell.","比利摇晃着倒下了。"],"lesson":"u07-l04","group":"s 相关"},{"w":"sweep","p":"swiːp","m":"v.打扫；清除 n.清扫；巡行；席卷","tip":"s（联想“美女”）+ weep（哭）→ 美女哭了，因为她不想“打扫”卫生。","ex":["I don't have to sweep and mop every day.","我不用每天扫地拖地。"],"lesson":"u07-l04","group":"s 相关"},{"w":"erase","p":"ɪˈreɪz","m":"v.擦掉，抹掉（笔迹等）；清除，消除","tip":"eraser n.橡皮擦 → erase v.","ex":["It erases the belief that growing old means growing useless.","衰老即无用的信念得以消除。"],"lesson":"u07-l04","group":"s 相关"},{"w":"scare","p":"skeə(r)","m":"v.惊吓；（使）害怕 n.惊恐，恐慌","tip":"s（联想“蛇”）+ care（照顾）→ 他说让蛇来照顾我，我很“害怕”。","ex":["You scared me.","你吓了我一跳。"],"lesson":"u07-l04","group":"s 相关"},{"w":"spill","p":"spɪl","m":"v.（使）洒出，溢出 n.洒出（量）；泄漏（量）","tip":"s（联想“美女”）+ p（联想“趴”）+ ill（生病）→ 美女生病趴在床上，不小心“洒出”了药汤。","ex":["I accidentally spilled my drink all over him.","我不小心把饮料洒了他一身。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"spread","p":"spred","m":"v.展开；散布 n.传播；广泛","tip":"s（联想“蛇”）+ p（联想“趴”）+ read（读）→ 假如连蛇都趴在地上读我的书，就证明书得到了广泛“传播”。","ex":["I hurried off to spread the good news.","我赶紧去传播这个好消息。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"spit","p":"spɪt","m":"v.吐（唾沫、食物等）；怒斥 n.唾液","tip":"s（联想“美女”）+ pit（音似“呸他”）→ 美女呸他 → 吐（唾沫）","ex":["She took a mouthful of food and then suddenly spat it out.","她吃了一口食物，突然又吐了出来。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"spite","p":"spaɪt","m":"n.恶意；怨恨 v.故意使烦恼","tip":"这个人怨恨（spite）他，看到他就吐唾沫（spit）。","ex":["I'm sure he only said it out of spite.","我相信他只是为了泄愤才那么说的。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"despite","p":"dɪˈspaɪt","m":"prep.尽管，即使","tip":"de（音似“弟”）+ spite（怨恨）→ “即使”你不喜欢弟弟，也不要怨恨他。","ex":["Despite applying for hundreds of jobs, he is still out of work.","尽管他申请了数百份工作，但仍然在失业中。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"pray","p":"preɪ","m":"v.祈祷；恳求","tip":"p（联想“趴”）+ ray（光线）→ 他趴在地上，向着光线投来的方向“祈祷”。","ex":["Let's pray for peace.","让我们一起祈祷和平。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"spray","p":"spreɪ","m":"v.喷，喷洒 n.浪花，水花","tip":"s（联想“美女”）+ pray（祈祷）→ 美女在许愿池边祈祷，池中泛起“水花”。","ex":["The crops are regularly sprayed with pesticide.","庄稼定期喷洒杀虫剂。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"split","p":"splɪt","m":"v.（使）分裂；产生分歧；分开","tip":"s（联想“蛇”）+ p（联想“扑”）+ l（形似 1）+ it（它）→ 蛇扑过去，把它的猎物一分为二 → 分开","ex":["The public overall is split on whether they'd like to use a driverless car.","在是否愿意使用无人驾驶汽车的问题上，公众总体上存在分歧。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"stem","p":"stem","m":"n.（植物的）茎，干 v.起源于，来自","tip":"s（联想“蛇”）+ tem（联想“他妹”）→ 一条树藤像蛇一样缠在他妹妹的身上 → 茎，干","ex":["There are several leaves on each stem.","每一根茎上都有几片叶子。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"swell","p":"swel","m":"n.涌浪；隆起处；增加；重要人士 v.膨胀；隆起；增强","tip":"s（联想“蛇”）+ well（井）→ 蛇掉到井里，被泡肿了 → 膨胀","ex":["When IT is operating as it should, employees' self-confidence swells.","当信息技术正常运转时，员工的自信心就会增强。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"sword","p":"sɔːd","m":"n.剑，刀","tip":"s（联想“美女”）+ word（话）→ 这个美女说的话像“剑”一样犀利。","ex":["In fact, the sword hasn't had a military function for many years.","事实上，这把剑已经多年没有军事用途了。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"arrow","p":"ˈærəʊ","m":"n.箭；箭头","tip":"单词发音类似“哎哟”→ 哎哟，他的腿被“箭”射中了。","ex":["An officer then shot an arrow to put it to sleep.","一名警官随后射了一箭使它沉睡。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"sample","p":"ˈsɑːmpl","m":"n.样品；试样 v.抽样调查","tip":"s（联想“蛇”）+ ample（充足的）→ 他选取了足量的蛇作为“样品”。","ex":["Women in our sample tend to over-perceive their weight.","我们样本中的女性往往过度关注自己的体重。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"specimen","p":"ˈspesɪmən","m":"n.样品；标本","tip":"speci（联想 special）+ men（人）→ 特别的人可以被选取为研究对象 → 样品","ex":["It is displaying more fossil specimens.","它展示了更多的化石标本。"],"lesson":"u07-l04","group":"“喷、洒”相关"},{"w":"insure","p":"ɪnˈʃʊə(r)","m":"v.投保；确保","tip":"in（里面）+ sure（确定的）→ 他心里确定要“投保”。","ex":["The use of wood was minimised to insure fire safety.","为了确保消防安全，尽量减少使用木材。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"assure","p":"əˈʃʊə(r)","m":"v.保证；使确信","tip":"as-（表加强）+ sure（确定的）→ 保证；使确信","ex":["I can assure you that the animals are well cared for.","我可以向你保证这些动物都被照看得很好。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"ensure","p":"ɪnˈʃʊə(r)","m":"v.保证，确保","tip":"en-（使）+ sure（确定的）→ 保证，确保","ex":["The United States Postal Service has a system to ensure its employees' safety.","美国邮政署有一个系统来确保其员工的安全。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"guarantee","p":"ˌɡærənˈtiː","m":"v.保证，担保 n.保证；保证书","tip":"guar（联想 guard）+ ant（蚂蚁）+ ee（形似两只眼睛）→ 蚂蚁哨兵瞪着两只小眼睛，“保证”会完成任务。","ex":["We guarantee to deliver your goods within a week.","我们保证一周内交货。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"promise","p":"ˈprɒmɪs","m":"v.许诺；保证；答应 n.承诺；迹象；吉兆","tip":"","ex":["She wanted to honour her father's promise.","她想兑现父亲的承诺。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"compromise","p":"ˈkɒmprəmaɪz","m":"n. & v.妥协，折中","tip":"com-（所有）+ promise（承诺）→ 他“妥协”了，承诺把所有东西都给我。","ex":["There are a couple of ways to compromise on the issue.","在这个问题上有几种折中的方法。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"pledge","p":"pledʒ","m":"n.保证；诺言 v.正式承诺；（使）发誓","tip":"单词发音类似“扑来鸡”→ 一只鸡突然朝他扑来，他“发誓”一定要抓住它。","ex":["It has pledged to take the lead in reducing carbon emissions.","它承诺率先减少碳排放。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"allege","p":"əˈledʒ","m":"v.（未提出证据的）断言；声称；指控","tip":"al-（一再地）+ lege（音似“乐极”）→ 他今天一再地表示快乐极了，我“断言”他遇到了好事。","ex":["The prosecution alleges that she was driving carelessly.","控方指控她粗心驾驶。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"swear","p":"sweə(r)","m":"v.发誓；诅咒","tip":"s（联想“美女”）+ wear（穿）→ 美女穿着正式，是要去宣誓 → 发誓","ex":["I swear I had nothing to do with it.","我发誓，这跟我一点关系也没有。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"sweat","p":"swet","m":"n.汗 v.出汗；辛苦工作；担心，焦虑","tip":"所有甜蜜的（sweet）东西都是用汗水（sweat）换来的。","ex":["His skin was agleam with sweat.","他的皮肤因出汗而发光。"],"lesson":"u07-l04","group":"“保证”相关"},{"w":"deliver","p":"dɪˈlɪvə(r)","m":"v.传送；发送；发表；移交；运载","tip":"de（音似“弟”）+ liver（肝脏）→ 弟弟的肝脏适配成功，正在“传送”中。","ex":["They worry assistants will one day be used to deliver advertising directly to us.","他们担心，有一天（智能）助手会被用来直接向我们发送广告。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"cell","p":"sel","m":"n.细胞；牢房；小房间；手机","tip":"手机（cellphone）的应用程序就像一个个的小房间（cell）。","ex":["Changes in brain cells can affect communication between different regions of the brain.","脑细胞的变化会影响大脑不同区域之间的交流。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"organ","p":"ˈɔːɡən","m":"n.（人体或动植物的）器官；（官方的）机构；风琴","tip":"单词发音类似“哦肝”→ 哦，肝是人体的“器官”。","ex":["The heart is an organ.","心脏是一个器官。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"organism","p":"ˈɔːɡənɪzəm","m":"n.有机体；生物","tip":"","ex":["It seems simple enough to distinguish between the organism and the surrounding environment.","区分生物和周围的环境似乎很简单。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"organise","p":"ˈɔːɡənaɪz","m":"v.组织；安排；处理；分配","tip":"organ（器官）+ -ise/-ize（使……化）→ 使器官秩序化 → 组织","ex":["They organise their own laboratory work.","他们组织自己的实验室工作。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"function","p":"ˈfʌŋkʃn","m":"n.功能；职能；函数 v.起作用；运转","tip":"单词发音类似“放颗心”→ 放心吧，你的身体各器官“功能”良好。","ex":["This is evidence that our immune system really doesn't function so well when we age.","这表明，随着年龄的增长，我们的免疫系统确实不能很好地发挥作用。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"absorb","p":"əbˈzɔːb","m":"v.吸收（液体，知识等）；同化；理解，使全神贯注","tip":"ab-（一再地）+ sorb（音似吮吸声）→ 一再地吸 → 吸收","ex":["Some people are absorbed in the past but not open to new memories, but that's not the case for me.","有些人沉湎于过去，不愿接受新的回忆，但我不是这样。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"suck","p":"sʌk","m":"v.吸，吮；抽；吞没","tip":"su（音似“仨”）+ ck（联想“客”）→ 三个客人坐在一起用吸管喝饮料 → 吸，吮","ex":["Nowadays forests are increasingly welcome because they suck in carbon pollution from the air.","现在森林越来越受欢迎，因为它们从空气中吸收碳污染。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"intake","p":"ˈɪnteɪk","m":"n.（食物、饮料等的）摄入量，吸入量；吸收","tip":"in-（进入）+ take（拿，取）→ 进入并拿取 → 摄入量，吸入量","ex":["People who prioritise breakfasts tend to have lower calorie but higher nutritional intake.","优先吃早餐的人往往摄入的热量较低，但营养较高。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"straw","p":"strɔː","m":"n.稻草；吸管","tip":"他用吸管（straw）喝草莓（strawberry）奶昔。","ex":["It adds a layer of straw to the inside of the cup.","它在杯子里面加一层稻草。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"digest","p":"ˈdaɪdʒest","m":"n.摘要；概要；文摘；汇编","tip":"di（联想“弟”）+ ge（联想“哥”）+ st（联想 street）→ 弟弟和哥哥去街上散步，“消化”刚吃完的美食。","ex":["But you can't force the child to think carefully, enjoy books, digest complex information.","但你不能强迫孩子仔细思考，享受读书，消化复杂的信息。"],"lesson":"u08-l01","group":"“器官”相关"},{"w":"clinic","p":"ˈklɪnɪk","m":"n.诊所；临床实习；门诊部","tip":"野餐（picnic）时我吃坏了肚子，要去诊所（clinic）看医生。","ex":["He is being treated at a clinic.","他正在一家诊所接受治疗。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"diagnose","p":"ˈdaɪəɡnəʊz; ˌdaɪəɡˈnəʊz","m":"v.诊断（疾病）；判断（问题的原因）","tip":"di（联想“打”）+ ag（联想“阿哥”）+ nose（鼻子）→ 医生给阿哥打光是为了方便“诊断”鼻子的状况。","ex":["He was wrongly diagnosed.","他被误诊了。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"surgery","p":"ˈsɜːdʒəri","m":"n.外科手术；诊室；门诊处","tip":"","ex":["Health insurance and clinical guidelines promote treatment with drugs and surgery.","健康保险和临床指导方针提倡用药物和手术治疗。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"physical","p":"ˈfɪzɪkl","m":"adj.身体的；现实的；物质的；物理学的","tip":"phy（音似“肥”）+ si（联想“死”）+ -cal（形容词后缀）→ 过度肥胖对“身体的”危害非常大，甚至会增加死亡风险。","ex":["What mattered most was the residents' physical health and mental status.","最重要的是居民的身体健康和心理状态。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"physician","p":"fɪˈzɪʃn","m":"n.医生，内科医生","tip":"physic（医学；身体）+ -ian（人）→ 医生","ex":["They can save patients trouble visiting physicians.","他们可以为患者省去看医生的麻烦。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"dentist","p":"ˈdentɪst","m":"n.牙医，牙医诊所","tip":"dent（牙齿）+ -ist（人）→ 医治牙齿的人 → 牙医","ex":["I have to go to the dentist tomorrow.","我明天得去看牙医。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"dental","p":"ˈdentl","m":"adj.牙齿的；牙科的","tip":"dent（牙齿）+ -al（形容词后缀）→ 牙齿的；牙科的","ex":["I've got a dental appointment at 3 o'clock.","我约了3点看牙医。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"identical","p":"aɪˈdentɪkl","m":"adj.同一的，相同的","tip":"ident（相同）+ -ical（形容词后缀）→ 同一的，相同的","ex":["The two pictures are similar, although not identical.","这两幅画很相似，但不完全相同。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"identity","p":"aɪˈdentəti","m":"n.身份，特性；同一性，一致","tip":"身份证（ID card）就是用来识别某个人“身份”（identity）的证件。","ex":["It clearly aims to form children's identity through play.","很明显，它的目的是通过游戏来形成孩子的身份。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"identify","p":"aɪˈdentɪfaɪ","m":"v.认出，识别；鉴定；找到","tip":"身份证（ID card）就是用来识别、鉴定（identify）身份（identity）的。","ex":["Postal services work hard to identify items that require priority treatment.","邮政服务部门努力识别需要优先处理的物品。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"dose","p":"dəʊs","m":"n.（药的）一剂 v.给（某人）服药","tip":"他的鼻子（nose）不舒服，去医院开了一剂（dose）药。","ex":["It will have considerable side effects if taken in large doses.","如果大量服用，会有相当大的副作用。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"sore","p":"sɔː(r)","m":"adj.（发炎）疼痛的；酸痛的；愤慨的 n.痛处；伤处","tip":"单词发音类似“烧”→ 嗓子像火烧一样“疼痛”。","ex":["Flu symptoms including fever and chills, sore throat and body aches come on suddenly.","流感症状比如发烧、寒战、喉咙痛和身体疼痛，会突然出现。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"tablet","p":"ˈtæblət","m":"n.药片；平板电脑","tip":"table（桌子）+ t（联想“他”）→ 桌子上有他的“药片”和“平板电脑”。","ex":["It involves buying lots of tablets and software.","它需要购买大量的平板电脑和软件。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"pill","p":"pɪl","m":"n.药丸；药片","tip":"单词发音类似“片”→“药片”是片剂。","ex":["I took a pill to help settle my nerves.","我吃了一片药，帮助放松一下神经。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"ambulance","p":"ˈæmbjələns","m":"n.救护车","tip":"单词发音类似“俺不能死”→ 俺不能死，赶紧叫“救护车”。","ex":["He was taken to hospital in an ambulance.","他被救护车送往医院。"],"lesson":"u08-l01","group":"“医疗”相关"},{"w":"headache","p":"ˈhedeɪk","m":"n.头痛；头痛的事","tip":"head（头）+ a（一）+ che（联想“扯”）→ 头上的伤口一扯就疼 → 头痛","ex":["The access codes may be another financial headache for students.","访问码可能是令学生们头疼的另一个经济问题。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"cancer","p":"ˈkænsə(r)","m":"n.癌症；（社会）毒瘤；（迅速蔓延的）邪恶","tip":"can（可以）+ c（音似“死”）+ -er（表示人的后缀）→ 可以让人死去的病 → 癌症","ex":["There are many people who recover from cancer, stroke, or heart disease.","许多人从癌症、中风或心脏病中康复。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"diabetes","p":"ˌdaɪəˈbiːtiːz","m":"n.糖尿病","tip":"di-（两个）+ a + bete（音似“鼻涕”）+ s → 两行鼻涕 →“糖尿病”患者因免疫力下降，经常感冒流鼻涕。","ex":["Diabetes patients are advised to eat more plant-based food.","建议糖尿病患者多吃植物性食物。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"obesity","p":"əʊˈbiːsəti","m":"n.肥胖","tip":"obese adj. 肥胖的 → obesity n.","ex":["The food industry plays a major role in fighting obesity.","食品业在抗击肥胖方面发挥着重要作用。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"slim","p":"slɪm","m":"adj.苗条的；薄的；（数量）微小的 v.减肥","tip":"单词发音类似“四厘米”→ 四厘米高的鞋跟让“苗条的”她体态更好。","ex":["How do you manage to stay so slim?","你是怎样把身材保持得这么苗条的？"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"lean","p":"liːn","m":"v.倾斜，倾向；倚靠 adj.精简的；苗条的，瘦的","tip":"他学习（learn）学得都瘦（lean）了。","ex":["I lean toward the latter view.","我倾向于后一种观点。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"slender","p":"ˈslendə(r)","m":"adj.苗条的；微小的","tip":"s（联想“美女”）+ lender（音似 Linda，人名）→ 身材“苗条”的 Linda 是个美女。","ex":["These claims are based on slender evidence.","这些说法基于微弱的证据。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"bundle","p":"ˈbʌndl","m":"n.捆；包；一批；一大笔钱 v.（成群地）匆忙赶往；捆绑","tip":"单词发音类似“绑的”→ 捆；捆绑","ex":["A bundle containing thousands of pounds got stolen.","一捆包含数千英镑的现金被偷了。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"restore","p":"rɪˈstɔː(r)","m":"v.恢复；使复原；修复","tip":"rest（休息）+ o（联想“一圈”）+ re（字母音似“阿姨”）→ 阿姨绕了一圈稍作休息，才“恢复”过来。","ex":["They were badly damaged but restored.","它们已严重受损，但已得到修复。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"recover","p":"rɪˈkʌvə(r)","m":"v.康复；痊愈；恢复","tip":"re-（重新）+ cover（覆盖）→ 重新覆盖 → 恢复","ex":["He's still recovering from his operation.","手术后，他仍在恢复之中。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"coverage","p":"ˈkʌvərɪdʒ","m":"n.新闻报道；覆盖范围","tip":"","ex":["The incident has received wide coverage in the press.","这个事件已被新闻界广泛报道。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"discover","p":"dɪˈskʌvə(r)","m":"v.发现；发觉；了解到","tip":"dis-（分开；除去）+ cover（覆盖；盖子）→ 除去覆盖物，我们就“发现”了真相。","ex":["They discovered Iceland in the ninth century.","他们在九世纪发现了冰岛。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"heal","p":"hiːl","m":"v.（使）康复；治愈（病人）；使又愉快起来","tip":"he（他）+ al（联想 all）→ 他的病都好了 → 康复；治愈","ex":["That hasn't stopped thousands of winter depressives from trying to heal themselves.","那并没有阻止成千上万的冬季抑郁症患者试图治愈自己。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"remedy","p":"ˈremədi","m":"n.处理方法；疗法；改进措施；补偿 v.改正；改进","tip":"re-（回来）+ me（我）+ dy（联想 dying）→ 我回来治疗垂死的病人 → 疗法","ex":["But many tech home remedies can be explained by a little science.","但是，许多科技家庭疗法可以用一点科学来解释。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"therapy","p":"ˈθerəpi","m":"n.治疗；心理治疗","tip":"the（这个）+ rap（说唱）+ y → 这个说唱歌手在舞台上表演，“治疗”你的心灵创伤。","ex":["They also had talk therapy with a nurse before and after quit day.","他们还在戒烟日前后与护士进行了谈话治疗。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"treatment","p":"ˈtriːtmənt","m":"n.治疗；待遇","tip":"","ex":["The elephant was given medical treatment for many days.","这头大象接受了多天的医学治疗。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"inject","p":"ɪnˈdʒekt","m":"v.（给……）注射（药物等）；投入","tip":"in-（进入）+ ject（扔）→ 扔进身体 → 注射","ex":["Look at your talk and pick out a few words or sentences which you can inject with humour.","请仔细审视你的演讲内容，挑选出一些可以巧妙植入幽默的词语或句子。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"subject","p":"ˈsʌbdʒɪkt","m":"n.主题；科目 adj.易遭受……的；服从于","tip":"sub-（往下）+ ject（扔）→ 使遭受；使服从","ex":["Most college professors agree the kind of exam they choose largely depends on the subject.","大多数大学教授都同意，他们选择的考试形式在很大程度上取决于学科性质。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"phenomenon","p":"fəˈnɒmɪnən","m":"n.现象；非凡的人","tip":"phe（音似“飞”）+ no（不）+ men（人）+ on（在……上面）→ 在上面飞的不是人，而是不明飞行物，大家都对这个“现象”感兴趣。","ex":["Muscle performance can also be affected by a phenomenon called \"central fatigue\".","肌肉表现也会受到一种叫作“中枢疲劳”的现象的影响。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"object","p":"ˈɒbdʒɪkt","m":"n.对象，物品，东西","tip":"ob-（表示方向）+ ject（扔）→ 朝着某个方向扔 → 反对","ex":["Her mother objected to Eric's flying lessons.","她母亲反对（她上）埃里克的飞行课。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"reject","p":"rɪˈdʒekt","m":"n.废品；不合格者","tip":"re-（回来）+ ject（扔）→ 扔回来 → 拒绝，抵制","ex":["They reject using toilet paper with unnecessary features.","他们拒绝使用带有不必要功能的卫生纸。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"project","p":"ˈprɒdʒekt","m":"n.计划，方案；项目","tip":"pro-（往前）+ ject（扔）→ 做一件事情之前，要提前扔出“计划”。","ex":["Business schools grade their students in part on their performance in group projects.","商学院对学生的评分部分取决于他们在小组项目中的表现。"],"lesson":"u08-l01","group":"“病痛”相关"},{"w":"charity","p":"ˈtʃærəti","m":"n.慈善；慈善团体；仁爱","tip":"cha（联想“插”）+ r（形似花）+ -ity（名词后缀）→ 她把平时插花挣的钱，都做了“慈善”。","ex":["He was a popular guest at charity benefits and public events.","他是慈善活动和公开场合中备受青睐的嘉宾。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"donate","p":"dəʊˈneɪt","m":"v.捐赠；赠予","tip":"单词发音类似“兜内的”→ 他把兜内的钱都“捐赠”了出去。","ex":["It received an incredibly large number of donated books.","它收到了数量惊人的捐赠书籍。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"devote","p":"dɪˈvəʊt","m":"v.（～to）奉献；致力于","tip":"de（音似“弟”）+ vote（投票）→ 弟弟积极参与投票，“致力于”公益。","ex":["She decided to devote all her time to cultivating and developing it.","她决定把她所有的时间都用来培养和发展它。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"delicate","p":"ˈdelɪkət","m":"adj.易碎的，脆弱的；精致的；熟练的","tip":"deli（联想“得力”，文具品牌）+ cat（猫）+ e → 得力文具上刻有一只“精致的”猫。","ex":["Life is precious, and delicate.","生命是宝贵的，也是脆弱的。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"contribute","p":"kənˈtrɪbjuːt; ˈkɒntrɪbjuːt","m":"v.贡献，有助于；捐助","tip":"con-（一起，共同）+ tribut（给）+ e → 共同给 → 贡献","ex":["A variety of factors contribute to the long-run increase in the share of young adults living with their parents.","多种因素导致了与父母同住的年轻人比例的长期增长。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"distribute","p":"dɪˈstrɪbjuːt","m":"v.分发，分配；散布；分销","tip":"dis-（分开）+ tribut（给）+ e → 分发，分配","ex":["The scientific establishment is not very good at distributing money.","科学界在分配资金方面并不擅长。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"attribute","p":"əˈtrɪbjuːt","m":"n.属性，性质，特征","tip":"at-（一再地）+ tribut（给）+ e → 给出原因 → 把……归因于","ex":["Mistakes crack their self-confidence because they attribute errors to a lack of ability, which they feel powerless to change.","错误会让他们的自信心崩溃，因为他们把错误归咎于能力不足，觉得无力改变。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"owe","p":"əʊ","m":"v.欠（账、情）；归因于","tip":"o（形似矿井）+ we（我们）→ 我们得知矿井经营不善，已经“欠账”了。","ex":["The child may feel that he owes her an apology.","这孩子可能觉得他欠她一个道歉。"],"lesson":"u08-l01","group":"donation 相关"},{"w":"combine","p":"kəmˈbaɪn","m":"v.（使）结合；联合；兼备","tip":"com（联想 company）+ bine（联想“并”）→ 公司合并 →（使）结合；联合","ex":["They often fail to combine teaching with research.","他们常常不能把教学与研究结合起来。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"link","p":"lɪŋk","m":"n.联系；连接 v.把（物体、机器、地方等）连接起来；联系","tip":"单词发音类似“拎课”→ 他拎出一条线索，“联系”起课文情节。","ex":["The close link between age and stage may cease to exist in a multi-stage life.","在多阶段生活中，年龄和阶段之间的密切联系可能不再存在。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"connect","p":"kəˈnekt","m":"v.连接；联系","tip":"con-（所有的）+ ne（音似“奶”）+ ct（联想“剋他”）→ 所有的奶奶们“联系”好去剋（打）他。","ex":["Great innovators are good at connecting concepts from various academic fields.","伟大的创新者善于将各个学术领域的概念联系起来。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"coherent","p":"kəʊˈhɪərənt","m":"adj.连贯的；合乎逻辑的；有条理的","tip":"co-（= con-，都）+ her(e)（在这里）+ -ent（形容词后缀）→ 关键信息都在这里，构成了“连贯的”体系。","ex":["The subjects of the curriculum form a coherent whole.","课程中的科目构成了一个连贯的整体。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"cohesion","p":"kəʊˈhiːʒn","m":"n.黏合；结合；凝聚力","tip":"co-（= con-，都）+ hesion（联想“核心”）→ 大家都认为他是团队核心，很有“凝聚力”。","ex":["All this is done with the aim of improving workplace efficiency, collaboration and cohesion.","所有这些都是为了提高工作效率、协作能力和凝聚力。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"conjunction","p":"kənˈdʒʌŋkʃn","m":"n.连词；结合，同时发生","tip":"conj.是 conjunction 的缩写。","ex":["They work in conjunction with the environment.","它们与环境相结合。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"joint","p":"dʒɔɪnt","m":"n.关节，接头 adj.联合的","tip":"两个骨头连接（join）的地方就是关节（joint）。","ex":["Training can help to make muscles stronger and keeping joints lubricated.","训练有助于使肌肉更强壮并保持关节的润滑。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"knot","p":"nɒt","m":"n.结；一小群人 v.打结","tip":"k（联想“开”）+ not（不）→ 绳子打了“结”，解不开。","ex":["She tied a knot in a cherry stem.","她在樱桃梗上打了个结。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"integrate","p":"ˈɪntɪɡreɪt","m":"v.（使）合并，成为一体；（使）加入；（使）融入","tip":"inte（音似“音体”）+ grate（音似 great）→ 该校推出的音乐、体育一体化教学，让学生获得了非常棒的体验发展 → 成为一体","ex":["But not many are able to integrate innovation into their business.","但能够将创新融入业务的企业并不多。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"disintegrate","p":"dɪsˈɪntɪɡreɪt","m":"v.解体；崩溃，瓦解；破裂","tip":"dis-（不，非）+ integrate（使合并）→ 解体；崩溃","ex":["When governments lose their control on power, law and order begin to disintegrate.","当政府失去对权力的控制时，法律和秩序就开始瓦解。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"tangible","p":"ˈtændʒəbl","m":"adj.有形的；真实的；可触知的；可感知的","tip":"tan（音似“弹”）+ g + -ible（形容词后缀，可以……的）→ 可以弹的 → 可触知的","ex":["Craft activities result in tangible and often useful products.","手工活动产生有形的，并且通常是有用的产品。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"contact","p":"ˈkɒntækt","m":"n.（尤指经常的）联系；接触 v.联系 adj.供联系的","tip":"con-（共同）+ tact（触摸）→ 共同触摸 → 联系；接触","ex":["However, merely having contact with children does not guarantee happiness in old age.","然而，仅仅和孩子接触并不能保证老年幸福。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"intact","p":"ɪnˈtækt","m":"adj.完整的；完好无损的","tip":"in-（没有）+ tact（触摸）→ 没有被触摸过的 → 完整的","ex":["It wants to keep its own environment intact.","它想保持自己环境的完整。"],"lesson":"u08-l02","group":"“联系、连接”相关"},{"w":"attach","p":"əˈtætʃ","m":"v.贴上；把……固定，（使）与……有联系；重视","tip":"at-（一再地）+ tach（音似 touch）→ 一再触摸 → 贴上","ex":["It does not attach enough importance to task-based practice.","它对任务型实践的重视不够。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"cling","p":"klɪŋ","m":"v.紧紧抓住；粘住","tip":"单词发音类似“可怜”→ 那个可怜的孩子“紧紧抓住”母亲的衣角。","ex":["He had one last hope to cling on to.","他还抱着最后的一线希望。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"collar","p":"ˈkɒlə(r)","m":"n.衣领；颈圈 v.抓住","tip":"单词发音类似“扣了”→“衣领”最上面的扣子扣了吗？","ex":["She flicked the dust off her collar.","她轻轻掸掉了衣领上的灰尘。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"stick","p":"stɪk","m":"n.枝条；条状物 v.（~with）坚持；刺，插入；粘着","tip":"粘（stick）好照片后，在空白处打钩（tick）确认。","ex":["We love to establish a routine and stick with it.","我们喜欢建立一个常规并坚持下去。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"drum","p":"drʌm","m":"n.鼓；鼓状物，圆桶","tip":"单词发音类似“抓木”→ 鼓手抓紧木槌，奋力敲“鼓”。","ex":["I used to play drums in a band.","我以前在乐队里打鼓。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"branch","p":"brɑːntʃ","m":"n.树枝；分支；支流","tip":"单词发音类似“不让骑”→ 爬树的时候，父母不让他骑在“树枝”上，以免发生危险。","ex":["Taijiquan, stemming from ancient China, is an important branch of Chinese martial arts.","太极拳源于中国古代，是中国武术的一个重要分支。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"trunk","p":"trʌŋk","m":"n.树干；（人的）躯干；后备箱；象鼻","tip":"单词发音类似“撞开”→ 大象用“象鼻”把人撞开。","ex":["She popped the trunk and we tossed the stuff inside.","她打开后备箱，我们把东西扔了进去。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"cement","p":"sɪˈment","m":"n.水泥；胶合剂；纽带 v.黏结；加强，巩固","tip":"单词发音类似“塞门它”→ 往门缝下塞“水泥”能填补好缝隙。","ex":["Mix the sand and cement together.","把沙子和水泥混合在一起。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"glue","p":"ɡluː","m":"n.胶；胶水 v.黏合，粘贴","tip":"g（联想“哥”）+ lu（联想“鹿”）+ e → 哥哥用“胶水”黏起了小鹿玩具。","ex":["There is some glue on the envelope.","信封上有一些胶水。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"clue","p":"kluː","m":"n.线索；提示","tip":"单词发音类似“可鹿”→ 根据“线索”可以找到鹿的踪迹。","ex":["They would run around looking for clues and at the end unmask the bad guy.","他们会四处找线索，最后揭开坏人的真面目。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"cue","p":"kjuː","m":"n.暗示；提示 v.给（某人）暗示（或提示）","tip":"我们根据线索（clue）的暗示（cue）找到了真相。","ex":["I think that's my cue to explain why I'm here.","我想，现在该轮到我解释一下我来这里的原因了。"],"lesson":"u08-l02","group":"“粘、贴”相关"},{"w":"recommend","p":"ˌrekəˈmend","m":"v.推荐；介绍；劝告；建议","tip":"re（字母音似“阿姨”）+ com（音似“可”）+ mend（音似“闷的”）→ 阿姨是个可（很）闷的人，不爱与人交流，给她“推荐”个朋友吧。","ex":["Of the nearly 100 Americans recommended to be studied, 77% were white.","在被推荐研究的近100名美国人中，77%是白人。"],"lesson":"u08-l02","group":"re 相关"},{"w":"suggest","p":"səˈdʒest","m":"v.建议；推荐；表明","tip":"","ex":["This suggests their higher IQs result from the time they spend teaching their siblings.","这表明他们智商更高是因为花时间教兄弟姐妹。"],"lesson":"u08-l02","group":"re 相关"},{"w":"relax","p":"rɪˈlæks","m":"v.放松，休息","tip":"re（字母音似“阿姨”）+ la（音似“来”）+ x（联想“某地”）→ 阿姨来某地“放松”。","ex":["But don't kids need time to relax?","但是孩子们不需要时间放松吗？"],"lesson":"u08-l02","group":"re 相关"},{"w":"nerve","p":"nɜːv","m":"n.神经；神经质；勇气","tip":"","ex":["Pain is the only feeling to which the nerves in that layer respond.","疼痛是这一层神经所能反应的唯一感觉。"],"lesson":"u08-l02","group":"re 相关"},{"w":"calm","p":"kɑːm","m":"v.使平静 adj.沉着的；平静的","tip":"cal（联想 call）+ m（联想“妈妈”）→ 他心情不好时就给妈妈打电话，妈妈的安慰会让他“平静”。","ex":["Sit down and try to calm yourself.","坐下，试着让自己平静下来。"],"lesson":"u08-l02","group":"re 相关"},{"w":"religion","p":"rɪˈlɪdʒən","m":"n.宗教，宗教信仰","tip":"re（字母音似“阿姨”）+ ligion（音似“历尽”）→ 阿姨历尽沧桑之后开始研究“宗教”。","ex":["It is mainly based on a society's religion.","这主要基于一个社会的宗教信仰。"],"lesson":"u08-l02","group":"re 相关"},{"w":"saint","p":"seɪnt","m":"n.圣人，圣徒","tip":"单词发音类似“神他”→ 孔子既有神人之慧，又有“圣人”之德。","ex":["She mainly drew on stories of ancient saints.","她主要借鉴了古代圣人的故事。"],"lesson":"u08-l02","group":"re 相关"},{"w":"holy","p":"ˈhəʊli","m":"adj.神圣的，圣洁的","tip":"好莱坞（Hollywood）是电影人心目中神圣的（holy）逐梦乐园。","ex":["The place is considered holy by the local people.","当地人认为这个地方是神圣的。"],"lesson":"u08-l02","group":"re 相关"},{"w":"solemn","p":"ˈsɒləm","m":"adj.庄严的，隆重的；（表情）严肃的","tip":"单词发音类似“所罗门”（古以色列王国的王）→ 国王用“严肃的”表情扫视四周。","ex":["Her face grew solemn.","她的脸变得严肃起来。"],"lesson":"u08-l02","group":"re 相关"},{"w":"church","p":"tʃɜːtʃ","m":"n.教堂，教会","tip":"单词发音类似“撤吃”→ 在战争时期，难民撤入“教堂”后才吃得到一些食物。","ex":["The tradition, dating back to 300 B.C., was later incorporated into the Christian church.","这一传统可以追溯到公元前300年，后来被纳入基督教会。"],"lesson":"u08-l02","group":"re 相关"},{"w":"bless","p":"bles","m":"v.祝福；保佑","tip":"b（音似“不”）+ less（少的）→ 过年时，“祝福”的话一句都不能少。","ex":["Most of us in the entrepreneurial community are blessed—or cursed—with higher-than-average ambition.","在企业家群体中，大多数人都有高于平均水平的雄心壮志，这或是祝福，或是诅咒。"],"lesson":"u08-l02","group":"re 相关"},{"w":"celebrate","p":"ˈselɪbreɪt","m":"v.庆祝；庆贺；赞美","tip":"ce（音似“赛”）+ le（联想“了”）+ br（联想“必然”）+ ate（eat 的过去式）→ 比赛结束了，大家必然要吃饭“庆祝”一下。","ex":["So it's no surprise that cultures around the world celebrate spring by honouring the egg.","因此，世界各地的文化通过纪念鸡蛋来庆祝春天也就不足为奇了。"],"lesson":"u08-l02","group":"re 相关"},{"w":"banquet","p":"ˈbæŋkwɪt","m":"n.宴会；筵席","tip":"单词发音类似“办亏特”→ 举办非常豪华的“宴会”是特别有可能亏钱的。","ex":["A state banquet was held in honour of the visiting president.","为欢迎来访总统，特设国宴以示礼遇。"],"lesson":"u08-l02","group":"re 相关"},{"w":"ceremony","p":"ˈserəməni","m":"n.仪式，典礼","tip":"单词发音类似“赛罗蒙你”→ 赛罗（人名）说为你举行一个“仪式”，结果蒙（骗）了你。","ex":["He attended his graduation ceremony.","他参加了毕业典礼。"],"lesson":"u08-l02","group":"re 相关"},{"w":"funeral","p":"ˈfjuːnərəl","m":"n.葬礼","tip":"fune（联想 fuel）+ r + al（联想 all）→ 身体的燃料（能量）全部用尽时，“葬礼”将送走过往。","ex":["Many people attended her funeral.","许多人参加了她的葬礼。"],"lesson":"u08-l02","group":"re 相关"},{"w":"fuel","p":"ˈfjuːəl","m":"n.燃料 v.给……提供燃料；增加；刺激","tip":"单词发音类似“费油”→ 汽车费油，即消耗很多“燃料”。","ex":["It does produce much less pollution than that caused by energy production through fossil fuels.","它产生的污染的确比化石燃料能源生产产生的污染要少得多。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"gas","p":"ɡæs","m":"n.气体；天然气；汽油","tip":"单词发音类似“该死”→ 该死！“汽油”又涨价了。","ex":["The road was covered with spilled gas.","路上满是溢出的汽油。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"carbon","p":"ˈkɑːbən","m":"n.碳","tip":"car（车）+ bon（联想 born）→ 小轿车会产生“碳”排放。","ex":["Scotland will reach the national target in carbon emissions reduction ahead of schedule.","苏格兰将提前实现国家碳减排目标。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"silicon","p":"ˈsɪlɪkən","m":"n.硅","tip":"单词发音类似“死力啃”→ 要死力（拼命）啃（读）书才能到“硅”谷发展。","ex":["The personal computing revolution and philosophy of disruptive innovation of Silicon Valley grew.","个人计算机革命和硅谷的颠覆性创新理念蓬勃发展。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"nuclear","p":"ˈnjuːkliə(r)","m":"adj.原子能的；核能的","tip":"nu（联想 new）+ clear（清洁的）→ 新的清洁能源 → 原子能的；核能的","ex":["They argued in favour of keeping a nuclear deterrent.","他们主张保留核威慑力量。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"atom","p":"ˈætəm","m":"n.原子，微粒","tip":"单词发音类似“阿童木”→ 阿童木又名“原子”小金刚。","ex":["Two atoms of hydrogen combine with one atom of oxygen to form a molecule of water.","两个氢原子和一个氧原子结合组成一个水分子。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"electron","p":"ɪˈlektrɒn","m":"n.电子","tip":"单词发音类似“一来可愁”→“电子”时代一来临，父母担心孩子们玩游戏、上网会影响学习。","ex":["The former have atoms that contain more free electrons than the latter.","前者的原子比后者含有更多的自由电子。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"electricity","p":"ɪˌlekˈtrɪsəti","m":"n.电力；电流","tip":"","ex":["Try to imagine what it is like to live without electricity.","试着想象一下没有电的生活是什么样子。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"bury","p":"ˈberi","m":"v.埋葬；隐藏","tip":"bu（联想“不”）+ ry（联想“如意”）→ 把不如意“埋葬”，让希望破土成长。","ex":["Capture carbon dioxide and bury it under the sea.","捕获二氧化碳并将其埋在海底。"],"lesson":"u08-l02","group":"“能源”相关"},{"w":"cheer","p":"tʃɪə(r)","m":"v.使振作；鼓舞 n.欢呼声","tip":"","ex":["We gave out a cheer when the red roof of the cottage came into view.","当小屋的红色屋顶映入眼帘时，我们发出了欢呼声。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"pleasure","p":"ˈpleʒə(r)","m":"n.愉快，快乐；乐事","tip":"pleas（联想 please）+ ure → 常说“请”字懂礼貌，心情“愉快”没烦恼。","ex":["She always derives great pleasure from designing something new.","她总是从设计新东西中获得极大的乐趣。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"joy","p":"dʒɔɪ","m":"n.高兴，喜悦；乐趣；满足","tip":"当你享受（enjoy）一件事的时候，一定是高兴（joy）的。","ex":["We do work that gives us bursts of joy each new day.","我们所做的工作每一天都给我们带来阵阵喜悦。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"comfortable","p":"ˈkʌmftəbl","m":"adj.舒适的；自在的","tip":"","ex":["Students are more comfortable seeking counselling in school.","学生在学校寻求心理咨询更为自在。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"cheek","p":"tʃiːk","m":"n.脸颊","tip":"ch（联想“吃”）+ ee（联想“两只鹅”）+ k（联想 king）→ 国王吃完两只鹅，“脸颊”变得红润了。","ex":["One common French custom of greetings is cheek-kissing.","法国人的一个常见的问候习惯是亲吻脸颊。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"elevate","p":"ˈelɪveɪt","m":"v.举起；晋升；使情绪高昂","tip":"ele（联想人名“爱丽”）+ vate（音似“喂她”）→ 爱丽长得很高，喂她吃饭时必须踮起脚尖，“举起”手臂。","ex":["Smoking often elevates blood pressure.","抽烟常常使血压升高。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"lift","p":"lɪft","m":"n.电梯；提；上升；搭便车 v.（被）举起；鼓舞","tip":"","ex":["Medical Association offers a picture of how risky it is to get a lift from a teenage driver.","医学协会提供了一张图片，展示了从十几岁的司机那里搭便车有多危险。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"rise","p":"raɪz","m":"n.上涨，提高；增强 v.上升；起身；起义","tip":"ri（联想“日”）+ s（联想“复数”）+ e（往外）→ 在后羿射日的故事中，十个太阳都想往外升起 → 上升","ex":["Leslie worries that the rise of the Internet has reduced our appetite for aimless adventures.","莱斯利担心互联网的兴起已经减少了我们对漫无目的冒险的兴趣。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"arise","p":"əˈraɪz","m":"v.起来；出现","tip":"a-（一再地）+ rise（升起）→ 出现","ex":["What problem may arise if classes go online?","如果把课程放到网上可能会出现什么问题？"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"arouse","p":"əˈraʊz","m":"v.唤醒；引起","tip":"a-（一再地）+ rouse（音似“热死”）→ 十个太阳同时出现后，一再地热死人，“引起”了大家的反感。","ex":["Most stores open with flowers, fruit and vegetables at the front as a breath of freshness to arouse our appetite.","大多数商店都把鲜花、水果和蔬菜放在最前面，给人一种新鲜的感觉，唤起我们的食欲。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"rouse","p":"raʊz","m":"v.唤醒；使醒来","tip":"","ex":["The telephone roused me from my sleep at 6 a.m.","早晨6点钟，电话铃声就把我从睡梦中吵醒了。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"raise","p":"reɪz","m":"n.加薪 v.举起；升起；引起；提出；抚养；组建","tip":"十个太阳再次升起（rise），后羿举（raise）手表示要去射下其中九个。","ex":["This has already raised privacy concerns.","这已经引起了人们对隐私的担忧。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"waken","p":"ˈweɪkən","m":"v.醒来，唤醒","tip":"wa（联想“哇”）+ ken（联想“肯”，人名）→ 哇，沉睡几天的肯终于“醒来”了。","ex":["They are wakened several times during the night.","他们在夜间被弄醒了好几次。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"awake","p":"əˈweɪk","m":"adj.醒着的 v.唤醒","tip":"","ex":["I was barely able to stay awake.","我几乎无法保持醒着。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"drag","p":"dræɡ","m":"v.拖，拽 n.累赘；无聊的事","tip":"单词发音类似“拽个”→ 拖，拽","ex":["I dragged the chair over to the window.","我把椅子拖到了窗子那边。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"dragon","p":"ˈdræɡən","m":"n.龙","tip":"单词发音类似“拽根”→ 一条“龙”拽着树根盘踞在原地。","ex":["You should check the toy dragon one more time before playing.","你在玩之前应该再检查一次这个玩具龙。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"haul","p":"hɔːl","m":"v.（用力）拖，拉，拽 n.拖，拉；旅程","tip":"单词发音类似“嚎”→ 纤夫拉船时发出的声音像“嚎”，拖得很长 → 拖，拉，拽","ex":["These people are usually unable or unprepared to endure the long haul.","这些人通常无法或没有准备好忍受长期的考验。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"roar","p":"rɔː(r)","m":"n.咆哮；（机器的）隆隆声 v.咆哮；放声大笑","tip":"野猪（boar）发出咆哮（roar）声。","ex":["I could hear nothing but the roar of the airplane engines.","除了飞机引擎的轰鸣声，我什么也听不到。"],"lesson":"u08-l02","group":"“愉快”相关"},{"w":"bitter","p":"ˈbɪtə(r)","m":"adj.激烈而不愉快的；严寒的；味苦的","tip":"黄油（butter）香，咖啡苦（bitter）。","ex":["On Wednesday, a polar wind brought bitter cold to the Midwest.","周三，一股极地风给中西部带来了刺骨的寒冷。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"bit","p":"bɪt","m":"n.一点；少量；一部分","tip":"","ex":["I learned a little bit of Spanish.","我学了一点西班牙语。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"misery","p":"ˈmɪzəri","m":"n.痛苦；悲惨；不痛快的人","tip":"单词发音类似“没滋味”→ 生活没滋味还真是一件“痛苦”的事。","ex":["Fame brought her nothing but misery.","名声只给她带来了痛苦。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"hardship","p":"ˈhɑːdʃɪp","m":"n.艰难，困苦","tip":"hard（困难的）+ ship（船）→ 他乘船经历一段非常困难的旅程 → 艰难，困苦","ex":["Most people will experience some form of financial hardship at some point in their lives.","大多数人在他们生命中的某个时候都会经历某种形式的经济困难。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"distress","p":"dɪˈstres","m":"n.悲痛，痛苦 v.使痛苦，使悲伤","tip":"di-（两）+ stress（压力）→ 两份压力 → 一份压力催人奋进，两份压力就使人“痛苦”了。","ex":["The baby was clearly in distress.","婴儿显然很痛苦。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"stress","p":"stres","m":"n.精神压力，紧张；重音；强调 v.强调；重读","tip":"stre（音似“死拽”）+ ss（联想“丝”）→ 死死地拽着头发丝 → 他“头悬梁，锥刺股”，保持“紧张”的状态学习。","ex":["There're three main types of financial stress people encounter.","人们遇到的财务压力主要有三种类型。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"hell","p":"hel","m":"n.地狱；悲惨的境况；该死","tip":"he（他）+ ll（形似罗马数字 2）→ 他独自抚养两个年幼的孩子，处境艰难 → 悲惨的境况","ex":["The last three months have been hell.","过去的三个月真受罪。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"poverty","p":"ˈpɒvəti","m":"n.贫穷，贫困；短缺；劣质","tip":"pover（联想 poor）+ -ty（名词后缀）→ 贫穷","ex":["It is impossible for Americans to lift themselves out of poverty entirely on their own.","美国人不可能完全靠自己摆脱贫困。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"sorrow","p":"ˈsɒrəʊ","m":"n.悲伤；伤心事 v.感到悲伤","tip":"单词发音类似“缩肉”→ 过度“悲伤”会使人体消瘦。","ex":["They have their own joys and sorrows.","他们有自己的欢乐和悲伤。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"painful","p":"ˈpeɪnfl","m":"adj.痛苦的；困难的","tip":"pain n.痛苦 → painful adj.","ex":["It was a difficult and painful operation.","这是一次艰难而痛苦的手术。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"tough","p":"tʌf","m":"adj.艰难的；坚韧的；强硬的","tip":"单词发音类似“他服”→ 他很佩服你熬过了那段“艰难的”日子。","ex":["It's a good problem to have, but it can be a tough skill to master.","这是一个很好的问题，但它可能是一个很难掌握的技能。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"rough","p":"rʌf","m":"adj.粗糙的；不平的；粗暴的；艰难的；粗略的","tip":"如果路面不平（rough），人走起来是很艰难的（tough）。","ex":["Cathy did a rough calculation.","凯茜作了一个粗略的计算。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"harsh","p":"hɑːʃ","m":"adj.严酷的，残酷的；恶劣的；艰苦的","tip":"har（联想 hard）+ sh（音似“事”）→ 艰难的事 → 残酷的","ex":["We had to face up to the harsh realities of life sooner or later.","我们迟早都得正视生活的严酷现实。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"cruel","p":"ˈkruːəl","m":"adj.残酷的；残忍的；引起痛苦的 v.搞糟；使机会丧失","tip":"","ex":["Hunting foxes with dogs is considered cruel and violent.","用狗猎狐狸被认为是残忍且暴力的。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"brutal","p":"ˈbruːtl","m":"adj.野蛮的；凶残的；直截了当的","tip":"单词发音类似“不如逃”→ 他是个“凶残的”人，我们不如快点逃走。","ex":["The number of people opposed to fox hunting, because they think it is brutal, has risen sharply.","反对猎狐的人数急剧上升，因为他们认为这是残忍的。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"stiff","p":"stɪf","m":"adj.僵硬的；稠的；艰难的；激烈的","tip":"st（联想 stand）+ iff（联想 cliff）→ 站在悬崖边上，他身体僵硬不敢动 → 僵硬的","ex":["Her hands are now less stiff and painful.","她的手现在不那么僵硬和疼痛了。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"clumsy","p":"ˈklʌmzi","m":"adj.笨拙的，不得体的；不灵活的","tip":"clum（音似“哥拉妹”）+ sy → 哥哥第一次拉妹妹出去玩，他“笨拙的”动作说明他很紧张。","ex":["She took her clumsy shoe off her left foot, and put on the golden slipper.","她脱下左脚上笨重的鞋子，然后穿上金色的拖鞋。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"flexible","p":"ˈfleksəbl","m":"adj.能适应新情况的；灵活的；柔韧的；有弹性的；可弯曲的","tip":"fl（联想 fly）+ ex（向外）+ -ible（形容词后缀）→ 这只小鸟以“灵活的”姿态向外飞出了房间。","ex":["This might mean thinking of non-financial ways to reward employees, like unpaid time off or flexible work schedules.","这可能意味着考虑非经济方式来奖励员工，比如无薪休假或灵活的工作时间表。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"reflect","p":"rɪˈflekt","m":"v.反射；反映；反省","tip":"re-（回）+ flect（弯曲）→ 弯曲回来，折回来 → 反射","ex":["The national statistics did not reflect the actual calorie consumption.","国家统计数据并没有反映出实际的卡路里消耗。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"vulnerable","p":"ˈvʌlnərəbl","m":"adj.易受……伤害的，（身体上或感情上）脆弱的","tip":"单词发音类似“哇！你弱爆”→ 哇！你弱爆了，太脆弱了 → 脆弱的","ex":["They can become increasingly vulnerable to serious illnesses.","他们可能变得越来越容易受到严重疾病的影响。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"tender","p":"ˈtendə(r)","m":"adj.温柔的；柔软的；疼痛的；易坏的；脆弱的","tip":"单词发音类似“疼的”→ 别人稍微碰他一下，他就喊疼 → 脆弱的","ex":["Boil the beans until they are tender.","把豆子煮到变软。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"mild","p":"maɪld","m":"adj.温暖的；和善的；温和的；轻微的","tip":"单词发音类似“妹爱的”→ 妹妹喜爱跟“和善的”人交往。","ex":["It has mild weather both in summer and in winter.","夏天和冬天的天气都很温和。"],"lesson":"u08-l03","group":"“痛苦、绝望”相关"},{"w":"tremble","p":"ˈtrembl","m":"v.发抖；焦虑；摇晃 n.颤抖；摇晃","tip":"单词发音类似“穿薄”→ 他穿得很薄，冷风一吹，就“发抖”。","ex":["My legs were trembling with fear.","我吓得双腿直发抖。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"shiver","p":"ˈʃɪvə(r)","m":"n.颤抖 v.发抖","tip":"单词发音类似“洗我”→ 冬天洗完澡，刚出浴室的我冻得直“发抖”。","ex":["He felt a cold shiver of fear run through him.","他吓得打了一个寒战。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"quake","p":"kweɪk","m":"v.（因恐惧而）颤抖；（大地、建筑物等）震动 n.地震","tip":"","ex":["The ground quaked as the bomb exploded.","炸弹爆炸时，地面都震动了。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"despair","p":"dɪˈspeə(r)","m":"n.绝望 v.绝望；丧失信心","tip":"de（音似“弟”）+ s + pair（一双）→ 弟弟丢了一双限量款鞋子，他非常“绝望”。","ex":["Consumers say they're not in despair.","消费者表示，他们并没有感到绝望。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"compare","p":"kəmˈpeə(r)","m":"v.比较；比作；与……类似；比喻","tip":"com-（所有）+ pare（联想 pair）→ 把所有成对的物品都“比较”一下。","ex":["Let's compare a theoretical financial education subject to the standard compulsory English class.","让我们将理论金融教育科目与标准必修英语课进行比较。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"mess","p":"mes","m":"n.肮脏，杂乱；麻烦，困境 v.弄脏，弄乱","tip":"me（我）+ ss（音似“死”）→ 我回到家看到一堆“杂乱”的文件，烦得要死。","ex":["He has made a mess of his midterm exam.","他把期中考试搞得一团糟。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"fuss","p":"fʌs","m":"n.大惊小怪；反对，抗议 v.瞎操心；打扰","tip":"单词发音类似“发丝”→ 有些人发丝有点干枯，就“大惊小怪”地认为自己得病了。","ex":["He loves them but does not want to make a fuss.","他爱他们，但不想大惊小怪。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"dilemma","p":"dɪˈlemə","m":"n.困境；（进退两难的）窘境","tip":"单词发音类似“弟来吗”→ 我不确定弟弟到底来不来，所以陷入了“困境”。","ex":["The solution to this dilemma is using data and instincts in conjunction.","解决这一困境的办法是结合使用数据和直觉。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"chaos","p":"ˈkeɪɒs","m":"n.混乱，混沌","tip":"chao（联想“吵”）+ s（音似“死”）→ 他的家里每天都吵死了，屋内永远“混乱”不堪。","ex":["Heavy snow has caused total chaos on the roads.","大雪导致道路上交通一片混乱。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"disorder","p":"dɪsˈɔːdə(r)","m":"n.失调，紊乱；混乱；疾病","tip":"dis-（否定前缀）+ order（顺序）→ 没有顺序 → 混乱","ex":["This is a rare disorder of the liver.","这是一种罕见的肝病。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"orderly","p":"ˈɔːdəli","m":"adj.有秩序的；整洁的","tip":"","ex":["It was a civilised and orderly society.","那是个文明有序的社会。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"desperate","p":"ˈdespərət","m":"adj.拼命的，不顾一切的；绝望的；渴望的；极严重的","tip":"de（联想“弟”）+ spe（音似“撕破”）+ rate（速度）→ 运动会上，弟弟撕（打）破速度的极限，以“拼命的”态度冲向终点。","ex":["Doctors were fighting a desperate battle to save the little girl's life.","医生们不惜一切地奋力抢救小女孩的生命。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"accelerate","p":"əkˈseləreɪt","m":"v.（使）加速，加快","tip":"ac-（加强）+ cele（音似“赛了”）+ rate（速度）→ 他“加快”了比赛速度。","ex":["It accelerates the exhaustion of rare minerals.","它加速了稀有矿物的枯竭。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"decelerate","p":"ˌdiːˈseləreɪt","m":"v.减速，降低速度","tip":"de-（否定前缀）+ cele（音似“赛了”）+ rate（速度）→ 比赛时不加速就是在“减速”。","ex":["The car decelerated because of the sudden change in the weather.","由于天气的突然变化，汽车减速了。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"exaggerate","p":"ɪɡˈzædʒəreɪt","m":"v.夸张，夸大","tip":"ex-（向外）+ agg(e)（联想 egg）+ rate（速度）→ 这只鸡向外下蛋的速度被“夸大”了。","ex":["They provide objective information without exaggerating.","他们提供客观的信息，不夸大其词。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"weaken","p":"ˈwiːkən","m":"v.削弱；变弱","tip":"weak（虚弱的）+ -en（动词后缀）→ 使变得虚弱 → 削弱","ex":["Stress will weaken the body's defense against germs.","压力会削弱身体对病菌的防御能力。"],"lesson":"u08-l03","group":"“颤抖”相关"},{"w":"shortcoming","p":"ˈʃɔːtkʌmɪŋ","m":"n.缺点，缺陷","tip":"","ex":["Humility leads to an honest view of one's own advantages and shortcomings.","谦逊会让人们诚实地看待自己的优点和缺点。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"shortage","p":"ˈʃɔːtɪdʒ","m":"n.不足；缺少；短缺","tip":"","ex":["There is a growing shortage of medical personnel.","医务人员日益短缺。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"advantage","p":"ədˈvɑːntɪdʒ","m":"n.有利条件；优势；优点","tip":"ad-（一再地）+ van（音似“玩”）+ tage（联想“她哥”）→ 玩耍时，大家一再地发现她哥哥的“优点”。","ex":["She had the advantage of a good education.","她具有受过良好教育的有利条件。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"fault","p":"fɔːlt","m":"n.缺点；过错；责任；故障","tip":"fau（音似 for）+ l（联想“了”）+ t（联想“他”）→ 为了他，我曾犯下许多“过错”。","ex":["It is not an individual's fault if they develop obesity.","如果他们患上肥胖症，这不是个人的错。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"setback","p":"ˈsetbæk","m":"n.挫折；阻碍","tip":"set（设置）+ back（后退）→ 游戏中设置让玩家后退的是“阻碍”。","ex":["But curiosity can also be dangerous, leading to setbacks or even downfalls.","但好奇心也可能是危险的，它会导致挫折甚至失败。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"obstacle","p":"ˈɒbstəkl","m":"n.障碍；干扰；阻碍；绊脚石","tip":"单词发音类似“哦，不是特抠”→ 我不是特别抠，我只是面临经济“障碍”。","ex":["Though there are plans to add translations, language barriers can be a big obstacle.","虽然有增加翻译的计划，但语言障碍可能是一个很大的阻碍。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"hinder","p":"ˈhɪndə(r)","m":"v.阻碍；妨碍；阻挡","tip":"hind（后面的）+ -er（后缀）→ 拉后腿 → 阻碍；妨碍","ex":["A fixed mindset can also hinder communication and progress in the workplace.","思维定势也会阻碍职场中的沟通和进步。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"restrain","p":"rɪˈstreɪn","m":"v.（尤指用武力）制止，阻止；约束，控制","tip":"re（字母音“阿姨”）+ s（联想“蛇”）+ train（火车）→ 阿姨要带蛇上火车，安检人员赶紧“阻止”了她。","ex":["Do not try to restrain me from beating him.","不要试图阻止我打他。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"restrict","p":"rɪˈstrɪkt","m":"v.限制，限定（数量、范围等）；束缚；阻碍","tip":"re-（再）+ strict（严格的）→ 她再次严格控制自己的饮食，并“限制”自己每天只喝一杯咖啡。","ex":["Laws can restrict or ban voting, access to public housing, and professional and business licensing.","法律可对选举权、公共住房获取权、职业及商业许可权实施限制或禁令。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"haste","p":"heɪst","m":"n.匆忙，急忙；赶紧；催促","tip":"单词发音类似“恨死他”→ 她被骗后恨死他了，随后“匆忙”离开了他。","ex":["The letter had clearly been written in haste.","这封信明显是在匆忙中写的。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"hate","p":"heɪt","m":"v.厌恶，讨厌，憎恶（某事物） n.憎恨；厌恶；憎恨的人","tip":"","ex":["I hate it because it's an obligation disguised as an option.","我讨厌它，因为它是一个伪装成自由选择的义务。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"hatred","p":"ˈheɪtrɪd","m":"n.憎恶，憎恨，仇恨","tip":"hate v. & n.讨厌，憎恨 → hatred n.","ex":["Philosophers believe that desire, hatred and envy are \"negative emotions\".","哲学家认为，欲望、仇恨和忌妒都是“负面情绪”。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"harmony","p":"ˈhɑːməni","m":"n.调和；协调；和谐","tip":"harm（伤害）+ on（联想 no）+ y（联想 you）→ 你与大家“和谐”共处，没有任何人会伤害你。","ex":["They are built in harmony with the environment.","它们是以与环境协调的方式建造的。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"coordinate","p":"kəʊˈɔːdɪneɪt","m":"v.使协调；使相配合；（衣服、家具等）搭配，协调","tip":"我们都是普通（ordinary）人，要一起配合（coordinate）才能把工作做好。","ex":["They will coordinate with the Social Security Administration.","他们将与社会保障局进行协调。"],"lesson":"u08-l03","group":"“缺点、限制”相关"},{"w":"classic","p":"ˈklæsɪk","m":"adj.最优秀的；典型的 n.（书、电影或歌曲的）经典作品，杰作","tip":"class（等级）+ -ic（后缀）→ 最优秀的；经典作品","ex":["In the classic marriage vow, couples promise to stay together in sickness and in health.","在经典的婚姻誓约中，夫妻俩承诺无论疾病还是健康都会在一起。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"classify","p":"ˈklæsɪfaɪ","m":"v.分类；归类；划分","tip":"class（种类）+ -ify（动词后缀）→ 分类；归类","ex":["There is not enough evidence to classify it as a disease.","目前还没有足够的证据将它归类为一种疾病。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"middle-class","p":"ˌmɪdl ˈklɑːs","m":"adj.中产阶级的；古板的","tip":"","ex":["A good education has been the most important thing for middle-class households.","良好的教育对中产阶级家庭来说是最重要的事情。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"layer","p":"ˈleɪə(r)","m":"n.层；表层；层次；阶层","tip":"lay（放）+ -er（名词后缀）→ 被放置后呈现的状态 → 层；层次","ex":["The earth is composed of several layers.","地球由几层组成。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"upgrade","p":"ˌʌpˈɡreɪd","m":"v.（使机器、计算机系统等）升级；改进","tip":"up（向上）+ grade（等级）→ 等级向上走 → 使升级；改进","ex":["Fast technological change makes it necessary for one to constantly upgrade their skills.","快速的技术变革使人们有必要不断地提高自己的技能。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"rank","p":"ræŋk","m":"n.（尤指较高的）地位，级别；等级 v.把……分等级；名列","tip":"ran（run 的过去式）+ k（联想“课”）→ 他经常跑着去上课，且上课态度积极，为的是能够在班上“名列”前茅。","ex":["Promotion will mean that I'm immediately above him in rank.","升职后我会比他高一级。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"degree","p":"dɪˈɡriː","m":"n.程度，度数；（大学）学位","tip":"de（音似“弟”）+ gree（联想 green）→ 弟弟对绿色的喜爱“程度”特别深。","ex":["Today foreign students earn 30 percent of the doctoral degrees awarded in the United States.","如今，在美国获得博士学位的学生中，外国学生占30%。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"scale","p":"skeɪl","m":"n.规模；范围；程度；等级","tip":"sca（联想 scar）+ le（联想“了”）→ 他受伤“程度”严重，后期留下了伤疤。","ex":["On a global scale, 77 percent of energy is created from fossil fuels.","在全球范围内，77%的能源来自化石燃料。"],"lesson":"u08-l03","group":"“层级”相关"},{"w":"tap","p":"tæp","m":"n.水龙头；旋塞；轻拍 v.轻敲，轻拍；开发，利用（资源、形势）","tip":"ta（联想“他”）+ p（联想“拍”）→ “水龙头”不出水了，他“轻拍”了一下。","ex":["Scientists have tried to tap Internet donors, too, with mixed success.","科学家们也试图利用互联网捐助者，但结果喜忧参半。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"pat","p":"pæt","m":"v.轻拍，爱抚","tip":"单词发音类似“拍它”→ 轻拍","ex":["She patted the dog on the head.","她轻轻地拍着狗的头。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"passion","p":"ˈpæʃn","m":"n.激情，热情","tip":"单词发音类似“拍心”→ 演讲者“激情”澎湃，说到动情处拍心（胸脯）表示诚意。","ex":["I admire the passion and commitment shown by the players.","我钦佩运动员们表现出的激情和承诺。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"enthusiasm","p":"ɪnˈθjuːziæzəm","m":"n.热情；热忱；热心","tip":"en-（进入某种状态）+ thus（神）+ -iasm（名词后缀）→ 完全入神，全情投入 → 热情","ex":["It breeds long-term passion and enthusiasm.","它培养了长期的激情和热情。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"keen","p":"kiːn","m":"adj.渴望的；热切的；热情的；强烈的","tip":"单词发音类似“凯恩”→ 凯恩是英格兰著名足球运动员，球迷“渴望”见到他上场。","ex":["They are keen on high technology.","他们热衷于高科技。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"beat","p":"biːt","m":"v.打；打败；赢","tip":"单词发音类似“逼他”→ 成功的欲望逼他“打败”了对手。","ex":["Their children must excel and beat their white peers in academic settings so they have the same chances to excel later.","他们的孩子必须在学业上超越并打败他们的白人同龄人，这样他们以后才有同样的机会出类拔萃。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"beast","p":"biːst","m":"n.野兽；牲畜","tip":"单词发音类似“逼死他”→ 把别人逼死了，是“野兽”的行径。","ex":["The villagers finally banded together and scared the beast away with firecrackers and drums.","村民们最终团结起来，用爆竹和鼓把野兽吓跑了。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"battle","p":"ˈbætl","m":"n.战役；战斗 v.争论；斗争","tip":"bat（联想 beat）+ t（联想“他”）+ le（联想“了”）→ 打他了 → 战斗；斗争","ex":["In the battle against weight gain, people should pay more attention to exercise and less to what they eat and drink.","在对抗体重增加的战斗中，人们应该多注意锻炼，少注意饮食。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"fight","p":"faɪt","m":"v.打架；与……作斗争","tip":"单词发音类似“罚他”→ 如果他“打架”，他妈妈就会惩罚他。","ex":["Online programs to fight depression are already commercially available.","对抗抑郁症的在线程序已经上市了。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"struggle","p":"ˈstrʌɡl","m":"n.奋斗，努力 v.奋斗，努力；抗争；争夺","tip":"stru（音似“死抓”）+ gg（联想“哥哥”）+ le（联想“了”）→ 他死死抓住哥哥的手，鼓励他与病魔“抗争”。","ex":["They struggle to satisfy the demands of both work and home.","他们努力满足工作和家庭的需求。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"combat","p":"ˈkɒmbæt","m":"v.防止；减轻；战斗 n.战斗，打仗","tip":"com-（一起，都）+ bat（打）→ 战斗","ex":["He was killed in combat.","他在战斗中阵亡。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"whip","p":"wɪp","m":"n.鞭子 v.鞭策；鞭打","tip":"whi（音似 we）+ p（联想“扑”）→ 我们扑上去，把他手中的“鞭子”夺了过来，阻止他继续“鞭打”别人。","ex":["In a Los Angeles Times article, one employee referred to the board as a \"digital whip\".","在《洛杉矶时报》的一篇文章中，一名员工称该董事会为“数字鞭子”。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"conflict","p":"ˈkɒnflɪkt","m":"n.冲突，争执；战斗","tip":"con-（都）+ fli（联想 fly）+ ct（音似“剋”）→ 所有人都飞奔过来剋（打）他，从而引发了肢体“冲突”。","ex":["In order to learn the art of persuasion at the workplace, you need to understand how to handle conflicts and reach agreements.","为了在工作场所学习说服的艺术，你需要了解如何处理冲突和达成一致。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"confront","p":"kənˈfrʌnt","m":"v.面临，面对；对抗；解决（问题或困境）","tip":"con-（一起）+ front（面对）→ 一起面对 → 面对","ex":["Most people when confronted with a horse will pat it.","大多数人遇见马时都会轻轻地拍拍它。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"hit","p":"hɪt","m":"v.（用手或器具）打；撞到；达到 n.打；很受欢迎的人或事物","tip":"","ex":["The Britannic hit a naval mine in 1916 and subsequently sank as well.","“不列颠尼克号”在1916年撞上了一枚水雷，随后也沉没了。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"strike","p":"straɪk","m":"v.打，击；突然发生；罢工 n.罢工","tip":"st（联想 street）+ rike（联想 rock）→ 摇滚乐队的鼓手在街上“击”鼓。","ex":["Its crew members went on strike.","乘务组罢工了。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"striking","p":"ˈstraɪkɪŋ","m":"adj.引人注目的；异乎寻常的；显著的","tip":"strik（= strike）+ -ing（形容词后缀）→ 引人注目的","ex":["The similarities between the two cases are striking.","这两个案例之间的相似之处是惊人的。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"stroke","p":"strəʊk","m":"v.抚摸；击球，击打 n.抚摸；中风","tip":"吸烟（smoke）会增加中风（stroke）的风险。","ex":["What a beautiful stroke!","多漂亮的击球动作啊！"],"lesson":"u08-l04","group":"“打”相关"},{"w":"hammer","p":"ˈhæmə(r)","m":"n.锤子，榔头 v.锤打；敲打","tip":"单词发音类似“海摸”→ 他赶海的时候，在海里摸到一把“锤子”。","ex":["Smash the car window with a hammer when in danger.","在有危险时，要用锤子砸碎车窗。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"punch","p":"pʌntʃ","m":"n.重拳击打 v.拳打","tip":"单词发音类似“乓啧”→“重拳击打”到麻袋上会发出类似“乓啧”的声音。","ex":["He also figured out a new way to make a punch look real.","他还想出一个新办法，让出拳看起来像真的一样。"],"lesson":"u08-l04","group":"“打”相关"},{"w":"brunch","p":"brʌntʃ","m":"n.早午餐","tip":"br（= breakfast）+ unch（= lunch）→ 早午餐","ex":["What did you have for your brunch?","你早午餐吃了些什么？"],"lesson":"u08-l04","group":"“打”相关"},{"w":"debate","p":"dɪˈbeɪt","m":"n.（各自发表不同意见的）争论；讨论 v.（尤指正式）讨论，辩论","tip":"de-（往下）+ bate（联想 beat）→ 把对手往下打 → 争论；辩论","ex":["In the age of the Internet, there's no such thing as a private debate.","在互联网时代，没有所谓的私人辩论。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"dispute","p":"dɪˈspjuːt; ˈdɪspjuːt","m":"v.对……提出质询；对……表示异议（或怀疑）","tip":"dis-（分开）+ pute（考虑）→ 想法不一；各执己见 → 争论","ex":["Men are more likely to face that dispute from the perspective of what benefits them most.","从对他们最有利的角度来看，男性更有可能面对那种争论。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"argument","p":"ˈɑːɡjumənt","m":"n.争论；辩论；论据","tip":"argu（联想“阿哥”）+ -ment（名词后缀）→ 阿哥喜欢“辩论”。","ex":["The problem with this argument is that most children aren't playing outside or even spending time with other kids.","这个论点的问题是，大多数孩子都没有在外面玩，甚至没有花时间和其他孩子在一起。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"hint","p":"hɪnt","m":"n. & v.暗示，提示","tip":"单词发音类似“恨他”→ 她的眼神“暗示”她很恨他。","ex":["Should I drop a hint to Matt?","我应该给马特一点暗示吗？"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"demonstrate","p":"ˈdemənstreɪt","m":"v.证明；论证；说明；表现","tip":"demon（精力充沛的人）+ st（联想 street）+ rate（速度）→ 一群精力充沛的人在街上以很快的速度奔跑，“证明”自己的能力。","ex":["New research demonstrates why playing with blocks might have been time better spent.","新的研究证明了为什么玩积木或许可以更好地消磨时间。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"demo","p":"ˈdeməʊ","m":"n.游行示威；示范，演示；样品 v.试用；演示","tip":"","ex":["He demoed the new program he had just created.","他演示了他刚编写的新程序。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"explain","p":"ɪkˈspleɪn","m":"v.解释；说明；阐明","tip":"ex-（出来）+ plain（清晰的）→ 清晰地说出来 → 解释","ex":["First, I'll explain the rules of the game.","首先，我要说明一下游戏规则。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"illustrate","p":"ˈɪləstreɪt","m":"v.（用示例、图画等）说明，解释","tip":"ill（有病的）+ us（我们）+ trate（联想 trait）→ 他向我们举例“说明”有这种病的人的特征。","ex":["His success clearly illustrates the emergence of a huge sharing economy.","他的成功清楚地说明了一种巨大的共享经济的出现。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"imply","p":"ɪmˈplaɪ","m":"v.暗示；表明","tip":"","ex":["What does the author imply about the classes at present?","关于目前的课程，作者暗示了什么？"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"implicit","p":"ɪmˈplɪsɪt","m":"adj.含蓄的，不直接的；内含的；完全的","tip":"","ex":["The point is to use the results of this study to open up meaningful dialogues on implicit gender bias.","关键在于利用这项研究的结果，就隐含的性别偏见展开有意义的对话。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"explicit","p":"ɪkˈsplɪsɪt","m":"adj.明确的；清楚的","tip":"ex-（向外）+ plicit（联想 implicit）→ 不含蓄的 → 明确的；清楚的","ex":["Parents and teachers can help children by providing explicit instruction.","父母和老师可以通过提供明确的指导来帮助孩子。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"convey","p":"kənˈveɪ","m":"v.表达，传递；运送，输送","tip":"con-（所有的）+ vey（联想 way）→ 所有的东西都已在路上“运送”了。","ex":["This is your chance to convey boundless enthusiasm for the subject.","这是你表达对这门学科无限热情的机会。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"survey","p":"ˈsɜːveɪ","m":"n.民意调查；总体研究","tip":"sur-（上面）+ vey（联想 way）→ 他们正在路上“调查”真相。","ex":["The survey allowed for reading materials on a digital device.","这项调查允许在数字设备上阅读材料。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"invest","p":"ɪnˈvest","m":"v.投资；授予","tip":"in-（进入）+ vest（联想 west）→ 深入推进西部大开发需要大量“投资”。","ex":["They need to invest more in hospital staff and facilities.","他们需要在医院人员和设施方面加大投资。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"investigate","p":"ɪnˈvestɪɡeɪt","m":"v.调查；研究","tip":"invest（投资）+ i（我）+ gate（门）→ 我投资前会先在对方门口做“调查”。","ex":["The report calls for a commission to investigate the matter further.","该报告呼吁成立一个委员会来进一步调查此事。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"statistic","p":"stəˈtɪstɪk","m":"n.统计数字；统计学；（一项）统计数据","tip":"sta（联想 star）+ ti（联想“踢”）+ stic（联想 stick）→ 那个人即使踢到了木棍，依然仰望星空，因为他试图统计星星的数量 → 统计学","ex":["A man who can recite sports statistics from 30 years ago, may not remember to drop a letter in the mailbox.","一个能背诵30年前体育统计数据的人，可能不记得要往邮箱里投一封信。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"data","p":"ˈdeɪtə","m":"n.资料；数据（datum 的复数）","tip":"把数据（data）按照日期（date）顺序保存起来。","ex":["Coca-cola also released data detailing its funding.","可口可乐还公布了详细的资金数据。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"finding","p":"ˈfaɪndɪŋ","m":"n.调查发现；调研结果","tip":"","ex":["These findings suggest that there is no direct link between unemployment and crime.","这些调研结果表明失业和犯罪之间没有直接联系。"],"lesson":"u08-l04","group":"“争论、说明”相关"},{"w":"consent","p":"kənˈsent","m":"n. & v.同意；准许","tip":"con-（都）+ sent（send 的过去式）→ 我问他能否把所有玩具都送给我，他“同意”了。","ex":["You should not be afraid to show it or drastically change your behaviors—just ask for consent beforehand!","你不应该害怕表现出来或彻底改变你的行为——只要事先征得同意就行了！"],"lesson":"u08-l04","group":"sent 相关"},{"w":"resent","p":"rɪˈzent","m":"v.怨恨；感到气愤","tip":"re-（重复）+ sent（send 的过去式）→ 这个网站反复给我推送广告，真是让人生气 → 感到气愤","ex":["It is only natural that he should resent you.","他怨恨你是很自然的事。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"present","p":"prɪˈzent","m":"adj.出席的；现在的；存在的 n.礼物；现在","tip":"pre-（提前）+ sent（send 的过去式）→ 提前“出席的”人获得了举办方送的“礼物”。","ex":["They present their views clearly and explicitly.","他们清楚而明确地提出自己的观点。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"represent","p":"ˌreprɪˈzent","m":"v.代表；作为……的代言人；维护……的利益","tip":"re-（重复）+ present（展示）→ 重复展示 → 代表；作为……的代言人","ex":["Red, however, does not always represent good luck and happiness.","然而，红色并不总是代表好运和幸福。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"behalf","p":"bɪˈhɑːf","m":"n.代表；利益","tip":"be（是）+ half（一半）→ 我是一半群体的“代表”。","ex":["It has ignored campaigns on behalf of the left-handed.","它忽视了左利手的权益运动。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"absent","p":"ˈæbsənt","m":"adj.缺席的；不存在的","tip":"ab-（否定前缀）+ sent（send 的过去式）→ 因为我今天没送孩子去上学，所以她缺席了 → 缺席的","ex":["The man was absent from the weekly meeting.","这个人缺席了周会。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"missing","p":"ˈmɪsɪŋ","m":"adj.不在的；丢失的；缺少的","tip":"miss（不在，错过）+ -ing（形容词后缀）→ 不在的","ex":["He found the 60 pounds in his pocket missing.","他发现口袋里的60英镑不见了。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"exist","p":"ɪɡˈzɪst","m":"v.存在；（尤指在困境或贫困中）生存；生活","tip":"ex-（出）+ ist（联想 sist，站立）→ 站出来，出现 → 存在","ex":["They still existed six months after the course ended.","课程结束六个月后，它们仍然存在。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"punctual","p":"ˈpʌŋktʃuəl","m":"adj.准时的；守时的","tip":"punct（联想“怕个糗”）+ -ual（形容词后缀）→ 上课“准时的”人不怕迟到出糗。","ex":["They should make sure their children are always punctual for school.","他们应该确保他们的孩子总是准时上学。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"postpone","p":"pəˈspəʊn","m":"v.延迟；延期","tip":"post（邮寄）+ pone（联想 phone）→ 别人邮寄给我的手机因故“延迟”送达。","ex":["Millennials seem to be extending this phase of life as they postpone marriage.","千禧一代似乎通过推迟结婚来延长这一人生阶段。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"postage","p":"ˈpəʊstɪdʒ","m":"n.邮费；邮寄","tip":"post（邮寄）+ age（年代）→ 那个年代，“邮寄”东西的“邮费”很低。","ex":["The virtues of physical fitness are shown on magazine covers, postage stamps, and television ads.","杂志封面、邮票、电视广告里都展示了健身的优点。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"postcard","p":"ˈpəʊstkɑːd","m":"n.明信片","tip":"post（邮寄）+ card（卡片）→ 可以邮寄的卡片 → 明信片","ex":["Send your answers on a postcard to the above address.","把答案写在明信片上，寄到上述地址。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"delay","p":"dɪˈleɪ","m":"n.延期，延误 v.延期；推迟","tip":"de-（往下）+ lay（放）→ 把一件事情往下放 → 延期；推迟","ex":["They should learn to delay gratification so that they can pursue abstract goals, like going to college.","他们应该学会延迟满足，这样他们就可以追求抽象的目标，比如上大学。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"certificate","p":"səˈtɪfɪkət","m":"n.证书，证明书","tip":"他需要一个证书（certificate）来证明（certify）他的专业能力。","ex":["They can take all of the platform's classes and obtain professional certificates for free.","他们可以免费参加该平台的所有课程，并获得专业证书。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"certain","p":"ˈsɜːtn","m":"adj.某一；确定的 pron.某些","tip":"cert（确定）+ -ain（后缀）→ 确定的","ex":["Sometimes, rational analysis and data are impractical to be employed in certain situations.","有时，在某些情况下，理性分析和数据是不切实际的。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"licence","p":"ˈlaɪsns","m":"n.执照，许可证","tip":"单词发音类似“来审视”→ 驾照和“执照”都需要定期接受审查。","ex":["You also have to take the time to apply for your marriage licence.","你还得花点时间去申请结婚证。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"diploma","p":"dɪˈpləʊmə","m":"n.毕业文凭；学位证书","tip":"单词发音类似“弟扑了妈”→ 弟弟拿到“毕业文凭”后，激动地扑向了妈妈。","ex":["She is taking a diploma in management studies.","她在攻读管理学文凭课程。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"diplomat","p":"ˈdɪpləmæt","m":"n.外交官","tip":"diploma（毕业文凭）+ t（联想“他”）→ 他拿到毕业文凭以后成为一名“外交官”。","ex":["His creations soon captured the discriminating eye of a French diplomat.","他的作品很快就吸引了一位有鉴赏力的法国外交官的注意。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"embassy","p":"ˈembəsi","m":"n.大使馆","tip":"单词发音类似“俺办事”→ 我办理领事认证的地方是“大使馆”。","ex":["He drove past the embassy the other day.","前几天他开车经过大使馆。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"ambassador","p":"æmˈbæsədə(r)","m":"n.大使","tip":"大使馆（embassy）里面有大使（ambassador）。","ex":["It was donated by a U.S. ambassador.","它是由一位美国大使捐赠的。"],"lesson":"u08-l04","group":"sent 相关"},{"w":"pack","p":"pæk","m":"v.打包，收拾（行李）；装（箱） n.（商品的）纸包，纸盒，包装盒","tip":"单词发音类似“派客”→他的工作是给客户“打包”并派送包裹。","ex":["One had to quit abruptly on a given day, going from about a pack a day to zero.","吸烟者必须在某一天突然戒烟，从每天一包到零包。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"packet","p":"ˈpækɪt","m":"n.（商品的）小包装纸袋；（邮政）小件包裹","tip":"单词发音类似“派个他”→派他去送“小件包裹”。","ex":["He claims a packet of chips now contains less salt.","他声称，现在一袋薯片的含盐量更少了。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"parcel","p":"ˈpɑːsl","m":"n.包裹，邮包 v.包，打包","tip":"单词发音类似“怕馊”→妈妈怕饭馊了，用袋子把饭“包”起来放入冰箱。","ex":["It can be hard to identify which parcels are carrying crucial items.","很难确定哪些包裹里装的是关键物品。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"wrap","p":"ræp","m":"v.包，用……绕住；使文字换行 n.披肩，围巾；包裹物","tip":"单词发音类似“外婆”→冬天外婆总是用“围巾”“包”着头，防止受风寒。","ex":["Each apple was wrapped in paper.","每个苹果都用纸包着。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"towel","p":"ˈtaʊəl","m":"n.毛巾，手巾","tip":"单词发音类似“头”→他洗完头发，在头上包了条“毛巾”。","ex":["If you're going on a trip, it's a good idea to bring your own towel.","如果你要去旅行，最好自己带条毛巾。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"tower","p":"ˈtaʊə(r)","m":"n.塔 v.高于，超过","tip":"单词发音类似“塔窝”→塔","ex":["There is a tower at each corner of the castle.","城堡的每个角各有一个塔楼。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"veil","p":"veɪl","m":"n.（尤指女用的）面纱，面罩 v.戴面纱；掩饰；掩盖","tip":"v（形似罗马数字 5）+ e（联想“鹅”）+ il（联想 ill）→五只鹅生病了，要戴“面罩”，防止传染。","ex":["They see a benefit to successfully veiling their contempt for you.","他们认为成功地掩饰他们对你的蔑视是有好处的。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"mask","p":"mɑːsk","m":"n.面具；面罩；伪装 v.掩饰，掩盖","tip":"m（联想“妹”）+ ask（问）→妹妹很害羞，每次问问题都“掩盖”着嘴。","ex":["National data masks the variation in the performance of individual universities.","国家数据掩盖了个别大学表现的差异。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"naked","p":"ˈneɪkɪd","m":"adj.裸体的；裸露的；直白的","tip":"na（联想“那”）+ ked（联想“磕的”）→那磕到的伤口要保持“裸露的”状态。","ex":["They found him half naked and bleeding to death.","他们发现他身体半裸，流着血，快不行了。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"tissue","p":"ˈtɪʃuː","m":"n.纸巾，面巾纸，薄织物","tip":"单词发音类似“提漱”→他拿出一提“纸巾”，准备去洗漱。","ex":["They try to limit their usage of facial tissue to save money.","他们试图限制纸巾的使用，以节省开支。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"issue","p":"ˈɪʃuː","m":"n.问题；发行 v.发表；分发","tip":"单词发音类似“一休”→聪明的一休很会解决“问题”。","ex":["Increasingly states and companies are starting to take up the issue.","越来越多的州和公司开始关注这个问题。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"baggage","p":"ˈbæɡɪdʒ","m":"n.行李","tip":"bag（包）+ ga（音似“给”）+ ge（联想“哥”）→这包是给哥哥准备的“行李”。","ex":["Remember no more than 10 ounces of carry-on baggage are allowed.","记住随身携带的行李不能超过 10 盎司。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"burden","p":"ˈbɜːdn","m":"n.负担，重担 v.担负；负重","tip":"单词发音类似“笨蛋”→身边有个笨蛋是他的“负担”。","ex":["He has been burdened with excessive work.","他的工作负担过重。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"afford","p":"əˈfɔːd","m":"v.买得起；提供","tip":"af-（一再地）+ ford（联想“福特”）→他一再地看福特车是因为“买得起”。","ex":["They find it increasingly difficult to afford a place to live.","他们发现越来越难以负担住处。"],"lesson":"u09-l01","group":"“包裹”相关"},{"w":"fabric","p":"ˈfæbrɪk","m":"n.织物，布料；结构","tip":"单词发音类似“帆布”→帆布属于一种“布料”。","ex":["It's so hard to create fabric.","制作布料很困难。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"rag","p":"ræɡ","m":"n.破布，抹布；（pl.）破衣烂衫","tip":"ra（联想“让”）+ g（联想“哥”）→他让哥哥拿块“抹布”。","ex":["I wiped the window with a damp rag.","我用湿抹布擦窗户。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"textile","p":"ˈtekstaɪl","m":"n.纺织品，织物；纺织业","tip":"text（课文）+ i（我）+ le（联想“了”）→通过这篇课文，我了解了“纺织业”的发展史。","ex":["He got a job in textiles.","他在纺织行业找到一份工作。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"knit","p":"nɪt","m":"v.编织；（折骨）愈合；（使）紧密结合","tip":"单词发音类似“你他”→你和他联合完成了任务→紧密结合","ex":["The bone failed to knit correctly.","骨头愈合得不好。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"weave","p":"wiːv","m":"v.织，编；纺织","tip":"单词发音类似“为我”→妈妈为我“织”了件毛衣。","ex":["A bird must weave these materials into a nest.","鸟必须把这些材料编织成巢。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"wave","p":"weɪv","m":"n.波，波浪 v.（挥手）示意，致意","tip":"单词发音类似“喂，我”→有人在跟我打招呼→（挥手）示意，致意","ex":["The people on the bus waved and we waved back.","公共汽车上的人挥手致意，我们也向他们挥手。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"microwave","p":"ˈmaɪkrəweɪv","m":"n.微波炉，微波","tip":"micro-（微小）+ wave（波）→微波","ex":["The microwave and fast-food chains were the biggest catalysts.","微波炉和快餐连锁店是最大的催化剂。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"tide","p":"taɪd","m":"n.潮汐，潮水；潮水般的人流","tip":"","ex":["The tide swept in quickly at the beach.","潮水很快冲上了海滩。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"tidy","p":"ˈtaɪdi","m":"adj.整齐的，整洁的 v.整理；收拾","tip":"单词发音类似“泰迪”→他的那只泰迪犬是“整洁的”。","ex":["I keep our streets clean and tidy every day.","我每天保持我们的街道干净整洁。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"fibre","p":"ˈfaɪbə(r)","m":"n.（食物的）纤维，（布绳的）纤维","tip":"单词发音类似“饭钵”→我饭钵里的饭“纤维素”含量很高。","ex":["Breakfast foods are often higher in fibre and nutrients.","早餐食品的纤维含量和营养成分通常都较高。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"vitamin","p":"ˈvɪtəmɪn","m":"n.维生素","tip":"单词发音类似“维他命”→维他命是“维生素”的旧称。","ex":["Vitamins are complex substances that the body requires in very small amounts.","维生素是人体需要的极少量的复杂物质。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"protein","p":"ˈprəʊtiːn","m":"n.蛋白质","tip":"单词发音类似“脯肉疼”→他胸脯上的肉疼，可能缺乏“蛋白质”。","ex":["Vegetarian protein may be easier to absorb.","素食蛋白可能更容易吸收。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"nutrition","p":"njuˈtrɪʃn","m":"n.营养，营养学","tip":"单词发音类似“牛吹神”→“营养”品再牛也不能被吹成神药。","ex":["Nutrition information is now provided on the back of most food products.","现在大多数食品的背面都有营养信息。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"nuisance","p":"ˈnjuːsns","m":"n.令人讨厌的人或事物","tip":"单词发音类似“牛绅士”→这个“令人讨厌的人”假扮成一个很牛的绅士。","ex":["I don't want to be a nuisance, so tell me if you want to be alone.","我不想讨人嫌，所以你要是想一个人待着就说一声。"],"lesson":"u09-l01","group":"“纺织”相关"},{"w":"reputation","p":"ˌrepjuˈteɪʃn","m":"n.名誉，名声","tip":"re-（一再地）+ put（放）+ -ation（名词后缀）→一再把一个人的名字放到前面，说明这个人“名声”很大。","ex":["Since the 1940s, southern California has had a reputation for smog.","自 20 世纪 40 年代以来，南加州一直因雾霾闻名。"],"lesson":"u09-l01","group":"reputation 相关"},{"w":"fame","p":"feɪm","m":"n.名气；名声；声誉","tip":"famous adj. 著名的→fame n.","ex":["Its fame in high technology is incomparable.","它在高科技领域的名气是无与伦比的。"],"lesson":"u09-l01","group":"reputation 相关"},{"w":"image","p":"ˈɪmɪdʒ","m":"n.形象，样子；印象；声誉","tip":"i（我）+ m（联想“妈”）+ age（年龄）→我妈妈各个年龄段的“形象”都让我终生难忘。","ex":["The advertisements are intended to improve the company's image.","这些广告旨在提高公司的形象。"],"lesson":"u09-l01","group":"reputation 相关"},{"w":"imagine","p":"ɪˈmædʒɪn","m":"v.想象；设想，胡乱猜想；猜测","tip":"他试图把妈妈的形象（image）想象（imagine）出来。","ex":["I can imagine how many difficulties and obstacles you've conquered.","我可以想象你克服了多少困难和障碍。"],"lesson":"u09-l01","group":"reputation 相关"},{"w":"reply","p":"rɪˈplaɪ","m":"v.回答；回应；作出反应 n.回答；答复","tip":"re（字母音“阿姨”）+ ply（音似“不辣”）→吃火锅时，我问阿姨辣不辣，阿姨“回答”说不辣。","ex":["He hasn't replied to any of my text messages.","他还没有回复我的任何短信。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"relay","p":"ˈriːleɪ; rɪˈleɪ","m":"v.转发，转送；播放，转播（电视或广播信号）","tip":"re（字母音“阿姨”）+ lay（躺）→阿姨跑完“接力赛”，累得躺下了。","ex":["Patients are using new devices to relay their vital signs to their doctors.","患者正在使用新的设备将他们的生命体征传给医生。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"rely","p":"rɪˈlaɪ","m":"v.依靠，依赖；信赖","tip":"re-（回）+ ly（联想 lying）→他回家后就躺在沙发上→依靠，依赖","ex":["It would be rash to rely on such evidence.","依靠这样的证据太轻率了。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"reliable","p":"rɪˈlaɪəbl","m":"adj.可信赖的；可依靠的","tip":"","ex":["We are looking for someone who is reliable and hard-working.","我们在物色可靠而又勤奋的人。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"liable","p":"ˈlaɪəbl","m":"adj.（法律上）有责任的，有义务的；可能（做某事），倾向于","tip":"li（音似 lie，躺）+ able（音似“饿饱”）→“饿了站起来，饱了就躺下”的“可能”只有筷子。","ex":["You will be liable for any damage caused.","你必须对造成的任何损失负赔偿责任。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"credit","p":"ˈkredɪt","m":"n.信用，信誉；贷款；学分 v.信任；把……归于","tip":"credit card（信用卡）→credit（信誉）","ex":["They use credit cards for their daily purchases.","他们使用信用卡进行日常购物。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"credible","p":"ˈkredəbl","m":"adj.可信的；可靠的","tip":"","ex":["It is just not credible that she would cheat.","她会行骗简直难以置信。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"faithful","p":"ˈfeɪθfl","m":"adj.忠诚的，忠贞的；可信任的，可信赖的","tip":"faith（音似 face）+ -ful（形容词后缀）→看他的脸就知道他是个“可信赖的”人。","ex":["Friends should always be faithful to each other.","朋友应该永远对彼此忠诚。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"loyal","p":"ˈlɔɪəl","m":"adj.忠诚的；忠实的","tip":"单词发音类似“老友”→老朋友是对我们“忠诚的”人。","ex":["Consumers are loyal to certain brands.","消费者对某些品牌很忠诚。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"royal","p":"ˈrɔɪəl","m":"adj.皇家的，王室的 n.王室成员","tip":"","ex":["He regards his royal duties as a burden.","他认为王室职责是一种负担。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"noble","p":"ˈnəʊbl","m":"n.贵族成员 adj.贵族的；高贵的","tip":"no（不）+ ble（音似“抱”）→不抱谄媚之心，坚守“高贵的”尊严。","ex":["He was not a noble, but the son of a leather trader.","他不是一个贵族，而是一个皮革商人的儿子。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"crown","p":"kraʊn","m":"n.皇冠，王冠，冕；花冠","tip":"cr（联想“超人”）+ own（拥有）→超人拥有自己的“王冠”。","ex":["The king in the picture is wearing a crown.","照片中的国王戴着一顶王冠。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"queen","p":"kwiːn","m":"n.女王，女首领；王后","tip":"扑克牌中的 Q 就是 queen，代表“女王”。","ex":["She became queen at the age of fifteen.","她 15 岁时成为女王。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"queue","p":"kjuː","m":"n.队，行列 v.排队","tip":"女王（queen）出门也会排队（queue），以示亲民。","ex":["There were long queues at polling stations.","投票站排起了长队。"],"lesson":"u09-l01","group":"“信赖、皇家”相关"},{"w":"considerate","p":"kənˈsɪdərət","m":"adj.考虑周到的；为（他人）着想的；体贴的","tip":"consider（考虑）+ ate（eat 的过去式）→ 连吃都考虑到了 → 考虑周到的；体贴的","ex":["It was very considerate of him to wait.","他一直在等候着，真是体贴。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"considerable","p":"kənˈsɪdərəbl","m":"adj.相当多的；相当大的；可以考虑的","tip":"consider（考虑）+ -able（能够……的）→ 可以考虑的","ex":["The project wasted a considerable amount of time and money.","那项工程耗费了相当多的时间和资金。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"consideration","p":"kənˌsɪdəˈreɪʃn","m":"n.仔细考虑；斟酌；必须考虑的事","tip":"consider（考虑）+ -ation（名词后缀）→ 仔细考虑；斟酌","ex":["Her ideas are worthy of serious consideration.","她的想法值得仔细考虑。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"diligent","p":"ˈdɪlɪdʒənt","m":"adj.勤劳的，勤奋的；细致的；潜心的","tip":"di（音似“弟”）+ ligen（音似“历尽”）+ t（联想“他”）→ “勤奋的”弟弟历尽艰辛，终于考进了他理想的大学。","ex":["Such a brilliant and diligent girl! She deserves it.","多么聪明、勤奋的女孩！她值得。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"labour","p":"ˈleɪbə(r)","m":"n.劳动；工作；劳动力","tip":"单词发音类似“累不”→ 正在“劳动”的你累不累？","ex":["It created a pool of labour for factories.","它为工厂创造了大量劳动力。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"frank","p":"fræŋk","m":"adj.坦白的，直率的","tip":"弗兰克（Frank）是一个直率的（frank）孩子。","ex":["What is needed is a frank exchange of views.","（我们）需要的是坦诚的意见交换。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"honesty","p":"ˈɒnəsti","m":"n.诚实；老实；正直","tip":"honest adj.诚实的 → honesty n.","ex":["She answered all my questions with her usual honesty.","她像平常一样老老实实地回答了我的所有问题。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"moral","p":"ˈmɒrəl","m":"adj.道德的；品行端正的；有道德的","tip":"m（联想“妈”）+ oral（口头的）→ 妈妈口头上教育我们要做“品行端正的”人。","ex":["They make sensible decisions when facing moral dilemmas.","面对道德困境时，他们会做出明智的决定。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"oral","p":"ˈɔːrəl","m":"adj.口腔的；口头的","tip":"","ex":["Particular emphasis will be placed on oral language training.","口语训练将被予以非同寻常的重视。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"ethic","p":"ˈeθɪk","m":"n.道德体系；行为准则；道德","tip":"单词发音类似“爱思考”→ 他爱思考“道德”问题。","ex":["This is a code of ethics.","这是一项道德规范。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"ethnic","p":"ˈeθnɪk","m":"adj.种族的；民族的","tip":"单词发音类似“爱死尼克”→ 她特别爱尼克（人名），甚至专门去了解了他们“民族的”习俗。","ex":["They have the same ethnic background.","他们有相同的种族背景。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"racial","p":"ˈreɪʃl","m":"adj.人种的，种族的","tip":"rac(e)（人种，种族）+ -ial（形容词后缀）→ 人种的，种族的","ex":["Teachers don't have to share the same racial or ethnic background as their students.","老师和学生不必有相同的种族或民族背景。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"radical","p":"ˈrædɪkl","m":"adj.根本的；彻底的；激进的，极端的 n.激进分子；游离基","tip":"ra（联想“让”）+ dical（音似“弟扣”）→ 让那么小的弟弟学扣篮，太激进了 → 激进的，极端的","ex":["A new technology has the potential to change modern society in radical ways.","一项新技术有可能彻底改变现代社会。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"merit","p":"ˈmerɪt","m":"n.优点；美德；价值","tip":"me（我）+ r（形似花）+ it（它）→ 我知道这种花有很多“优点”，所以养了它。","ex":["The plan is entirely without merit.","这个计划毫无价值。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"virtue","p":"ˈvɜːtʃuː","m":"n.正直的品性；优点；美德；良好习惯","tip":"vi（形似罗马数字 6）+ r（形似花）+ tue（联想 true）→ 他得到六朵小红花，说明他的“优点”真的很多。","ex":["He always emphasised the virtues of compromise and conciliation.","他总是强调妥协与和解的优点。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"violent","p":"ˈvaɪələnt","m":"adj.暴力的；猛烈的","tip":"vi（形似罗马数字 6）+ o（形似圈）+ lent（借）→ 六个人把他围在圈中间借钱，这是一种“暴力的”威胁。","ex":["Do violent video games lead to violence?","暴力电子游戏会导致暴力吗？"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"violate","p":"ˈvaɪəleɪt","m":"v.违反，违背；侵犯；妨碍；亵渎","tip":"vi（形似罗马数字 6）+ o（形似球）+ late（迟到）→ 六个人因为打球上课迟到，“违反”了学校的纪律。","ex":["She accused the press photographers of violating her privacy.","她指责新闻摄影记者侵犯了她的隐私。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"defy","p":"dɪˈfaɪ","m":"v.违抗；违反，违背；蔑视；经受住","tip":"单词发音类似“抵法”→ 抵制法律实施是“违反”法律的行为。","ex":["I wouldn't have dared to defy my teachers.","我可不敢违背老师的话。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"obey","p":"əˈbeɪ","m":"v.遵守，服从，听从","tip":"单词发音类似“我辈”→ 我辈新青年，都要“遵守”法律。","ex":["Dogs can be trained to obey orders.","狗可以被训练听从命令。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"isolate","p":"ˈaɪsəleɪt","m":"v.（使）隔离，孤独，孤立，脱离","tip":"i（我）+ so（如此）+ late（晚）→ 我来得如此晚，是因为我被“隔离”了。","ex":["Patients with the disease should be isolated.","这种病的患者应予以隔离。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"via","p":"ˈvaɪə; ˈviːə","m":"prep.经由，经过；通过，凭借","tip":"vi（形似罗马数字 6）+ a（形似小乌龟）→ 六只小乌龟“经由”此处过了河。","ex":["Emergency workers have made contact with the miners via a radio.","紧急救援人员通过无线电与矿工取得了联系。"],"lesson":"u09-l02","group":"“人类品质”相关"},{"w":"limit","p":"ˈlɪmɪt","m":"n.限度，限制；界限，边界 v.限制","tip":"单词发音类似“立美她”→ 他想尽一切办法立刻美化她，没有任何“限制”。","ex":["They imposed a strict spending limit.","他们实施了严格的开支限制。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"infinite","p":"ˈɪnfɪnət","m":"adj.无限的，无穷的；极大的，极多的 n.无限的事物","tip":"in-（无）+ fin（范围）+ -ite（形容词后缀）→ 没有范围的 → 无限的","ex":["A teacher must be capable of infinite patience.","教师必须具有无限的耐心。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"define","p":"dɪˈfaɪn","m":"v.给（词语）下定义，解释；阐明","tip":"de-（分开）+ fin(e)（范围）→ 把不同的范围分开 → 给（词语）下定义，解释","ex":["The term \"mental illness\" is difficult to define.","\"精神病\"这个词很难下定义。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"definite","p":"ˈdefɪnət","m":"adj.清楚的，明确的；确定的","tip":"defin(e)（下定义）+ -ite（形容词后缀）→（已经）下定义的 → 明确的","ex":["No definite conclusions can be drawn from this study.","从这项研究中不能得出明确的结论。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"confine","p":"kənˈfaɪn","m":"v.约束，限制，局限","tip":"con-（一起）+ fin(e)（范围）→ 一起划定范围 → 约束；限制","ex":["The dominance of television was not confined to our living rooms.","电视的主导地位并不局限于我们的客厅。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"refine","p":"rɪˈfaɪn","m":"v.精炼；提纯；改进；改善","tip":"re-（再）+ fine（好的）→ 好上加好 → 精炼；改进","ex":["Groups like these will help you refine your analytical skills and enable you to express yourself better.","像这样的小组将帮助你改善分析能力，让你更好地表达自己。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"fine","p":"faɪn","m":"n.罚金，罚款 v.罚款 adj.很好的；不错的，身体好的；精致的；晴朗的","tip":"单词发音类似“罚”→ 罚款","ex":["If you do not, you could be fined up to £50.","如果你不这样做，你可能会被处以最高 50 英镑的罚款。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"emphasise","p":"ˈemfəsaɪz","m":"v.强调；重视；使突出","tip":"em-（= en-，使）+ pha（音似“佛”）+ size（尺寸）→ 他“强调”要使佛像的尺寸合适。","ex":["The author emphasises being anumeric does not affect one's cognitive ability.","作者强调不识数并不影响一个人的认知能力。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"analyse","p":"ˈænəlaɪz","m":"v.分析，分解，解析","tip":"a(n)（音似“俺”）+ na（联想“奶”）+ ly（联想 lying）+ se（联想“色”）→ 俺奶躺在绿色的床上“分析”我晚到的原因。","ex":["The researcher studied the videotapes to analyse the matches in detail.","研究人员研究了录像以便详细分析比赛。"],"lesson":"u09-l02","group":"fin 相关"},{"w":"professional","p":"prəˈfeʃənl","m":"adj.职业的；专业的 n.专家","tip":"教授（professor）就是在某个学科领域特别专业的（professional）人。","ex":["With this comprehensive knowledge of the history of art, he has since become a professional painter.","凭借对艺术史的全面了解，他从此成了一名专业画家。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"profession","p":"prəˈfeʃn","m":"n.职业；专业","tip":"职业（profession）发展往往需要专业的（professional）知识。","ex":["It is necessary to use terms other than gamification for some professions.","对于某些职业，有必要使用游戏化以外的术语。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"confess","p":"kənˈfes","m":"v.承认，坦白；忏悔","tip":"con-（都）+ fess（说，承认）→ 把做过的事都说了 → 承认，坦白","ex":["I confessed that I was wrong.","我承认我错了。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"occupy","p":"ˈɒkjupaɪ","m":"v.使用，占用；忙着（做某事）","tip":"","ex":["People occupy valuable table space in quiet times.","在淡季的时候，人们占用宝贵的餐桌空间。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"occupation","p":"ˌɒkjuˈpeɪʃn","m":"n.职业，工作","tip":"occup(y)（占用）+ -ation（名词后缀）→ 每天占用我们很多时间的就是“工作”。","ex":["It's commonly known that certain diseases are linked with occupations.","众所周知，某些疾病与职业有关。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"philosophy","p":"fəˈlɒsəfi","m":"n.哲学，哲理","tip":"单词发音类似“费老师费”→ 费老师花费时间教他“哲学”。","ex":["This philosophy applies in many areas of life.","这种哲学在生活的许多领域适用。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"barber","p":"ˈbɑːbə(r)","m":"n.理发师","tip":"单词发音类似“叭叭”→ 那个“理发师”叭叭地向客户推销理发卡。","ex":["They collected 200 hair samples from 65 barber shops.","他们从 65 家理发店收集了 200 份头发样本。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"amateur","p":"ˈæmətə(r)","m":"n.业余爱好者；外行 adj.业余的","tip":"单词发音类似“爱莫他”→ 他爱莫能助，因为他是“业余的”。","ex":["The amateur tradition in music criticism has been in headlong retreat.","音乐评论的业余传统已在迅猛衰退。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"veteran","p":"ˈvetərən","m":"n.老兵，退伍军人；老手；经验丰富的人","tip":"v（形似罗马数字 5）+ ete（形似人脸）+ ran（run 的过去式）→ 五个“老兵”通过变脸化妆逃跑了。","ex":["It's creating some tension between newcomers and veterans.","它在新人和老手之间制造了一些紧张。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"sophisticated","p":"səˈfɪstɪkeɪtɪd","m":"adj.见多识广的；老练的；精密的；先进的","tip":"大二学生（sophomore）在学校待了两年，变成老练的（sophisticated）人了。","ex":["USPS has sophisticated emergency plans for natural disasters.","美国邮政有针对自然灾害的精密应急计划。"],"lesson":"u09-l02","group":"profession 相关"},{"w":"clarify","p":"ˈklærəfaɪ","m":"v.澄清，阐明","tip":"clar（清楚，明白）+ -ify（使……化）→ 澄清，阐明","ex":["It is an attempt to clarify misunderstanding about the origin of language.","它试图澄清对语言起源的误解。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"confirm","p":"kənˈfɜːm","m":"v.证实，证明；批准","tip":"con-（表加强）+ firm（坚固）→ 使（观点）坚固 → 证实，证明","ex":["The authorities refused to confirm any details.","当局拒绝证实任何细节。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"firm","p":"fɜːm","m":"n.商行；商号；公司 adj.坚固的；结实的；牢固的","tip":"这家公司（firm）的形式（form）很特别。","ex":["He doesn't feel at ease in the firm.","他在公司里感到不自在。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"affirm","p":"əˈfɜːm","m":"v.证实；确认；肯定，断言","tip":"af-（表加强）+ firm（坚固的）→ 使（观点）变得坚固 → 证实；断言","ex":["The state affirms its supreme power over the individuals within its own borders.","该国确认其对自己境内的个人有最高领导权。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"claim","p":"kleɪm","m":"v.声称；索取 n.声称，主张；索赔","tip":"c（音似“可”）+ laim（联想“拉妹”）→ 姐姐“声称”可以拉住妹妹，不让她乱跑。","ex":["She claimed to hate all art.","她声称讨厌所有艺术。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"proclaim","p":"prəˈkleɪm","m":"v.宣告，公布；声明","tip":"pro-（向前）+ claim（声称）→ 向前面（的人）声称 → 宣告，公布","ex":["The president proclaimed a state of emergency.","总统宣告了紧急状态。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"acclaim","p":"əˈkleɪm","m":"n.赞扬，高度评价 v.给予高度评价","tip":"ac-（= to，对）+ claim（声称）→ 赞扬","ex":["The film met with considerable critical and public acclaim.","这部电影得到了评论和公众的广泛赞扬。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"exclaim","p":"ɪkˈskleɪm","m":"v.呼喊，呼叫，大声说","tip":"ex-（外）+ claim（声称）→ 呼喊，呼叫","ex":["The player proceeded to rub his gloves and then exclaimed.","这名球员继续揉搓他的手套，然后呼喊起来。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"whisper","p":"ˈwɪspə(r)","m":"v.耳语，低语，小声说 n.耳语（声）；低语（声）","tip":"whi（音似 we）+ sper（音似“撕破”）→ 我们撕破脸了，这种事要“小声说”。","ex":["Pay attention to the whispers so you won't have to hear the screams.","留心于低声细语，便听不见嘶吼声。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"whistle","p":"ˈwɪsl","m":"n.口哨 v.吹口哨","tip":"whi（音似 we）+ stle（音似“哨”）→ 我们一起“吹口哨”。","ex":["He kept shouting, blowing his whistle to stop the excited players.","他不停地喊着，吹着哨子阻止那些兴奋的球员。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"declare","p":"dɪˈkleə(r)","m":"v.公布；宣布；声称，宣称","tip":"dec（音似“弟可”）+ la（联想“拉”）+ re（字母音似“阿姨”）→ 弟弟“宣布”他可算拉住阿姨了。","ex":["\"Play is not silly behaviour,\" the academy's report declares.","该学院的报告宣称，\"玩耍不是愚蠢的行为。\""],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"announce","p":"əˈnaʊns","m":"v.宣布；通知；声称","tip":"","ex":["They will announce their engagement.","他们将宣布订婚。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"admire","p":"ədˈmaɪə(r)","m":"v.赞美，赞赏，钦佩","tip":"ad-（一再地）+ m（联想“妹”）+ i（我）+ re（字母音似“阿姨”）→ 我和妹妹一再地围着阿姨，因为我们“钦佩”她。","ex":["They admire the courage of space explorers.","他们钦佩太空探险者的勇气。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"adore","p":"əˈdɔː(r)","m":"v.崇拜，爱慕；非常喜欢","tip":"ad-（一再地）+ o（形似圈）+ re（字母音似“阿姨”）→ 孩子们一再地在阿姨周围围成一个圈，因为他们都“非常喜欢”阿姨。","ex":["All the children adored the girl as their elder sister.","所有孩子都非常喜欢这个女孩，把她当作他们的大姐姐。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"worship","p":"ˈwɜːʃɪp","m":"n. & v.崇拜，敬仰；礼拜","tip":"wor（音似“哇”）+ ship（船）→ “哇！船！”孩子们“崇拜”地看着大船喊。","ex":["In ancient times, many nations worshipped different gods.","在古代，很多民族崇拜不同的神灵。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"envy","p":"ˈenvi","m":"n. & v.羡慕；忌妒","tip":"单词发音类似“恩威”→ 他“羡慕”那个杀伐果断、恩威并施、受人爱戴的君主。","ex":["Being an information technology, or IT, worker is not a job I envy.","我并不羡慕从事信息技术（IT）工作的人。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"jealous","p":"ˈdʒeləs","m":"adj.妒忌的；猜疑的；爱惜的","tip":"单词发音类似“姐乐思”→ 姐姐说，遇到乐事时不要张扬，免得让其他人起了“妒忌”的心思。","ex":["She's jealous of my success.","她忌妒我的成功。"],"lesson":"u09-l02","group":"“澄清、说明”相关"},{"w":"apply","p":"əˈplaɪ","m":"v.申请；应用，适用","tip":"","ex":["They learned about the growth mindset and how to apply it to schoolwork.","他们学习了成长型思维模式，以及如何将其应用到学校作业中。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"utilise","p":"ˈjuːtəlaɪz","m":"v.利用，使用","tip":"u（联想 use）+ ti（音似“特”）+ l + -ise/-ize（动词后缀）→ 特别使用 → 利用，使用","ex":["Languages that exist today vary dramatically in how they utilise numbers.","现存的语言在使用数字的方式上有着巨大的差异。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"applicable","p":"əˈplɪkəbl; ˈæplɪkəbl","m":"adj.适用的；合适的","tip":"","ex":["It is obvious that this new rule is applicable to everyone without exception.","很明显，这条新规则适用于每个人，无一例外。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"appliance","p":"əˈplaɪəns","m":"n.（家用）电器，器具","tip":"apply v.运用 → appliance n.","ex":["Consumers could use appliances in a more efficient way by adjusting the time of cooking.","消费者可以调整烹饪时间，从而更有效地使用电器。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"implement","p":"ˈɪmplɪment","m":"v.实施，执行","tip":"i（我）+ m（联想“妹”）+ plemen（联想“破了门”）+ t（联想“他”）→ 我妹妹破门而入抓捕他，是在“执行”任务。","ex":["Managers should implement solutions.","管理者应该实施解决方案。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"supply","p":"səˈplaɪ","m":"v.供应；满足（需要）；提供，供给 n.供应；存货；必需品","tip":"这家餐厅经常提供（supply）免费晚饭（supper）。","ex":["Advances in agriculture increased the food supply.","农业的进步增加了粮食供应。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"supplement","p":"ˈsʌplɪmənt","m":"n.补充（物）；添加物","tip":"supply v.供应 → supplement n.","ex":["He used a potent ingredient in a food supplement.","他在食品补充剂中使用了一种强效成分。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"provide","p":"prəˈvaɪd","m":"v.提供，供给；给予；规定","tip":"pro-（提前）+ vi（形似罗马数字 6）+ de（联想“的”）→ 我们六个提前去那个人的家，给他“提供”了一些食物。","ex":["They provide shelter for the farmers.","他们为农民提供住所。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"provided","p":"prəˈvaɪdɪd","m":"conj.如果，假如，只要","tip":"","ex":["We'll buy everything you produce, provided of course the price is right.","当然如果价格合适的话，我们将采购你方生产的全部产品。"],"lesson":"u09-l03","group":"apply 相关"},{"w":"tend","p":"tend","m":"v.趋向于；往往会","tip":"我们做不到十（ten）全十美，只能趋向于（tend）完美。","ex":["People who prioritise breakfasts tend to have lower calorie but higher nutritional intake.","优先吃早餐的人往往摄入的热量较低，但营养较高。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"tendency","p":"ˈtendənsi","m":"n.倾向，偏好；趋势","tip":"","ex":["Great benefit and great harm can come from the same human tendency.","同样的人类倾向可能带来巨大的利益，也可能带来巨大的危害。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"trend","p":"trend","m":"n.倾向，趋势","tip":"tren（音似“穿”）+ d（联想“搭”）→ 潮人会按照流行“趋势”来穿搭。","ex":["This is not necessarily a new trend, but it is a somewhat puzzling one.","这未必是一种新趋势，但多少有点令人费解。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"extend","p":"ɪkˈstend","m":"v.延长，延伸，伸展","tip":"ex-（外）+ tend（伸）→ 往外延伸 → 延长，伸展","ex":["Their average lifespan has been considerably extended.","它们的平均寿命大大延长。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"stretch","p":"stretʃ","m":"v.伸展；延伸 n.伸展；弹性","tip":"单词发音类似“死拽扯”→ 他伸出手臂死死地扯拽对方 → 伸展","ex":["She stretched up to reach the top shelf.","她伸手向上去够顶层架子。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"extent","p":"ɪkˈstent","m":"n.广度，宽度，长度；程度；范围","tip":"ex-（出）+ tent（= tend，伸）→ 程度；范围","ex":["I do agree with him to an extent.","我在一定程度上确实同意他的意见。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"attend","p":"əˈtend","m":"v.出席，参加；照顾；注意，专心","tip":"at-（表加强）+ tend（伸）→（身体）延伸至某处 → 参加","ex":["Offering online classes certainly helps students who would otherwise not be able to attend classroom sessions.","提供在线课程当然可以帮助那些无法参加课堂教学的学生。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"contend","p":"kənˈtend","m":"v.主张，认为；竞争","tip":"con-（共同）+ tend（伸）→ 共同伸向 → 主张","ex":["I would contend that the minister's thinking is flawed on this point.","我倒认为部长的想法在这一点上有漏洞。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"intend","p":"ɪnˈtend","m":"v.打算，想要；意指","tip":"in（里面）+ tend（伸）→（想法）在里面（内心）延伸 → 打算","ex":["It intends to keep its traditional diet.","它打算保持传统饮食。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"intention","p":"ɪnˈtenʃn","m":"n.打算，意图，目的","tip":"intend v.打算，想要 → intention n.","ex":["The intention to put a home-cooked meal on the table was pretty much universal.","把家常菜摆上餐桌的意图几乎是普遍的。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"pretend","p":"prɪˈtend","m":"v.假装，佯装；模拟；自认为","tip":"pre-（提前）+ tend（伸）→ 提前伸展，行为超出实际 → 假装","ex":["He pretended not to notice.","他假装没注意。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"disguise","p":"dɪsˈɡaɪz","m":"v.假扮；装扮；伪装 n.伪装物","tip":"dis（音似“弟似”）+ gui（联想“鬼”）+ se（联想“色”）→ 万圣节弟弟“装扮”得好似个鬼，把我吓得脸色苍白。","ex":["She disguised herself as a boy.","她女扮男装。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"fake","p":"feɪk","m":"adj.假的；伪造的 n.假货 v.伪造；冒充；假装，伪装","tip":"fa（联想 father）+ ke（联想“磕”）→ 爸爸“假装”磕到了，想吸引儿女注意。","ex":["The fake websites have authentic-sounding names involving a mix of keywords.","这些假冒网站的名字听起来很真实，其中包含多个关键字。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"simulate","p":"ˈsɪmjuleɪt","m":"v.模仿，模拟；假装","tip":"simu（联想“四目”）+ late（迟到）→ 班长“假装”有四只眼睛，能抓住从各个方向跑来的迟到者。","ex":["Over the centuries, they have simulated dialogues in a number of ways.","几个世纪以来，他们以多种方式模拟对话。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"stimulate","p":"ˈstɪmjuleɪt","m":"v.促进；激发；激励；刺激","tip":"同桌一个劲地模仿（simulate）他（t），他就受刺激（stimulate）了。","ex":["The teacher is able to stimulate students' curiosity.","这位老师能激发学生的好奇心。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"spur","p":"spɜː(r)","m":"v.鞭策；激励；刺激 n.马刺；鞭策；激励","tip":"单词发音类似“死破”→ 尽管他的衣服很破，但他坚持“鞭策”自己努力学习。","ex":["Let the cheers from the crowd spur you on.","让人群的欢呼声激励你前进。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"imitate","p":"ˈɪmɪteɪt","m":"v.模仿，仿制","tip":"i（我）+ m（联想“门”）+ it（联想“它”）+ ate（eat 的过去式）→ 我小时候会“模仿”门外的它（小动物）吃东西。","ex":["The dancers move in harmony as they imitate the animal's natural movements in the wild.","舞者们在模仿野生动物的自然动作时，动作很和谐。"],"lesson":"u09-l03","group":"tend 相关"},{"w":"convenience","p":"kənˈviːniəns","m":"n.方便，便利；方便的东西","tip":"con-（都）+ venien（音似“为您”）+ ce → 他做这一切都是为了您的“方便”。","ex":["A growing number of bike riders are attracted to electric bikes for convenience.","越来越多的自行车爱好者被电动自行车所吸引，因为它们方便。"],"lesson":"u09-l03","group":"“方便”相关"},{"w":"handy","p":"ˈhændi","m":"adj.手边的；便于使用的，方便的","tip":"那本书就在你的手（hand）边，非常方便（handy）拿取。","ex":["Always keep a first-aid kit handy.","手边要常备急救箱。"],"lesson":"u09-l03","group":"“方便”相关"},{"w":"handwriting","p":"ˈhændraɪtɪŋ","m":"n.手写，书写；笔迹；书法","tip":"hand（手）+ writing（写）→ 手写","ex":["His handwriting has a unique style.","他的书法风格独特。"],"lesson":"u09-l03","group":"“方便”相关"},{"w":"convince","p":"kənˈvɪns","m":"v.使确信；使相信；使信服；说服","tip":"con-（一起，共同）+ vinc(e)（征服）→ 使相信","ex":["It convinced the public that fashionable clothes should be made durable.","它使公众相信，时尚的衣服应该经久耐穿。"],"lesson":"u09-l03","group":"“方便”相关"},{"w":"lobby","p":"ˈlɒbi","m":"v.游说 n.游说团体；大厅；（英国议会中的）民众接待厅","tip":"单词发音类似“老辈”→ 有些老一辈的人经常“游说”年轻人。","ex":["Farmers will lobby Congress for higher subsidies.","农民将游说国会提高补贴。"],"lesson":"u09-l03","group":"“方便”相关"},{"w":"doubtful","p":"ˈdaʊtfl","m":"adj.拿不定主意的；不确定的；怀疑的","tip":"doubt（怀疑）+ -ful（形容词后缀）→ 不确定的；怀疑的","ex":["Americans are less doubtful when it comes to politics.","美国人在政治问题上没有那么多疑。"],"lesson":"u09-l03","group":"“方便”相关"},{"w":"disaster","p":"dɪˈzɑːstə(r)","m":"n.灾难，灾祸","tip":"dis-（表否定）+ aster（= star）→ 以前的人认为，星位不正预示着可能有“灾难”。","ex":["Natural disasters can wreck a community's infrastructure.","自然灾害可以摧毁一个社区的基础设施。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"famine","p":"ˈfæmɪn","m":"n.饥荒，饥饿","tip":"fa（联想“发”）+ mi（联想“米”）+ ne（联想“呢”）→ 这里闹“饥荒”了，政府在发米呢。","ex":["Occurrences of shortages and droughts are causing famine and distress in some areas.","（粮食）短缺和干旱的发生正在一些地区造成饥荒和灾难。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"volcano","p":"vɒlˈkeɪnəʊ","m":"n.火山","tip":"vol（音似“我”）+ can（能）+ o（形似圈）→ 我能圈出地图上的“火山”。","ex":["They nest on the volcano's slopes.","它们在火山的斜坡上筑巢。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"vague","p":"veɪɡ","m":"adj.模糊的，不清楚的","tip":"单词发音类似“喂，哥”→ 他打电话时一直喊“喂，哥！”，因为电话听不清楚 → 模糊的，不清楚的","ex":["Most people will be able to give a vague description of their main meals.","大多数人都能对他们的主餐进行一个模糊的描述。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"blur","p":"blɜː(r)","m":"n.模糊的记忆 v.（使）变得模糊不清","tip":"单词发音类似“不乐”→ 这个老人不太快乐，因为他看东西有点模糊 → （使）变得模糊不清","ex":["Tears blurred her eyes.","泪水模糊了她的视线。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"dim","p":"dɪm","m":"adj.昏暗的；朦胧的；模糊的，不清楚的","tip":"di-（= bi-，两个）+ m（联想“妹”）→ “昏暗的”夜色下，我把一个妹妹看成两个了。","ex":["This light is too dim to read by.","这光线太暗，看不了书。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"district","p":"ˈdɪstrɪkt","m":"n.区；地区，区域","tip":"di-（两个）+ strict（严格）→ 重庆和北京两个“地区”的安检都很严格。","ex":["The school district was facing a crisis.","这个学区正面临危机。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"disgust","p":"dɪsˈɡʌst","m":"n.厌恶，恶心，反感 v.使人厌恶，使人作呕","tip":"dis-（不）+ gu（联想“姑”）+ st（联想 street）→ 姑姑从不在街上吃小吃，她认为那样不文雅 → 厌恶，反感","ex":["He walked away in disgust.","他厌恶地走开了。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"disturb","p":"dɪˈstɜːb","m":"v.打扰；使烦恼","tip":"单词发音类似“弟是特不”→ 弟弟真是特别不懂事，总是“打扰”别人。","ex":["If you get up early, try not to disturb everyone else.","如果你起得早，尽量不要打扰别人。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"dimension","p":"daɪˈmenʃn; dɪˈmenʃn","m":"n.维度，范围，规模，尺寸","tip":"di-（两个）+ mension（音似“门神”）→ 春节时我家门上要贴两个“尺寸”一样的门神。","ex":["We measured the dimensions of the kitchen.","我们量了厨房的尺寸。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"column","p":"ˈkɒləm","m":"n.柱，圆柱；专栏","tip":"单词发音类似“靠了门”→ 靠在门两边的柱子，通常都是“圆柱”。","ex":["She might close his Monday column.","她可能会关闭他周一的专栏。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"anchor","p":"ˈæŋkə(r)","m":"n.锚；支柱 v.抛锚；使固定","tip":"单词发音类似“安个”→ 安装个“锚”，可以让船停靠得更稳定。","ex":["They cast anchor at nightfall.","他们傍晚抛锚停泊。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"ankle","p":"ˈæŋkl","m":"n.踝，踝关节","tip":"单词发音类似“俺磕”→ 俺磕到脚“踝”了。","ex":["She broke her ankle.","她摔断了踝关节。"],"lesson":"u09-l03","group":"disaster 相关"},{"w":"respond","p":"rɪˈspɒnd","m":"v.（口头或书面）回答，回应；作出反应","tip":"re（字母音似“阿姨”）+ spond（音似“是胖的”）→ 阿姨“回应”，这只小狗是胖的。","ex":["I asked him his name, but he didn't respond.","我问他叫什么名字，可他没回答。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"respondent","p":"rɪˈspɒndənt","m":"n.回答问题的人；（尤指）调查对象","tip":"respond（回答）+ -ent（表示人的后缀）→ 回答问题的人","ex":["Sixty percent of the respondents agreed with the suggestion.","60%的调查对象同意这一建议。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"correspond","p":"ˌkɒrəˈspɒnd","m":"v.相符；一致","tip":"cor-（所有的，一起）+ respond（回应）→ 一起回应，异口同声 → 相符；一致","ex":["Your account and hers do not correspond.","你说的情况与她说的不相符。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"feedback","p":"ˈfiːdbæk","m":"n.反馈；反馈的意见（或信息）","tip":"feed（喂养，提供）+ back（回）→ 反馈","ex":["There is a huge value in learning with instant feedback.","通过即时反馈进行学习具有巨大的价值。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"phase","p":"feɪz","m":"n.（发展变化的）阶段；时期","tip":"单词发音类似“肥死”→ 即使再胖，减肥也要按“阶段”慢慢来。","ex":["This technology is still in an early phase of development.","这项技术仍处于早期开发阶段。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"phrase","p":"freɪz","m":"n.短语；习惯用语","tip":"初级阶段（phase）的短语（phrase）较简单。","ex":["One of the most well-worn phrases of parents is that breakfast is the most important meal of the day.","父母最常说的一句话就是，早餐是一天中最重要的一餐。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"fatigue","p":"fəˈtiːɡ","m":"n.疲乏，疲劳，疲惫","tip":"fat（胖的）+ i（我）+ gue（音似“哥”）→ 我哥哥比较胖，走两步就容易“疲劳”。","ex":["No wonder so many of us suffer from emotional fatigue.","难怪我们中有这么多人会患情绪疲劳。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"exhaust","p":"ɪɡˈzɔːst","m":"v.使精疲力尽；用完，耗尽","tip":"单词发音类似“一个早死的”→ 有一个人因体力“耗尽”而早早死去。","ex":["It now turns out that exercise can exhaust not only your muscles, but also your eyes.","现在发现，运动不仅会使你的肌肉疲劳，还会使你的眼睛疲劳。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"expand","p":"ɪkˈspænd","m":"v.扩大，发展，增强（尺码、数量或重要性），扩展","tip":"ex-（外）+ pand（音似“胖的”）→ 一个人越来越胖，相当于往外“扩大”。","ex":["Learning can expand your company and your career.","学习可以发展你的公司和职业生涯。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"feasible","p":"ˈfiːzəbl","m":"adj.可行的；行得通的","tip":"fea（音似“肥”）+ s（联想“四”）+ -ible（形容词后缀）→ 减肥四斤是“可行的”。","ex":["I would argue that this is a perfectly feasible solution.","我认为这是一个完全可行的解决方案。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"feature","p":"ˈfiːtʃə(r)","m":"n.特色；特征；特点 v.以……为特色；是……的特征","tip":"fea（音似“肥”）+ ture（联想 true）→ 肥真的是我家小仓鼠的一个“特点”。","ex":["Luxurious features add much to the price.","豪华的特点大大提高了价格。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"feather","p":"ˈfeðə(r)","m":"n.羽毛；翎毛；羽状物","tip":"单词发音类似“飞着”→ 空中飞着一根“羽毛”。","ex":["The most common materials used for nests are grasses, branches and feathers.","筑巢最常用的材料是草、树枝和羽毛。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"character","p":"ˈkærəktə(r)","m":"n.品质，性格；特点，特征；人物，角色","tip":"cha（联想“插”）+ r（形似花）+ acter（联想 actor）→ 这个演员头上插了朵花，这是他的“特点”。","ex":["Each one has a unique character.","每个人都有自己独特的性格。"],"lesson":"u09-l04","group":"“胖”谐音相关"},{"w":"figure","p":"ˈfɪɡə(r)","m":"n.数字；人物；图表 v.是重要部分；认为","tip":"单词发音类似“肥哥”→ 在这部剧里，肥哥是个小“人物”。","ex":["By 2017, this figure had risen to 14 million.","到2017年为止，这个数字已经增长到1,400万。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"file","p":"faɪl","m":"n.文件夹，档案 v.归档，存档","tip":"fi（联想“飞”）+ le（联想“了”）→ 他保存的“档案”不翼而飞了。","ex":["It classifies information and places it in different files.","它对信息进行分类，并将其放在不同的文件夹中。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"document","p":"ˈdɒkjument","m":"v.记录，记载（详情）","tip":"do（音似“捣”）+ cu + men（联想“门”）+ t（联想“他”）→ 他每天在门里面捣鼓“文件”。","ex":["Please e-sign the document and email it back.","请在文件上进行电子签名，然后用电子邮件发回。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"forge","p":"fɔːdʒ","m":"v.锻造，伪造；艰苦干成","tip":"for（形似 four）+ ge（联想“哥”）→ 为了不被叫家长，四个哥哥竟然“伪造”了父母的签名。","ex":["She forged a new career in the music business.","她在乐坛上另创一番新事业。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"range","p":"reɪndʒ","m":"n.一系列；范围，界限 v.（在一定的范围内）变化","tip":"ran（跑）+ ge（联想“哥”）→ 哥哥通常在这个“范围”内跑步。","ex":["So far, participants have ranged in age from 2 to 85.","到目前为止，参与者的年龄从2岁到85岁不等。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"arrange","p":"əˈreɪndʒ","m":"v.安排；筹备；整理；布置","tip":"ar-（一再地）+ range（范围）→ 一再地在一个范围内 → 我能力有限，只能在一定的范围内“安排”事情。","ex":["Doris helped him arrange the furniture.","多丽丝帮他布置家具。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"event","p":"ɪˈvent","m":"n.事件，重要事情，大事，活动","tip":"单词发音类似“姨问他”→ 阿姨问他发生了什么“大事”。","ex":["Most people do not have clear memories of past events.","大多数人对过去的事情没有清晰的记忆。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"eventually","p":"ɪˈventʃuəli","m":"adv.终于；最后，最终","tip":"事情（event）终于（eventually）结束了。","ex":["The waste problem will eventually hurt all of us.","浪费的问题最终会伤害我们所有人。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"final","p":"ˈfaɪnl","m":"adj.最终的；最后的 n.决赛","tip":"finally adv. 最终 → final adj. & n.","ex":["She is never sure what the final design will look like until the end.","直到最后，她才确定最终的设计是什么样子。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"consequence","p":"ˈkɒnsɪkwəns","m":"n.结果，后果；价值；重要性","tip":"con-（所有的）+ sequence（一系列）→ 所有的系列（都结束了）→ 结果","ex":["Focusing on output alone can have unintended consequences.","只关注产出可能会产生意想不到的后果。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"sequence","p":"ˈsiːkwəns","m":"n.一连串，一系列；顺序","tip":"se（联想 see）+ quen（联想 queen）+ ce（走）→ 他要见女王必须按“顺序”排队走。","ex":["He described the sequence of events leading up to the robbery.","他描述了抢劫案发生前的一系列有关情况。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"subsequent","p":"ˈsʌbsɪkwənt","m":"adj.随后的；后来的；接下来的","tip":"sub-（下面）+ sequent（后来的）→ 随后的；后来的；接下来的","ex":["More on this study and the star ratings will appear in a subsequent post.","关于这项研究和星级评分的更多信息将出现在随后的帖子中。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"vain","p":"veɪn","m":"adj.徒劳的，无结果的；虚荣的","tip":"单词发音类似“问”→ 你问也是“徒劳的”，不会得到答案。","ex":["They pressed criminal charges in vain.","他们提出了刑事指控，但没有成功。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"series","p":"ˈsɪəriːz","m":"n.连续，一系列；连续剧","tip":"“福无双至，祸不单行”，严重的（serious）祸事有时会连续（series）发生。","ex":["This case raises a whole series of important questions.","这个案子提出了一系列重要的问题。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"chain","p":"tʃeɪn","m":"n.链（条）；一系列；连锁店 v.用链条拴住","tip":"cha（联想“插”）+ in（里面）→ 他把“链条”锁插进自行车轮里锁车。","ex":["They break up nature's food supply chain.","它们破坏了自然界的食物链。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"addition","p":"əˈdɪʃn","m":"n.加；增加；增加物","tip":"add v. 增加 → addition n.","ex":["All of these technologies are fairly recent additions.","所有这些技术都是最近才加入的。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"increasingly","p":"ɪnˈkriːsɪŋli","m":"adv.越来越多地；不断增加地","tip":"","ex":["An increasingly important skill will be your ability to deal with change.","你应对变化的能力将是一项越来越重要的技能。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"gradually","p":"ˈɡrædʒuəli","m":"adv.逐渐地；渐进地","tip":"我的孩子们逐渐（gradually）毕业（graduate）了。","ex":["Their memory gradually deteriorates.","他们的记忆力逐渐退化。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"further","p":"ˈfɜːðə(r)","m":"adj.更多的；更进一步的；附加的 adv.（空间距离）较远，更远 v.促进","tip":"","ex":["Feedback from the teachable agents further enhances the tutors' learning.","教学智能体的实时反馈，持续优化辅导老师的学习能力。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"frequent","p":"ˈfriːkwənt","m":"adj.频繁的；经常发生的","tip":"fre（联想 free）+ qu（联想“去”）+ ent（联想 enter）→ 他们可以免费进出公园，所以经常去 → 频繁的；经常发生的","ex":["He is a frequent visitor to this country.","他常访问这个国家。"],"lesson":"u09-l04","group":"“文件、结果”相关"},{"w":"secondary","p":"ˈsekəndri","m":"adj.次要的；从属的；间接引发的；中学的","tip":"second（第二）+ -ary（形容词后缀）→ 次要的；从属的","ex":["She finished her secondary school.","她完成了中学学业。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"chief","p":"tʃiːf","m":"adj.首席的；最重要的；主要的 n.首领","tip":"单词发音类似“欺负”→ 这个“首领”喜欢欺负别人。","ex":["Exposure to blue light is the chief cause of obesity.","暴露在蓝光下是肥胖的主要原因。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"primary","p":"ˈpraɪməri","m":"adj.主要的；首要的，最初的；小学教育的；初等教育的","tip":"primary school 小学 → primary adj.","ex":["Their primary requirement for their children is to study hard.","他们对孩子的首要要求就是努力学习。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"prime","p":"praɪm","m":"adj.主要的；优质的 n.盛年；鼎盛时期 v.事先指点；使（某人）做好准备","tip":"一个人最主要的（primary）奋斗时期就是他的盛年（prime）。","ex":["She primed herself to new opportunities.","她为自己准备好迎接新的机会。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"preliminary","p":"prɪˈlɪmɪnəri","m":"adj.预备性的；初步的 n.初步行动（或活动）；预备性措施","tip":"pre-（提前）+ limin（联想 limit）+ -ary（形容词后缀）→ 提前限制孩子看电视，是为让他好好学习做的“初步的”准备。","ex":["Research will be needed as a preliminary to taking a decision.","做决定之前需要进行研究。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"primitive","p":"ˈprɪmətɪv","m":"adj.原始的；粗糙的；简单的","tip":"人类文明发展最初的（primary）阶段具有原始的（primitive）特征。","ex":["Primitive forms of life have been seen there.","在该处已观测到原始生命形式的存在。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"coarse","p":"kɔːs","m":"adj.粗糙的；粗俗的","tip":"他用粗糙的（coarse）材料准备了一系列手工课程（course）。","ex":["Her coarse hands are the result of years of hard work.","她粗糙的双手是常年艰辛劳作的结果。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"rude","p":"ruːd","m":"adj.粗鲁的，无礼的","tip":"单词发音类似“辱的”→ 侮辱别人的人是“粗鲁的”。","ex":["Don't you know it's rude to whisper?","难道你不知道窃窃私语是不礼貌的吗？"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"manner","p":"ˈmænə(r)","m":"n.态度，举止；方式；礼貌","tip":"单词发音类似“卖呢”→ 我不喜欢他卖东西的“方式”呢。","ex":["It is bad manners to talk with your mouth full.","嘴里塞满了东西跟人说话是不礼貌的。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"offend","p":"əˈfend","m":"v.冒犯，使不愉快","tip":"他经常（often）冒犯（offend）别人。","ex":["It may sound safe to avoid all physical contact so as not to offend anyone.","避免所有的身体接触以不冒犯任何人听起来可能是安全的。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"defend","p":"dɪˈfend","m":"v.防御；保护；保卫；防守；替……辩护","tip":"de（音似“弟”）+ f（联想“飞”）+ end（最后）→ 弟弟飞奔过来“保护”我们，并坚持到了最后。","ex":["A tiger usually fights another tiger to defend its own territory.","老虎通常会与同类搏斗来保卫自己的领地。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"fence","p":"fens","m":"n.栅栏；篱笆 v.（用栅栏，篱笆或围栏）围住，隔开","tip":"fen（联想“粉”）+ ce（联想“侧”）→ 我在粉刷一侧的“栅栏”。","ex":["Officers use soccer goals to fence the animal in.","警官们用足球球门把这只动物围起来。"],"lesson":"u09-l04","group":"“重要的、次要的”相关"},{"w":"property","p":"ˈprɒpəti","m":"n.所有物；财产；不动产；房地产","tip":"两个人适不适合（proper），不是以财产（property）的多少衡量的。","ex":["This building is government property.","这座大楼是政府的财产。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"appropriate","p":"əˈprəʊpriət","m":"v.私占；盗用；挪用；拨出（专款）","tip":"ap-（一再地）+ propri（= proper）+ -ate（形容词后缀）→ 适当的","ex":["It was thought appropriate to award her the prize.","大家都认为把奖颁给她是恰当的。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"possess","p":"pəˈzes","m":"v.占有，拥有；具有","tip":"po（联想“魄”）+ ss（联想“美女”）+ e + ss（联想“美女”）→ 即使陷入困难暂时落魄，美女们内心仍“拥有”希望。","ex":["Interesting people usually possess certain unique qualities.","有趣的人通常具有某些独特的品质。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"estate","p":"ɪˈsteɪt","m":"n.个人财产；遗产；庄园；工业区","tip":"单词发音类似“爱死他的”→ 有些人最爱的就是他的“个人财产”。","ex":["He left estate valued at a million dollars.","他留下了价值100万美元的遗产。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"wealth","p":"welθ","m":"n.财富；大量；富有","tip":"单词发音类似“威尔士”→ 威尔士这个国家有大量城堡，“财富”丰厚。","ex":["It can bring wealth and honour to them.","它可以给他们带来财富和荣誉。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"fortune","p":"ˈfɔːtʃuːn","m":"n.财富，财产；运气","tip":"for（为了）+ tune（联想“吃”）→ 为了孩子吃得好一些，父母决定去大城市碰“运气”找工作。","ex":["They believe others care most about fame and fortune.","他们认为别人最在乎名声和财富。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"worth","p":"wɜːθ","m":"adj.值……钱的；值得的 n.价值","tip":"单词发音类似“我思”→ 我经常思考人生的“价值”。","ex":["It's worth asking if things are necessary.","如果有必要的话，问一问是值得的。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"worthwhile","p":"ˌwɜːθˈwaɪl","m":"adj.值得的；值得花时间的","tip":"worth（值得）+ while（一段时间）→ 值得（花时间）的","ex":["Fire insurance is a worthwhile investment.","火灾险是值得投资的。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"asset","p":"ˈæset","m":"n.资产，财产","tip":"as-（一再地）+ set（放）→ 他一再地把“财产”放置起来。","ex":["Her assets include shares in the company and a house in France.","她的财产包括公司的股份和一座法国的房子。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"upset","p":"ˌʌpˈset","m":"adj.心烦的；沮丧的","tip":"up（向上）+ set（放下）→ 七上八下 → 心烦的","ex":["I understand how upset you must be feeling.","我明白你有多沮丧。"],"lesson":"u09-l04","group":"“财产”相关"},{"w":"settle","p":"ˈsetl","m":"v.安顿；定居；解决","tip":"放下（set）自己 → 定居（settle）；放下（set）问题 → 解决（settle）","ex":["She settled in Vienna after her father's death.","父亲死后，她就在维也纳定居了。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"handle","p":"ˈhændl","m":"v.解决，处理，应付 n.柄；把手","tip":"单词发音类似“憨豆”→ 憨豆先生“处理”问题时状况百出。","ex":["It's time to re-evaluate how women handle conflict at work.","是时候重新考虑女性如何处理工作冲突了。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"tackle","p":"ˈtækl","m":"v.应付，处理，解决（难题或局面）","tip":"单词发音类似“太抠”→ 应付太抠门的人不大容易。","ex":["Unless we accept that obesity is a disease, we are not going to be able to tackle it.","除非我们接受肥胖是一种疾病，否则我们将无法解决它。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"cope","p":"kəʊp","m":"v.（成功地）对付，处理，解决 n.（圣职人员在特定礼仪中穿的）斗篷式祭衣，大圆衣","tip":"单词发音类似“抠破”→ 你得把抠破的伤口“处理”一下。","ex":["Some students cope with this shock by avoiding challenges.","一些学生通过回避挑战来应对这种冲击。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"solve","p":"sɒlv","m":"v.解决；处理；破解","tip":"so（所以）+ l（联想“来”）+ ve（音似“我”）→ 这道题比较难，所以我来“解决”吧。","ex":["Environmental problems must be solved to ease the current global food shortage.","必须解决环境问题，以缓解目前的全球粮食短缺问题。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"resolve","p":"rɪˈzɒlv","m":"v.解决；决定，下决心","tip":"re-（表加强）+ solve（解决）→ 解决；下决心","ex":["Both sides met in order to try to resolve their differences.","双方会晤以努力解决分歧。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"resolution","p":"ˌrezəˈluːʃn","m":"n.决心，决定；解决","tip":"resolve v. 解决；下决心 → resolution n.","ex":["I made a New Year resolution to give up smoking.","我决心在新的一年把烟戒掉。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"dissolve","p":"dɪˈzɒlv","m":"v.溶解；解除","tip":"dis-（= away）+ solve（解决）→ 解决掉 → 溶解；解除","ex":["The rubbish takes long to dissolve.","这些垃圾需要很长时间才能溶解。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"address","p":"əˈdres","m":"n.住址；地址；演说 v.写地址；演讲；设法解决；处理","tip":"ad-（一再地）+ dress（裙子）→ 她一再地在网上买裙子，需要填写邮寄“地址”。","ex":["Under a voice-activated command, you say an address.","在声控命令下，你说出一个地址。"],"lesson":"u09-l04","group":"“处理、解决”相关"},{"w":"giant","p":"ˈdʒaɪənt","m":"adj.巨大的；伟大的 n.巨人；大公司；伟人","tip":"单词发音类似“站他”→ 我们学习科学知识，需要站在“巨人”的肩膀上。","ex":["He is the CEO of a giant company.","他是一家大公司的首席执行官。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"gigantic","p":"dʒaɪˈɡæntɪk","m":"adj.巨大的，巨人般的","tip":"泰坦尼克（Titanic）是一艘巨大的（gigantic）轮船。","ex":["Curiosity is one of the tools humans have found to accomplish that gigantic task.","好奇心是人类发现的完成那一艰巨任务的工具之一。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"immense","p":"ɪˈmens","m":"adj.极大的，巨大的","tip":"i（我）+ mmense（音似“闷死”）→ 这里就像一个“巨大的”火炉，都快把我闷死了。","ex":["That is a sign of its immense potential.","这是其巨大潜力的标志。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"tremendous","p":"trəˈmendəs","m":"adj.巨大的，极大的；极好的","tip":"tre（联想 tree）+ mend（音似“门的”）+ -ous（形容词后缀）→ 树都长到门的两边了，说明这棵树是“巨大的”。","ex":["One of humans' key characteristics is tremendous linguistic diversity.","人类的一个重要特征是庞大的语言多样性。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"enormous","p":"ɪˈnɔːməs","m":"adj.巨大的，庞大的，极大的","tip":"e-（超出）+ norm（标准）+ -ous（形容词后缀）→ 超出标准大小的 → 巨大的，庞大的","ex":["There's no question that self-driving vehicles could be an enormous benefit.","毫无疑问，自动驾驶汽车可能会带来巨大的利益。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"vast","p":"vɑːst","m":"adj.巨大的，广大的","tip":"单词发音类似“哇死（很）特”→ 哇，这艘轮船真的很大，特别大 → 巨大的，广大的","ex":["Your help made a vast difference.","你的帮助产生了巨大的影响。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"largely","p":"ˈlɑːdʒli","m":"adv.在很大程度上；多半；主要地","tip":"large（大的）+ -ly（副词后缀）→ 在很大程度上；多半；主要地","ex":["He was largely regarded as past his prime.","人们普遍认为他已经过了黄金时期。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"highly","p":"ˈhaɪli","m":"adv.非常；高标准地；高度地；钦佩地","tip":"high（高的）+ -ly（副词后缀）→ 非常；高标准地；高度地","ex":["Computers can become highly intelligent.","计算机可以变得高度智能。"],"lesson":"u10-l01","group":"“巨大的”相关"},{"w":"standard","p":"ˈstændəd","m":"n.标准，水平 adj.标准的","tip":"stand（站）+ -ard（后缀）→ 一个人站也有站的“标准”。","ex":["Thus, they had to keep working just as much in order to maintain their standard of living.","因此，为了维持生活水平，他们不得不继续付出同样多的劳动。"],"lesson":"u10-l01","group":"“标准”相关"},{"w":"norm","p":"nɔːm","m":"n.社会准则，行为规范；标准；正常水平","tip":"no（没有）+ r（联想“人”）+ m（联想“妈”）→ 没有人可以定义好妈妈的“标准”。","ex":["She considered people to be products of the values and norms of the society.","她认为人是社会价值观和规范的产物。"],"lesson":"u10-l01","group":"“标准”相关"},{"w":"normal","p":"ˈnɔːml","m":"adj.典型的，正常的，一般的 n.常态；通常标准","tip":"norm（标准）+ -al（后缀）→ 典型的；正常的；常态","ex":["Such tasks can get our brains thinking flexibly, beyond our normal comfort zone.","这样的任务可以让我们的大脑灵活思考，跳出常规舒适区。"],"lesson":"u10-l01","group":"“标准”相关"},{"w":"precise","p":"prɪˈsaɪs","m":"adj.精确的，准确的；确切的；（强调时间或方式等）就，恰好","tip":"pre-（提前）+ cise（音似“杀死”）→ 杀死害虫，需要提前确定“精确的”路线。","ex":["Can you give a more precise definition of the word?","你能给这个词下个更确切的定义吗？"],"lesson":"u10-l01","group":"“标准”相关"},{"w":"brief","p":"briːf","m":"adj.短暂的；简短的；简洁的 n.任务简介，指示 v.给（某人）指示","tip":"br（联想“病人”）+ i（字母音似“爱”）+ ef（音似“衣服”）→ 病人爱穿简洁风格的衣服 → 简洁的","ex":["He said nothing during the brief court appearance.","在短暂的出庭期间，他什么也没说。"],"lesson":"u10-l01","group":"“标准”相关"},{"w":"simple","p":"ˈsɪmpl","m":"adj.简单的；朴素的；（表示强调）纯粹的","tip":"sim（联想“四妹”）+ ple（音似“剖”）→ 四妹学医，她觉得解剖课是很“简单的”。","ex":["Some traditions are simple, like the red eggs that get baked into breads.","有些传统很简单，比如面包中烤制的红鸡蛋。"],"lesson":"u10-l01","group":"“标准”相关"},{"w":"extreme","p":"ɪkˈstriːm","m":"adj.极度的；严重的；极端的 n.极端不同的感情（或境况、行为方式等）；完全相反的事物","tip":"ex-（向外）+ tre（音似“踹”）+ me（我）→ 他说要出来踹我，这种行为是“极端的”。","ex":["We are working under extreme pressure at the moment.","目前我们正在极大的压力下工作。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"utmost","p":"ˈʌtməʊst","m":"adj.最大的；极度的 n.最大量；最大限度","tip":"","ex":["They had the utmost comfort passengers could enjoy in mind.","他们考虑到了乘客能享受到的最大舒适度。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"utter","p":"ˈʌtə(r)","m":"adj.完全的；十足的；彻底的 v.出声；说；讲","tip":"单词发音类似“啊特”→ 啊，他特别恨那个“十足的”骗子。","ex":["Falling into a routine can turn a person into an utter bore.","墨守成规会让人变得无聊透顶。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"sheer","p":"ʃɪə(r)","m":"adj.完全的；十足的；陡峭的 adv.垂直地；陡峭地","tip":"she（她）+ er（联想“表示人的后缀”）→ 她是个“十足的”好人。","ex":["Outside there was a sheer drop down to the sea below.","外面是一道陡坡，直插大海。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"absolute","p":"ˈæbsəluːt","m":"adj.完全的；绝对的；确凿的","tip":"ab-（一再地）+ so（如此）+ lute（联想 late）→ 一再地如此晚 → 完全晚了 → 完全的","ex":["Value is almost never absolute.","价值几乎永远不是绝对的。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"possibility","p":"ˌpɒsəˈbɪləti","m":"n.可能；可能性","tip":"","ex":["The study did not examine the possibility of deep significance.","这项研究并没有考虑可能产生的深层影响。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"impossible","p":"ɪmˈpɒsəbl","m":"adj.不可能的；难处理的","tip":"","ex":["Without effort, getting any kind of decent job is impossible.","没有努力，找到任何体面的工作都是不可能的。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"probable","p":"ˈprɒbəbl","m":"adj.很可能发生（或存在）的 n.可能入选者","tip":"pro-（往前）+ bab（联想 baby）+ le（联想“了”）→ 那个婴儿自己往前走了，摔跤是“很可能发生的”事情。","ex":["The most probable reason for the popularity is that they are less expensive.","流行的最可能的原因是它们更便宜。"],"lesson":"u10-l01","group":"“绝对”相关"},{"w":"abstract","p":"ˈæbstrækt","m":"adj.抽象的 n.（文献等的）摘要","tip":"abs-（从……离开）+ tract（拖，拉，拽）→ 提取","ex":["We may talk of beautiful things but beauty itself is abstract.","我们可以谈论美的事物，但美本身却是抽象的。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"tractor","p":"ˈtræktə(r)","m":"n.拖拉机；牵引机","tip":"tract（拖，拉，拽）+ -or（名词后缀）→ 用来拖、拉、拽的东西 → 拖拉机","ex":["We had to use a tractor to pull the car out of the mud.","我们不得不用拖拉机把车从泥地里拖出来。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"subtract","p":"səbˈtrækt","m":"v.减去，扣除","tip":"sub-（往下）+ tract（拖，拉，拽）→ 往下拖，拉，拽 → 减去，扣除","ex":["This subtracts loss in value of factories and equipment.","这减去了工厂和设备的价值损失。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"reduce","p":"rɪˈdjuːs","m":"v.减少，缩小（尺寸、数量、价格等）","tip":"","ex":["The number of employees was reduced from 40 to 25.","雇员人数从 40 人减少到了 25 人。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"contract","p":"ˈkɒntrækt","m":"n.合同，契约 v.与……订立合同（或契约）","tip":"con-（一起）+ tract（拖，拉，拽）→ 把双方拉到一起 → 合同","ex":["All employees have a written contract of employment.","所有员工都有一份书面聘用合同。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"attract","p":"əˈtrækt","m":"v.吸引；使喜爱；引起……的好感","tip":"at-（朝，向）+ tract（拖，拉，拽）→ 吸引","ex":["What first attracted me to her was her sense of humour.","她首先吸引我的是她的幽默感。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"induce","p":"ɪnˈdjuːs","m":"v.劝诱，诱导；引产","tip":"in（里面）+ du（联想“毒”）+ ce（音似“死”）→ 他“劝诱”我把家里的害虫毒死。","ex":["Some producers may induce customers to make more unplanned purchases.","一些生产商可能诱导顾客进行更多计划外的购买。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"hook","p":"hʊk","m":"n.钩，挂钩 v.钩住","tip":"动画片中的胡克（Hook）船长有一个鹰钩（hook）鼻。","ex":["Your coat's hanging on a hook behind the door.","你的外套挂在门后的挂钩上。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"distract","p":"dɪˈstrækt","m":"v.分散注意力；分散；使分心","tip":"dis-（分开）+ tract（拖，拉，拽）→ 向不同方向拖，拉，拽 → 分散；使分心","ex":["Members of poorly managed teams are easily distracted from their work.","管理不善的团队成员很容易在工作中分心。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"fascinate","p":"ˈfæsɪneɪt","m":"v.深深吸引；迷住","tip":"单词发音类似“帅死你她”→ 他很帅，把你和她都“迷住”了。","ex":["It was a question that had fascinated him since he was a boy.","这是他自幼就着迷的问题。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"fantasy","p":"ˈfæntəsi","m":"n.幻想，白日梦","tip":"单词发音类似“范特西”→ 范特西是一个爱“幻想”的人。","ex":["He spoke of his childhood fantasies about becoming a football player.","他谈起儿时想成为足球运动员的幻想。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"fantastic","p":"fænˈtæstɪk","m":"adj.极好的；了不起的；怪诞的","tip":"","ex":["This was a fantastic opportunity for students.","这对学生来说是一个极好的机会。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"fancy","p":"ˈfænsi","m":"n. & v.想象，设想；喜欢 adj.精致的，绚丽的","tip":"单词发音类似“烦死”→ 当你特别烦时，不如“想象”一下未来的幸福时光。","ex":["She enjoys buying a lot of fancy things.","她喜欢买很多精致的东西。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"illusion","p":"ɪˈluːʒn","m":"n.幻想；错觉；错误的观念","tip":"单词发音类似“一路引”→ 他想要一直有人为他的人生引路，但这只是他的“幻想”。","ex":["Google can give us the powerful illusion that all questions have definite answers.","谷歌能给我们一种强大的错觉，即所有的问题都有明确的答案。"],"lesson":"u10-l01","group":"tract 相关"},{"w":"plastic","p":"ˈplæstɪk","m":"n.塑料 adj.塑料的；人造的","tip":"大多数塑料（plastic）可以持续（last）使用。","ex":["Do you buy water in plastic bottles or take your chances with tap water?","你会买塑料瓶装水，还是碰碰运气喝自来水？"],"lesson":"u10-l01","group":"“持续的、裸露的”相关"},{"w":"permanent","p":"ˈpɜːmənənt","m":"adj.永久的，永恒的；固定的","tip":"per-（每一）+ man（人）+ ent（联想 enter）→ 每一个人都想进入时间“永恒的”世界。","ex":["If working from home becomes permanent, employees will have to dedicate part of their private space to work.","如果居家办公成为常态，员工将不得不拿出部分私人空间用于工作。"],"lesson":"u10-l01","group":"“持续的、裸露的”相关"},{"w":"eternal","p":"ɪˈtɜːnl","m":"adj.不朽的；永恒的；永久的","tip":"eter（音似“一特”）+ n（形似门）+ -al（形容词后缀）→ 这一扇特色之门是城市“永恒的”印记。","ex":["I'm tired of your eternal arguments.","我烦透了你们那无休止的争论。"],"lesson":"u10-l01","group":"“持续的、裸露的”相关"},{"w":"barely","p":"ˈbeəli","m":"adv.仅仅；几乎不，几乎没有；刚好","tip":"裸露的（bare）就是几乎没有（barely）穿衣服。","ex":["The economy would become so productive that people would barely need to work at all.","经济发展将更具生产力，人们几乎不再需要工作。"],"lesson":"u10-l01","group":"“持续的、裸露的”相关"},{"w":"bare","p":"beə(r)","m":"adj.裸露的，裸体的；（树木）光秃秃的","tip":"bar（木条）+ e（字母音似“姨”）→ 木条划破了阿姨的衣袖，使她露出了胳膊 → 裸露的","ex":["She likes to walk around in bare feet.","她喜欢光着脚走来走去。"],"lesson":"u10-l01","group":"“持续的、裸露的”相关"},{"w":"mere","p":"mɪə(r)","m":"adj.仅仅，只不过","tip":"单词发音类似“米儿”→ 世界那么大，我们“仅仅”像一粒米那样渺小。","ex":["Social robots will be much more like companions than mere tools.","社交机器人将会更像是伙伴，而不仅仅是工具。"],"lesson":"u10-l01","group":"“持续的、裸露的”相关"},{"w":"sole","p":"səʊl","m":"adj.仅有的，唯一的；独占的，专有的","tip":"单词发音类似“馊”→ 馊了也不给别人吃，要独占这一食物 → 独占的，专有的","ex":["GDP is no longer regarded as the sole measure of a country's success.","国内生产总值不再被视为衡量一个国家成功与否的唯一标准。"],"lesson":"u10-l01","group":"“持续的、裸露的”相关"},{"w":"accident","p":"ˈæksɪdənt","m":"n.（交通）事故；意外遭遇；不测事件","tip":"ac-（一再地）+ cident（音似“死等”）→ 她一再地等他，但他就是没来，她担心出了“事故”。","ex":["He was involved in a terrible car accident last April.","去年四月，他遭遇了一场严重的车祸。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"incident","p":"ˈɪnsɪdənt","m":"n.事件；事故；摩擦","tip":"","ex":["The most recent incident occurred last January.","最近的一次事件发生在去年一月。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"incidence","p":"ˈɪnsɪdəns","m":"n.发生率；发生范围；影响程度","tip":"inciden(t)（事故）+ ce（联想“车”）→ 车辆事故有一定的“发生率”。","ex":["Not eating breakfast is related to the incidence of certain diseases.","不吃早餐与某些疾病的发病率有关。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"occasion","p":"əˈkeɪʒn","m":"n.特殊场合；时刻；机会","tip":"","ex":["He has mentioned this on many previous occasions.","他在以前的许多场合都提到过这一点。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"casual","p":"ˈkæʒuəl","m":"adj.不经意的；非正式的，随便的；偶然的","tip":"casu（联想“卡苏”，人名）+ -al（形容词后缀）→ 卡苏是个外国人，穿衣风格是很“随便的”。","ex":["Siri has often been praised for its ability to interpret our casual language.","Siri 经常受到称赞，因为它能够解释我们非正式的语言。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"opportunity","p":"ˌɒpəˈtjuːnəti","m":"n.机会，时机","tip":"op（联想 open）+ port（港口）+ unity（团结一致）→ 在开放的港口城市生存，我们要团结一致，抓住发展“机会”。","ex":["This is an opportunity that must not be wasted.","这是一个绝不能浪费的机会。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"chance","p":"tʃɑːns","m":"n.机会，时机；可能性","tip":"","ex":["Some people view socialising at the workplace as a chance to develop personal relationships.","有些人将职场社交视为发展人际关系的机会。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"occur","p":"əˈkɜː(r)","m":"v.发生；出现","tip":"o（字母音似“偶”）+ ccur（音似“磕”）→ 我偶然磕了腿，“发生”了意外。","ex":["It occurs when people are doing a repetitive activity.","当人们在做重复性的活动时，它就会发生。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"curb","p":"kɜːb","m":"v.控制；抑制；限定 n.控制；限制","tip":"cur（联想 occur）+ b（联想“不”）→ 让一件事情不发生，就要“抑制”它。","ex":["He needs to learn to curb his temper.","他得学着控制自己的脾气。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"spot","p":"spɒt","m":"n.地点，场所；污点，污渍；斑点 v.认出，发现","tip":"s（联想“美女”）+ pot（坛子）→ 美女打翻了泡菜坛子，身上溅了很多“污渍”。","ex":["A deadly fish has been spotted in the ocean.","在海洋中发现了一种致命的鱼类。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"potential","p":"pəˈtenʃl","m":"n.潜能，潜力 adj.潜在的，可能的","tip":"pot（坛子）+ ent（联想 enter）+ -ial（后缀）→ 他一进入像坛子一样封闭的环境，“潜能”就会被激发出来。","ex":["These educational experiences have enormous potential to brighten my future.","这些教育经历有巨大的潜力来照亮我的未来。"],"lesson":"u10-l01","group":"“事故”相关"},{"w":"scent","p":"sent","m":"n.香味；（人的）气味，气息；察觉 v.嗅出；觉察出","tip":"他给我邮寄了（sent）一束花，香味（scent）扑鼻。","ex":["Scientists have found that scents affect working efficiency.","科学家发现，气味可以影响工作效率。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"poison","p":"ˈpɔɪzn","m":"n.毒，毒药 v.毒害","tip":"单词发音类似“泼一身”→他被泼了一身“毒药”。","ex":["What people eat can be medicine or poison.","人们吃的东西可能是药，也可能是毒药。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"transmit","p":"trænzˈmɪt","m":"v.传输；传播；发射","tip":"trans-（从……到……）+ mi（音似“妹”）+ t（联想“他”）→ 妹妹和他成为朋友是从传纸条开始的 → 传输","ex":["The ceremony was transmitted live by satellite to over fifty countries.","典礼通过卫星向五十多个国家进行了实况转播。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"omit","p":"əˈmɪt","m":"v.删除；忽略；遗漏；不做","tip":"o（形似圆圈）+ mit（送）→ 把圈中的送出去 → 删除","ex":["His name had been omitted from the list of honor students.","他的名字被从优秀学生名单上删除了。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"mission","p":"ˈmɪʃn","m":"n.使命，任务","tip":"miss（= mit，送）+ -ion（名词后缀）→ 谍战片里，卧底必须想方设法把情报送出去，这是“任务”。","ex":["Learning is a daily experience and a lifetime mission.","学习是每天的经历，也是一生的使命。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"dismiss","p":"dɪsˈmɪs","m":"v.不予考虑；驳回；摒除（思想、感情等）；解雇","tip":"dis-（分开）+ miss（= mit，送）→ 送走，使分开 → 解雇","ex":["I think we can dismiss their objections.","我认为我们可以驳回他们的异议。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"missile","p":"ˈmɪsaɪl","m":"n.导弹；投射物","tip":"miss（错过）+ i（我）+ le（联想“了”）→ 我错过了“导弹”发射的播出画面。","ex":["The army fired more than two hundred missiles.","军队发射了200多枚导弹。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"emit","p":"ɪˈmɪt","m":"v.发出，射出；排出","tip":"e-（出去）+ mit（送）→ 送出去 → 发出，射出；排出","ex":["These cars emit more than all the microwaves in the EU.","这些汽车排放的废气比欧盟所有的微波炉排放的都多。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"submit","p":"səbˈmɪt","m":"v.提交，呈递；服从","tip":"sub-（下）+ mit（送）→ 从下往上送 → 提交，呈递","ex":["These digital products aren't just mechanisms for students to submit homework.","这些数字产品不仅仅是学生提交作业的机制。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"admit","p":"ədˈmɪt","m":"v.承认；准许……进入","tip":"ad-（一再地）+ mit（送）→ 他一再地运送货物，保安最终准许他进入了 → 承认；准许……进入","ex":["She refuses to admit the truth.","她拒不承认事实。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"commission","p":"kəˈmɪʃn","m":"n.委员会；委托 v.委托（别人写报告、创作艺术品等）","tip":"com-（所有）+ mission（任务）→ 公司所有重要任务都是“委员会”决定的。","ex":["We'd like to see the commission make further changes to the guidelines.","我们希望看到委员会对准则做出进一步的修改。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"committee","p":"kəˈmɪti","m":"n.委员会","tip":"委员会（committee）做出了承诺（commit）。","ex":["She's on the planning committee.","她是计划委员会的成员。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"commit","p":"kəˈmɪt","m":"v.犯（罪或错等）；承诺，保证；投入","tip":"委员会（committee）做出了承诺（commit）。","ex":["When someone commits a criminal act, we always hope the punishment will match the offense.","当有人犯罪时，我们总是希望惩罚与罪行相匹配。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"summit","p":"ˈsʌmɪt","m":"n.最高点，顶峰；峰会（最高级会议）","tip":"sum（联想 sun）+ mit（送）→ 送到太阳上去 → 最高点","ex":["The new research has profound implications for the environmental summit.","这项新研究对环境峰会具有深远影响。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"peak","p":"piːk","m":"n.山顶，顶峰 adj.最高的 v.到达最高点","tip":"他站在山顶（peak）大声说话（speak）。","ex":["They reach a peak at the age of 20.","他们在20岁时达到顶峰。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"ceiling","p":"ˈsiːlɪŋ","m":"n.天花板；上限","tip":"单词发音类似“系铃”→“天花板”上系了一个风铃。","ex":["The room's ceilings are too low to wear the lion heads for jumping practice.","房间的天花板太低了，无法戴着狮头进行跳跃练习。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"altitude","p":"ˈæltɪtjuːd","m":"n.高，高度；高处","tip":"","ex":["The plane made a dive to a lower altitude.","飞机俯冲到较低高度。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"attitude","p":"ˈætɪtjuːd","m":"n.态度；做派","tip":"a（音似“爱”）+ tti（音似“踢”）+ tu（联想“吐”）+ de（音似“的”）→ 他爱到处乱踢又吐，这说明他的“态度”有问题。","ex":["If you want to pass your exams, you'd better change your attitude.","你若想通过考试，最好改变你的态度。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"aptitude","p":"ˈæptɪtjuːd","m":"n.天资；天赋","tip":"想要学有所成，天赋（aptitude）是一部分，态度（attitude）是另一部分，而后者决定了你的高度（altitude）。","ex":["Researchers used ACT scores as a measure of intellectual aptitude.","研究人员用美国大学入学考试成绩来衡量智力资质。"],"lesson":"u10-l02","group":"mit 相关"},{"w":"password","p":"ˈpɑːswɜːd","m":"n.暗语；口令；密码","tip":"pass（通过）+ word（字，词）→ 密码","ex":["Companies should promise that they would never ask for passwords.","公司应该承诺，他们永远不会索要密码。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"cross","p":"krɒs","m":"v.交叉；穿越；越过；渡过 n.叉字形记号；十字形记号；十字架 adj.恼怒的","tip":"单词发音类似“可绕死”→ 这里的路可太绕了，要穿过好几个路口 → 穿越","ex":["Put a cross if the answer is wrong.","如果答案错误，打叉。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"code","p":"kəʊd","m":"n.准则；代码；密码，编码","tip":"单词发音类似“扣的”→ 我们的电脑要用“密码”扣（锁）住。","ex":["The sport has a strict code of conduct.","体育运动有严格的行为准则。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"regulate","p":"ˈreɡjuleɪt","m":"v.管理；调节；规范","tip":"re（字母音似“阿姨”）+ gu（联想“故”）+ late（迟到）→ 阿姨故意迟到，想让我们随她的时间调整时间表 → 调节","ex":["Their emotions were much harder to regulate.","他们的情绪更难调节。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"regular","p":"ˈreɡjələ(r)","m":"adj.有规律的；频繁的；普通的 n.常客；老主顾","tip":"","ex":["It's joyful in a way that you don't get from a regular bike.","这是一辆普通自行车所不能带给你的快乐。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"relate","p":"rɪˈleɪt","m":"v.联系；叙述，讲述","tip":"re（字母音似“阿姨”）+ late（迟到）→ 阿姨迟到了，她要向我“讲述”理由，因为我和她之间有“联系”。","ex":["People's psychological well-being is related to various factors.","人们的心理健康与多种因素有关。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"relative","p":"ˈrelətɪv","m":"adj.比较的；相对的 n.亲戚","tip":"","ex":["She was finally rescued by her relatives.","她终于被亲戚们救了出来。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"relevant","p":"ˈreləvənt","m":"adj.有关的，切题的","tip":"re-（重复）+ le（音似“了”）+ vant（音似“问他”）→ 我重复问了他好几遍，因为这件事跟他是“有关的”。","ex":["The incident is still under investigation by the relevant authorities.","该事件仍在接受有关当局的调查。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"narrate","p":"nəˈreɪt","m":"v.讲（故事）；叙述","tip":"na（联想“那”）+ r（联想“人”）+ rate（速度）→ 那个人用很快的速度给我“讲故事”。","ex":["My grandmother used to narrate bedtime stories to me when I was young.","我小的时候，祖母经常给我讲睡前故事。"],"lesson":"u10-l02","group":"“密码、规范”相关"},{"w":"hesitate","p":"ˈhezɪteɪt","m":"v.犹豫，踌躇","tip":"he（他）+ sit（坐）+ ate（eat 的过去式）→ 他坐在餐桌旁，“犹豫”要不要吃。","ex":["She never hesitates to speak her mind.","她从不犹豫说出自己的想法。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"compensate","p":"ˈkɒmpenseɪt","m":"v.补偿；弥补","tip":"com-（所有）+ pens（钢笔）+ ate（eat 的过去式）→ 他把我所有的钢笔都弄坏了，所以我要求他请我吃饭来“补偿”我。","ex":["The lack of knowledge is difficult if not impossible to compensate for later on.","即使不是完全不可能，知识的缺乏在日后也很难弥补。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"candidate","p":"ˈkændɪdət; ˈkændɪdeɪt","m":"n.候选人，申请人；应试者","tip":"can（能够）+ did（做）+ ate（eat 的过去式）→ 他作为“候选人”有些紧张，能做的就是先吃些东西，缓解紧张的心情。","ex":["He is the best candidate for the job.","他是这个职位的最佳候选人。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"negotiate","p":"nɪˈɡəʊʃieɪt","m":"v.谈判，商定；协商","tip":"ne（音似“你”）+ go（去）+ ti（联想“提”）+ ate（eat 的过去式）→ 你去提有关“吃”的问题，要跟食堂负责人“协商”。","ex":["They are better at negotiating an agreement.","他们更擅长协商协议。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"initiate","p":"ɪˈnɪʃieɪt","m":"v.发起，开始；使了解；传授","tip":"i（我）+ ni（联想“你”）+ ti（联想“提”）+ ate（eat 的过去式）→ 我和你总提吃的，于是我们决定“开始”加入餐饮行业。","ex":["It initiated the digital revolution in the film industry.","它开启了电影行业的数字革命。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"launch","p":"lɔːntʃ","m":"v.发行；发起；启动；起飞 n.（产品的）发行；发射","tip":"他们一般都是午饭（lunch）后发射（launch）卫星。","ex":["The government recently launched a national road safety campaign.","政府最近发起了一场全国道路安全运动。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"innovate","p":"ˈɪnəveɪt","m":"v.引入（新事物、思想或方法）；创新，改革","tip":"in（进入）+ nov（新的）+ -ate（动词后缀）→ 创新；改革","ex":["He called on graduates to innovate in his speech.","他在他的演讲中呼吁毕业生们创新。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"renovation","p":"ˌrenəˈveɪʃn","m":"n.整修，翻新","tip":"re-（再）+ nov（新的）+ -ation（名词后缀）→ 翻新","ex":["This renovation project cost much money.","这个翻新项目花费了大量资金。"],"lesson":"u10-l02","group":"ate 相关"},{"w":"legend","p":"ˈledʒənd","m":"n.传说；传奇故事；传奇人物","tip":"运动员在腿（leg）受伤的情况下完成比赛，成了传奇人物（legend）。","ex":["The film is based on the legend.","这部电影是根据传奇故事改编的。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"myth","p":"mɪθ","m":"n.神话；神话故事；虚构的东西；荒诞的说法","tip":"单词发音类似“没死”→“神话”中的世界没有死亡，都是“虚构的东西”。","ex":["American myth is that you can pull yourself up by your own efforts and change a bad situation into a good one.","美国人的神话是你可以通过自己的努力振作起来，转逆为顺。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"mystery","p":"ˈmɪstri","m":"n.神秘的事情，谜；不可理解之事","tip":"my（我的）+ st（联想 street）+ -ery（名词后缀）→ 我家附近的街上发生了一件“神秘的事情”。","ex":["They were puzzled by the mystery.","他们对这谜感到困惑。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"novel","p":"ˈnɒvl","m":"n.（长篇）小说 adj.新颖的，珍奇的","tip":"小说（novel）更新需要创新（innovation）。","ex":["They prefer to go after all that is novel.","他们更喜欢追求一切新奇的事物。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"essay","p":"ˈeseɪ","m":"n.短文，文章，小品文","tip":"e-（往外）+ s（联想“美女”）+ say（说）→ 美女通过一篇“短文”把心中的想法表达出来。","ex":["For each assignment, I was to write the best essay as I could.","对于每一项作业，我都要尽我所能写出最好的文章。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"article","p":"ˈɑːtɪkl","m":"n.文章；条款；物品；冠词","tip":"","ex":["It will be a great loss if we no longer read books and longer articles.","如果我们不再阅读书籍和长篇文章，那将是一个巨大的损失。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"chapter","p":"ˈtʃæptə(r)","m":"n.（书的）章节，篇章；（人生或历史的）时期","tip":"cha（联想“查”）+ pt（联想“葡萄”）+ -er（名词后缀）→ 查一下有葡萄的“篇章”。","ex":["I've just finished Chapter 3.","我刚完成第3章。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"romance","p":"rəʊˈmæns; ˈrəʊmæns","m":"n.（通常指短暂的）浪漫史，爱情关系，风流韵事；爱情故事","tip":"单词发音类似“罗曼史”。","ex":["This ancient town is regarded as the paradise of love and romance.","这个古镇被视为爱情和浪漫的天堂。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"fiction","p":"ˈfɪkʃn","m":"n.小说，虚构的事","tip":"单词发音类似“飞可神”→ 这部“小说”中的每个人都会飞，可神奇了。","ex":["It resembles fragments of science fiction.","它类似于科幻小说的片段。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"brochure","p":"ˈbrəʊʃə(r)","m":"n.（资料或广告的）手册","tip":"bro（联想 brother）+ chure（音似“车”）→ 哥哥车里拉了很多招生“手册”。","ex":["The brochure should give you a good idea of the hotel.","这本手册应该能让您很好地了解这家酒店。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"comprehend","p":"ˌkɒmprɪˈhend","m":"v.理解；领悟；懂","tip":"","ex":["Reading and comprehending longer books and chapters takes practice.","阅读并理解较长的书和章节需要练习。"],"lesson":"u10-l02","group":"“文章”相关"},{"w":"drama","p":"ˈdrɑːmə","m":"n.戏剧；戏剧性；戏剧性情节；激动；兴奋；刺激","tip":"单词发音类似“抓妈”→ 他做游戏时一下子抓住了妈妈，场面充满了“戏剧性”。","ex":["It was recognised that crying in response to drama brought pleasure.","人们已经意识到，因戏剧而哭泣能带来愉悦感。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"dramatic","p":"drəˈmætɪk","m":"adj.突然的；巨大的；引人注目的；戏剧性的","tip":"","ex":["Climate change will have a dramatic impact on the health of the planet.","气候变化将对地球的健康产生巨大影响。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"drastic","p":"ˈdræstɪk","m":"adj.急剧的；激烈的；极端的；严厉的","tip":"dra（音似“抓”）+ stic（联想 stick）→ 他动不动就抓起棍子想要打人，真的太极端了 → 极端的","ex":["The city officials then decided to take drastic action.","市政府官员随后决定采取果断行动。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"tragedy","p":"ˈtrædʒədi","m":"n.悲剧，灾难","tip":"单词发音类似“踹着弟”→ 哥哥踹了弟弟一脚，真是“悲剧”。","ex":["His childhood was one part tragedy, equal part mystery.","他的童年一半是悲剧，一半是悬疑。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"comedy","p":"ˈkɒmədi","m":"n.喜剧；搞笑的东西","tip":"come（来）+ dy（音似“弟”）→ 好久不见的弟弟来了，我很高兴 → 喜剧","ex":["It's a charity comedy night with lots of different acts.","这是一个慈善喜剧之夜，有很多不同的表演。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"ridiculous","p":"rɪˈdɪkjələs","m":"adj.可笑的，荒谬的","tip":"单词发音类似“瑞迪可乐死”→ 瑞迪“可笑的”样子把我逗乐了。","ex":["He looks ridiculous in this hat.","他戴这顶帽子看上去很可笑。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"biography","p":"baɪˈɒɡrəfi","m":"n.传记（作品）","tip":"bio-（生物，生命）+ graph（写）+ -y（名词后缀）→ 对生命的书写 → 传记","ex":["The biography shows him in a favourable light.","传记刻画出了他的正面形象。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"literature","p":"ˈlɪtrətʃə(r)","m":"n.文献；文学，文学作品","tip":"liter（联想 litter）+ a + ture（联想 true）→ 他吐槽那些“文学作品”像垃圾一样，真的会害人。","ex":["Paperbacks of popular literature are more likely to be replaced by e-books.","通俗文学的平装书更有可能被电子书所取代。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"literacy","p":"ˈlɪtərəsi","m":"n.读写能力；识字；专业知识","tip":"","ex":["Most of the students here need help with literacy and numeracy.","这里的大多数学生需要识字和算术方面的帮助。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"literal","p":"ˈlɪtərəl","m":"adj.字面意义的；完全按原文的；缺乏想象力的","tip":"单词发音类似“李特弱”→ 李同学的英语基础特别薄弱，只能按字面意思翻译 → 字面意义的","ex":["I am not referring to \"small\" people in the literal sense of the word.","我指的不是字面意义上的“小”人。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"best-seller","p":"ˌbest ˈselə(r)","m":"n.畅销品；畅销书","tip":"","ex":["He turned this novel into an English best-seller.","他把这本小说变成了英语畅销书。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"second-hand","p":"ˌsekənd ˈhænd","m":"adj.二手的；间接得来的","tip":"","ex":["I bought a second-hand camera.","我买了一台二手照相机。"],"lesson":"u10-l03","group":"drama 相关"},{"w":"patience","p":"ˈpeɪʃns","m":"n.耐心；忍耐力；毅力；坚忍","tip":"单词发音类似“陪生死”→ 能一直陪着你、生死不离的人，一定很有“耐心”。","ex":["Learning from experience is something that takes time and patience.","从经验中学习需要时间和耐心。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"patient","p":"ˈpeɪʃnt","m":"n.病人 adj.有耐心的；能忍耐的","tip":"照顾病人（patient）要有耐心（patience）。","ex":["He was very patient with me.","他对我很有耐心。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"patent","p":"ˈpætnt; ˈpeɪtnt","m":"n.专利；专利权，专利证书","tip":"申请专利（patent）是需要有耐心的（patient），因为要等待很久才能审核通过。","ex":["He held a number of patents for his many innovations.","他拥有多项发明的专利权。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"brand","p":"brænd","m":"n.商标；品牌 v.印……商标于；铭记；铭刻于","tip":"单词发音类似“不让的”→“商标”是不能任意转让的。","ex":["Few people are successful when they try to build their first brand.","很少有人在尝试建立自己的第一个品牌时取得成功。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"label","p":"ˈleɪbl","m":"n.标签；商标 v.贴标签","tip":"实验室（lab）门口一般都要贴个标签（label）——“闲人勿扰”。","ex":["The bottle is sealed, and the label says \"pure water\".","瓶子是密封的，标签上写着“纯净水”。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"tag","p":"tæɡ","m":"n.标签；标牌 v.给……加标签；把……称作","tip":"ta（联想“他”）+ g（联想“哥”）→ 他哥哥爱给别人贴“标签”。","ex":["The man was tagged a \"loser\".","这个男人被称为“失败者”。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"lag","p":"læɡ","m":"n.落后；（时间上的）间隔 v.缓缓而行；掉队，落后于","tip":"la（联想“拉”）+ g（联想“哥”）→ 他拉了哥哥一把，因为哥哥“落后”了。","ex":["Ten minutes later, some runners in the race began to lag.","十分钟后，比赛中的一些赛跑者开始落后了。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"pace","p":"peɪs","m":"n.步；速度","tip":"单词发音类似“陪死”→ 你的爱人遇见你之后，在你人生的每一“步”都陪着你，直到死去。","ex":["Readers proceed at their own pace.","读者按照自己的节奏阅读。"],"lesson":"u10-l03","group":"“品牌、标签”相关"},{"w":"household","p":"ˈhaʊshəʊld","m":"n.一家人；家庭；同住一所房子的人","tip":"house（房子）+ hold（容纳）→ 房子里容纳的是“一家人”。","ex":["Most households now own at least one car.","现在大多数家庭至少有一辆汽车。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"housewife","p":"ˈhaʊswaɪf","m":"n.家庭主妇","tip":"","ex":["A housewife who opens a shop online can even out-earn a white-collar worker.","一个在网上开店的家庭主妇甚至比一个白领挣得多。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"gap","p":"ɡæp","m":"n.缝隙，缺口；差距","tip":"水龙头（tap）上有个缺口（gap）。","ex":["It often widens the gap between rich and poor and sustains the old world order.","它经常扩大贫富差距，维持旧的世界秩序。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"garage","p":"ˈɡærɑːʒ; ˈɡærɪdʒ","m":"n.车库；加油站；汽车修理厂","tip":"g（联想“哥”）+ a（一）+ rage（生气）→ 哥哥每到一个“车库”停车就生气，因为找个位置太难了。","ex":["Faith in the skill of a garage mechanic is increased by a uniform.","一套制服增加了人们对汽车修理厂机械师技能的信心。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"rage","p":"reɪdʒ","m":"n.狂怒，狂暴；愤怒的行为 v.发怒","tip":"r（形似花）+ age（年龄）→ 青少年正处于花一样的年龄，比较敏感，容易“发怒”。","ex":["She raged when her jewels were stolen.","当她的珠宝被偷时，她发怒了。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"temper","p":"ˈtempə(r)","m":"n.坏脾气；情绪；发怒 v.使缓和","tip":"天气的温度（temperature）就像人的脾气（temper），不太稳定。","ex":["All at once she lost her temper.","她突然大发脾气。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"attempt","p":"əˈtempt","m":"v.尝试，试图 n.试图，努力","tip":"at-（一再地）+ tempt（诱惑）→ 他一再地诱惑猎物，“试图”使其落入陷阱。","ex":["They abandoned the attempt to roast coffee beans in space.","他们放弃了在太空中烤咖啡豆的尝试。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"contempt","p":"kənˈtempt","m":"n.轻视，藐视","tip":"con-（所有）+ tempt（诱惑）→ 所有人都“藐视”无法拒绝利益诱惑的人。","ex":["She looked at him with contempt.","她轻蔑地看着他。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"host","p":"həʊst","m":"n.主人；东道主，主持人 v.主持；主办","tip":"单词发音类似“齁死他”→“主人”做的饭太咸了，快齁死人了。","ex":["South Africa hosted the World Cup finals.","南非主办了世界杯决赛。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"hostile","p":"ˈhɒstaɪl","m":"adj.敌意的，敌视的","tip":"host（主人）+ (t)i（联想“踢”）+ le（联想“了”）→ 主人踢了他一脚 → 敌意的","ex":["It tried to arouse hostile feelings among consumers.","它试图引起消费者的敌意。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"glove","p":"ɡlʌv","m":"n.手套","tip":"g（音似“哥”）+ love（爱）→ 哥哥很爱妈妈织的这双“手套”。","ex":["He must have been wearing gloves.","他一定戴着手套。"],"lesson":"u10-l03","group":"“家庭”相关"},{"w":"craft","p":"krɑːft","m":"n.工艺；技巧；飞行器 v.（尤指用手工）精心制作","tip":"cra（联想 car）+ ft（联想“福特”）→ 福特车的“工艺”是很好的。","ex":["Each doll is crafted individually by specialists.","每个玩偶都由专业人员手工制作。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"aircraft","p":"ˈeəkrɑːft","m":"n.飞机；航空器","tip":"air（空中）+ craft（飞行器）→ 飞机","ex":["He owns a fleet of aircraft.","他拥有一支机队。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"airport","p":"ˈeəpɔːt","m":"n.航空站；航空港；机场","tip":"air（空中）+ port（港口）→ 航空站","ex":["The plane is going to land at another airport.","飞机将在另一个机场降落。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"aviation","p":"ˌeɪviˈeɪʃn","m":"n.航空；航空制造业","tip":"a（一）+ vi（形似罗马数字 6）+ -ation（名词后缀）→ 他研究“航空”学，一天进行六次测试。","ex":["It uses the latest aviation technology.","它采用最新的航空技术。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"jet","p":"dʒet","m":"n.喷气式飞机","tip":"单词发音类似“接她”→ 他开着“喷气式飞机”去接她。","ex":["The giant jet will be forced to land.","巨型喷气式飞机将被迫降落。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"terminal","p":"ˈtɜːmɪnl","m":"n.航站楼；终点站；计算机终端 adj.终点的；晚期的；不治的","tip":"term（学期，期限）+ inal（联想 final）→ 最终期限 → 终点的","ex":["He has terminal lung cancer.","他患有晚期肺癌。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"airline","p":"ˈeəlaɪn","m":"n.航空公司","tip":"air（空中）+ line（线）→ 航线 → 航空公司","ex":["Our job as designers is to reinforce the airline's brand.","作为设计师，我们的工作就是强化航空公司的品牌。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"flight","p":"flaɪt","m":"n.飞行；飞机的航程；航班","tip":"f（联想“飞”）+ light（光）→“航班”的“飞行”速度就像光一样快。","ex":["Long queues and delayed flights at airports have become a topic for conversation in Britain.","在英国，机场排长队和航班延误已经成为人们谈论的话题。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"helicopter","p":"ˈhelɪkɒptə(r)","m":"n.直升机","tip":"heli（音似“海狸”）+ cop（警察）+ ter → 海狸警察开着“直升机”去追犯罪分子。","ex":["He was rushed to the hospital by helicopter.","他由直升机火速送到医院。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"pilot","p":"ˈpaɪlət","m":"n.飞行员 adj.试点的","tip":"单词发音类似“怕了它”→ 当飞机遭遇强气流时，“飞行员”都怕了。","ex":["There are a few pilot schools already making the transition to digital books.","有一些试点学校已经开始向数字图书过渡。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"plain","p":"pleɪn","m":"n.大平原；朴实无华的东西 adj.普通的；直接的","tip":"单词发音类似“扑来”→ 坐在高铁上往外看，“大平原”映入眼帘，像要扑过来一样。","ex":["The geographic feature of this country is mainly plains.","这个国家的主要地理特征是平原。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"complain","p":"kəmˈpleɪn","m":"v.抱怨；埋怨；发牢骚","tip":"com-（所有）+ plain（音似“扑来”）→ 所有人都扑来，向他“抱怨”。","ex":["Some of the people who work in Songdo complain about boredom in the workplace.","一些在松岛工作的人抱怨工作场所无聊。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"plunge","p":"plʌndʒ","m":"v.使突然前冲（或下落）；骤降 n.（价值或数量的）骤然下跌","tip":"单词发音类似“扑浪激”→ 他突然冲向大海，扑通一下跳入水中，激起浪花 → 使突然前冲（或下落）","ex":["People the world over are afraid of a further plunge in oil prices.","全世界的人都担心油价会进一步下跌。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"dive","p":"daɪv","m":"v.跳水；急剧下降 n.跳水；潜水；暴跌","tip":"di（联想“弟”）+ ve（音似“我”）→ 弟弟和我练习“跳水”。","ex":["He dived into the river but couldn't reach the surface.","他跳进河里，但不能浮到水面。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"drown","p":"draʊn","m":"v.淹死，溺死；沉浸于","tip":"单词发音类似“撞”→ 一只小鸭子游泳时不小心撞上了石头，差点“淹死”。","ex":["Some young adults are drowning in credit-card debt.","一些年轻人正被信用卡债务淹没。"],"lesson":"u10-l03","group":"“航空”相关"},{"w":"pork","p":"pɔːk","m":"n.猪肉","tip":"单词发音类似“剖开”→ 他把“猪肉”剖开。","ex":["The restaurant introduced barbecue pork ribs.","该餐厅推出了烤猪肋排。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"beef","p":"biːf","m":"n.牛肉；怨言","tip":"bee（蜜蜂）+ f（联想“飞”）→ 蜜蜂飞到“牛肉”上了。","ex":["We sat by the fireplace, eating beef and onions.","我们坐在壁炉旁，吃着牛肉和洋葱。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"slice","p":"slaɪs","m":"n.薄片；小块；部分 v.切；划","tip":"s（联想“美女”）+ lice（音似“辣死”）→ 美女吃了一“小块”辣椒，就被辣到了。","ex":["She asked the waiter to cut the cheese into slices.","她请服务员把奶酪切成薄片。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"chip","p":"tʃɪp","m":"n.油炸土豆条；（木头、玻璃等的）缺口；碎片；筹码","tip":"chi（联想“吃”）+ p（联想“盘”）→ 我吃了一盘“油炸土豆条”。","ex":["Performance is your best bargaining chip when you are seeking a raise.","当你要求加薪时，业绩是你最好的谈判筹码。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"onion","p":"ˈʌnjən","m":"n.洋葱，洋葱头","tip":"on（在……上）+ i（形似 1）+ on（在……上）→ 剥“洋葱”时，剥了上面一层，下面还有一层。","ex":["Experts observe that \"textbooks come in layers, something like an onion.\"","专家说“教科书是分层的，有点像洋葱。”"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"snack","p":"snæk","m":"n.点心；小吃；零食；快餐","tip":"蛇（snake）也爱吃小吃（snack）。","ex":["We get almost 25% of our daily calories from snacks.","我们每天获得的热量中的大约 25% 来自零食。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"sauce","p":"sɔːs","m":"n.调味汁；酱","tip":"单词发音类似“臊子”→ 炸“酱”面里面有臊子。","ex":["I prefer ice cream with chocolate sauce.","我更喜欢加巧克力酱的冰激凌。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"chef","p":"ʃef","m":"n.厨师；主厨","tip":"che（联想“车”）+ f（联想“夫”）→ 车夫失业后来当“厨师”。","ex":["He learned his trade from a famous dessert chef.","他从一位著名甜点主厨那里学到了手艺。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"dine","p":"daɪn","m":"v.进餐；用饭","tip":"dinner n.正餐，晚餐 → dine v.","ex":["This can help improve the quality of the restaurants they dine in.","这能帮助提高他们就餐的餐馆的质量。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"picnic","p":"ˈpɪknɪk","m":"n.郊游，野餐 v.野餐","tip":"pic（联想 pick）+ nic（音似“你磕”）→ 他周末出去“野餐”了，在采摘水果时磕到了腿。","ex":["It turns parks into picnic sites.","它把公园变成了野餐地。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"chew","p":"tʃuː","m":"v.咀嚼，嚼碎","tip":"单词发音类似“粗”→ 吃太粗糙的食物时，要多“咀嚼”。","ex":["After the operation you may find it difficult to chew and swallow.","手术后你可能会发现难以咀嚼和吞咽。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"gum","p":"ɡʌm","m":"n.牙龈；口香糖；树胶","tip":"gu（音似“尬”）+ m（联想“妹”）→ 妹嚼了块“口香糖”来掩饰尴尬。","ex":["I do not chew gum in public.","我不在公共场合嚼口香糖。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"lick","p":"lɪk","m":"v.舔；掠过；（火舌）舔食 n.舔","tip":"单词发音类似“立刻”→ 小狗口渴了，看到有水就立刻“舔”起来了。","ex":["He likes to lick the covering of the yogurt.","他喜欢舔酸奶的盖子。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"napkin","p":"ˈnæpkɪn","m":"n.餐巾；餐巾纸","tip":"单词发音类似“奶扑啃”→ 小宝宝看到酸奶块就扑过去啃了起来，我要用“餐巾纸”给他擦拭一下。","ex":["She dabbed her mouth with her table napkin.","她用餐巾轻轻擦了擦嘴。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"nap","p":"næp","m":"v.（日间的）小睡，打盹 n.（日间的）小睡","tip":"na（音似“奶”）+ p（联想“趴”）→ 奶奶趴在那里“小睡”了一会儿。","ex":["Taking a nap after learning can help you find the way through the maze.","学习后小睡一会儿可以帮助你找到走出迷宫的路。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"pour","p":"pɔː(r)","m":"v.倾倒；倒（饮料等）；倾泻；倾盆而下","tip":"单词发音类似“泼”→ 大雨下得就像泼下来一样 → 倾泻","ex":["Tea is poured into a cup from a teapot.","茶是从茶壶倒进杯子里的。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"puzzle","p":"ˈpʌzl","m":"v.使困惑，使迷惑 n.令人费解的人或事物；难题","tip":"pu（音似“趴”）+ zz（联想“睡觉”的符号）+ le（联想“了”）→ 我被“难题”困住，趴着睡着了。","ex":["Their functioning is still a puzzle to be solved.","它们的功能仍然是一个有待解决的难题。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"guess","p":"ɡes","m":"v. & n.猜测，推测","tip":"单词发音类似“该死”→ 该死，又让我“猜测”答案。","ex":["They're asked to guess that person's name.","他们被要求猜出那个人的名字。"],"lesson":"u10-l03","group":"“食物”相关"},{"w":"rebel","p":"rɪˈbel","m":"v.造反，反叛，反抗","tip":"re-（再）+ bel（联想 bell）→ 警铃再次被摇响，有人在“造反”。","ex":["He attempts to rebel against the existing social order.","他企图反抗现有的社会秩序。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"riot","p":"ˈraɪət","m":"n.暴乱，骚动 v.发生暴乱","tip":"rio（联想 Rio，酒品牌）+ t（联想“他”）→ 喝醉酒的他引发了“暴乱”。","ex":["The police were able to take preventive action and avoid a possible riot.","警方得以采取防范措施，避免了可能发生的暴乱。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"terror","p":"ˈterə(r)","m":"n.恐惧；恐怖行动","tip":"单词发音类似“太弱”→ 他太软弱，遇到一点挫折就生“恐惧”。","ex":["Her eyes were filled with terror.","她的眼睛里充满了恐惧。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"terrify","p":"ˈterɪfaɪ","m":"v.使惊吓；恐吓；威胁","tip":"terr（怕，恐吓）+ -ify（动词后缀）→ 使惊吓；恐吓；威胁","ex":["They could sometimes terrify adults.","它们有时会吓到成年人。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"shock","p":"ʃɒk","m":"n.震惊；休克；令人震惊的事 v.使震惊","tip":"单词发音类似“休克”。","ex":["These are machines that shock and awe you.","这些机器会让你感到震惊和敬畏。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"horror","p":"ˈhɒrə(r)","m":"n.震惊；恐惧；恐怖故事","tip":"单词发音类似“嚎我”→ 它对着我嚎叫，让我产生了“恐惧”。","ex":["I have heard some horror stories.","我听说过一些恐怖故事。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"pale","p":"peɪl","m":"adj.苍白的；浅的，淡的 v.变苍白；变淡","tip":"pa（联想“怕”）+ le（联想“了”）→ 他的脸色逐渐“变苍白”，因为他害怕了。","ex":["He was pale and looked sick to death.","他脸色苍白，看上去病入膏肓。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"palm","p":"pɑːm","m":"n.手掌，手心；棕榈树","tip":"pa（联想“怕”）+ l（联想“了”）+ m（联想“吗”）→ 如来佛祖将悟空困于“手掌”之中，并问他“怕了吗”。","ex":["He fell from a tall palm tree by accident.","他不小心从一棵高棕榈树上摔了下来。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"limb","p":"lɪm","m":"n.肢；大树枝","tip":"li（联想“立”）+ m（联想“妹”）+ b → 妹妹站在一个“大树枝”上。","ex":["It has got one of its limbs injured.","它的一条腿受伤了。"],"lesson":"u10-l03","group":"“吓唬”相关"},{"w":"caution","p":"ˈkɔːʃn","m":"n.小心，谨慎 v.警告，劝……小心","tip":"单词发音类似“靠心”→ 人要依靠良心做事，态度需“谨慎”。","ex":["Statistics should be treated with caution.","对待统计数字要小心。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"precaution","p":"prɪˈkɔːʃn","m":"n.预防措施；防备","tip":"pre-（提前）+ caution（小心）→ 预防措施","ex":["I hope all the precautions against air pollution will be seriously considered here.","我希望在这里能认真考虑所有抵御空气污染的预防措施。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"warning","p":"ˈwɔːnɪŋ","m":"n.警告，警示；先兆","tip":"warn（警告）+ -ing（名词后缀）→ 警告，警示","ex":["The driver annoyed after receiving continuous warnings.","该司机在连续收到警告后感到恼火。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"aware","p":"əˈweə(r)","m":"adj.知道；发觉；意识到","tip":"a（一）+ war（战争）+ e（字母音似“姨”）→ 一场战争让阿姨“意识到”和平的生活有多可贵。","ex":["They are less aware of the value of their money.","他们很少意识到钱的价值。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"alert","p":"əˈlɜːt","m":"adj.警觉的；警惕的；意识到；注意到 v.向……报警；使警觉 n.警戒；戒备；警报","tip":"a（一）+ ler（音似“乐”）+ t（联想“他”）→ 他一直情绪低落，今天突然乐起来，我们要对他突然变化的精神状态保持警惕 → 警惕的","ex":["We are able to issue alerts about the latest threats they should be aware of.","我们能够就他们应注意的最新威胁发出警报。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"conscious","p":"ˈkɒnʃəs","m":"adj.意识到的；有意识的；有意的","tip":"单词发音类似“靠心的”→ 靠心去感应，去思考 → 意识到的；有意识的","ex":["This environmentally conscious product will save millions of liters of water a year.","这种具有环保意识的产品每年将节省数百万升水。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"conscience","p":"ˈkɒnʃəns","m":"n.良知，良心","tip":"con-（所有）+ science（科学）→ 我们希望所有懂科学的人都是有“良知”的，为人类谋福利。","ex":["This is an issue of equality, opportunity and national conscience.","这是一个关于平等、机会和国家良知的问题。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"perceive","p":"pəˈsiːv","m":"v.察觉到；注意到；意识到；理解","tip":"单词发音类似“破媳妇”→ 他“察觉到”媳妇的衣服破了个洞。","ex":["I perceived a change in his behaviour.","我注意到他举止有些改变。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"deceive","p":"dɪˈsiːv","m":"v.欺骗，蒙骗，诓骗","tip":"单词发音类似“弟媳妇”→ 这部电影里，主角的弟媳妇是个骗子，“欺骗”了弟弟。","ex":["She deceived him into handing over all his savings.","她骗他交出了所有的积蓄。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"cheat","p":"tʃiːt","m":"v.欺骗；作弊","tip":"单词发音类似“欺他”→ 人们“欺骗”了他。","ex":["If he thinks he can cheat me, just let him try!","要是他以为能够骗过我，就让他来试一下吧！"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"receive","p":"rɪˈsiːv","m":"v.收到，接到；遭受；接见","tip":"re（字母音似“阿姨”）+ ceive（音似“媳妇”）→ 阿姨从车站“接到”了她的儿媳妇。","ex":["Farmers ring up to receive the information.","农民们打电话来接收信息。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"receipt","p":"rɪˈsiːt","m":"n.发票，收据；收入","tip":"他收到（receive）了收据（receipt）。","ex":["Can I have a receipt, please?","请给我开个收据，好吗？"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"receptionist","p":"rɪˈsepʃənɪst","m":"n.接待员","tip":"reception（接待）+ -ist（表示人的后缀）→ 接待员","ex":["The hotel receptionist must make sure that guests are registered correctly.","酒店接待员必须确保客人正确登记。"],"lesson":"u10-l04","group":"“谨慎”相关"},{"w":"resemble","p":"rɪˈzembl","m":"v.类似于；像；看起来像","tip":"re-（重复）+ sem（联想 same）+ ble → 重复同样的 → 像；看起来像","ex":["She closely resembles her sister.","她和她姐姐很像。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"assemble","p":"əˈsembl","m":"v.集合，聚集；组装","tip":"as-（一再地）+ sem（联想 same）+ ble → 一再地相似 → 相似的都在一起 → 集合，聚集","ex":["It assembles super-intelligent robots.","它组装超级智能机器人。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"sympathy","p":"ˈsɪmpəθi","m":"n.同情；赞同；支持","tip":"sym（音似 same）+ path（道路）+ y → 同道中人最能相互“同情”。","ex":["Our heartfelt sympathy goes out to the victims of the war.","我们对战争的受害者表示由衷的同情。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"mercy","p":"ˈmɜːsi","m":"n.仁慈；幸运，恩惠","tip":"me（我）+ rcy（联想 cry）→ 她是一个“仁慈”的人，因同情我的遭遇而落泪。","ex":["It's a mercy she wasn't seriously hurt.","幸运的是她伤势不重。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"symptom","p":"ˈsɪmptəm","m":"n.征兆；特征；（医）症状","tip":"sym（音似 same）+ p + tom（音似“童木”）→ 他和阿童木有同样的“特征”。","ex":["Many women say their physicians sometimes don't even recognize the symptoms.","许多女性表示，她们的医生有时甚至无法识别这些症状。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"symbol","p":"ˈsɪmbl","m":"n.符号，记号；标记；标志，象征","tip":"sym（音似 same）+ bol（联想 ball）→ 他用相同的球做“标记”。","ex":["The new school stands as a symbol of hope for a better future.","这所新学校象征着对更美好的未来的希望。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"badge","p":"bædʒ","m":"n.徽章；标记；象征","tip":"bad（坏的）+ ge（联想“哥”）→ 做了坏事的哥哥被没收了“徽章”。","ex":["Today, consulting for five businesses at the same time is a badge of honor.","如今，同时为五家企业提供咨询是一种荣誉的象征。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"likewise","p":"ˈlaɪkwaɪz","m":"adv.相似地；相同地","tip":"","ex":["The method works for English, and likewise for French.","这种方法适用于英语，同样也适用于法语。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"wise","p":"waɪz","m":"adj.明智的，高明的","tip":"wi（联想 we）+ se（联想“蛇”）→ 我们没有打草惊蛇，作出的决定是非常“明智的”。","ex":["She doesn't think it wise to pay before attending any class.","她认为先交钱再上课是不明智的。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"alike","p":"əˈlaɪk","m":"adj.相似的，相像的 adv.相似地，相像地；同样都","tip":"a-（表加强）+ like（像）→ 相似地","ex":["Good management benefits employers and employees alike.","良好的管理对雇主和雇员同样有利。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"clockwise","p":"ˈklɒkwaɪz","m":"adv. & adj.顺时针方向（的）","tip":"clock（时钟）+ -wise（表方向）→ 钟表指针转动方向 → 顺时针方向（的）","ex":["He walked clockwise on the playground.","他在操场上按顺时针方向走。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"insane","p":"ɪnˈseɪn","m":"adj.精神失常的；荒唐的；疯狂的","tip":"in-（否定前缀）+ sane（音似“神”）→ 心神不宁，心智不全 → 精神失常的","ex":["She was driving me insane with her constant chatter.","她唠叨个没完，快把我逼得精神失常了。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"wit","p":"wɪt","m":"n.风趣；机智，理解力","tip":"智慧（wisdom）与理解力（wit）密不可分。","ex":["The game was a long battle of wits.","这场游戏是长时间的斗智。"],"lesson":"u10-l04","group":"“相似的”相关"},{"w":"broad","p":"brɔːd","m":"adj.宽阔的；广泛的；普遍的","tip":"b（联想 big）+ road（路）→ 大路是“宽阔的”。","ex":["He's got broad shoulders.","他的肩很宽。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"abroad","p":"əˈbrɔːd","m":"adv.到国外，在国外","tip":"a-（一）+ broad（宽阔的）→ 他“在国外”旅游，正走在一条宽阔的道路上。","ex":["She is abroad on business.","她在国外出差。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"overseas","p":"ˌəʊvəˈsiːz","m":"adj.海外的 adv.在海外","tip":"","ex":["The firm is expanding into overseas markets.","该公司正在向海外市场扩张。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"board","p":"bɔːd","m":"n.木板；董事会；伙食（尤指付费的） v.登上（船、飞机等）","tip":"黑板（blackboard）就是黑色的（black）木板（board）。","ex":["Some employees found the board motivating.","一些员工发现董事会具有激励作用。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"aboard","p":"əˈbɔːd","m":"adv. & prep.在（船、飞机、火车等）上；上（船、飞机、火车等）","tip":"a-（= on，在……上）+ board（木板）→ 上（船、飞机、火车等）","ex":["The captain welcomed everyone aboard.","船长欢迎所有人登船。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"panel","p":"ˈpænl","m":"n.专家咨询组；嵌板；控制板；仪表盘","tip":"单词发音类似“拍喽”→ 能给这件事拍板的人 → 专家咨询组","ex":["They agreed to cover the entire building in solar panels.","他们同意用太阳能电池板覆盖整座建筑。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"depth","p":"depθ","m":"n.向下的距离；深（度）；纵深","tip":"de(e)p（深的）+ -th（名词后缀）→ 深度","ex":["We must continually explore the depths of our species' linguistic diversity.","我们必须不断探索我们物种语言多样性的深度。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"height","p":"haɪt","m":"n.（人或物的）身高；高度；最强点，顶点","tip":"","ex":["Please state your height and weight.","请说明你的身高和体重。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"weight","p":"weɪt","m":"n.重量；体重；重担；重压 v.使加权；使负重","tip":"单词发音类似“喂他”→ 他的父母不停地喂他吃东西，导致他的“体重”日渐增加。","ex":["Choosing what to eat and drink is key to weight control.","选择吃什么和喝什么是控制体重的关键。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"wide","p":"waɪd","m":"adj.宽的，宽阔的；广泛的","tip":"wi（联想 we）+ de（联想“的”）→ 我们的心胸是“宽阔的”。","ex":["The river gets quite wide here.","河流在此段变得很宽。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"width","p":"wɪdθ; wɪtθ","m":"n.宽度；广度","tip":"","ex":["The carpet is available in different widths.","这款地毯有各种宽度可供选择。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"wild","p":"waɪld","m":"adj.野生的，野外的；狂热的；荒芜的 n.野生环境；偏远地区","tip":"wil（联想 will）+ d（联想“的”）→ 我们将要开始“野外的”冒险之旅。","ex":["Climate change has little effect on the lives of wild ducks.","气候变化对野鸭的生活几乎没有影响。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"lengthen","p":"ˈleŋ(k)θən","m":"v.延长，加长","tip":"length（长度）+ -en（动词后缀）→ 使……变长 → 延长，加长","ex":["Healthy habits can effectively lengthen people's life expectancy.","健康的习惯能有效延长人的预期寿命。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"measure","p":"ˈmeʒə(r)","m":"n.措施；计量单位；程度，标准 v.测量；度量","tip":"","ex":["The office asked for the public's help to measure their speed results.","办公室请求公众帮助测量他们的速度结果。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"centimetre","p":"ˈsentɪmiːtə(r)","m":"n.厘米","tip":"","ex":["The shrimps grow from their original 1 millimetre to a length of about 1.5 centimetres.","虾从原来的1毫米长到大约1.5厘米的长度。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"kilometre","p":"ˈkɪləmiːtə(r)","m":"n.千米；公里","tip":"","ex":["She had been driving at 110 kilometres per hour.","她一直以每小时110千米的速度行驶。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"billion","p":"ˈbɪljən","m":"num.十亿","tip":"","ex":["Textbooks represent an 11 billion dollar industry.","教科书行业价值110亿美元。"],"lesson":"u10-l04","group":"“宽广”相关"},{"w":"former","p":"ˈfɔːmə(r)","m":"n.前者 adj.以前的；（两者中）前者的","tip":"","ex":["She is my former employee.","她是我的前员工。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"later","p":"ˈleɪtə(r)","m":"adv.后来，随后 adj.后来的；以后的","tip":"","ex":["This might present problems for young people later on.","这可能会在以后给年轻人带来问题。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"meanwhile","p":"ˈmiːnwaɪl","m":"adv.在此期间，同时","tip":"","ex":["Meanwhile, it is also the most practiced art form in the world.","同时，它也是世界上得到最广泛实践的艺术形式。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"meantime","p":"ˈmiːntaɪm","m":"n. & adv.其间，同时","tip":"","ex":["My first novel was rejected. In the meantime I had written a play.","我的第一部小说遭到拒绝。同时，我又完成了一部戏剧。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"whereas","p":"ˌweərˈæz","m":"conj.然而，但是，尽管","tip":"","ex":["We thought she was arrogant, whereas in fact she was just very shy.","我们认为她傲慢，然而事实上她只是非常害羞。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"unless","p":"ənˈles","m":"conj.除非；若非，如果不","tip":"","ex":["They can't function unless exposed to sunlight.","除非暴露在阳光下，否则它们无法正常工作。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"nevertheless","p":"ˌnevəðəˈles","m":"adv.尽管如此；不过；然而","tip":"","ex":["What you said was true. It was, nevertheless, a little unkind.","你说的都是实话，只不过有点刻薄。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"else","p":"els","m":"adv.其他的，别的；另外的；不同的","tip":"","ex":["How can you quantify a person's boredom level and compare it with someone else's?","你如何量化一个人的无聊程度，并与其他人的无聊程度进行比较？"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"elsewhere","p":"ˌelsˈweə(r)","m":"adv.在别处；去别处","tip":"","ex":["If the destruction is extreme, mail addressed to the area will get sent elsewhere.","如果破坏严重，寄往该地区的邮件将被发送到别处。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"otherwise","p":"ˈʌðəwaɪz","m":"adv.否则；另外；在其他方面","tip":"","ex":["It keeps many otherwise qualified women off the runway.","这让许多其他方面合格的女性无法走上T台。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"therefore","p":"ˈðeəfɔː(r)","m":"adv.因此，所以","tip":"","ex":["He's only 17 and therefore not eligible to vote.","他只有17岁，因此没有投票选举的资格。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"thereby","p":"ˌðeəˈbaɪ","m":"adv.因此；由此；从而","tip":"","ex":["Regular exercise strengthens the heart, thereby reducing the risk of heart attack.","经常锻炼可以增强心脏机能，从而减少心脏病发作的危险。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"thus","p":"ðʌs","m":"adv.因此，所以；这样；如此","tip":"","ex":["She rarely gave interviews and thus avoided being asked questions she would rather not answer.","她很少接受采访，因此避免了被问到她不愿回答的问题。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"moreover","p":"mɔːrˈəʊvə(r)","m":"adv.此外；而且","tip":"","ex":["Moreover, schools should be more than simple institutions of traditional learning.","此外，学校不应该仅仅是简单的传统学习机构。"],"lesson":"u10-l04","group":"“逻辑关系”相关"},{"w":"furthermore","p":"ˌfɜːðəˈmɔː(r)","m":"adv.此外；而且；再者","tip":"further（进一步）+ more（更多）→ 此外；而且","ex":["Furthermore, listening can benefit yourself.","此外，倾听对你自己有益。"],"lesson":"u10-l04","group":"“逻辑关系”相关"}];
